struct Mesh { std::vector<V3> v; std::vector<MeshTri> t; };
struct WheelDef { V3 p; float r, w; bool steer; };

struct CarModel {
    std::string name;
    Mesh lod[4];
    std::vector<MatEntry> mats;
    std::vector<WheelDef> wheels;
    float halfW = 0.9f, height = 1.4f, halfL = 2.3f, minZ = -2.3f, maxZ = 2.3f;
    V3 plateF, plateR; float plateScale = 1;
    V3 headL, tailL;           // левая фара/фонарь (x>0 — зеркалим)
    V3 exhaust;
    float roofY = 1.4f, doorX = 0.9f, doorZ = 0.2f, doorY = 0.6f;
    float wheelbase = 2.6f;
    float dpsY = 0.8f; bool procStripe = false; float stripeY = 0.55f;
    std::vector<float> sideZ, sideX;   // профиль борта для полосы ливреи
    float trunkZ = -2.0f, trunkY = 0.9f, trunkW = 0.6f;   // задний проём
    bool tallRear = false;     // открывается дверь 5-го типа
    float mass = 1.0f;
    int hitchModel = -1; float hitchZ = 0, kingpinZ = 0;   // фура
    int wheelStyle = 0;
    float radius = 2.5f;
};
static std::vector<CarModel> CM;

// нормали граней + сглаженные нормали в углах (по совпадающим позициям вершин,
// только между гранями одного материала и с углом меньше ~38°) — плавное освещение кузова
static void finalizeMesh(Mesh& m) {
    size_t nt = m.t.size();
    std::vector<V3> fa(nt);
    for (size_t i = 0; i < nt; i++) {
        MeshTri& t = m.t[i];
        V3 a = m.v[t.a], b = m.v[t.b], c = m.v[t.c];
        fa[i] = cross(b - a, c - a);
        t.n = norm(fa[i]);
        if (len(fa[i]) * 0.5f < 0.012f) t.flags |= TF_SMALL; else t.flags &= ~TF_SMALL;
        t.cen = (a + b + c) * (1.0f / 3);
    }
    // группы вершин по позиции
    std::vector<int> grp(m.v.size());
    {
        std::vector<std::pair<uint64_t, int>> keys(m.v.size());
        for (size_t i = 0; i < m.v.size(); i++) {
            const V3& p = m.v[i];
            uint64_t kx = (uint64_t)(int64_t)lroundf(p.x * 2000) & 0x1fffff, ky = (uint64_t)(int64_t)lroundf(p.y * 2000) & 0x1fffff, kz = (uint64_t)(int64_t)lroundf(p.z * 2000) & 0x1fffff;
            keys[i] = std::make_pair((kx << 42) | (ky << 21) | kz, (int)i);
        }
        std::sort(keys.begin(), keys.end());
        int g = -1;
        for (size_t i = 0; i < keys.size(); i++) { if (i == 0 || keys[i].first != keys[i - 1].first) g++; grp[keys[i].second] = g; }
    }
    int ng = 0; for (int g : grp) ng = std::max(ng, g + 1);
    std::vector<int> start(ng + 1, 0), list(nt * 3);
    for (size_t i = 0; i < nt; i++) { start[grp[m.t[i].a] + 1]++; start[grp[m.t[i].b] + 1]++; start[grp[m.t[i].c] + 1]++; }
    for (int g = 0; g < ng; g++) start[g + 1] += start[g];
    std::vector<int> fill(start.begin(), start.end() - 1);
    for (size_t i = 0; i < nt; i++) { list[fill[grp[m.t[i].a]]++] = (int)i; list[fill[grp[m.t[i].b]]++] = (int)i; list[fill[grp[m.t[i].c]]++] = (int)i; }
    const float creaseCos = 0.79f;
    for (size_t i = 0; i < nt; i++) {
        MeshTri& t = m.t[i];
        uint16_t idx[3] = {t.a, t.b, t.c};
        for (int k = 0; k < 3; k++) {
            int g = grp[idx[k]];
            V3 s(0, 0, 0);
            for (int j = start[g]; j < start[g + 1]; j++) {
                const MeshTri& o = m.t[list[j]];
                if (o.mat != t.mat) continue;
                if (dot(o.n, t.n) < creaseCos) continue;
                s = s + fa[list[j]];
            }
            float l = len(s);
            t.cn[k] = l > 1e-9f ? s * (1.0f / l) : t.n;
        }
    }
}

// ---- base64 ----
static std::vector<uint8_t> b64decode(const char* s) {
    static int8_t T[256]; static bool init = false;
    if (!init) { for (int i = 0; i < 256; i++) T[i] = -1; const char* a = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"; for (int i = 0; i < 64; i++) T[(uint8_t)a[i]] = (int8_t)i; init = true; }
    std::vector<uint8_t> out; uint32_t acc = 0; int bits = 0;
    for (const char* p = s; *p; p++) {
        int v = T[(uint8_t)*p]; if (v < 0) continue;
        acc = (acc << 6) | (uint32_t)v; bits += 6;
        if (bits >= 8) { bits -= 8; out.push_back((uint8_t)((acc >> bits) & 255)); }
    }
    return out;
}

// профиль борта: максимальная ширина кузова на высоте полосы вдоль длины
static void buildSideProfile(CarModel& M, bool flat = false) {
    M.sideZ.clear(); M.sideX.clear();
    float z0 = M.minZ + 0.35f, z1 = M.maxZ - 0.35f;
    if (M.wheels.size() >= 4) { z0 = M.wheels[2].p.z + M.wheels[2].r + 0.08f; z1 = M.wheels[0].p.z - M.wheels[0].r - 0.08f; }
    int n = std::max(2, (int)((z1 - z0) / 0.25f));
    for (int i = 0; i <= n; i++) {
        float z = z0 + (z1 - z0) * i / n, best = 0;
        for (const V3& v : M.lod[0].v) if (fabsf(v.z - z) < 0.18f && fabsf(v.y - M.stripeY) < 0.12f) best = std::max(best, fabsf(v.x));
        if (flat) best = M.doorX; else if (best < 0.3f) continue;   // процедурные: плоский борт
        M.sideZ.push_back(z); M.sideX.push_back(best);
    }
    float dx = 0;
    if (!flat) for (const V3& v : M.lod[0].v) if (fabsf(v.z - M.doorZ) < 0.45f && fabsf(v.y - M.dpsY) < 0.1f) dx = std::max(dx, fabsf(v.x));
    if (dx > 0.3f) M.doorX = dx;
}
static bool gFixWinding = true;
// согласовать направление обхода треугольников: внутри связной поверхности соседние грани
// должны проходить общее ребро в разные стороны; затем вся поверхность разворачивается «наружу»
// по большинству голосов. Иначе часть граней отсекается как задние — и в кузове видны просветы.
static void fixWinding(Mesh& m, const V3& center, const V3& ext) {
    size_t nt = m.t.size(); if (!nt) return;
    std::vector<int> grp(m.v.size());
    {
        std::vector<std::pair<uint64_t, int>> keys(m.v.size());
        for (size_t i = 0; i < m.v.size(); i++) {
            const V3& p = m.v[i];
            uint64_t kx = (uint64_t)(int64_t)lroundf(p.x * 2000) & 0x1fffff, ky = (uint64_t)(int64_t)lroundf(p.y * 2000) & 0x1fffff, kz = (uint64_t)(int64_t)lroundf(p.z * 2000) & 0x1fffff;
            keys[i] = std::make_pair((kx << 42) | (ky << 21) | kz, (int)i);
        }
        std::sort(keys.begin(), keys.end());
        int g = -1;
        for (size_t i = 0; i < keys.size(); i++) { if (i == 0 || keys[i].first != keys[i - 1].first) g++; grp[keys[i].second] = g; }
    }
    struct EdgeRef { uint64_t key; int tri; int dir; };
    std::vector<EdgeRef> es; es.reserve(nt * 3);
    for (size_t i = 0; i < nt; i++) {
        int v[3] = {grp[m.t[i].a], grp[m.t[i].b], grp[m.t[i].c]};
        for (int k = 0; k < 3; k++) {
            int a = v[k], b = v[(k + 1) % 3]; if (a == b) continue;
            uint64_t key = ((uint64_t)std::min(a, b) << 32) | (uint32_t)std::max(a, b);
            es.push_back({key, (int)i, a < b ? 1 : -1});
        }
    }
    std::sort(es.begin(), es.end(), [](const EdgeRef& x, const EdgeRef& y) { return x.key < y.key; });
    std::vector<std::vector<std::pair<int, bool>>> adj(nt);
    for (size_t i = 0; i < es.size();) {
        size_t j = i; while (j < es.size() && es[j].key == es[i].key) j++;
        if (j - i == 2 && es[i].tri != es[i + 1].tri) {
            bool same = es[i].dir == es[i + 1].dir;
            adj[es[i].tri].push_back({es[i + 1].tri, same});
            adj[es[i + 1].tri].push_back({es[i].tri, same});
        }
        i = j;
    }
    std::vector<int> comp(nt, -1); std::vector<char> flip(nt, 0);
    std::vector<int> stack;
    int nc = 0;
    for (size_t s0 = 0; s0 < nt; s0++) {
        if (comp[s0] >= 0) continue;
        std::vector<int> members;
        comp[s0] = nc; flip[s0] = 0; stack.push_back((int)s0);
        while (!stack.empty()) {
            int t = stack.back(); stack.pop_back(); members.push_back(t);
            for (auto& nb : adj[t]) {
                if (comp[nb.first] >= 0) continue;
                comp[nb.first] = nc; flip[nb.first] = flip[t] ^ (nb.second ? 1 : 0);
                stack.push_back(nb.first);
            }
        }
        double vote = 0;
        for (int t : members) {
            const MeshTri& tr = m.t[t];
            V3 a = m.v[tr.a], b = m.v[tr.b], c = m.v[tr.c];
            V3 n = cross(b - a, c - a); if (flip[t]) n = n * -1.0f;
            V3 r = (a + b + c) * (1.0f / 3) - center;
            V3 out(r.x / (ext.x * ext.x), r.y / (ext.y * ext.y), r.z / (ext.z * ext.z));
            vote += dot(n, out) > 0 ? len(n) : -len(n);
        }
        if (vote < 0) for (int t : members) flip[t] ^= 1;
        nc++;
    }
    for (size_t i = 0; i < nt; i++) if (flip[i]) std::swap(m.t[i].b, m.t[i].c);
}
static void loadEmbeddedModel(const CarModelDesc& d) {
    CarModel M;
    M.name = d.name;
    std::vector<uint8_t> raw = b64decode(d.data);
    size_t off = 0;
    int nvs[4] = {d.nv0, d.nv1, d.nv2, d.nv3}, nts[4] = {d.nt0, d.nt1, d.nt2, d.nt3};
    for (int L = 0; L < 4; L++) {
        Mesh& m = M.lod[L];
        m.v.resize(nvs[L]);
        for (int i = 0; i < nvs[L]; i++) {
            int16_t q[3]; memcpy(q, &raw[off], 6); off += 6;
            m.v[i] = V3(q[0] / 32767.0f * d.ext[0], q[1] / 32767.0f * d.ext[1], q[2] / 32767.0f * d.ext[2]);
        }
        m.t.resize(nts[L]);
        for (int i = 0; i < nts[L]; i++) {
            uint16_t ix[3]; memcpy(ix, &raw[off], 6); off += 6;
            MeshTri& t = m.t[i]; t.a = ix[0]; t.b = ix[1]; t.c = ix[2]; t.mat = raw[off++]; t.flags = 0;
        }
        if (gFixWinding && !(d.flags & 1)) fixWinding(m, V3(0, d.ext[1] * 0.5f, 0), V3(d.ext[0], d.ext[1] * 0.6f, d.ext[2]));
        finalizeMesh(m);
    }
    for (int i = 0; i < d.nm; i++) M.mats.push_back(d.mats[i]);
    // габариты
    float mnx = 1e9f, mxx = -1e9f, mxy = 0, mnz = 1e9f, mxz = -1e9f;
    for (const V3& v : M.lod[0].v) { mnx = std::min(mnx, v.x); mxx = std::max(mxx, v.x); mxy = std::max(mxy, v.y); mnz = std::min(mnz, v.z); mxz = std::max(mxz, v.z); }
    M.halfW = (mxx - mnx) * 0.5f; M.height = mxy; M.minZ = mnz; M.maxZ = mxz; M.halfL = (mxz - mnz) * 0.5f;
    M.wheels.push_back({V3(d.fw[0], d.fw[1], d.fw[2]), d.fw[3], d.fw[4], true});
    M.wheels.push_back({V3(-d.fw[0], d.fw[1], d.fw[2]), d.fw[3], d.fw[4], true});
    M.wheels.push_back({V3(d.rw[0], d.rw[1], d.rw[2]), d.rw[3], d.rw[4], false});
    M.wheels.push_back({V3(-d.rw[0], d.rw[1], d.rw[2]), d.rw[3], d.rw[4], false});
    M.wheelbase = d.fw[2] - d.rw[2];
    // мелкие тёмные накладки снаружи кузова (не в арках колёс) получают сдвиг в сортировке
    for (int L = 0; L < 4; L++)
        for (MeshTri& t : M.lod[L].t) {
            uint8_t ty = M.mats[t.mat].type;
            if (d.flags & 1) {   // импортированные модели: тёмные щели и уплотнители — «за» краской
                if (ty == M_CLAD) t.flags |= TF_TRIM;   // ровные накладные линии (швы, стойки) — поверх краски
                else if (ty == M_BLACK || ty == M_FRAME) t.flags |= TF_BACK;
                continue;
            }
            if (!(t.flags & TF_SMALL) || !(ty == M_BLACK || ty == M_FRAME || ty == M_CLAD)) continue;
            bool nearWheel = false;
            for (const WheelDef& w : M.wheels) { float dy = t.cen.y - w.p.y, dz = t.cen.z - w.p.z; if (dy * dy + dz * dz < (w.r * 1.45f) * (w.r * 1.45f)) nearWheel = true; }
            if (!nearWheel) t.flags |= TF_TRIM;
        }
    // «Старый джип»: в исходной модели порог между колёсами — гребёнка из белых и чёрных треугольников.
    // Делаем порог сплошным чёрным
    if (strcmp(d.name, "СТАРЫЙ ДЖИП") == 0) {
        int blackMat = -1;
        for (size_t i = 0; i < M.mats.size(); i++) if (M.mats[i].type == M_BLACK) { blackMat = (int)i; break; }
        if (blackMat >= 0)
            for (int L = 0; L < 4; L++)
                for (MeshTri& t : M.lod[L].t)
                    if (M.mats[t.mat].type == M_PAINT && t.cen.y < 0.42f && fabsf(t.cen.x) > M.halfW * 0.72f && t.cen.z < d.fw[2] - d.fw[3] * 1.05f && t.cen.z > d.rw[2] + d.rw[3] * 1.05f)
                        t.mat = (uint8_t)blackMat;
    }
    M.headL = V3(d.hl[0], d.hl[1], d.hl[2]); M.tailL = V3(d.tl[0], d.tl[1], d.tl[2]);
    // номер — по высоте бампера
    M.plateF = V3(0, 0.48f, d.pf + 0.025f); M.plateR = V3(0, 0.55f, d.pr - 0.025f);
    // если в модели есть ниша под номер (чёрная площадка по центру бампера/крышки) — ставим номер в неё
    for (int side = 0; side < 2; side++) {
        float sg = side == 0 ? 1.f : -1.f;
        const Mesh& m0 = M.lod[0];
        int best = -1; float bestA = 0;
        auto cand = [&](const MeshTri& t) {
            uint8_t ty = M.mats[t.mat].type;
            if (ty != M_BLACK && ty != M_PLATEM && ty != M_BADGED && ty != M_FRAME && !((d.flags & 1) && ty == M_CHROME)) return false;
            if (t.n.z * sg < 0.6f || fabsf(t.cen.x) > 0.45f || t.cen.y < 0.3f || t.cen.y > 1.25f) return false;
            return side == 0 ? t.cen.z > M.maxZ - 0.6f : t.cen.z < M.minZ + 0.6f;
        };
        for (size_t i = 0; i < m0.t.size(); i++) {
            const MeshTri& t = m0.t[i]; if (!cand(t)) continue;
            float ar = len(cross(m0.v[t.b] - m0.v[t.a], m0.v[t.c] - m0.v[t.a]));
            if (M.mats[t.mat].type == M_PLATEM) ar += 100.f;   // ниша номера, размеченная явно, — в приоритете
            if (ar > bestA) { bestA = ar; best = (int)i; }
        }
        if (best < 0) continue;
        V3 c0 = m0.t[best].cen;
        bool bestPlate = M.mats[m0.t[best].mat].type == M_PLATEM;
        float x0 = 1e9f, x1 = -1e9f, y0 = 1e9f, y1 = -1e9f, zz = side == 0 ? -1e9f : 1e9f;
        for (const MeshTri& t : m0.t) {
            if (bestPlate && M.mats[t.mat].type != M_PLATEM) continue;
            if (!cand(t) || fabsf(t.cen.x - c0.x) > 0.4f || fabsf(t.cen.y - c0.y) > 0.16f || fabsf(t.cen.z - c0.z) > 0.12f) continue;
            uint16_t ix[3] = {t.a, t.b, t.c};
            for (int k = 0; k < 3; k++) { const V3& v = m0.v[ix[k]]; x0 = std::min(x0, v.x); x1 = std::max(x1, v.x); y0 = std::min(y0, v.y); y1 = std::max(y1, v.y); zz = side == 0 ? std::max(zz, v.z) : std::min(zz, v.z); }
        }
        float w = x1 - x0, h = y1 - y0, cx = (x0 + x1) * 0.5f;
        if (w > 0.3f && w < 0.8f && h > 0.07f && h < 0.32f && fabsf(cx) < 0.12f) {
            V3 p(0, (y0 + y1) * 0.5f, zz + sg * 0.02f);
            if (side == 0) M.plateF = p; else M.plateR = p;
        }
    }
    // крыша, двери, задний проём
    float roof = 0; float door = 0; float trunkTop = 0;
    for (const V3& v : M.lod[0].v) {
        if (fabsf(v.x) < 0.3f && fabsf(v.z) < 0.6f) roof = std::max(roof, v.y);
        if (v.z > -0.3f && v.z < 0.7f && v.y > 0.45f && v.y < 0.75f) door = std::max(door, fabsf(v.x));
        if (fabsf(v.x) < 0.3f && v.z < M.minZ + 0.6f) trunkTop = std::max(trunkTop, v.y);
    }
    M.roofY = roof > 0.5f ? roof : M.height; M.doorX = door > 0.3f ? door : M.halfW; M.doorZ = 0.2f; M.doorY = 0.62f;
    M.trunkZ = M.minZ + 0.15f; M.trunkY = trunkTop > 0.5f ? trunkTop : 0.95f; M.trunkW = M.halfW * 0.72f;
    M.tallRear = (M.trunkY > 1.15f);
    M.dpsY = M.height * 0.56f;
    M.exhaust = V3(-M.halfW * 0.55f, 0.28f, M.minZ + 0.05f);
    M.radius = sqrtf(M.halfW * M.halfW + M.halfL * M.halfL);
    M.stripeY = M.height * 0.4f;
    M.procStripe = true;
    buildSideProfile(M);
    CM.push_back(M);
}

// ---------------------------------------------------------------------
//  Процедурные модели
// ---------------------------------------------------------------------
struct MeshB {
    Mesh* m; V3 center;
    int addV(const V3& p) { m->v.push_back(p); return (int)m->v.size() - 1; }
    // треугольник с проверкой ориентации (нормаль от центра)
    void tri(const V3& a, const V3& b, const V3& c, int mat, V3 ref) {
        int ia = addV(a), ib = addV(b), ic = addV(c);
        V3 n = cross(b - a, c - a); V3 cc = (a + b + c) * (1.f / 3);
        MeshTri t; t.mat = (uint8_t)mat; t.flags = 0;
        if (dot(n, cc - ref) < 0) { t.a = (uint16_t)ia; t.b = (uint16_t)ic; t.c = (uint16_t)ib; }
        else { t.a = (uint16_t)ia; t.b = (uint16_t)ib; t.c = (uint16_t)ic; }
        m->t.push_back(t);
    }
    void quad(const V3& a, const V3& b, const V3& c, const V3& d, int mat, V3 ref) { tri(a, b, c, mat, ref); tri(a, c, d, mat, ref); }
    // параллелепипед
    void box(V3 c, V3 h, int mat, bool bottom = false, int matTop = -1) {
        V3 p[8];
        for (int i = 0; i < 8; i++) p[i] = V3(c.x + ((i & 1) ? h.x : -h.x), c.y + ((i & 2) ? h.y : -h.y), c.z + ((i & 4) ? h.z : -h.z));
        quad(p[1], p[3], p[7], p[5], mat, c);  // +x
        quad(p[0], p[4], p[6], p[2], mat, c);  // -x
        quad(p[2], p[6], p[7], p[3], matTop >= 0 ? matTop : mat, c);  // +y
        if (bottom) quad(p[0], p[1], p[5], p[4], mat, c);
        quad(p[4], p[5], p[7], p[6], mat, c);  // +z
        quad(p[0], p[2], p[3], p[1], mat, c);  // -z
    }
    // плоская наклейка (прямоугольник в плоскости), смотрит по normal
    void decal(V3 c, V3 ax, V3 ay, int mat, V3 normal) { quad(c - ax - ay, c + ax - ay, c + ax + ay, c - ax + ay, mat, c - normal); }
};

struct Sec { float z, yb, yBelt, yTop, wB, wT; int cab; };
// «лофт» кузова из поперечных сечений
static void loft(MeshB& B, const std::vector<Sec>& S, int paint, int glass, int black) {
    const int NP = 12;
    auto ring = [](const Sec& s, V3* p) {
        float r = std::min(0.09f, (s.yTop - s.yBelt) * 0.4f);
        p[0] = V3(0, s.yb, s.z); p[1] = V3(s.wB * 0.9f, s.yb, s.z); p[2] = V3(s.wB, s.yb + 0.1f, s.z); p[3] = V3(s.wB, s.yBelt, s.z);
        p[4] = V3(s.wT, s.yTop - r, s.z); p[5] = V3(s.wT * 0.8f, s.yTop, s.z); p[6] = V3(0, s.yTop, s.z);
        p[7] = V3(-s.wT * 0.8f, s.yTop, s.z); p[8] = V3(-s.wT, s.yTop - r, s.z); p[9] = V3(-s.wB, s.yBelt, s.z); p[10] = V3(-s.wB, s.yb + 0.1f, s.z); p[11] = V3(-s.wB * 0.9f, s.yb, s.z);
    };
    for (size_t i = 0; i + 1 < S.size(); i++) {
        V3 a[NP], b[NP]; ring(S[i], a); ring(S[i + 1], b);
        const Sec &s0 = S[i], &s1 = S[i + 1];
        for (int k = 0; k < NP; k++) {
            int k1 = (k + 1) % NP; int mat = paint;
            if (k == 0 || k == 11) mat = black;
            else if (k == 3 || k == 8) mat = (s0.cab && s1.cab) ? glass : (s0.cab != s1.cab ? glass : paint);
            else if (k >= 4 && k <= 7) mat = (s0.cab != s1.cab) ? glass : paint;
            V3 ref = V3(0, (s0.yb + s0.yTop) * 0.5f, (s0.z + s1.z) * 0.5f);
            if (dist2d(a[k], b[k]) < 1e-4f && fabsf(a[k].y - b[k].y) < 1e-4f && dist2d(a[k1], b[k1]) < 1e-4f && fabsf(a[k1].y - b[k1].y) < 1e-4f) continue;
            B.quad(a[k], a[k1], b[k1], b[k], mat, ref);
        }
    }
    // торцы
    for (int e = 0; e < 2; e++) {
        const Sec& s = e == 0 ? S.front() : S.back();
        V3 p[NP]; ring(s, p);
        V3 c(0, (s.yb + s.yTop) * 0.5f, s.z);
        V3 ref = c + V3(0, 0, e == 0 ? 1.f : -1.f);
        for (int k = 0; k < NP; k++) B.tri(c, p[k], p[(k + 1) % NP], paint, ref);
    }
}

static int addMat(CarModel& M, int type, int r, int g, int b) {
    MatEntry e; e.type = (uint8_t)type; e.r = (uint8_t)r; e.g = (uint8_t)g; e.b = (uint8_t)b;
    M.mats.push_back(e); return (int)M.mats.size() - 1;
}
struct StdMats { int paint, glass, black, chrome, head, tail, ind, paint2, frame; };
static StdMats stdMats(CarModel& M) {
    StdMats s;
    s.paint = addMat(M, M_PAINT, 236, 236, 240);
    s.glass = addMat(M, M_GLASS, 26, 36, 46);
    s.black = addMat(M, M_BLACK, 22, 22, 25);
    s.chrome = addMat(M, M_CHROME, 190, 192, 198);
    s.head = addMat(M, M_HEAD, 225, 225, 200);
    s.tail = addMat(M, M_TAIL, 200, 15, 15);
    s.ind = addMat(M, M_IND, 242, 128, 13);
    s.paint2 = addMat(M, M_PAINT2, 60, 90, 160);
    s.frame = addMat(M, M_FRAME, 50, 50, 55);
    return s;
}
static void finishProcModel(CarModel& M) {
    finalizeMesh(M.lod[0]);
    M.lod[1] = M.lod[0]; M.lod[2] = M.lod[0]; M.lod[3] = M.lod[0];
    float mnx = 1e9f, mxx = -1e9f, mxy = 0, mnz = 1e9f, mxz = -1e9f;
    for (const V3& v : M.lod[0].v) { mnx = std::min(mnx, v.x); mxx = std::max(mxx, v.x); mxy = std::max(mxy, v.y); mnz = std::min(mnz, v.z); mxz = std::max(mxz, v.z); }
    M.halfW = (mxx - mnx) * 0.5f; M.height = mxy; M.minZ = mnz; M.maxZ = mxz; M.halfL = (mxz - mnz) * 0.5f;
    M.radius = sqrtf(M.halfW * M.halfW + M.halfL * M.halfL);
    M.procStripe = true;
    buildSideProfile(M, true);
}

// полукруглая «арка» над колесом на боковой плоскости x (тёмная), верхняя половина
static void archDecal(MeshB& B, float x, float y, float z, float R, int mat) {
    const int SEG = 10; float sg = x > 0 ? 1.f : -1.f;
    V3 c(x, y, z);
    for (int k = 0; k < SEG; k++) {
        float a0 = PI * k / SEG, a1 = PI * (k + 1) / SEG;
        B.tri(c, V3(x, y + sinf(a0) * R, z + cosf(a0) * R), V3(x, y + sinf(a1) * R, z + cosf(a1) * R), mat, c - V3(sg, 0, 0));
    }
}
// прямоугольник на наклонном борту: x линейно меняется от xb (на высоте yb) до xt (на высоте yt)
static void sidePane(MeshB& B, int side, float z0, float z1, float y0, float y1, float yb, float xb, float yt, float xt, int mat, float off = 0.012f) {
    auto X = [&](float y) { return side * (xb + (xt - xb) * (y - yb) / (yt - yb) + off); };
    V3 a(X(y0), y0, z0), b(X(y0), y0, z1), c(X(y1), y1, z1), d(X(y1), y1, z0);
    B.quad(a, b, c, d, mat, V3(0, (y0 + y1) * 0.5f, (z0 + z1) * 0.5f));
}

// «Газель» — маршрутное такси (капот, наклонное лобовое, ряд боковых окон, сдвижная дверь)
static void buildMinibus() {
    CarModel M; M.name = "МАРШРУТКА";
    StdMats s = stdMats(M);
    MeshB B; B.m = &M.lod[0];
    const float W = 1.0f, WT = 0.96f, BELT = 1.2f, TOP = 2.3f;
    std::vector<Sec> S = {
        {-2.80f, 0.50f, BELT, 2.22f, 0.98f, 0.93f, 0}, {-2.72f, 0.44f, BELT, TOP, W, WT, 0},
        {1.48f, 0.44f, BELT, TOP, W, WT, 0}, {2.10f, 0.44f, 1.16f, 1.30f, W, 0.95f, 0},
        {2.62f, 0.46f, 1.02f, 1.12f, 0.98f, 0.9f, 0}, {2.82f, 0.52f, 0.86f, 0.96f, 0.9f, 0.82f, 0}};
    loft(B, S, s.paint, s.glass, s.black);
    V3 nf(0, 0, 1), nr(0, 0, -1);
    // лобовое стекло на наклонной плоскости между сечениями 1.48 и 2.10
    {
        V3 a(-0.86f, 1.34f, 2.06f), b(0.86f, 1.34f, 2.06f), c(0.84f, 2.2f, 1.55f), d(-0.84f, 2.2f, 1.55f);
        V3 n = norm(cross(b - a, d - a)); if (n.z < 0) n = n * -1.0f;
        V3 o = n * 0.012f;
        B.quad(a + o, b + o, c + o, d + o, s.glass, V3(0, 1.5f, 1.2f));
        B.box(V3(0, 1.36f, 2.07f), V3(0.6f, 0.012f, 0.03f), s.black, true);   // дворники
    }
    const float yb = BELT, xb = W, yt = TOP - 0.09f, xt = WT;
    for (int k = -1; k <= 1; k += 2) {
        // окна: водительская дверь и три в салоне
        sidePane(B, k, 0.98f, 1.45f, 1.32f, 2.05f, yb, xb, yt, xt, s.glass);
        sidePane(B, k, -0.35f, 0.72f, 1.32f, 2.05f, yb, xb, yt, xt, s.glass);
        sidePane(B, k, -1.55f, -0.47f, 1.32f, 2.05f, yb, xb, yt, xt, s.glass);
        sidePane(B, k, -2.58f, -1.67f, 1.32f, 2.05f, yb, xb, yt, xt, s.glass);
        // стыки дверей
        B.box(V3(k * (W + 0.006f), 1.1f, 0.88f), V3(0.004f, 0.62f, 0.012f), s.black);
        if (k > 0) { B.box(V3(W + 0.006f, 1.15f, -0.42f), V3(0.004f, 0.68f, 0.012f), s.black); B.box(V3(W + 0.006f, 1.15f, 0.8f), V3(0.004f, 0.68f, 0.012f), s.black); }
        // молдинг, ручка, арки колёс
        B.box(V3(k * (W + 0.008f), 0.78f, 0.0f), V3(0.008f, 0.045f, 2.6f), s.black);
        B.box(V3(k * (W + 0.01f), 1.12f, 0.98f), V3(0.01f, 0.02f, 0.07f), s.black);
        archDecal(B, k * (W + 0.006f), 0.36f, 2.0f, 0.5f, s.black);
        archDecal(B, k * (W + 0.006f), 0.36f, -1.45f, 0.5f, s.black);
        // зеркала на кронштейнах
        B.box(V3(k * 1.08f, 1.5f, 1.62f), V3(0.08f, 0.015f, 0.015f), s.black, true);
        B.box(V3(k * 1.17f, 1.5f, 1.62f), V3(0.025f, 0.14f, 0.07f), s.black, true);
        // фары, поворотники, задние фонари, противотуманки
        B.decal(V3(k * 0.64f, 0.92f, 2.70f), V3(0.2f, 0, 0), V3(0, 0.075f, -0.05f), s.head, V3(0, 0.3f, 1));
        B.decal(V3(k * 0.86f, 0.9f, 2.62f), V3(0.0f, 0, 0.06f), V3(0, 0.05f, 0), s.ind, V3((float)k, 0, 0.4f));
        B.decal(V3(k * 0.82f, 1.05f, -2.815f), V3(0.08f, 0, 0), V3(0, 0.22f, 0), s.tail, nr);
        B.decal(V3(k * 0.62f, 0.52f, 2.88f), V3(0.07f, 0, 0), V3(0, 0.035f, 0), s.head, nf);
        // задние распашные двери со стёклами
        B.decal(V3(k * 0.42f, 1.75f, -2.815f), V3(0.33f, 0, 0), V3(0, 0.3f, 0), s.glass, nr);
    }
    B.box(V3(0, 1.25f, -2.81f), V3(0.006f, 0.75f, 0.006f), s.black);                 // стык задних дверей
    // решётка радиатора с хромом
    B.decal(V3(0, 0.9f, 2.73f), V3(0.36f, 0, 0), V3(0, 0.1f, -0.03f), s.black, V3(0, 0.25f, 1));
    for (int g = 0; g < 2; g++) B.box(V3(0, 0.86f + g * 0.08f, 2.745f), V3(0.34f, 0.008f, 0.01f), s.chrome);
    // бамперы и подножка
    B.box(V3(0, 0.55f, 2.84f), V3(0.97f, 0.11f, 0.08f), s.black, true);
    B.box(V3(0, 0.5f, -2.84f), V3(0.97f, 0.09f, 0.07f), s.black, true);
    B.box(V3(0, 0.42f, -2.95f), V3(0.45f, 0.03f, 0.08f), s.black, true);
    B.box(V3(1.02f, 0.4f, 0.2f), V3(0.04f, 0.03f, 0.55f), s.black, true);           // ступенька у сдвижной двери
    // табличка маршрута за лобовым стеклом
    B.box(V3(0.35f, 2.05f, 1.64f), V3(0.3f, 0.07f, 0.01f), s.ind, true);
    M.wheels = {{V3(0.82f, 0.36f, 2.0f), 0.36f, 0.22f, true}, {V3(-0.82f, 0.36f, 2.0f), 0.36f, 0.22f, true},
                {V3(0.82f, 0.36f, -1.45f), 0.36f, 0.24f, false}, {V3(-0.82f, 0.36f, -1.45f), 0.36f, 0.24f, false}};
    M.wheelbase = 3.45f;
    M.plateF = V3(0, 0.62f, 2.93f); M.plateR = V3(0, 0.72f, -2.92f);
    M.headL = V3(0.64f, 0.92f, 2.75f); M.tailL = V3(0.82f, 1.05f, -2.83f);
    M.exhaust = V3(-0.6f, 0.3f, -2.7f);
    M.roofY = 2.3f; M.doorX = 1.0f; M.doorZ = 0.0f; M.doorY = 0.9f;
    M.trunkZ = -2.7f; M.trunkY = 2.0f; M.trunkW = 0.8f; M.tallRear = true;
    M.mass = 1.6f;
    finishProcModel(M);
    CM.push_back(M);
}

// кабина грузовика (общая для грузовика и тягача)
static void truckCab(MeshB& B, StdMats& s, float z0, float z1, float yb, float top, float w) {
    std::vector<Sec> S = {
        {z0, yb, 1.75f, top, w, w - 0.08f, 1}, {z1 - 0.18f, yb, 1.75f, top, w, w - 0.08f, 1},
        {z1, yb, 1.70f, top - 0.18f, w - 0.02f, w - 0.14f, 0}};
    loft(B, S, s.paint, s.glass, s.black);
    V3 nf(0, 0, 1);
    // решётка со «жабрами», фары, противотуманки, бампер
    B.decal(V3(0, 1.25f, z1 + 0.012f), V3(w * 0.55f, 0, 0), V3(0, 0.22f, 0), s.black, nf);
    for (int g = 0; g < 4; g++) B.box(V3(0, 1.08f + g * 0.11f, z1 + 0.02f), V3(w * 0.53f, 0.012f, 0.012f), s.chrome);
    B.box(V3(0, 0.75f, z1 + 0.05f), V3(w, 0.13f, 0.09f), s.black, true);
    B.box(V3(0, 0.6f, z1 + 0.02f), V3(w * 0.9f, 0.03f, 0.1f), s.black, true);      // нижняя губа
    // козырёк над лобовым, оранжевые габариты на крыше
    B.box(V3(0, top + 0.02f, z1 - 0.12f), V3(w * 0.95f, 0.03f, 0.16f), s.black, true);
    for (int g = -2; g <= 2; g++) B.box(V3(g * 0.25f, top + 0.06f, z1 - 0.2f), V3(0.05f, 0.025f, 0.03f), s.ind, true);
    B.box(V3(0, 1.78f, z1 - 0.17f), V3(w * 0.55f, 0.012f, 0.02f), s.black, true);  // дворники
    for (int k = -1; k <= 1; k += 2) {
        B.decal(V3(k * (w - 0.25f), 0.95f, z1 + 0.012f), V3(0.16f, 0, 0), V3(0, 0.09f, 0), s.head, nf);
        B.decal(V3(k * (w - 0.18f), 0.68f, z1 + 0.15f), V3(0.07f, 0, 0), V3(0, 0.04f, 0), s.head, nf);
        B.decal(V3(k * (w - 0.04f), 0.95f, z1 - 0.05f), V3(0, 0, 0.06f), V3(0, 0.07f, 0), s.ind, V3((float)k, 0, 0));
        // зеркала на кронштейнах
        B.box(V3(k * (w + 0.06f), 2.0f, z1 - 0.3f), V3(0.07f, 0.015f, 0.015f), s.black, true);
        B.box(V3(k * (w + 0.14f), 2.0f, z1 - 0.3f), V3(0.035f, 0.24f, 0.07f), s.black, true);
        // дверь: стык, ручка, ступеньки, крыло над передним колесом
        float zd0 = z0 + 0.25f, zd1 = z1 - 0.35f;
        B.box(V3(k * (w + 0.006f), (yb + 1.75f) * 0.5f + 0.25f, zd0), V3(0.004f, 0.75f, 0.012f), s.black);
        B.box(V3(k * (w + 0.006f), (yb + 1.75f) * 0.5f + 0.25f, zd1), V3(0.004f, 0.75f, 0.012f), s.black);
        B.box(V3(k * (w + 0.012f), 1.55f, zd0 + 0.15f), V3(0.012f, 0.02f, 0.08f), s.chrome);
        for (int st = 0; st < 2; st++) B.box(V3(k * (w - 0.05f), 0.45f + st * 0.32f, (zd0 + zd1) * 0.5f), V3(0.12f, 0.025f, 0.22f), s.black, true);
    }
}

static void buildTruck() {
    CarModel M; M.name = "ГРУЗОВИК";
    StdMats s = stdMats(M);
    MeshB B; B.m = &M.lod[0];
    truckCab(B, s, 1.95f, 3.55f, 0.85f, 2.85f, 1.2f);
    B.box(V3(0, 0.68f, -0.1f), V3(0.48f, 0.13f, 3.65f), s.black, true);              // рама
    B.box(V3(0, 2.15f, -1.05f), V3(1.25f, 1.2f, 2.85f), s.paint2, false);           // будка
    for (int i = 0; i < 6; i++) {                                                     // рёбра будки
        float z = -3.8f + i * 1.13f;
        for (int k = -1; k <= 1; k += 2) B.box(V3(k * 1.255f, 2.15f, z), V3(0.012f, 1.2f, 0.05f), s.frame);
    }
    B.box(V3(0, 0.95f, -3.95f), V3(1.2f, 0.08f, 0.04f), s.black, true);
    V3 nr(0, 0, -1);
    for (int k = -1; k <= 1; k += 2) {
        B.decal(V3(k * 0.95f, 0.95f, -3.995f), V3(0.13f, 0, 0), V3(0, 0.06f, 0), s.tail, nr);
        B.box(V3(k * 1.1f, 0.85f, -0.9f), V3(0.1f, 0.12f, 0.9f), s.frame, true);     // боковые ящики
    }
    // будка: верхний и нижний пояс, задние двери с петлями и запорами, светоотражатели, брызговики
    for (int k = -1; k <= 1; k += 2) {
        B.box(V3(k * 1.26f, 3.33f, -1.05f), V3(0.02f, 0.03f, 2.86f), s.frame);
        B.box(V3(k * 1.26f, 0.98f, -1.05f), V3(0.02f, 0.04f, 2.86f), s.frame);
        for (int r = 0; r < 4; r++) B.decal(V3(k * 1.278f, 1.05f, -3.5f + r * 1.6f), V3(0, 0, 0.05f), V3(0, 0.025f, 0), s.ind, V3((float)k, 0, 0));
        for (int r = 0; r < 3; r++) B.box(V3(k * 0.62f, 1.4f + r * 0.8f, -3.915f), V3(0.07f, 0.03f, 0.012f), s.frame);   // петли
        B.box(V3(k * 0.25f, 2.15f, -3.915f), V3(0.012f, 1.1f, 0.012f), s.chrome);                                         // запорные штанги
        B.box(V3(k * 0.98f, 0.95f, -3.3f), V3(0.22f, 0.015f, 0.22f), s.black, true);                                       // брызговик-крыло
        B.box(V3(k * 0.98f, 0.62f, -3.47f), V3(0.2f, 0.3f, 0.008f), s.black);                                              // брызговик
    }
    B.box(V3(0, 2.15f, -3.912f), V3(0.006f, 1.15f, 0.006f), s.black);
    M.wheels = {{V3(1.0f, 0.5f, 2.7f), 0.5f, 0.3f, true}, {V3(-1.0f, 0.5f, 2.7f), 0.5f, 0.3f, true},
                {V3(0.98f, 0.5f, -1.55f), 0.5f, 0.42f, false}, {V3(-0.98f, 0.5f, -1.55f), 0.5f, 0.42f, false},
                {V3(0.98f, 0.5f, -2.75f), 0.5f, 0.42f, false}, {V3(-0.98f, 0.5f, -2.75f), 0.5f, 0.42f, false}};
    M.wheelbase = 4.8f;
    M.plateF = V3(0, 0.75f, 3.66f); M.plateR = V3(0, 0.8f, -4.0f);
    M.headL = V3(0.95f, 0.95f, 3.57f); M.tailL = V3(0.95f, 0.95f, -4.0f);
    M.exhaust = V3(1.15f, 2.9f, 1.85f);
    M.roofY = 3.35f; M.doorX = 1.2f; M.doorZ = 2.7f; M.doorY = 1.6f;
    M.trunkZ = -3.9f; M.trunkY = 3.2f; M.trunkW = 1.15f; M.tallRear = true;
    M.mass = 4;
    finishProcModel(M);
    CM.push_back(M);
}

static void buildTractor() {
    CarModel M; M.name = "ФУРА";
    StdMats s = stdMats(M);
    MeshB B; B.m = &M.lod[0];
    truckCab(B, s, 1.0f, 3.0f, 0.9f, 3.45f, 1.25f);
    B.box(V3(0, 0.72f, 0.0f), V3(0.5f, 0.15f, 3.05f), s.black, true);
    B.box(V3(0, 0.92f, -1.6f), V3(0.6f, 0.06f, 0.6f), s.frame, true);    // седло
    B.box(V3(0, 3.55f, 1.6f), V3(1.1f, 0.12f, 0.6f), s.paint, true);      // обтекатель
    for (int k = -1; k <= 1; k += 2) {
        B.box(V3(k * 1.1f, 0.85f, 0.3f), V3(0.18f, 0.28f, 0.55f), s.chrome, true);   // баки
        B.box(V3(k * 0.9f, 2.6f, 0.85f), V3(0.07f, 1.0f, 0.07f), s.chrome);           // трубы
    }
    for (int k = -1; k <= 1; k += 2) {
        B.box(V3(k * 1.12f, 0.75f, -0.45f), V3(0.03f, 0.2f, 0.4f), s.paint, true);           // боковые обтекатели за баками
        B.box(V3(k * 1.0f, 1.02f, -1.82f), V3(0.24f, 0.02f, 0.95f), s.black, true);          // крылья над задними осями
        B.box(V3(k * 1.0f, 0.62f, -3.0f), V3(0.22f, 0.3f, 0.008f), s.black);                 // брызговики
        B.box(V3(k * 0.35f, 3.7f, 2.2f), V3(0.05f, 0.05f, 0.22f), s.chrome);                 // пневмосигналы
    }
    B.box(V3(0, 0.6f, -3.05f), V3(1.0f, 0.06f, 0.05f), s.black, true);
    M.wheels = {{V3(1.02f, 0.52f, 2.15f), 0.52f, 0.32f, true}, {V3(-1.02f, 0.52f, 2.15f), 0.52f, 0.32f, true},
                {V3(1.0f, 0.52f, -1.2f), 0.52f, 0.45f, false}, {V3(-1.0f, 0.52f, -1.2f), 0.52f, 0.45f, false},
                {V3(1.0f, 0.52f, -2.45f), 0.52f, 0.45f, false}, {V3(-1.0f, 0.52f, -2.45f), 0.52f, 0.45f, false}};
    M.wheelbase = 4.0f;
    M.plateF = V3(0, 0.75f, 3.16f); M.plateR = V3(0, 0.75f, -3.08f);
    M.headL = V3(1.0f, 0.95f, 3.02f); M.tailL = V3(0.9f, 0.8f, -3.06f);
    M.exhaust = V3(0.9f, 3.65f, 0.85f);
    M.roofY = 3.67f; M.doorX = 1.25f; M.doorZ = 2.0f; M.doorY = 1.7f;
    M.hitchModel = (int)CM.size() + 1; M.hitchZ = -1.6f;
    M.mass = 6;
    finishProcModel(M);
    CM.push_back(M);
}
static void buildTrailer() {
    CarModel M; M.name = "ПОЛУПРИЦЕП";
    StdMats s = stdMats(M);
    MeshB B; B.m = &M.lod[0];
    B.box(V3(0, 2.65f, 0), V3(1.27f, 1.38f, 6.8f), s.paint2, true);
    B.box(V3(0, 1.15f, -1.0f), V3(0.45f, 0.12f, 5.6f), s.black, true);
    for (int i = 0; i < 12; i++) for (int k = -1; k <= 1; k += 2) B.box(V3(k * 1.275f, 2.65f, -6.5f + i * 1.18f), V3(0.012f, 1.38f, 0.04f), s.frame);
    V3 nr(0, 0, -1);
    for (int k = -1; k <= 1; k += 2) {
        B.decal(V3(k * 0.95f, 1.05f, -6.83f), V3(0.15f, 0, 0), V3(0, 0.07f, 0), s.tail, nr);
        B.box(V3(k * 0.7f, 0.7f, 3.0f), V3(0.05f, 0.5f, 0.05f), s.frame, true);   // опоры
        B.box(V3(k * 1.0f, 0.9f, 0.5f), V3(0.02f, 0.28f, 2.6f), s.frame);          // боковая защита
    }
    B.box(V3(0, 0.82f, -6.85f), V3(1.25f, 0.08f, 0.04f), s.black, true);
    // верхний и нижний пояс, боковые габариты, задние двери, брызговики
    for (int k = -1; k <= 1; k += 2) {
        B.box(V3(k * 1.282f, 4.0f, 0), V3(0.02f, 0.035f, 6.8f), s.frame);
        B.box(V3(k * 1.282f, 1.3f, 0), V3(0.02f, 0.05f, 6.8f), s.frame);
        for (int r = 0; r < 7; r++) B.decal(V3(k * 1.305f, 1.35f, -6.3f + r * 2.1f), V3(0, 0, 0.05f), V3(0, 0.03f, 0), s.ind, V3((float)k, 0, 0));
        for (int r = 0; r < 4; r++) B.box(V3(k * 1.15f, 1.7f + r * 0.8f, -6.815f), V3(0.08f, 0.03f, 0.012f), s.frame);    // петли
        B.box(V3(k * 0.3f, 2.65f, -6.815f), V3(0.012f, 1.3f, 0.012f), s.chrome);                                          // запорные штанги
        B.box(V3(k * 0.7f, 2.65f, -6.815f), V3(0.012f, 1.3f, 0.012f), s.chrome);
        B.box(V3(k * 1.0f, 0.6f, -6.6f), V3(0.22f, 0.3f, 0.008f), s.black);                                                // брызговики
    }
    B.box(V3(0, 2.65f, -6.812f), V3(0.006f, 1.36f, 0.006f), s.black);
    M.wheels = {{V3(1.0f, 0.5f, -3.9f), 0.5f, 0.45f, false}, {V3(-1.0f, 0.5f, -3.9f), 0.5f, 0.45f, false},
                {V3(1.0f, 0.5f, -5.0f), 0.5f, 0.45f, false}, {V3(-1.0f, 0.5f, -5.0f), 0.5f, 0.45f, false},
                {V3(1.0f, 0.5f, -6.1f), 0.5f, 0.45f, false}, {V3(-1.0f, 0.5f, -6.1f), 0.5f, 0.45f, false}};
    M.plateF = V3(0, -5, 0); M.plateR = V3(0, 1.05f, -6.86f);
    M.headL = V3(0, -5, 0); M.tailL = V3(0.95f, 1.05f, -6.86f);
    M.exhaust = V3(0, -5, 0);
    M.roofY = 4.03f; M.doorX = 1.27f;
    M.trunkZ = -6.7f; M.trunkY = 3.8f; M.trunkW = 1.2f; M.tallRear = true;
    M.kingpinZ = 5.7f;
    M.mass = 8;
    finishProcModel(M);
    CM.push_back(M);
}

// единичное колесо: ось по X, наружная сторона +X
// стили дисков: 0 обычный (5 спиц), 1 спортивный (10 тонких спиц), 2 внедорожный (6 толстых спиц, высокий профиль), 3 грузовой штампованный
enum { WS_STD = 0, WS_SPORT, WS_SUV, WS_TRUCK, WS_N };
static Mesh WHEEL[WS_N][2];
static void buildWheelMesh() {
    struct WStyle { float rr; int spokes; float frac; };
    static const WStyle ST[WS_N] = {{0.66f, 5, 0.42f}, {0.76f, 10, 0.32f}, {0.58f, 6, 0.55f}, {0.62f, 8, 0.62f}};
    for (int sty = 0; sty < WS_N; sty++)
    for (int L = 0; L < 2; L++) {
        Mesh& m = WHEEL[sty][L];
        const WStyle& ws = ST[sty];
        int N = L == 0 ? (sty == WS_SPORT ? 40 : 30) : 10;
        float rr = ws.rr;
        // материалы: 0 шина, 1 диск, 2 тёмное (ступица/провалы диска)
        auto addT = [&](V3 a, V3 b, V3 c, int mat, V3 ref) {
            int i = (int)m.v.size(); m.v.push_back(a); m.v.push_back(b); m.v.push_back(c);
            MeshTri t; t.mat = (uint8_t)mat; t.flags = 0;
            if (dot(cross(b - a, c - a), (a + b + c) * (1.f / 3) - ref) < 0) { t.a = (uint16_t)i; t.b = (uint16_t)(i + 2); t.c = (uint16_t)(i + 1); }
            else { t.a = (uint16_t)i; t.b = (uint16_t)(i + 1); t.c = (uint16_t)(i + 2); }
            m.t.push_back(t);
        };
        // кольцо в плоскости x между радиусами r0..r1, сектор a0..a1
        auto ringQ = [&](float x, float r0, float r1, float c0, float s0, float c1, float s1, int mat) {
            V3 out(-1, 0, 0);
            addT(V3(x, s0 * r0, c0 * r0), V3(x, s0 * r1, c0 * r1), V3(x, s1 * r1, c1 * r1), mat, out);
            addT(V3(x, s0 * r0, c0 * r0), V3(x, s1 * r1, c1 * r1), V3(x, s1 * r0, c1 * r0), mat, out);
        };
        for (int i = 0; i < N; i++) {
            float a0 = i * 2 * PI / N, a1 = (i + 1) * 2 * PI / N, am = (a0 + a1) * 0.5f;
            float c0 = cosf(a0), s0 = sinf(a0), c1 = cosf(a1), s1 = sinf(a1);
            // протектор
            addT(V3(-0.5f, s0, c0), V3(0.5f, s0, c0), V3(0.5f, s1, c1), 0, V3(0, 0, 0));
            addT(V3(-0.5f, s0, c0), V3(0.5f, s1, c1), V3(-0.5f, s1, c1), 0, V3(0, 0, 0));
            // боковина шины
            ringQ(0.5f, rr, 1.0f, c0, s0, c1, s1, 0);
            // бортик между шиной и утопленным диском
            addT(V3(0.5f, s0 * rr, c0 * rr), V3(0.45f, s0 * rr, c0 * rr), V3(0.45f, s1 * rr, c1 * rr), 2, V3(0.48f, (s0 + s1) * rr, (c0 + c1) * rr));
            addT(V3(0.5f, s0 * rr, c0 * rr), V3(0.45f, s1 * rr, c1 * rr), V3(0.5f, s1 * rr, c1 * rr), 2, V3(0.48f, (s0 + s1) * rr, (c0 + c1) * rr));
            // внутренняя сторона
            addT(V3(-0.5f, s0, c0), V3(-0.5f, s1, c1), V3(-0.5f, 0, 0), 2, V3(1, 0, 0));
            if (L == 1) {   // дальний вариант: диск одним цветом
                addT(V3(0.45f, s0 * rr, c0 * rr), V3(0.45f, s1 * rr, c1 * rr), V3(0.46f, 0, 0), 1, V3(-1, 0, 0));
                continue;
            }
            // обод диска
            ringQ(0.455f, rr * 0.88f, rr, c0, s0, c1, s1, 1);
            float ph = fmodf(am / (2 * PI) * ws.spokes + 0.25f, 1.0f);
            bool solid = ph < ws.frac;
            if (sty == WS_TRUCK) {
                ringQ(0.45f, rr * 0.72f, rr * 0.88f, c0, s0, c1, s1, 1);
                ringQ(0.45f, rr * 0.5f, rr * 0.72f, c0, s0, c1, s1, solid ? 1 : 2);   // кольцо отверстий
                ringQ(0.46f, rr * 0.3f, rr * 0.5f, c0, s0, c1, s1, 1);
            } else {
                ringQ(0.45f, rr * 0.3f, rr * 0.88f, c0, s0, c1, s1, solid ? 1 : 2);     // спицы и провалы между ними
            }
            // ступица и колпачок
            addT(V3(0.465f, s0 * rr * 0.3f, c0 * rr * 0.3f), V3(0.465f, s1 * rr * 0.3f, c1 * rr * 0.3f), V3(0.48f, 0, 0), sty == WS_SPORT ? 2 : 1, V3(-1, 0, 0));
        }
        finalizeMesh(m);
    }
}


// ---------------------------------------------------------------------
//  Отрисовка машины
// ---------------------------------------------------------------------
struct DrawCar {
    V3 pos; float yaw = 0, pitch = 0, roll = 0;
    Col paint = Col(0.9f, 0.9f, 0.9f), paint2 = Col(0.2f, 0.35f, 0.7f);
    int plate = -1;
    bool police = false, taxi = false, flash = false, headOn = false, brake = false, reverse = false;
    int blink = 0;            // -1 левый, 1 правый, 2 аварийка
    float spin = 0, steer = 0, time = 0;
    float trunk = 0;          // 0..1 открыт багажник
    bool hideBody = false;    // вид из кабины
    bool highlight = false;   // подсветка цели
    float camDist = 0;
    int flatMask = 0;         // пробитые колёса (бит на колесо)
    int wheelStyle = -1;      // стиль дисков (-1 — как у модели)
};

struct Mat3 { V3 c0, c1, c2; };  // столбцы
static inline V3 mul(const Mat3& m, const V3& v) { return m.c0 * v.x + m.c1 * v.y + m.c2 * v.z; }
static Mat3 rotYPR(float yaw, float pitch, float roll) {
    // сначала крен (вокруг z), затем тангаж (вокруг x), затем курс (вокруг y)
    float cy = cosf(yaw), sy = sinf(yaw), cp = cosf(pitch), sp = sinf(pitch), cr = cosf(roll), sr = sinf(roll);
    auto apply = [&](V3 v) {
        V3 a(v.x * cr - v.y * sr, v.x * sr + v.y * cr, v.z);
        V3 b(a.x, a.y * cp - a.z * sp, a.y * sp + a.z * cp);
        return V3(b.x * cy + b.z * sy, b.y, -b.x * sy + b.z * cy);
    };
    Mat3 m; m.c0 = apply(V3(1, 0, 0)); m.c1 = apply(V3(0, 1, 0)); m.c2 = apply(V3(0, 0, 1)); return m;
}

static std::vector<V3> gTmpV;
static bool gHideSeams = true;
static bool gLinerDebug = false;
static bool gMatDebug = false; static int gOnlyType = -1;   // отладка: красить грани по типу материала
static int CAR_CULL = 1;    // направление отсечения задних граней (проверено тестом)

static Col matColor(const CarModel& M, const DrawCar& d, const MeshTri& t, float& emis, int& special) {
    const MatEntry& me = M.mats[t.mat];
    Col base(me.r / 255.f, me.g / 255.f, me.b / 255.f);
    emis = 0; special = 0;
    switch (me.type) {
        case M_PAINT:
            base = d.paint;
            break;
        case M_PAINT2: base = d.paint2; break;
        case M_PLATEM: base = d.paint * 0.9f; break;   // синяя подложка номера из исходной модели — под цвет кузова
        case M_GLASS: case M_TINT: special = 1; break;
        case M_HEAD:
            if (d.headOn) { base = Col(1, 0.97f, 0.85f); emis = 1; }
            break;
        case M_TAIL:
            if (d.brake) { base = Col(1, 0.1f, 0.08f); emis = 1; }
            else if (d.headOn) { base = Col(0.75f, 0.05f, 0.04f); emis = 0.8f; }
            if (d.reverse && t.cen.y < M.tailL.y && fabsf(t.cen.x) < M.tailL.x) { base = Col(1, 1, 1); emis = 1; }
            break;
        case M_IND: {
            bool on = false;
            if (d.blink != 0 && fmodf(d.time, 0.8f) < 0.4f) {
                if (d.blink == 2) on = true;
                else if (d.blink == 1 && t.cen.x > 0) on = true;   // правый поворот — правая сторона (+x)
                else if (d.blink == -1 && t.cen.x < 0) on = true;
            }
            if (on) { base = Col(1, 0.6f, 0.1f); emis = 1; }
        } break;
        case M_CHROME: case M_RIM: special = 2; break;
        case M_BLACK: case M_FRAME: base = Col(std::max(base.r, 0.12f), std::max(base.g, 0.12f), std::max(base.b, 0.13f)); break;   // не «дыра», а тёмный пластик
        case M_BADGEC: case M_BADGED: case M_BADGEL: special = -1; break;   // эмблемы и шильдики марок не рисуем
        case M_SEAM: if (gHideSeams) special = -1; break;
        default: break;
    }
    return base;
}

// тёмные накладки (молдинги, пороги, расширители арок) лежат почти вплотную к кузову:
// чуть «ближе» в сортировке, чтобы не рассыпались на зубцы и пунктир
static inline float trimBias(const CarModel& M, const MeshTri& t) {
    uint8_t ty = M.mats[t.mat].type;
    (void)ty; return (t.flags & TF_TRIM) ? -0.045f : ((t.flags & TF_BACK) ? 0.035f : 0.f);
}
static inline bool me_isPaint(const CarModel& M, const MeshTri& t) { uint8_t ty = M.mats[t.mat].type; return ty == M_PAINT || ty == M_PAINT2; }
// отрисовать сетку с матрицей; возвращает false если вне поля зрения
static bool gSmooth = true;
static void drawMesh(const CarModel& M, const Mesh& m, const Mat3& rot, const V3& pos, const DrawCar& d, float bias) {
    // матрица мир->вид
    const V3 &Rr = R3.R, &Uu = R3.U, &Ff = R3.F;
    V3 rc0(dot(rot.c0, Rr), dot(rot.c0, Uu), dot(rot.c0, Ff));
    V3 rc1(dot(rot.c1, Rr), dot(rot.c1, Uu), dot(rot.c1, Ff));
    V3 rc2(dot(rot.c2, Rr), dot(rot.c2, Uu), dot(rot.c2, Ff));
    V3 tp = R3.toView(pos);
    if (gTmpV.size() < m.v.size()) gTmpV.resize(m.v.size());
    for (size_t i = 0; i < m.v.size(); i++) { const V3& p = m.v[i]; gTmpV[i] = rc0 * p.x + rc1 * p.y + rc2 * p.z + tp; }
    V3 camW = R3.pos;
    for (size_t i = 0; i < m.t.size(); i++) {
        const MeshTri& t = m.t[i];
        float emis; int special;
        Col base = matColor(M, d, t, emis, special);
        if (special < 0) continue;
        if (gOnlyType >= 0 && M.mats[t.mat].type != gOnlyType) continue;
        if (gMatDebug) {
            static const Col dc[25] = {Col(0.8f,0.8f,0.8f),Col(0.3f,0.6f,1),Col(0,0,0),Col(0.5f,0.5f,0.5f),Col(1,1,0.6f),Col(1,0,0),Col(0.05f,0.05f,0.05f),Col(0,1,1),Col(1,0.5f,0),Col(0.2f,0.3f,0.5f),
                Col(1,0,1),Col(0.6f,0,1),Col(0,1,0),Col(0.5f,0.25f,0),Col(0.3f,0.6f,0.3f),Col(1,0.7f,0.8f),Col(0,0,1),Col(1,1,1),Col(1,1,1),Col(1,1,1),Col(0.7f,0.7f,0.9f),Col(1,1,1),Col(1,1,1),Col(1,1,1),Col(1,1,1)};
            uint8_t ty = M.mats[t.mat].type; base = dc[ty < 25 ? ty : 0]; special = 0; emis = 0.6f;
        }
        V3 nw = mul(rot, t.n);
        V3 cw = mul(rot, t.cen) + pos;
        Col c;
        if (special == 1) {
            // стекло: тёмное + отражение неба по Френелю + бегущий блик
            V3 vd = norm(cw - camW);
            float ndv = fabsf(dot(nw, vd));
            float fr = 0.18f + 0.75f * powf(1 - ndv, 2.0f);
            float streak = 0.5f + 0.5f * sinf((cw.x + cw.z) * 0.45f + cw.y * 2.0f + nw.x * 2);
            streak = streak * streak * streak * streak;
            Col sky = lerpc(L.skyHor, L.skyTop, clampf(nw.y, 0, 1));
            c = base * (0.6f + 0.4f * (1 - L.night)) + sky * (fr * (0.65f - L.night * 0.4f)) + Col(1, 1, 1) * (streak * 0.22f * (1 - L.night * 0.7f) * (0.3f + fr));
        } else if (special == 2) {
            V3 vd = norm(cw - camW);
            V3 rf = vd - nw * (2 * dot(vd, nw));
            float sp = clampf(dot(rf, L.sun), 0, 1); sp = powf(sp, 8);
            c = shadeN(base * 0.85f, nw, cw, emis) + Col(1, 1, 1) * (sp * 0.35f * (1 - L.night));
        } else if (gSmooth && emis < 0.5f) {
            // плавное освещение: цвет в каждом углу по сглаженной нормали
            bool paint = me_isPaint(M, t);
            V3 vd = norm(cw - camW);
            Col cc[3];
            for (int k = 0; k < 3; k++) {
                V3 nk = mul(rot, t.cn[k]);
                cc[k] = shadeN(base, nk, cw, emis);
                if (paint) {
                    V3 rf = vd - nk * (2 * dot(vd, nk));
                    float sp = clampf(dot(rf, L.sun), 0, 1); sp = sp * sp; sp = sp * sp; sp = sp * sp;
                    cc[k] = cc[k] + Col(1, 1, 1) * (sp * 0.35f * (1 - L.night));
                }
                if (d.highlight) cc[k] = cc[k] + Col(0.12f, 0.1f, 0.0f) * (0.5f + 0.5f * sinf(d.time * 8));
            }
            float fz = (gTmpV[t.a].z + gTmpV[t.b].z + gTmpV[t.c].z) * (1.f / 3);
            float ff = fogFactor(fz);
            SDL_Color s0 = toSDL(lerpc(cc[0], L.fog, ff)), s1 = toSDL(lerpc(cc[1], L.fog, ff)), s2 = toSDL(lerpc(cc[2], L.fog, ff));
            R3.triView(gTmpV[t.a], gTmpV[t.b], gTmpV[t.c], s0, s1, s2, UV_WHITE, UV_WHITE, UV_WHITE, 2, CAR_CULL, bias + trimBias(M, t));
            continue;
        } else {
            c = shadeN(base, nw, cw, emis);
            if (me_isPaint(M, t)) {
                // лёгкий лаковый блик на краске
                V3 vd = norm(cw - camW);
                V3 rf = vd - nw * (2 * dot(vd, nw));
                float sp = clampf(dot(rf, L.sun), 0, 1); sp = sp * sp; sp = sp * sp; sp = sp * sp;
                c = c + Col(1, 1, 1) * (sp * 0.35f * (1 - L.night));
            }
        }
        if (d.highlight) c = c + Col(0.12f, 0.1f, 0.0f) * (0.5f + 0.5f * sinf(d.time * 8));
        float fz = (gTmpV[t.a].z + gTmpV[t.b].z + gTmpV[t.c].z) * (1.f / 3);
        float ff = fogFactor(fz);
        if (emis > 0.5f) ff *= 0.5f;
        c = lerpc(c, L.fog, ff);
        SDL_Color sc = toSDL(c);
        R3.triView(gTmpV[t.a], gTmpV[t.b], gTmpV[t.c], sc, sc, sc, UV_WHITE, UV_WHITE, UV_WHITE, 2, CAR_CULL, bias + trimBias(M, t));
    }
}

static void drawWheel(const WheelDef& w, const Mat3& bodyRot, const V3& pos, float yaw, const DrawCar& d, int lod, bool leftSide, bool flat = false) {
    const Mesh& m = WHEEL[d.wheelStyle >= 0 ? d.wheelStyle : 0][lod];
    float st = w.steer ? d.steer : 0;
    float wy = yaw + st;
    // матрица колеса: масштаб (w, r, r), вращение вокруг X (spin), зеркало для левой стороны, поворот
    float cs = cosf(d.spin), sn = sinf(d.spin);
    Mat3 yr = rotYPR(wy, 0, 0);
    V3 cw = mul(bodyRot, w.p) + pos;
    float sx = leftSide ? -w.w : w.w;
    V3 c0 = yr.c0 * sx;
    V3 c1 = (yr.c1 * cs + yr.c2 * sn) * w.r;
    V3 c2 = (yr.c2 * cs - yr.c1 * sn) * w.r;
    if (flat) {   // спущенная шина: сплющена снизу, диск ниже
        c1.y *= 0.72f; c2.y *= 0.72f; c1.x *= 1.04f; c1.z *= 1.04f; c2.x *= 1.04f; c2.z *= 1.04f;
        cw.y -= w.r * 0.26f;
    }
    const V3 &Rr = R3.R, &Uu = R3.U, &Ff = R3.F;
    V3 v0(dot(c0, Rr), dot(c0, Uu), dot(c0, Ff)), v1(dot(c1, Rr), dot(c1, Uu), dot(c1, Ff)), v2(dot(c2, Rr), dot(c2, Uu), dot(c2, Ff));
    V3 tp = R3.toView(cw);
    if (gTmpV.size() < m.v.size()) gTmpV.resize(m.v.size());
    for (size_t i = 0; i < m.v.size(); i++) { const V3& p = m.v[i]; gTmpV[i] = v0 * p.x + v1 * p.y + v2 * p.z + tp; }
    static const Col WC[WS_N][3] = {
        {Col(0.07f, 0.07f, 0.08f), Col(0.72f, 0.73f, 0.77f), Col(0.12f, 0.12f, 0.13f)},   // обычный: серебристый
        {Col(0.06f, 0.06f, 0.07f), Col(0.86f, 0.87f, 0.9f), Col(0.05f, 0.05f, 0.06f)},    // спорт: яркий, глубокие провалы
        {Col(0.08f, 0.08f, 0.08f), Col(0.36f, 0.37f, 0.4f), Col(0.1f, 0.1f, 0.11f)},      // внедорожный: тёмный графит
        {Col(0.07f, 0.07f, 0.08f), Col(0.55f, 0.56f, 0.58f), Col(0.08f, 0.08f, 0.09f)}};  // грузовой: крашеная сталь
    const Col* wc = WC[d.wheelStyle >= 0 ? d.wheelStyle : 0];
    float ff = fogFactor(tp.z);
    for (size_t i = 0; i < m.t.size(); i++) {
        const MeshTri& t = m.t[i];
        V3 nl = t.n; if (leftSide) nl.x = -nl.x;
        V3 nw = norm(yr.c0 * nl.x + (yr.c1 * cs + yr.c2 * sn) * nl.y + (yr.c2 * cs - yr.c1 * sn) * nl.z);
        Col c = shadeN(wc[t.mat], nw, cw);
        c = lerpc(c, L.fog, ff);
        SDL_Color sc = toSDL(c);
        // у левых колёс зеркальная матрица — меняем порядок обхода
        if (leftSide) R3.triView(gTmpV[t.a], gTmpV[t.c], gTmpV[t.b], sc, sc, sc, UV_WHITE, UV_WHITE, UV_WHITE, 2, CAR_CULL, 0);
        else R3.triView(gTmpV[t.a], gTmpV[t.b], gTmpV[t.c], sc, sc, sc, UV_WHITE, UV_WHITE, UV_WHITE, 2, CAR_CULL, 0);
    }
}

// наклейка на кузов (номер, ДПС) в локальных координатах
static void bodyDecal(const Mat3& rot, const V3& pos, V3 c, V3 ax, V3 ay, SDL_FPoint t0, SDL_FPoint t1, SDL_FPoint t2, SDL_FPoint t3, Col col, float bias, float emis = 0) {
    V3 a = mul(rot, c - ax + ay) + pos, b = mul(rot, c + ax + ay) + pos, cc = mul(rot, c + ax - ay) + pos, dd = mul(rot, c - ax - ay) + pos;
    V3 n = norm(cross(b - a, dd - a));
    Col sh = shadeN(col, n, a, emis);
    sh = lerpc(sh, L.fog, fogFactor(R3.toView(a).z));
    SDL_Color sc = toSDL(sh);
    R3.quadWT(a, b, cc, dd, sc, t0, t1, t2, t3, 2, 0, bias);
}

static void drawCarModel(int mi, const DrawCar& d) {
    const CarModel& M = CM[mi];
    if (!R3.sphereVisible(d.pos + V3(0, M.height * 0.5f, 0), M.radius + 0.5f)) return;
    V3 vp = R3.toView(d.pos);
    float dist = sqrtf(vp.x * vp.x + vp.y * vp.y + vp.z * vp.z);
    if (dist > L.fogEnd + M.radius) return;
    // полная модель — почти на любой видимой дистанции; упрощённые только совсем далеко
    int lod = dist < 70 ? 0 : (dist < 130 ? 1 : 2);
    gSmooth = true;
    Mat3 rot = rotYPR(d.yaw, d.pitch, d.roll);
    Mat3 rotY = rotYPR(d.yaw, 0, 0);
    if (!d.hideBody) {
        drawMesh(M, M.lod[lod], rot, d.pos, d, 0);
        // колёса
        // тёмные «подкрылки»: диск за каждым колесом, чтобы сквозь арку не просвечивал фон
        if (dist < 90) {
            Col wc = gLinerDebug ? Col(1, 0, 0) : shadeN(Col(0.05f, 0.05f, 0.055f), V3(0, 1, 0), d.pos);
            SDL_Color sc = toSDL(lerpc(wc, L.fog, fogFactor(R3.toView(d.pos).z)));
            const int SEG = 12;
            for (size_t i = 0; i < M.wheels.size(); i++) {
                const WheelDef& w = M.wheels[i];
                float sgn = w.p.x < 0 ? -1.f : 1.f;
                V3 c(w.p.x - sgn * w.w * 0.5f, w.p.y, w.p.z);
                float R = w.r * 1.65f, top = w.p.y + w.r * 1.2f;
                V3 cw = mul(rotY, c) + d.pos;
                V3 prev;
                for (int k = 0; k <= SEG; k++) {
                    float a = k * 2 * PI / SEG;
                    V3 lp(c.x, clampf(c.y + sinf(a) * R, std::max(0.04f, w.p.y - w.r * 0.55f), top), c.z + cosf(a) * R * 0.92f);
                    V3 p = mul(rotY, lp) + d.pos;
                    if (k > 0) R3.triW(cw, prev, p, sc, 2, 0, 0.45f);
                    prev = p;
                }
            }
        }
        DrawCar dw = d; if (dw.wheelStyle < 0) dw.wheelStyle = M.wheelStyle;
        if (dist < 140) for (size_t i = 0; i < M.wheels.size(); i++) drawWheel(M.wheels[i], rotY, d.pos, d.yaw, dw, dist < 30 ? 0 : 1, M.wheels[i].p.x < 0, ((d.flatMask >> i) & 1) != 0);
        // номера
        if (d.plate >= 0 && dist < 60) {
            float pw = 0.26f, ph = 0.06f;
            Col pc(1, 1, 1);
            float pe = d.headOn ? 0.5f : 0;
            if (M.plateF.y > 0) bodyDecal(rot, d.pos, M.plateF, V3(-pw, 0, 0), V3(0, ph, 0), plateUV(d.plate, 0, 0), plateUV(d.plate, 1, 0), plateUV(d.plate, 1, 1), plateUV(d.plate, 0, 1), pc, -0.15f, pe);
            if (M.plateR.y > 0) bodyDecal(rot, d.pos, M.plateR, V3(pw, 0, 0), V3(0, ph, 0), plateUV(d.plate, 0, 0), plateUV(d.plate, 1, 0), plateUV(d.plate, 1, 1), plateUV(d.plate, 0, 1), pc, -0.15f, pe);
        }
        // ливрея ДПС
        if (d.police && M.procStripe && dist < 160 && M.sideZ.size() >= 2) {
            Col blue(0.08f, 0.22f, 0.62f);
            for (int s = -1; s <= 1; s += 2) {
                for (size_t i = 0; i + 1 < M.sideZ.size(); i++) {
                    float x0 = s * (M.sideX[i] + 0.012f), x1 = s * (M.sideX[i + 1] + 0.012f);
                    float hy = 0.075f;
                    V3 a = mul(rot, V3(x0, M.stripeY + hy, M.sideZ[i])) + d.pos, b = mul(rot, V3(x1, M.stripeY + hy, M.sideZ[i + 1])) + d.pos;
                    V3 c2 = mul(rot, V3(x1, M.stripeY - hy, M.sideZ[i + 1])) + d.pos, dd = mul(rot, V3(x0, M.stripeY - hy, M.sideZ[i])) + d.pos;
                    V3 n = mul(rot, V3((float)s, 0, 0));
                    if (dot(R3.pos - a, n) <= 0) continue;   // дальний борт не виден — не рисуем
                    Col sh = lerpc(shadeN(blue, n, a), L.fog, fogFactor(dist));
                    R3.quadW(a, b, c2, dd, toSDL(sh), 2, 0, -0.35f);
                }
            }
        }
        if (d.police && dist < 80) {
            for (int s = -1; s <= 1; s += 2) {
                V3 c(s * (M.doorX + 0.018f), M.dpsY, M.doorZ);
                { V3 cw = mul(rot, c) + d.pos, nw = mul(rot, V3((float)s, 0, 0)); if (dot(R3.pos - cw, nw) <= 0) continue; }
                V3 ax(0, 0, s > 0 ? 0.42f : -0.42f), ay(0, 0.13f, 0);
                bodyDecal(rot, d.pos, c, ax, ay, uvp(DPS_X + 0.5f, DPS_Y + 0.5f), uvp(DPS_X + DPS_W - 0.5f, DPS_Y + 0.5f), uvp(DPS_X + DPS_W - 0.5f, DPS_Y + DPS_H - 0.5f), uvp(DPS_X + 0.5f, DPS_Y + DPS_H - 0.5f), Col(1, 1, 1), -0.45f);
            }
        }
        // мигалка
        if (d.police) {
            float y = M.roofY + 0.02f, z = (M.wheels.empty() ? 0 : -0.15f);
            bool ph = fmodf(d.time, 0.5f) < 0.25f;
            float fr = d.flash ? (ph ? 1.f : 0.25f) : 0.f, fb = d.flash ? (ph ? 0.25f : 1.f) : 0.f;
            Col cr = d.flash ? Col(1, 0.1f, 0.1f) * (0.35f + 0.65f * fr) : Col(0.55f, 0.08f, 0.08f);
            Col cb = d.flash ? Col(0.15f, 0.3f, 1) * (0.35f + 0.65f * fb) : Col(0.08f, 0.12f, 0.5f);
            // основание
            V3 p0 = mul(rot, V3(0, y + 0.03f, z)) + d.pos;
            (void)p0;
            auto lbox = [&](float x0, float x1, Col c, float e) {
                V3 pts[8];
                for (int i = 0; i < 8; i++) pts[i] = mul(rot, V3((i & 1) ? x1 : x0, y + ((i & 2) ? 0.13f : 0), z + ((i & 4) ? 0.13f : -0.13f))) + d.pos;
                int faces[5][4] = {{2, 3, 7, 6}, {4, 5, 7, 6}, {0, 1, 3, 2}, {1, 3, 7, 5}, {0, 2, 6, 4}};
                for (int f = 0; f < 5; f++) {
                    V3 n = norm(cross(pts[faces[f][1]] - pts[faces[f][0]], pts[faces[f][2]] - pts[faces[f][0]]));
                    Col sh = shadeN(c, n, pts[0], e);
                    R3.quadW(pts[faces[f][0]], pts[faces[f][1]], pts[faces[f][2]], pts[faces[f][3]], toSDL(lerpc(sh, L.fog, fogFactor(dist))), 2, 0, -0.05f);
                }
            };
            lbox(-0.55f, -0.08f, cr, d.flash ? 1.f : 0.f);
            lbox(-0.08f, 0.08f, Col(0.85f, 0.85f, 0.9f), 0);
            lbox(0.08f, 0.55f, cb, d.flash ? 1.f : 0.f);
            if (d.flash) {
                float gsz = 0.7f + L.night * 1.6f;
                V3 gl = mul(rot, V3(-0.35f, y + 0.08f, z)) + d.pos, gr = mul(rot, V3(0.35f, y + 0.08f, z)) + d.pos;
                R3.billboard(gl, gsz * fr, gsz * fr, toSDL(Col(1, 0.15f, 0.1f) * (0.5f + 0.5f * L.night)), 0, 3, -0.4f);
                R3.billboard(gr, gsz * fb, gsz * fb, toSDL(Col(0.2f, 0.35f, 1) * (0.5f + 0.5f * L.night)), 0, 3, -0.4f);
            }
        }
        // такси: шашечки на крыше
        if (d.taxi && dist < 120) {
            float y = M.roofY;
            for (int s = -1; s <= 1; s += 2) {
                V3 c(0, y + 0.1f, s * 0.0f); (void)c;
                bodyDecal(rot, d.pos, V3(0, y + 0.1f, s * 0.08f), V3(s > 0 ? -0.3f : 0.3f, 0, 0), V3(0, 0.08f, 0), uvp(CHECK_X + 0.5f, CHECK_Y + 0.5f), uvp(CHECK_X + 15.5f, CHECK_Y + 0.5f), uvp(CHECK_X + 15.5f, CHECK_Y + 7.5f), uvp(CHECK_X + 0.5f, CHECK_Y + 7.5f), Col(1, 1, 1), -0.1f, L.night * 0.6f);
            }
        }
    }
    // свет фар и фонарей ночью
    if (L.night > 0.2f && dist < 260) {
        float k = L.night;
        for (int s = -1; s <= 1; s += 2) {
            if (d.headOn && M.headL.y > 0) {
                V3 hp = mul(rot, V3(M.headL.x * s, M.headL.y, M.headL.z + 0.05f)) + d.pos;
                R3.billboard(hp, 0.45f, 0.45f, toSDL(Col(1, 0.95f, 0.8f) * (0.8f * k)), 0, 3, -0.3f);
            }
            if (M.tailL.y > 0 && (d.headOn || d.brake)) {
                V3 tp = mul(rot, V3(M.tailL.x * s, M.tailL.y, M.tailL.z - 0.05f)) + d.pos;
                float b = d.brake ? 0.9f : 0.45f;
                R3.billboard(tp, 0.35f, 0.35f, toSDL(Col(1, 0.1f, 0.05f) * (b * k)), 0, 3, -0.3f);
            }
        }
        if (d.headOn && dist < 120) {
            // пятно света на дороге
            V3 f = fwdOf(d.yaw), r = rightOf(d.yaw);
            V3 c = d.pos + f * (M.maxZ + 9.0f); c.y = 0.03f;
            R3.groundSprite(c, r * 4.0f, f * 9.5f, toSDL(Col(0.55f, 0.5f, 0.38f) * k), 1, 0);
        }
    }
}

static void loadAllModels() {
    int n = sizeof(CAR_MODELS_SRC) / sizeof(CAR_MODELS_SRC[0]);
    for (int i = 0; i < n; i++) loadEmbeddedModel(CAR_MODELS_SRC[i]);
    buildMinibus(); buildTruck(); buildTractor(); buildTrailer();
    buildWheelMesh();
    // диски по классу машины
    static const char* SPORT[] = {"СПОРТКАР", "СУПЕРКАР", "МОЩНЫЙ СЕДАН", "КУПЕ", "КУПЕ ГТ", "СПОРТКУПЕ", "РАЛЛИ-СЕДАН", "ТРЕКОВЫЙ СПОРТКАР", "ХОТ-ХЭТЧ", "РАЛЛИЙНАЯ", "ФАСТБЭК", "ЭЛЕКТРОСЕДАН"};
    static const char* SUV[] = {"ВНЕДОРОЖНИК", "СТАРЫЙ ДЖИП", "ПИКАП", "БОЛЬШОЙ ВНЕДОРОЖНИК", "КРОССОВЕР", "ПАРКЕТНИК"};
    static const char* TRUCK[] = {"МАРШРУТКА", "ГРУЗОВИК", "ФУРА", "ПОЛУПРИЦЕП"};
    for (CarModel& M : CM) {
        for (const char* n : SPORT) if (M.name == n) M.wheelStyle = WS_SPORT;
        for (const char* n : SUV) if (M.name == n) M.wheelStyle = WS_SUV;
        for (const char* n : TRUCK) if (M.name == n) M.wheelStyle = WS_TRUCK;
    }
}

// =====================================================================
//  Мир: дорожный граф, застройка, светофоры, пешеходы
// =====================================================================
struct Node {
    V3 p; std::vector<int> edges; bool light = false; float trim = 9; float phase = 0; bool city = true;
};
struct Edge {
    int a, b; int lanes; float laneW; float limitKmh; bool highway; float sidewalk;
    V3 dir; float len; float yaw; V3 pa, pb; float slen; float halfW;
    int district;
};
static std::vector<Node> NODES;
static std::vector<Edge> EDGES;

static const char* DISTRICT_NAMES[4] = {"ГОРОД", "ВОСТОЧНАЯ ТРАССА", "СЕВЕРНАЯ ТРАССА", "ЗАПАДНАЯ ТРАССА"};
static const int DISTRICT_RANK[4] = {0, 1, 3, 5};
static int districtAt(const V3& p) {
    if (p.x > -60 && p.x < 390 && p.z > -60 && p.z < 390) return 0;
    if (p.z >= 700) return 2;
    if (p.x >= 390) return 1;
    return 3;
}

static int addNode(float x, float z, bool city) { Node n; n.p = V3(x, 0, z); n.city = city; NODES.push_back(n); return (int)NODES.size() - 1; }
static int addEdge(int a, int b, int lanes, float limit, bool hw) {
    Edge e; e.a = a; e.b = b; e.lanes = lanes; e.laneW = 3.5f; e.limitKmh = limit; e.highway = hw; e.sidewalk = hw ? 0 : 3.5f;
    EDGES.push_back(e); int id = (int)EDGES.size() - 1;
    NODES[a].edges.push_back(id); NODES[b].edges.push_back(id);
    return id;
}
static inline float edgeHalfWidth(const Edge& e) { return e.lanes * e.laneW; }

static void finalizeRoads() {
    for (size_t i = 0; i < NODES.size(); i++) {
        Node& n = NODES[i];
        float mw = 0; for (int ei : n.edges) mw = std::max(mw, edgeHalfWidth(EDGES[ei]) + EDGES[ei].sidewalk);
        if (n.edges.size() == 2 && !n.city) n.trim = 45;
        else if (n.edges.size() == 2) n.trim = mw + 3;
        else n.trim = mw + 1.5f;
        n.light = n.edges.size() >= 3;
        n.phase = (float)(hash32((uint32_t)i * 31 + 7) % 32);
    }
    for (size_t i = 0; i < EDGES.size(); i++) {
        Edge& e = EDGES[i];
        V3 d = NODES[e.b].p - NODES[e.a].p; e.len = len(d); e.dir = d * (1 / e.len);
        e.yaw = atan2f(e.dir.x, e.dir.z);
        e.pa = NODES[e.a].p + e.dir * NODES[e.a].trim;
        e.pb = NODES[e.b].p - e.dir * NODES[e.b].trim;
        e.slen = e.len - NODES[e.a].trim - NODES[e.b].trim;
        e.halfW = edgeHalfWidth(e);
        e.district = districtAt((e.pa + e.pb) * 0.5f);
    }
}

static int CITY_N[4][4];
static void buildRoads() {
    for (int i = 0; i < 4; i++) for (int j = 0; j < 4; j++) CITY_N[i][j] = addNode(i * 110.f, j * 110.f, true);
    for (int i = 0; i < 4; i++) for (int j = 0; j < 4; j++) {
        if (i < 3) addEdge(CITY_N[i][j], CITY_N[i + 1][j], 1, 60, false);
        if (j < 3) addEdge(CITY_N[i][j], CITY_N[i][j + 1], 1, 60, false);
    }
    int HA = addNode(800, 110, false), HB = addNode(800, 1400, false), HC = addNode(-700, 1400, false);
    int HF = addNode(-700, 220, false), HD = addNode(-700, -900, false), HE = addNode(800, -900, false);
    addEdge(CITY_N[3][1], HA, 2, 70, true);
    addEdge(HF, CITY_N[0][2], 2, 70, true);
    addEdge(HA, HB, 2, 90, true); addEdge(HB, HC, 2, 90, true); addEdge(HC, HF, 2, 90, true);
    addEdge(HF, HD, 2, 90, true); addEdge(HD, HE, 2, 90, true); addEdge(HE, HA, 2, 90, true);
    finalizeRoads();
}

// --- полосы ---
// dir 0: a->b, 1: b->a. Полоса 0 — ближняя к осевой.
static inline void laneFrame(const Edge& e, int dir, V3& start, V3& fwd, V3& right, float& yaw) {
    if (dir == 0) { start = e.pa; fwd = e.dir; yaw = e.yaw; }
    else { start = e.pb; fwd = -e.dir; yaw = wrapAngle(e.yaw + PI); }
    right = rightOf(yaw);
}
static inline float laneOffset(const Edge& e, int lane) { return (lane + 0.5f) * e.laneW; }
static V3 lanePos(const Edge& e, int dir, int lane, float s, float lat) {
    V3 st, f, r; float y; laneFrame(e, dir, st, f, r, y);
    return st + f * s + r * (laneOffset(e, lane) + lat);
}
static inline int edgeEndNode(const Edge& e, int dir) { return dir == 0 ? e.b : e.a; }

// --- заправки (АЗС) у трасс ---
// Площадка: lx (поперёк дороги, наружу) от -hw до hw, lz (вдоль движения) от -hl до hl.
// Как на российских трассах: полоса торможения перед въездом, разделительный газон вдоль дороги,
// въезд и выезд на концах площадки, полоса разгона после выезда.
struct FuelStation { int edge = 0, dir = 0; float s = 0; V3 c, f, r; float yaw = 0; float hw = 14, hl = 32; uint32_t seed = 0; };
static const float FUEL_LANE = 75;       // длина полосы торможения/разгона (с отгоном 30 м)
static const float FUEL_THROAT = 12;     // ширина въезда/выезда вдоль дороги
static std::vector<FuelStation> FUELS;
static const float FUEL_PRICE = 57.9f;   // АИ-95, ₽/л
static inline void fuelLocal(const FuelStation& F, const V3& p, float& lx, float& lz) { V3 d = p - F.c; lx = d.x * F.r.x + d.z * F.r.z; lz = d.x * F.f.x + d.z * F.f.z; }
// вся зона заправки вместе с полосами торможения/разгона
static int fuelZone(const V3& p, float margin) {
    for (size_t i = 0; i < FUELS.size(); i++) {
        float lx, lz; fuelLocal(FUELS[i], p, lx, lz);
        if (lx > -FUELS[i].hw - 3.5f - margin && lx < FUELS[i].hw + margin && fabsf(lz) < FUELS[i].hl + FUEL_LANE + margin) return (int)i;
    }
    return -1;
}
// на полосе торможения/разгона (вдоль трассы)?
static bool fuelLaneAt(const V3& p) {
    for (const FuelStation& F : FUELS) {
        float lx, lz; fuelLocal(F, p, lx, lz);
        if (lx > -F.hw - 3.2f && lx < -F.hw + 0.6f && fabsf(lz) < F.hl + FUEL_LANE) return true;
    }
    return false;
}
// p в площадке заправки? (lx — поперёк дороги наружу, lz — вдоль движения)
static int fuelAt(const V3& p, float margin = 0, float* lxOut = nullptr, float* lzOut = nullptr) {
    for (size_t i = 0; i < FUELS.size(); i++) {
        const FuelStation& F = FUELS[i]; V3 d = p - F.c;
        float lx = d.x * F.r.x + d.z * F.r.z, lz = d.x * F.f.x + d.z * F.f.z;
        if (fabsf(lx) < F.hw + margin && fabsf(lz) < F.hl + margin) { if (lxOut) *lxOut = lx; if (lzOut) *lzOut = lz; return (int)i; }
    }
    return -1;
}

// светофор: ось 0 — дорога вдоль X, 1 — вдоль Z
static float gWorldTime = 0;
static int lightAxisOf(const Edge& e) { return fabsf(e.dir.x) > fabsf(e.dir.z) ? 0 : 1; }
static const float LIGHT_T = 32.0f;
static int lightState(int node, int axis) {   // 0 зелёный, 1 жёлтый, 2 красный
    const Node& n = NODES[node];
    if (!n.light) return 0;
    float t = fmodf(gWorldTime + n.phase, LIGHT_T);
    if (axis == 0) { if (t < 11) return 0; if (t < 13) return 1; return 2; }
    if (t >= 16 && t < 27) return 0;
    if (t >= 27 && t < 29) return 1;
    return 2;
}
static float lightRemaining(int node, int axis) {
    float t = fmodf(gWorldTime + NODES[node].phase, LIGHT_T);
    if (axis == 0) return t < 13 ? 13 - t : LIGHT_T - t;
    return (t >= 16 && t < 29) ? 29 - t : (t < 16 ? 16 - t : LIGHT_T - t + 16);
}

// ближайшая точка дороги к позиции
struct RoadHit { int edge; float s; float lat; float dist; bool onNode; int node; };
static RoadHit nearestRoad(const V3& p) {
    RoadHit best; best.edge = -1; best.dist = 1e9f; best.onNode = false; best.node = -1; best.s = 0; best.lat = 0;
    for (size_t i = 0; i < EDGES.size(); i++) {
        const Edge& e = EDGES[i];
        V3 d = p - e.pa; float s = dot(d, e.dir);
        float sc = clampf(s, 0, e.slen);
        V3 q = e.pa + e.dir * sc;
        float lat = dot(p - q, rightOf(e.yaw));
        float dd = dist2d(p, q);
        if (dd < best.dist) { best.dist = dd; best.edge = (int)i; best.s = sc; best.lat = lat; }
    }
    for (size_t i = 0; i < NODES.size(); i++) {
        float dd = dist2d(p, NODES[i].p);
        if (dd < NODES[i].trim && dd - NODES[i].trim * 0.6f < best.dist) { best.onNode = true; best.node = (int)i; }
    }
    return best;
}
// стационарные посты ДПС на трассах: навес над дорогой, здание со «стаканом», шлагбаумы в обе стороны
struct StatPost { int edge = 0; float s = 0; V3 c, f, r; float yaw = 0; int district = 0; bool closed = false; float arm = 0; float closedT = 0; };
static std::vector<StatPost> SPOSTS;
static const float SP_BAR = 9.0f;   // шлагбаум — за 9 м до середины навеса по ходу движения
static inline void spLocal(const StatPost& P, const V3& p, float& lx, float& lz) { V3 d = p - P.c; lx = d.x * P.r.x + d.z * P.r.z; lz = d.x * P.f.x + d.z * P.f.z; }
// расстояние (по ходу движения) от машины на участке до шлагбаума поста; <0 — уже проехала
static float spDistToBarrier(const StatPost& P, int dir, float s) {
    float sp = dir == 0 ? P.s : EDGES[P.edge].slen - P.s;
    return sp - SP_BAR - s;
}
static bool onRoadSurface(const V3& p, float* limitKmh) {
    if (fuelAt(p, 0.5f) >= 0) { if (limitKmh) *limitKmh = 20; return true; }
    if (fuelLaneAt(p)) { if (limitKmh) *limitKmh = 60; return true; }
    for (const StatPost& P : SPOSTS) {
        float lx, lz; spLocal(P, p, lx, lz);
        if (lx > -11 && lx < 18 && fabsf(lz) < 45) { if (limitKmh) *limitKmh = 40; return true; }   // пост и карман досмотра
    }
    RoadHit h = nearestRoad(p);
    if (h.onNode) {
        const Node& n = NODES[h.node];
        if (dist2d(p, n.p) < n.trim + 2) {
            if (limitKmh) { *limitKmh = n.city ? 60.f : 90.f; if (!n.city) for (int ei : n.edges) *limitKmh = std::min(*limitKmh, EDGES[ei].limitKmh); }
            if (!n.city && n.edges.size() == 2) {
                // поворот трассы: проверяем дугу
                return true;
            }
            return true;
        }
    }
    if (h.edge >= 0) {
        const Edge& e = EDGES[h.edge];
        if (limitKmh) *limitKmh = e.limitKmh;
        return h.dist < e.halfW + (e.highway ? 2.5f : 0.5f);
    }
    return false;
}

// ---------------------------------------------------------------------
//  Статические объекты
// ---------------------------------------------------------------------
enum ObjType { OB_BUILDING, OB_TREE, OB_LAMP, OB_SIGN, OB_BILLBOARD, OB_POST, OB_BUSH, OB_FENCE, OB_TLIGHT, OB_CAMERA, OB_BENCH, OB_KIOSK, OB_BLOCK, OB_FUEL, OB_FBOX, OB_FPOLE, OB_FSIGN, OB_SPOST, OB_NONE };
struct SObj {
    int type; V3 p; V3 h; float yaw; Col col; Col col2; int floors; uint32_t seed; float radius;
    int ival; std::string text; bool collide;
};
static std::vector<SObj> OBJS;
static const float GRID_X0 = -900, GRID_Z0 = -1100, GRID_CS = 60;
static const int GRID_NX = 46, GRID_NZ = 48;
static std::vector<int> GRID[GRID_NX * GRID_NZ];
static inline int gridIdx(float x, float z) {
    int gx = (int)((x - GRID_X0) / GRID_CS), gz = (int)((z - GRID_Z0) / GRID_CS);
    if (gx < 0 || gz < 0 || gx >= GRID_NX || gz >= GRID_NZ) return -1;
    return gz * GRID_NX + gx;
}
static void addObj(const SObj& o) {
    OBJS.push_back(o); int id = (int)OBJS.size() - 1;
    // в каждую ячейку, которую покрывает объект
    float r = o.radius;
    for (float x = o.p.x - r; x <= o.p.x + r + GRID_CS * 0.99f; x += GRID_CS) for (float z = o.p.z - r; z <= o.p.z + r + GRID_CS * 0.99f; z += GRID_CS) {
        int g = gridIdx(std::min(x, o.p.x + r), std::min(z, o.p.z + r));
        if (g >= 0 && (GRID[g].empty() || GRID[g].back() != id)) GRID[g].push_back(id);
    }
}
static bool pointNearRoad(const V3& p, float margin) {
    for (const Edge& e : EDGES) {
        float s = dot(p - e.pa, e.dir); float sc = clampf(s, -NODES[e.a].trim, e.slen + NODES[e.b].trim);
        V3 q = e.pa + e.dir * sc;
        if (dist2d(p, q) < e.halfW + e.sidewalk + margin) return true;
    }
    for (const Node& n : NODES) if (dist2d(p, n.p) < n.trim + margin + (n.city ? 0 : 20)) return true;
    return false;
}

struct Post { int edge, dir; float s; V3 pos; float yaw; int district; };
static Post POSTS[4];
struct Billboard { const char* text; };
static const char* BILLBOARD_TEXTS[] = {"ПРИСТЕГНИСЬ!", "НЕ ГОНИ!", "СОБЛЮДАЙ ДИСТАНЦИЮ", "ПЕШЕХОД ВСЕГДА ПРАВ", "ВЕДЁТСЯ ФОТОФИКСАЦИЯ", "ГИБДД: ТЕЛ. 112", "СКОРОСТЬ УБИВАЕТ"};

static void buildFuelStations(Rng& r) {
    FUELS.clear();
    int k = 0;
    for (size_t ei = 0; ei < EDGES.size() && FUELS.size() < 7; ei++) {
        const Edge& e = EDGES[ei];
        if (!e.highway || e.slen < 600) continue;
        FuelStation F; F.edge = (int)ei; F.dir = k & 1; k++;
        V3 st; laneFrame(e, F.dir, st, F.f, F.r, F.yaw);
        bool ok = false;
        for (float fr : {0.45f, 0.7f, 0.25f}) {
            F.s = e.slen * fr;
            F.c = st + F.f * F.s + F.r * (e.halfW + 3.0f + F.hw);
            bool bad = false;
            for (int q = 0; q < 4; q++) if (dist2d(F.c, POSTS[q].pos) < 200) bad = true;
            for (const FuelStation& G : FUELS) if (dist2d(F.c, G.c) < 450) bad = true;
            if (F.s < F.hl + FUEL_LANE + 40 || F.s > e.slen - F.hl - FUEL_LANE - 40) bad = true;
            if (!bad) { ok = true; break; }
        }
        if (!ok) continue;
        F.seed = r.next();
        FUELS.push_back(F);
        // убрать деревья, щиты и прочее с площадки
        for (SObj& o : OBJS) {
            V3 d = o.p - F.c; float lx = dot(d, F.r), lz = dot(d, F.f);
            if (lx > -F.hw - 3.5f && lx < F.hw + 9 && fabsf(lz) < F.hl + 9) { o.type = OB_NONE; o.collide = false; }
            if (lx > -F.hw - 3.5f && lx < -F.hw + 6 && fabsf(lz) < F.hl + FUEL_LANE + 5) { o.type = OB_NONE; o.collide = false; }   // полосы
        }
        int id = (int)FUELS.size() - 1;
        auto P = [&](float lx, float lz) { return F.c + F.r * lx + F.f * lz; };
        SObj o; o.type = OB_FUEL; o.p = F.c; o.yaw = F.yaw; o.h = V3(F.hw, 6, F.hl); o.radius = F.hl + 6; o.collide = false;
        o.col = Col(1, 1, 1); o.seed = F.seed; o.floors = 0; o.ival = id; addObj(o);
        auto box = [&](V3 p, float hx, float hz, float yaw) { SObj b; b.type = OB_FBOX; b.p = p; b.yaw = yaw; b.h = V3(hx, 1, hz); b.radius = std::max(hx, hz) + 1; b.collide = true; b.seed = 0; b.floors = 0; b.ival = id; addObj(b); };
        auto pole = [&](V3 p, float rad) { SObj b; b.type = OB_FPOLE; b.p = p; b.yaw = 0; b.h = V3(rad, 1, rad); b.radius = rad + 1; b.collide = true; b.seed = 0; b.floors = 0; b.ival = id; addObj(b); };
        box(P(9.5f, 0), 2.6f, 7.0f, F.yaw);                    // магазин
        box(P(-1.0f, 0), 0.7f, 5.2f, F.yaw);                   // островок с колонками
        for (int sx = -1; sx <= 1; sx += 2) for (int sz = -1; sz <= 1; sz += 2) pole(P(-1.0f + sx * 5.2f, sz * 7.5f), 0.3f);   // опоры навеса
        pole(P(-F.hw + 2.0f, -F.hl + FUEL_THROAT + 5), 0.7f);  // стела с ценами (на газоне у въезда)
        box(P(-F.hw + 2.0f, 0), 1.5f, F.hl - FUEL_THROAT, F.yaw);   // разделительный газон с бордюром
        // дорожные знаки 7.3 «АЗС»: за 500 и 150 м и у начала полосы торможения
        for (int k = 0; k < 3; k++) {
            static const float dz[3] = {500, 150, 0}; static const int lab[3] = {500, 150, 0};
            if (F.s - F.hl - FUEL_LANE - dz[k] < 40) continue;   // знак не дальше начала участка трассы
            SObj g; g.type = OB_FSIGN; g.p = P(-F.hw + 1.0f, -F.hl - FUEL_LANE - dz[k]); g.yaw = F.yaw; g.h = V3(0, 3, 0); g.radius = 2; g.collide = true;
            g.seed = 0; g.floors = lab[k]; g.ival = id; addObj(g);
        }
        // машины у колонок (декорация)
        if (F.seed & 1) box(P(2.6f, (F.seed & 2) ? 2.8f : -2.8f), 0.95f, 2.3f, F.yaw);
        if (F.seed & 4) box(P(9.5f - 5.2f, F.seed & 8 ? 12.0f : -12.0f), 0.95f, 2.3f, F.yaw);
    }
}

static void buildScenery() {
    Rng r(777);
    // городские кварталы
    static const Col facades[] = {hexc(0xd8d2c4), hexc(0xb8b8b4), hexc(0xc9876a), hexc(0xe6dcc0), hexc(0xa9c0d0), hexc(0xd0b090), hexc(0xe8e8e8), hexc(0x9aa59a)};
    for (int i = 0; i < 3; i++) for (int j = 0; j < 3; j++) {
        float x0 = i * 110 + 12, x1 = (i + 1) * 110 - 12, z0 = j * 110 + 12, z1 = (j + 1) * 110 - 12;
        bool park = (i == 1 && j == 1);
        if (park) {
            for (int k = 0; k < 26; k++) {
                SObj t; t.type = OB_TREE; t.p = V3(r.range(x0 + 3, x1 - 3), 0, r.range(z0 + 3, z1 - 3)); t.h = V3(0, r.range(5, 9), 0);
                t.col = Col(0.2f + r.f() * 0.1f, 0.45f + r.f() * 0.15f, 0.18f); t.radius = 3; t.seed = r.next(); t.collide = true; t.yaw = 0; t.floors = 0; t.ival = 0;
                addObj(t);
            }
            for (int k = 0; k < 6; k++) {
                SObj b; b.type = OB_BENCH; b.p = V3(x0 + 8 + k * 13, 0, (z0 + z1) * 0.5f + ((k & 1) ? 4 : -4)); b.h = V3(0.9f, 0.45f, 0.25f); b.yaw = 0; b.col = Col(0.5f, 0.32f, 0.18f);
                b.radius = 1; b.collide = true; b.seed = 0; b.floors = 0; b.ival = 0; addObj(b);
            }
            continue;
        }
        // 2-4 здания по периметру квартала
        int layout = r.i(3);
        std::vector<std::pair<V3, V3>> boxes;
        float mx = (x0 + x1) * 0.5f, mz = (z0 + z1) * 0.5f;
        if (layout == 0) {
            boxes.push_back({V3(mx - 21, 0, mz - 21), V3(18, 0, 18)}); boxes.push_back({V3(mx + 21, 0, mz - 21), V3(18, 0, 18)});
            boxes.push_back({V3(mx - 21, 0, mz + 21), V3(18, 0, 18)}); boxes.push_back({V3(mx + 21, 0, mz + 21), V3(18, 0, 18)});
        } else if (layout == 1) {
            boxes.push_back({V3(mx, 0, mz - 24), V3(38, 0, 12)}); boxes.push_back({V3(mx, 0, mz + 24), V3(38, 0, 12)});
        } else {
            boxes.push_back({V3(mx - 24, 0, mz), V3(12, 0, 38)}); boxes.push_back({V3(mx + 22, 0, mz - 18), V3(14, 0, 18)}); boxes.push_back({V3(mx + 22, 0, mz + 24), V3(14, 0, 11)});
        }
        for (auto& bx : boxes) {
            SObj b; b.type = OB_BUILDING; b.p = bx.first; b.yaw = 0;
            b.floors = 3 + r.i(i == 2 && j == 0 ? 14 : 9);
            if (r.chance(0.2f)) b.floors = 2 + r.i(3);
            b.h = V3(bx.second.x, b.floors * 3.2f, bx.second.z);
            b.col = facades[r.i(8)]; b.col2 = Col(0.35f, 0.33f, 0.32f); b.seed = r.next(); b.radius = sqrtf(b.h.x * b.h.x + b.h.z * b.h.z);
            b.collide = true; b.ival = r.chance(0.35f) ? 1 : 0;   // 1 — витрины на первом этаже
            addObj(b);
        }
        // деревья во дворах
        for (int k = 0; k < 4; k++) {
            SObj t; t.type = OB_TREE; t.p = V3(mx + r.range(-6, 6), 0, mz + r.range(-6, 6)); t.h = V3(0, r.range(5, 8), 0);
            t.col = Col(0.22f, 0.5f, 0.2f); t.radius = 3; t.seed = r.next(); t.collide = true; t.yaw = 0; t.floors = 0; t.ival = 0;
            if (layout != 0) addObj(t);
        }
    }
    // фонари и деревья вдоль городских улиц, ларьки
    for (size_t ei = 0; ei < EDGES.size(); ei++) {
        const Edge& e = EDGES[ei];
        V3 rr = rightOf(e.yaw);
        if (!e.highway) {
            for (float s = 10; s < e.slen - 5; s += 25) {
                for (int side = -1; side <= 1; side += 2) {
                    SObj l; l.type = OB_LAMP; l.p = e.pa + e.dir * s + rr * (side * (e.halfW + e.sidewalk - 0.4f)); l.yaw = e.yaw + (side > 0 ? -PI / 2 : PI / 2);
                    l.h = V3(0, 7, 0); l.radius = 1.5f; l.collide = true; l.col = Col(0.3f, 0.3f, 0.32f); l.seed = 0; l.floors = 0; l.ival = side;
                    if (((int)(s / 25) + side) % 2 == 0) addObj(l);
                }
            }
            if (r.chance(0.3f)) {
                SObj k; k.type = OB_KIOSK; float s = e.slen * r.range(0.3f, 0.7f); int side = r.chance(0.5f) ? 1 : -1;
                k.p = e.pa + e.dir * s + rr * (side * (e.halfW + e.sidewalk + 3.0f)); k.yaw = e.yaw + (side > 0 ? -PI / 2 : PI / 2);
                k.h = V3(1.8f, 2.6f, 1.4f); k.col = r.chance(0.5f) ? hexc(0x3070b0) : hexc(0x40a050); k.radius = 2.5f; k.collide = true; k.seed = r.next(); k.floors = 0; k.ival = 0;
                if (!pointNearRoad(k.p, 0.5f)) addObj(k);
            }
        } else {
            // отбойник с обеих сторон, деревья и поля дальше
            for (float s = 0; s < e.slen; s += 9) {
                for (int side = -1; side <= 1; side += 2) {
                    int n = r.i(3);
                    for (int k = 0; k < n; k++) {
                        float off = e.halfW + r.range(14, 80);
                        V3 p = e.pa + e.dir * (s + r.range(0, 9)) + rr * (side * off);
                        if (pointNearRoad(p, 7)) continue;
                        if (districtAt(p) == 0) continue;
                        SObj t; t.type = r.chance(0.25f) ? OB_BUSH : OB_TREE; t.p = p;
                        bool pine = (hash32((uint32_t)(p.x * 0.01f) * 13 + (uint32_t)(p.z * 0.01f + 50) * 7) % 3) == 0;
                        t.h = V3(0, t.type == OB_BUSH ? r.range(1, 2) : r.range(6, 13), 0);
                        t.col = pine ? Col(0.12f, 0.32f, 0.16f) : Col(0.25f + r.f() * 0.12f, 0.45f + r.f() * 0.15f, 0.15f);
                        t.ival = pine ? 1 : 0; t.radius = 3; t.seed = r.next(); t.collide = t.type == OB_TREE; t.yaw = 0; t.floors = 0;
                        addObj(t);
                    }
                }
            }
            for (float s = 120; s < e.slen - 100; s += 450 + r.range(0, 300)) {
                int side = r.chance(0.5f) ? 1 : -1;
                SObj b; b.type = OB_BILLBOARD; b.p = e.pa + e.dir * s + rr * (side * (e.halfW + 12)); b.yaw = e.yaw + (side > 0 ? PI : 0) * 0 + PI * (side > 0 ? 1.f : 0.f);
                b.yaw = (side > 0) ? wrapAngle(e.yaw + PI) : e.yaw;   // щит смотрит навстречу движению по ближней стороне
                b.h = V3(5, 7, 0.3f); b.text = BILLBOARD_TEXTS[r.i(7)]; b.col = r.chance(0.5f) ? hexc(0x1d4fa0) : hexc(0xc03028); b.radius = 6; b.collide = true; b.seed = r.next(); b.floors = 0; b.ival = 0;
                addObj(b);
            }
        }
        // знаки ограничения скорости в начале участка (для обоих направлений)
        for (int dir = 0; dir < 2; dir++) {
            V3 st, f, rgt; float y; laneFrame(e, dir, st, f, rgt, y);
            SObj sg; sg.type = OB_SIGN; sg.p = st + f * 15 + rgt * (e.halfW + (e.highway ? 3.0f : e.sidewalk - 0.6f)); sg.yaw = wrapAngle(y + PI);
            sg.h = V3(0, 2.6f, 0); sg.ival = (int)e.limitKmh; sg.radius = 1; sg.collide = true; sg.col = Col(1, 1, 1); sg.seed = 0; sg.floors = 0;
            addObj(sg);
        }
    }
    // светофоры на узлах
    for (size_t ni = 0; ni < NODES.size(); ni++) {
        const Node& n = NODES[ni];
        if (!n.light) continue;
        for (int ei : n.edges) {
            const Edge& e = EDGES[ei];
            int dir = (e.b == (int)ni) ? 0 : 1;   // направление, подходящее к узлу
            V3 st, f, rgt; float y; laneFrame(e, dir, st, f, rgt, y);
            V3 end = (dir == 0) ? e.pb : e.pa;
            SObj t; t.type = OB_TLIGHT; t.p = end + rgt * (e.halfW + 1.2f) + f * 1.0f; t.yaw = wrapAngle(y + PI);
            t.h = V3(0, 4.2f, 0); t.ival = (int)ni; t.floors = lightAxisOf(e); t.radius = 1; t.collide = true; t.col = Col(0.2f, 0.2f, 0.2f); t.seed = (uint32_t)e.lanes;
            addObj(t);
        }
    }
    // посты ДПС
    struct PD { int a, b; float s; };
    int ne = (int)EDGES.size();
    auto findEdge = [&](int na, int nb) { for (int i = 0; i < ne; i++) if ((EDGES[i].a == na && EDGES[i].b == nb) || (EDGES[i].a == nb && EDGES[i].b == na)) return i; return 0; };
    int city = findEdge(CITY_N[2][1], CITY_N[3][1]);
    int east = 0, north = 0, west = 0;
    for (int i = 0; i < ne; i++) {
        const Edge& e = EDGES[i];
        if (e.highway && fabsf(e.dir.z) > 0.9f && NODES[e.a].p.x > 700 && e.slen > 1000) east = i;
        if (e.highway && fabsf(e.dir.x) > 0.9f && NODES[e.a].p.z > 1300) north = i;
        if (e.highway && fabsf(e.dir.z) > 0.9f && NODES[e.a].p.x < -650 && NODES[e.a].p.z > 200 && NODES[e.b].p.z < 0) west = i;
    }
    int pe[4] = {city, east, north, west}; float ps[4] = {40, 420, 700, 500};
    for (int k = 0; k < 4; k++) {
        Post& P = POSTS[k]; P.edge = pe[k]; P.dir = 0; P.s = std::min(ps[k], EDGES[pe[k]].slen - 30);
        const Edge& e = EDGES[P.edge];
        V3 st, f, rgt; float y; laneFrame(e, P.dir, st, f, rgt, y);
        P.pos = st + f * P.s + rgt * (e.halfW + (e.highway ? 1.9f : 1.6f)); P.yaw = y; P.district = k;
        SObj o; o.type = OB_POST; o.p = st + f * (P.s + 10) + rgt * (e.halfW + (e.highway ? 10.5f : e.sidewalk + 3.5f)); o.yaw = wrapAngle(y - PI / 2);
        o.h = V3(2.2f, 3.0f, 2.0f); o.radius = 4; o.collide = true; o.col = Col(0.95f, 0.95f, 0.95f); o.seed = 0; o.floors = 0; o.ival = k;
        addObj(o);
    }
    // стационарные посты на трассах (вместо будок)
    SPOSTS.clear();
    for (int k = 1; k < 4; k++) {
        StatPost S; S.edge = POSTS[k].edge; S.s = POSTS[k].s; S.district = k;
        const Edge& e = EDGES[S.edge];
        S.f = e.dir; S.r = rightOf(e.yaw); S.yaw = e.yaw; S.c = e.pa + e.dir * S.s;
        SPOSTS.push_back(S);
        int id = (int)SPOSTS.size() - 1;
        // патрульная машина встаёт в карман досмотра за навесом, лицом к подъезжающим машинам
        POSTS[k].pos = S.c + S.r * 13.6f + S.f * 13.5f; POSTS[k].yaw = wrapAngle(e.yaw + PI);
        for (SObj& o : OBJS) {
            float lx, lz; spLocal(S, o.p, lx, lz);
            if ((o.type == OB_POST && o.ival == k) || (lx > -16 && lx < 34 && fabsf(lz) < 50 && o.type != OB_SIGN)) { o.type = OB_NONE; o.collide = false; }
        }
        auto P = [&](float lx, float lz) { return S.c + S.r * lx + S.f * lz; };
        SObj o; o.type = OB_SPOST; o.p = S.c; o.yaw = S.yaw; o.h = V3(30, 10, 45); o.radius = 50; o.collide = false; o.seed = 0; o.floors = 0; o.ival = id; addObj(o);
        auto box = [&](V3 p, float hx, float hz) { SObj b; b.type = OB_FBOX; b.p = p; b.yaw = S.yaw; b.h = V3(hx, 1, hz); b.radius = std::max(hx, hz) + 1; b.collide = true; b.seed = 0; b.floors = 0; b.ival = 0; addObj(b); };
        auto pole = [&](V3 p, float rad) { SObj b; b.type = OB_FPOLE; b.p = p; b.yaw = 0; b.h = V3(rad, 1, rad); b.radius = rad + 1; b.collide = true; b.seed = 0; b.floors = 0; b.ival = 0; addObj(b); };
        box(P(23, 0), 4.6f, 7.2f);                                            // здание
        for (int sx = -1; sx <= 1; sx += 2) for (int sz = -1; sz <= 1; sz += 2) pole(P(sx * 11.9f, sz * 4.0f), 0.35f);   // опоры навеса
        pole(P(8.4f, -SP_BAR), 0.3f); pole(P(-8.4f, SP_BAR), 0.3f);         // тумбы шлагбаумов
        // знаки в обе стороны: 70, 40, «Контроль», после поста — снова ограничение участка
        for (int dir = 0; dir < 2; dir++) {
            V3 st, f, rg; float y; laneFrame(e, dir, st, f, rg, y);
            float sp = dir == 0 ? S.s : e.slen - S.s;
            struct SG { float ds; int v; } sg[4] = {{-260, 70}, {-140, 40}, {-SP_BAR - 14, -1}, {70, (int)e.limitKmh}};
            for (const SG& g : sg) {
                float ss = sp + g.ds; if (ss < 20 || ss > e.slen - 20) continue;
                SObj z; z.type = OB_SIGN; z.p = st + f * ss + rg * (e.halfW + 3.0f); z.yaw = wrapAngle(y + PI);
                z.h = V3(0, 2.6f, 0); z.ival = g.v; z.radius = 1; z.collide = true; z.col = Col(1, 1, 1); z.seed = 0; z.floors = 0; addObj(z);
            }
        }
    }
    buildFuelStations(r);
}

// ---------------------------------------------------------------------
//  Отрисовка мира
// ---------------------------------------------------------------------
static inline SDL_Color fogged(const Col& c, float d) { return toSDL(lerpc(c, L.fog, fogFactor(d))); }
static inline SDL_Color foggedV(const Col& c, const V3& w) { return fogged(c, dist2d(w, R3.pos)); }

static void drawGround() {
    // дальняя плоскость цвета тумана — горизонт
    V3 c = R3.pos; c.y = 0;
    float F = 3000;
    Col far = L.fog;
    R3.quadW(c + V3(-F, -0.05f, -F), c + V3(F, -0.05f, -F), c + V3(F, -0.05f, F), c + V3(-F, -0.05f, F), toSDL(far), 0);
    // клетки травы/полей
    float cs = 40; int n = (int)(std::min(L.fogEnd, 360.f) / cs) + 1;
    int cx = (int)floorf(c.x / cs), cz = (int)floorf(c.z / cs);
    for (int dz = -n; dz <= n; dz++) for (int dx = -n; dx <= n; dx++) {
        float x0 = (cx + dx) * cs, z0 = (cz + dz) * cs;
        V3 cc(x0 + cs * 0.5f, 0, z0 + cs * 0.5f);
        if (!R3.sphereVisible(cc, cs * 0.75f)) continue;
        uint32_t h = hash32((uint32_t)(cx + dx + 1000) * 7919u + (uint32_t)(cz + dz + 1000) * 104729u);
        Col g;
        bool cityArea = (cc.x > -40 && cc.x < 370 && cc.z > -40 && cc.z < 370);
        if (cityArea) g = Col(0.42f, 0.44f, 0.4f);
        else {
            // поля крупными участками
            uint32_t fh = hash32((uint32_t)((int)floorf(cc.x / 160) + 500) * 31u + (uint32_t)((int)floorf(cc.z / 160) + 500) * 977u);
            int kind = fh % 5;
            if (kind == 0) g = Col(0.62f, 0.58f, 0.3f);
            else if (kind == 1) g = Col(0.42f, 0.52f, 0.25f);
            else g = Col(0.30f, 0.46f, 0.22f);
            float v = ((h & 255) / 255.f - 0.5f) * 0.05f;
            g = g + Col(v, v, v * 0.5f);
            if (L.rain > 0) g = g * (1 - 0.15f * L.rain);
        }
        Col lit = mulc(g, L.amb + L.sunCol * (L.sun.y * (1 - L.night * 0.85f)));
        V3 p0(x0, 0, z0), p1(x0 + cs, 0, z0), p2(x0 + cs, 0, z0 + cs), p3(x0, 0, z0 + cs);
        R3.quadWC(p0, p1, p2, p3, foggedV(lit, p0), foggedV(lit, p1), foggedV(lit, p2), foggedV(lit, p3), 0);
    }
}

static Col litFlat(const Col& c) { return mulc(c, L.amb + L.sunCol * (L.sun.y * (1 - L.night * 0.85f))); }

static void flatQuad(const V3& a, const V3& b, const V3& c, const V3& d, const Col& col) {
    Col l = litFlat(col);
    R3.quadWC(a, b, c, d, foggedV(l, a), foggedV(l, b), foggedV(l, c), foggedV(l, d), 0);
}

static void drawRoads() {
    Col asph = L.rain > 0.3f ? Col(0.2f, 0.2f, 0.22f) : Col(0.27f, 0.27f, 0.29f);
    Col walk = Col(0.6f, 0.6f, 0.58f), curb = Col(0.75f, 0.75f, 0.72f), white = Col(0.92f, 0.92f, 0.9f), shoulder = Col(0.38f, 0.36f, 0.33f);
    float maxD = L.fogEnd + 40;
    V3 cam = R3.pos;
    // 1) покрытие участков
    for (size_t ei = 0; ei < EDGES.size(); ei++) {
        const Edge& e = EDGES[ei];
        V3 rr = rightOf(e.yaw);
        float seg = 30;
        int ns = (int)ceilf(e.slen / seg);
        for (int k = 0; k < ns; k++) {
            float s0 = k * seg, s1 = std::min(e.slen, (k + 1) * seg);
            V3 c = e.pa + e.dir * ((s0 + s1) * 0.5f);
            if (dist2d(c, cam) > maxD + seg) continue;
            if (!R3.sphereVisible(c, seg * 0.6f + e.halfW + 6)) continue;
            V3 a = e.pa + e.dir * s0, b = e.pa + e.dir * s1;
            float w = e.halfW;
            V3 y1(0, 0.01f, 0);
            if (e.highway) {
                flatQuad(a - rr * (w + 3) + y1, b - rr * (w + 3) + y1, b + rr * (w + 3) + y1, a + rr * (w + 3) + y1, shoulder);
                flatQuad(a - rr * w + y1 * 2, b - rr * w + y1 * 2, b + rr * w + y1 * 2, a + rr * w + y1 * 2, asph);
            } else {
                flatQuad(a - rr * (w + e.sidewalk) + y1, b - rr * (w + e.sidewalk) + y1, b + rr * (w + e.sidewalk) + y1, a + rr * (w + e.sidewalk) + y1, walk);
                flatQuad(a - rr * (w + 0.2f) + y1 * 2, b - rr * (w + 0.2f) + y1 * 2, b + rr * (w + 0.2f) + y1 * 2, a + rr * (w + 0.2f) + y1 * 2, curb);
                flatQuad(a - rr * w + y1 * 3, b - rr * w + y1 * 3, b + rr * w + y1 * 3, a + rr * w + y1 * 3, asph);
            }
        }
    }
    // 1а) карман досмотра и площадка у стационарного поста
    for (const StatPost& S : SPOSTS) {
        if (dist2d(S.c, cam) > maxD + 60) continue;
        if (!R3.sphereVisible(S.c + S.r * 15, 60)) continue;
        auto Q = [&](float lx, float lz, float y) { return S.c + S.r * lx + S.f * lz + V3(0, y, 0); };
        for (int k = 0; k < 4; k++) {
            float z0 = -45 + k * 22.5f, z1 = z0 + 22.5f;
            flatQuad(Q(10.0f, z0, 0.025f), Q(10.0f, z1, 0.025f), Q(17.5f, z1, 0.025f), Q(17.5f, z0, 0.025f), asph);
        }
        flatQuad(Q(17.5f, -12, 0.025f), Q(17.5f, 12, 0.025f), Q(29.0f, 12, 0.025f), Q(29.0f, -12, 0.025f), Col(0.55f, 0.55f, 0.53f));
        flatQuad(Q(-17.0f, -12, 0.025f), Q(-17.0f, 12, 0.025f), Q(-10.0f, 12, 0.025f), Q(-10.0f, -12, 0.025f), asph);
        // разметка места досмотра
        if (dist2d(S.c, cam) < 200) for (int k = -4; k <= 1; k++) {
            float z = k * 9.0f;
            flatQuad(Q(10.3f, z - 0.08f, 0.04f), Q(10.3f, z + 0.08f, 0.04f), Q(17.2f, z + 0.08f, 0.04f), Q(17.2f, z - 0.08f, 0.04f), white);
        }
        // стоп-линии у шлагбаумов
        if (dist2d(S.c, cam) < 220) {
            flatQuad(Q(0.2f, -SP_BAR - 2.6f, 0.05f), Q(0.2f, -SP_BAR - 2.2f, 0.05f), Q(7.0f, -SP_BAR - 2.2f, 0.05f), Q(7.0f, -SP_BAR - 2.6f, 0.05f), white);
            flatQuad(Q(-7.0f, SP_BAR + 2.2f, 0.05f), Q(-7.0f, SP_BAR + 2.6f, 0.05f), Q(-0.2f, SP_BAR + 2.6f, 0.05f), Q(-0.2f, SP_BAR + 2.2f, 0.05f), white);
        }
    }
    // 1б) площадки заправок, полосы торможения/разгона, разметка
    for (const FuelStation& F : FUELS) {
        if (dist2d(F.c, cam) > maxD + F.hl + FUEL_LANE) continue;
        if (!R3.sphereVisible(F.c, F.hl + FUEL_LANE + 4)) continue;
        Col conc(0.5f, 0.5f, 0.49f), line(0.88f, 0.88f, 0.84f);
        float y1 = 0.025f, y2 = 0.04f;
        auto Q = [&](float lx, float lz, float y) { return F.c + F.r * lx + F.f * lz + V3(0, y, 0); };
        auto rect = [&](float x0, float x1, float z0, float z1, float y, const Col& c, int nz) {
            for (int k = 0; k < nz; k++) { float a = z0 + (z1 - z0) * k / nz, b = z0 + (z1 - z0) * (k + 1) / nz; flatQuad(Q(x0, a, y), Q(x0, b, y), Q(x1, b, y), Q(x1, a, y), c); }
        };
        float xr = -F.hw - 3.0f, xl = -F.hw + 0.5f;   // полоса торможения/разгона (поверх обочины)
        float hl = F.hl, LT = 30;                     // отгон
        // площадка и горловины въезда/выезда
        rect(-F.hw + 0.5f, F.hw, -hl, hl, y1, conc, 4);
        rect(xr, -F.hw + 0.5f, -hl - 1, -hl + FUEL_THROAT, y1, asph, 1);
        rect(xr, -F.hw + 0.5f, hl - FUEL_THROAT, hl + 1, y1, asph, 1);
        // полосы: торможения (до въезда) и разгона (после выезда), с клиновидным отгоном
        rect(xr, xl, -hl - FUEL_LANE + LT, -hl, y1, asph, 2);
        rect(xr, xl, hl, hl + FUEL_LANE - LT, y1, asph, 2);
        flatQuad(Q(xr, -hl - FUEL_LANE, y1), Q(xr, -hl - FUEL_LANE + LT, y1), Q(xl, -hl - FUEL_LANE + LT, y1), Q(xr, -hl - FUEL_LANE, y1), asph);
        flatQuad(Q(xr, hl + FUEL_LANE - LT, y1), Q(xr, hl + FUEL_LANE, y1), Q(xr, hl + FUEL_LANE, y1), Q(xl, hl + FUEL_LANE - LT, y1), asph);
        if (dist2d(F.c, cam) > 260) continue;
        // разметка 1.8 (крупная прерывистая) вместо сплошной края проезжей части
        float xm = xr - 0.3f;
        for (float z = -hl - FUEL_LANE + LT; z < hl + FUEL_LANE - LT; z += 4) {
            if (z > -hl + FUEL_THROAT && z < hl - FUEL_THROAT) { rect(xm - 0.1f, xm + 0.1f, z, std::min(z + 4, hl - FUEL_THROAT), y2, line, 1); continue; }   // вдоль газона — сплошная
            rect(xm - 0.15f, xm + 0.15f, z, z + 1.0f, y2, line, 1);
        }
        // край полосы снаружи — сплошная
        rect(xl - 0.1f, xl + 0.1f, -hl - FUEL_LANE + LT, -hl, y2, line, 2);
        rect(xl - 0.1f, xl + 0.1f, hl, hl + FUEL_LANE - LT, y2, line, 2);
        // стрелки «направо» на полосе торможения и «прямо» на полосе разгона
        auto arrow = [&](float lz, bool right) {
            float cx = (xr + xl) * 0.5f;
            rect(cx - 0.15f, cx + 0.15f, lz, lz + 3.0f, y2, line, 1);
            if (right) {
                rect(cx - 0.15f, cx + 0.9f, lz + 2.7f, lz + 3.0f, y2, line, 1);
                flatQuad(Q(cx + 0.9f, lz + 2.3f, y2), Q(cx + 0.9f, lz + 3.4f, y2), Q(cx + 1.5f, lz + 2.85f, y2), Q(cx + 0.9f, lz + 2.3f, y2), line);
            }
            flatQuad(Q(cx - 0.6f, lz + 3.0f, y2), Q(cx, lz + 4.2f, y2), Q(cx + 0.6f, lz + 3.0f, y2), Q(cx - 0.6f, lz + 3.0f, y2), line);
        };
        arrow(-hl - 30, true); arrow(-hl - 12, true);
        arrow(hl + 8, false);
        // стоп-линия/«уступи» на выезде: треугольники 1.13
        for (float x = xr + 0.3f; x < -F.hw + 0.3f; x += 1.0f)
            flatQuad(Q(x, hl + 0.6f, y2), Q(x + 0.35f, hl + 1.4f, y2), Q(x + 0.7f, hl + 0.6f, y2), Q(x, hl + 0.6f, y2), line);
        // полосы у колонок
        for (int sd = -1; sd <= 1; sd += 2) rect(-1.0f + sd * 4.4f - 0.08f, -1.0f + sd * 4.4f + 0.08f, -8, 8, y2, line, 1);
        // направление движения по площадке
        { float cx = -5.5f; rect(cx - 0.12f, cx + 0.12f, -hl + 4, -hl + 6.5f, y2, line, 1); flatQuad(Q(cx - 0.5f, -hl + 6.5f, y2), Q(cx, -hl + 7.6f, y2), Q(cx + 0.5f, -hl + 6.5f, y2), Q(cx - 0.5f, -hl + 6.5f, y2), line); }
    }
    // 2) узлы
    for (size_t ni = 0; ni < NODES.size(); ni++) {
        const Node& n = NODES[ni];
        if (dist2d(n.p, cam) > maxD + n.trim) continue;
        if (!R3.sphereVisible(n.p, n.trim * 1.5f + 8)) continue;
        if (n.city) {
            float t = n.trim, w = t + 0.01f;
            flatQuad(n.p + V3(-w, 0.01f, -w), n.p + V3(w, 0.01f, -w), n.p + V3(w, 0.01f, w), n.p + V3(-w, 0.01f, w), walk);
            float mw = 0; for (int ei : n.edges) mw = std::max(mw, EDGES[ei].halfW);
            // асфальт перекрёстка: крест
            for (int ei : n.edges) {
                const Edge& e = EDGES[ei];
                V3 d = (e.a == (int)ni) ? e.dir : -e.dir; V3 rr = rightOf(atan2f(d.x, d.z));
                flatQuad(n.p - rr * e.halfW - d * mw + V3(0, 0.03f, 0), n.p + d * (t + 0.05f) - rr * e.halfW + V3(0, 0.03f, 0), n.p + d * (t + 0.05f) + rr * e.halfW + V3(0, 0.03f, 0), n.p + rr * e.halfW - d * mw + V3(0, 0.03f, 0), asph);
            }
            flatQuad(n.p + V3(-mw, 0.03f, -mw), n.p + V3(mw, 0.03f, -mw), n.p + V3(mw, 0.03f, mw), n.p + V3(-mw, 0.03f, mw), asph);
        } else {
            // поворот/развязка трассы: веер из полос
            if (n.edges.size() == 2) {
                const Edge& e0 = EDGES[n.edges[0]]; const Edge& e1 = EDGES[n.edges[1]];
                V3 d0 = (e0.a == (int)ni) ? e0.dir : -e0.dir, d1 = (e1.a == (int)ni) ? e1.dir : -e1.dir;
                V3 p0 = n.p + d0 * n.trim, p1 = n.p + d1 * n.trim;
                float w = e0.halfW;
                int N = 10;
                V3 prevL, prevR;
                for (int k = 0; k <= N; k++) {
                    float t = k / (float)N;
                    V3 q = p0 * ((1 - t) * (1 - t)) + n.p * (2 * t * (1 - t)) + p1 * (t * t);
                    V3 tg = norm((n.p - p0) * (2 * (1 - t)) + (p1 - n.p) * (2 * t));
                    V3 rr(tg.z, 0, -tg.x);
                    V3 cl = q - rr * (w + 3), cr = q + rr * (w + 3);
                    V3 al = q - rr * w, ar = q + rr * w;
                    if (k > 0) {
                        flatQuad(prevL + V3(0, 0.01f, 0), cl + V3(0, 0.01f, 0), cr + V3(0, 0.01f, 0), prevR + V3(0, 0.01f, 0), shoulder);
                    }
                    prevL = cl; prevR = cr;
                    (void)al; (void)ar;
                }
                for (int k = 0; k < N; k++) {
                    float t0 = k / (float)N, t1 = (k + 1) / (float)N;
                    V3 q0 = p0 * ((1 - t0) * (1 - t0)) + n.p * (2 * t0 * (1 - t0)) + p1 * (t0 * t0);
                    V3 q1 = p0 * ((1 - t1) * (1 - t1)) + n.p * (2 * t1 * (1 - t1)) + p1 * (t1 * t1);
                    V3 g0 = norm((n.p - p0) * (2 * (1 - t0)) + (p1 - n.p) * (2 * t0)), g1 = norm((n.p - p0) * (2 * (1 - t1)) + (p1 - n.p) * (2 * t1));
                    V3 r0(g0.z, 0, -g0.x), r1(g1.z, 0, -g1.x);
                    flatQuad(q0 - r0 * w + V3(0, 0.02f, 0), q1 - r1 * w + V3(0, 0.02f, 0), q1 + r1 * w + V3(0, 0.02f, 0), q0 + r0 * w + V3(0, 0.02f, 0), asph);
                }
            } else {
                float t = n.trim + 0.5f;
                flatQuad(n.p + V3(-t, 0.02f, -t), n.p + V3(t, 0.02f, -t), n.p + V3(t, 0.02f, t), n.p + V3(-t, 0.02f, t), asph);
            }
        }
    }
    // 2б) заплатки и трещины на асфальте — подсказка глазу о скорости
    for (size_t ei = 0; ei < EDGES.size(); ei++) {
        const Edge& e = EDGES[ei];
        float near0 = dot(cam - e.pa, e.dir);
        if (dist2d(cam, e.pa + e.dir * clampf(near0, 0, e.slen)) > 120) continue;
        V3 rr = rightOf(e.yaw);
        float s0 = clampf(near0 - 110, 0, e.slen), s1 = clampf(near0 + 110, 0, e.slen);
        for (float s = floorf(s0 / 5) * 5; s < s1; s += 5) {
            uint32_t h = hash32((uint32_t)ei * 7919u + (uint32_t)(s / 5) * 104729u);
            if ((h & 3) == 0) continue;
            float lat = ((h >> 4) % 1000 / 1000.f * 2 - 1) * (e.halfW - 0.6f);
            float ln = 0.4f + ((h >> 14) % 100) / 100.f * 1.0f, wd = 0.2f + ((h >> 21) % 100) / 100.f * 0.5f;
            V3 c = e.pa + e.dir * (s + ((h >> 8) % 50) / 10.f) + rr * lat + V3(0, 0.035f, 0);
            if (dist2d(c, cam) > 110) continue;
            Col pc = ((h >> 28) & 1) ? asph * 0.86f : asph * 1.12f;
            flatQuad(c - e.dir * ln - rr * wd, c + e.dir * ln - rr * wd, c + e.dir * ln + rr * wd, c - e.dir * ln + rr * wd, pc);
        }
    }
    // 3) разметка
    for (size_t ei = 0; ei < EDGES.size(); ei++) {
        const Edge& e = EDGES[ei];
        V3 rr = rightOf(e.yaw);
        V3 y(0, 0.05f, 0);
        float near0 = dot(cam - e.pa, e.dir);
        float sFrom = clampf(near0 - maxD, 0, e.slen), sTo = clampf(near0 + maxD, 0, e.slen);
        if (dist2d(cam, e.pa + e.dir * clampf(near0, 0, e.slen)) > maxD) continue;
        // осевая
        if (e.highway) {
            for (float s = sFrom; s < sTo; s += 30) {
                float s1 = std::min(sTo, s + 30);
                V3 a = e.pa + e.dir * s, b = e.pa + e.dir * s1;
                if (!R3.sphereVisible((a + b) * 0.5f, 20)) continue;
                for (int k = -1; k <= 1; k += 2) {
                    V3 o = rr * (k * 0.15f);
                    flatQuad(a + o - rr * 0.06f + y, b + o - rr * 0.06f + y, b + o + rr * 0.06f + y, a + o + rr * 0.06f + y, white);
                    // края проезжей части (у заправок вместо сплошной — 1.8 у полос торможения/разгона)
                    V3 o2 = rr * (k * (e.halfW - 0.3f));
                    float ca = s, cb = s1;
                    for (const FuelStation& F : FUELS) {
                        if (F.edge != (int)ei || (F.dir == 0 ? 1 : -1) != k) continue;
                        float se = F.dir == 0 ? F.s : e.slen - F.s, z0 = se - F.hl - FUEL_LANE + 30, z1 = se + F.hl + FUEL_LANE - 30;
                        if (cb > z0 && ca < z1) {
                            if (ca < z0) { V3 a2 = e.pa + e.dir * ca, b2 = e.pa + e.dir * z0; flatQuad(a2 + o2 - rr * 0.1f + y, b2 + o2 - rr * 0.1f + y, b2 + o2 + rr * 0.1f + y, a2 + o2 + rr * 0.1f + y, white); }
                            ca = std::max(ca, z1);
                        }
                    }
                    if (ca < cb) { V3 a2 = e.pa + e.dir * ca, b2 = e.pa + e.dir * cb; flatQuad(a2 + o2 - rr * 0.1f + y, b2 + o2 - rr * 0.1f + y, b2 + o2 + rr * 0.1f + y, a2 + o2 + rr * 0.1f + y, white); }
                }
            }
            // прерывистая между полосами
            float st = floorf(sFrom / 12) * 12;
            for (float s = st; s < sTo; s += 12) {
                V3 a = e.pa + e.dir * s, b = e.pa + e.dir * std::min(s + 4, e.slen);
                if (dist2d(a, cam) > 140) continue;
                for (int k = -1; k <= 1; k += 2) {
                    V3 o = rr * (k * e.laneW);
                    flatQuad(a + o - rr * 0.08f + y, b + o - rr * 0.08f + y, b + o + rr * 0.08f + y, a + o + rr * 0.08f + y, white);
                }
            }
        } else {
            float st = floorf(sFrom / 6) * 6;
            for (float s = st; s < sTo - 6; s += 6) {
                if (s < 8 || s > e.slen - 10) continue;
                V3 a = e.pa + e.dir * s, b = e.pa + e.dir * (s + 3);
                if (dist2d(a, cam) > 120) continue;
                flatQuad(a - rr * 0.07f + y, b - rr * 0.07f + y, b + rr * 0.07f + y, a + rr * 0.07f + y, white);
            }
            // сплошная перед перекрёстком, стоп-линии и «зебры»
            for (int end = 0; end < 2; end++) {
                int node = end == 0 ? e.a : e.b;
                V3 base = end == 0 ? e.pa : e.pb; V3 inw = end == 0 ? e.dir : -e.dir;
                if (dist2d(base, cam) > 150) continue;
                flatQuad(base + inw * 8 - rr * 0.07f + y, base + inw * 4.6f - rr * 0.07f + y, base + inw * 4.6f + rr * 0.07f + y, base + inw * 8 - rr * 0.07f + y, white);
                if (NODES[node].light) {
                    // стоп-линия — на полосе, подходящей к узлу (справа по ходу к узлу)
                    V3 rIn = -rr * (end == 0 ? -1.f : 1.f);
                    (void)rIn;
                    V3 approachR = (end == 0) ? -rr : rr;   // правая сторона для движения к узлу
                    flatQuad(base + inw * 4.6f + y, base + inw * 4.2f + y, base + inw * 4.2f + approachR * e.halfW + y, base + inw * 4.6f + approachR * e.halfW + y, white);
                    for (float x = -e.halfW + 0.3f; x < e.halfW - 0.3f; x += 1.0f) {
                        V3 p = base + inw * 0.6f + rr * x;
                        flatQuad(p + y, p + inw * 3.2f + y, p + inw * 3.2f + rr * 0.5f + y, p + rr * 0.5f + y, white);
                    }
                }
            }
        }
    }
}

// --- объекты ---
// четырёхугольник, разбитый на плитки (для правильной сортировки крупных граней)
static void quadSub(const V3& a, const V3& b, const V3& c, const V3& d, SDL_Color col, float bias, float tile = 1.2f) {
    int nu = std::min(6, std::max(1, (int)ceilf(len(b - a) / tile))), nv = std::min(6, std::max(1, (int)ceilf(len(d - a) / tile)));
    if (nu == 1 && nv == 1) { R3.quadW(a, b, c, d, col, 2, 0, bias); return; }
    for (int j = 0; j < nv; j++) for (int i = 0; i < nu; i++) {
        float u0 = i / (float)nu, u1 = (i + 1) / (float)nu, v0 = j / (float)nv, v1 = (j + 1) / (float)nv;
        auto P = [&](float u, float v) { V3 top = lerp3(a, b, u), bot = lerp3(d, c, u); return lerp3(top, bot, v); };
        R3.quadW(P(u0, v0), P(u1, v0), P(u1, v1), P(u0, v1), col, 2, 0, bias);
    }
}
static void shadedBox(const V3& c, const V3& h, float yaw, const Col& col, int cull = -1, const Col* top = nullptr, float bias = 0) {
    V3 f = fwdOf(yaw), r = rightOf(yaw), u(0, 1, 0);
    V3 p[8];
    for (int i = 0; i < 8; i++) p[i] = c + r * ((i & 1) ? h.x : -h.x) + u * ((i & 2) ? h.y : -h.y) + f * ((i & 4) ? h.z : -h.z);
    struct F4 { int a, b, c, d; V3 n; };
    F4 fs[5] = {{1, 5, 7, 3, r}, {0, 2, 6, 4, -r}, {2, 3, 7, 6, u}, {4, 6, 7, 5, f}, {0, 1, 3, 2, -f}};
    float d = dist2d(c, R3.pos);
    bool big = h.x > 0.7f || h.y > 0.7f || h.z > 0.7f;
    for (int k = 0; k < 5; k++) {
        // грань, отвёрнутая от камеры, не видна (коробка замкнута)
        V3 fc = (p[fs[k].a] + p[fs[k].c]) * 0.5f;
        if (big && dot(R3.pos - fc, fs[k].n) < 0) continue;
        Col base = (k == 2 && top) ? *top : col;
        Col s = shadeN(base, fs[k].n, c);
        SDL_Color sc = fogged(s, d);
        if (big) quadSub(p[fs[k].a], p[fs[k].b], p[fs[k].c], p[fs[k].d], sc, bias, 0.8f);
        else R3.quadW(p[fs[k].a], p[fs[k].b], p[fs[k].c], p[fs[k].d], sc, 2, 0, bias);
        (void)cull;
    }
}

static void drawText3D(const V3& origin, const V3& right, const V3& up, const char* str, float px, SDL_Color c, float bias = -0.05f) {
    // origin — центр строки
    std::vector<uint32_t> cps = utf8Decode(str);
    float w = (cps.size() * 6 - 1) * px;
    V3 o = origin - right * (w * 0.5f) + up * (3.5f * px);
    for (size_t i = 0; i < cps.size(); i++) {
        if (cps[i] != ' ') {
            int g = glyphIndex(cps[i]); int gx, gy; glyphCell(g, gx, gy);
            V3 a = o + right * (i * 6 * px), b = a + right * (5 * px), cc = b - up * (7 * px), d = a - up * (7 * px);
            R3.quadWT(a, b, cc, d, c, uvp(gx, gy), uvp(gx + 5, gy), uvp(gx + 5, gy + 7), uvp(gx, gy + 7), 2, 0, bias);
        }
    }
}

static void drawBuilding(const SObj& b, float dist) {
    V3 c = b.p;
    float hx = b.h.x, hz = b.h.z, H = b.h.y;
    V3 corners[4] = {c + V3(-hx, 0, -hz), c + V3(hx, 0, -hz), c + V3(hx, 0, hz), c + V3(-hx, 0, hz)};
    V3 normals[4] = {V3(0, 0, -1), V3(1, 0, 0), V3(0, 0, 1), V3(-1, 0, 0)};
    for (int w = 0; w < 4; w++) {
        V3 a = corners[w], bb = corners[(w + 1) % 4];
        V3 n = normals[w];
        if (dot(R3.pos - a, n) <= 0) continue;   // стена смотрит от камеры
        float wl = dist2d(a, bb);
        Col s = shadeN(b.col, n, a + V3(0, H * 0.5f, 0));
        if (dist > 170) {
            SDL_Color sc = fogged(s * 0.9f, dist);
            R3.quadW(a, bb, bb + V3(0, H, 0), a + V3(0, H, 0), sc, 2, 0, 0);
            continue;
        }
        int cols = std::max(1, (int)(wl / 5.0f));
        float cw = wl / cols;
        V3 dirw = (bb - a) * (1.0f / wl);
        for (int fl = 0; fl < b.floors; fl++) {
            float y0 = fl * 3.2f, y1 = y0 + 3.2f;
            for (int k = 0; k < cols; k++) {
                V3 p0 = a + dirw * (k * cw), p1 = a + dirw * ((k + 1) * cw);
                uint32_t hsh = hash32(b.seed + fl * 131 + k * 7 + w * 1013);
                int tile = 0;
                if (fl == 0 && b.ival == 1) tile = 3;
                else if (L.night > 0.5f) tile = (hsh % 100) < 40 ? 1 : 2;
                float emis = (tile == 1 || (tile == 3 && L.night > 0.5f)) ? L.night * 0.9f : 0;
                Col cc = lerpc(s, b.col, emis);
                if (tile == 1 || tile == 3) cc = lerpc(s, Col(1, 1, 1), emis);
                float pd = dist2d(p0, R3.pos);
                SDL_Color sc = fogged(cc, pd);
                float tx = WIN_X + tile * 16;
                R3.quadWT(p0 + V3(0, y1, 0), p1 + V3(0, y1, 0), p1 + V3(0, y0, 0), p0 + V3(0, y0, 0), sc, uvp(tx + 0.5f, WIN_Y + 0.5f), uvp(tx + 15.5f, WIN_Y + 0.5f), uvp(tx + 15.5f, WIN_Y + 15.5f), uvp(tx + 0.5f, WIN_Y + 15.5f), 2, 0, 0);
            }
        }
    }
    // крыша и парапет
    Col roof = shadeN(b.col2, V3(0, 1, 0), c);
    if (R3.pos.y > H - 1 || true) {
        SDL_Color sc = fogged(roof, dist);
        R3.quadW(corners[0] + V3(0, H, 0), corners[1] + V3(0, H, 0), corners[2] + V3(0, H, 0), corners[3] + V3(0, H, 0), sc, 2, 0, 0.5f);
    }
}

static void drawTree(const SObj& t, float dist) {
    float h = t.h.y;
    Col trunk(0.35f, 0.25f, 0.17f);
    float tw = 0.18f + h * 0.01f;
    shadedBox(t.p + V3(0, h * 0.18f, 0), V3(tw, h * 0.18f, tw), 0, trunk);
    int sides = dist < 80 ? 7 : 5;
    float rot = (t.seed % 100) * 0.06f;
    if (t.ival == 1) {
        // ель — три яруса конусов
        for (int tier = 0; tier < 3; tier++) {
            float y0 = h * (0.2f + tier * 0.22f), y1 = y0 + h * 0.42f, rr = h * (0.3f - tier * 0.07f);
            V3 top = t.p + V3(0, y1, 0);
            for (int i = 0; i < sides; i++) {
                float a0 = rot + i * 2 * PI / sides, a1 = rot + (i + 1) * 2 * PI / sides;
                V3 p0 = t.p + V3(cosf(a0) * rr, y0, sinf(a0) * rr), p1 = t.p + V3(cosf(a1) * rr, y0, sinf(a1) * rr);
                V3 n = norm(cross(p1 - p0, top - p0)); if (n.y < 0) n = -n;
                Col s = shadeN(t.col * (0.85f + 0.15f * (i & 1)), n, top);
                R3.triW(p0, p1, top, fogged(s, dist), 2, 0, 0);
            }
        }
    } else {
        // лиственное — «шар» из двух пирамид
        float y0 = h * 0.35f, ym = h * 0.65f, y1 = h * 1.0f, rr = h * 0.33f;
        V3 top = t.p + V3(0, y1, 0), bot = t.p + V3(0, y0, 0);
        for (int i = 0; i < sides; i++) {
            float a0 = rot + i * 2 * PI / sides, a1 = rot + (i + 1) * 2 * PI / sides;
            V3 p0 = t.p + V3(cosf(a0) * rr, ym, sinf(a0) * rr), p1 = t.p + V3(cosf(a1) * rr, ym, sinf(a1) * rr);
            V3 n1 = norm(cross(p1 - p0, top - p0)); if (n1.y < 0) n1 = -n1;
            V3 n2 = norm(cross(p0 - p1, bot - p1)); if (n2.y > 0) n2 = -n2;
            Col c1 = t.col * (0.9f + 0.1f * (i & 1));
            R3.triW(p0, p1, top, fogged(shadeN(c1, n1, top), dist), 2, 0, 0);
            R3.triW(p0, p1, bot, fogged(shadeN(c1 * 0.8f, n2, bot), dist), 2, 0, 0);
        }
    }
}

static void drawTrafficLight(const SObj& o, float dist) {
    V3 f = fwdOf(o.yaw), r = rightOf(o.yaw);
    Col pole(0.25f, 0.25f, 0.27f);
    shadedBox(o.p + V3(0, 2.2f, 0), V3(0.08f, 2.2f, 0.08f), o.yaw, pole);
    // консоль над дорогой
    float arm = o.seed >= 2 ? 6.0f : 3.0f;
    V3 armC = o.p + r * (-arm * 0.5f) + V3(0, 4.6f, 0);
    shadedBox(armC, V3(arm * 0.5f, 0.06f, 0.06f), o.yaw, pole);
    V3 boxC = o.p + r * (-arm + 0.3f) + V3(0, 4.1f, 0);
    shadedBox(boxC, V3(0.2f, 0.55f, 0.15f), o.yaw, Col(0.12f, 0.12f, 0.12f));
    V3 boxC2 = o.p + V3(0, 2.6f, 0) + f * 0.12f;
    shadedBox(boxC2, V3(0.17f, 0.45f, 0.12f), o.yaw, Col(0.12f, 0.12f, 0.12f));
    int st = lightState(o.ival, o.floors);
    Col lc[3] = {Col(1, 0.15f, 0.1f), Col(1, 0.8f, 0.1f), Col(0.2f, 1, 0.4f)};
    int on = st == 0 ? 2 : (st == 1 ? 1 : 0);
    for (int k = 0; k < 3; k++) {
        bool lit = (k == on);
        Col c = lit ? lc[k] : lc[k] * 0.18f;
        for (int b2 = 0; b2 < 2; b2++) {
            V3 bc = b2 == 0 ? boxC : boxC2;
            float step = b2 == 0 ? 0.34f : 0.28f;
            V3 lp = bc + f * (b2 == 0 ? 0.16f : 0.13f) + V3(0, step * (1 - k), 0);
            float s = b2 == 0 ? 0.12f : 0.1f;
            R3.quadW(lp - r * s + V3(0, s, 0), lp + r * s + V3(0, s, 0), lp + r * s - V3(0, s, 0), lp - r * s - V3(0, s, 0), fogged(c, dist * (lit ? 0.4f : 1)), 2, 0, -0.1f);
            if (lit && dist < 220) R3.billboard(lp + f * 0.05f, 0.45f + L.night * 0.5f, 0.45f + L.night * 0.5f, toSDL(c * (0.35f + 0.5f * L.night)), 0, 3, -0.3f);
        }
    }
}

static void drawSign(const SObj& o, float dist) {
    V3 f = fwdOf(o.yaw), r = rightOf(o.yaw);
    shadedBox(o.p + V3(0, 1.2f, 0), V3(0.04f, 1.2f, 0.04f), o.yaw, Col(0.5f, 0.5f, 0.52f));
    V3 c = o.p + V3(0, 2.55f, 0) + f * 0.06f;
    int N = 16; float R1 = 0.38f, R2 = 0.29f;
    bool front = dot(R3.pos - c, f) > 0;
    if (!front) {
        // обратная сторона — серый металлический круг
        Col back = shadeN(Col(0.55f, 0.56f, 0.58f), -f, c);
        for (int i = 0; i < N; i++) {
            float a0 = i * 2 * PI / N, a1 = (i + 1) * 2 * PI / N;
            R3.triW(c, c + r * (cosf(a0) * R1) + V3(0, sinf(a0) * R1, 0), c + r * (cosf(a1) * R1) + V3(0, sinf(a1) * R1, 0), fogged(back, dist), 2, 0, 0);
        }
        return;
    }
    Col red = shadeN(Col(0.85f, 0.1f, 0.1f), f, c), wh = shadeN(Col(0.95f, 0.95f, 0.95f), f, c);
    for (int i = 0; i < N; i++) {
        float a0 = i * 2 * PI / N, a1 = (i + 1) * 2 * PI / N;
        V3 o0 = c + r * (cosf(a0) * R1) + V3(0, sinf(a0) * R1, 0), o1 = c + r * (cosf(a1) * R1) + V3(0, sinf(a1) * R1, 0);
        V3 i0 = c + r * (cosf(a0) * R2) + V3(0, sinf(a0) * R2, 0), i1 = c + r * (cosf(a1) * R2) + V3(0, sinf(a1) * R2, 0);
        R3.quadW(i0, o0, o1, i1, fogged(red, dist), 2, 0, -0.02f);      // красное кольцо (не перекрывает белый круг)
        R3.triW(c, i0, i1, fogged(wh, dist), 2, 0, -0.02f);              // белый круг
    }
    if (dist < 90) {
        SDL_Color tc = fogged(Col(0.05f, 0.05f, 0.05f), dist);
        if (o.ival < 0) drawText3D(c + f * 0.01f, -r, V3(0, 1, 0), "КОНТРОЛЬ", 0.0105f, tc, -0.3f);   // знак 3.17.3
        else { std::string s = fmt("%d", o.ival); drawText3D(c + f * 0.01f, -r, V3(0, 1, 0), s.c_str(), 0.045f, tc, -0.3f); }
    }
}

static void drawLamp(const SObj& o, float dist) {
    V3 f = fwdOf(o.yaw);
    Col pole(0.32f, 0.33f, 0.35f);
    shadedBox(o.p + V3(0, 3.5f, 0), V3(0.07f, 3.5f, 0.07f), o.yaw, pole);
    shadedBox(o.p + V3(0, 6.95f, 0) + f * 0.9f, V3(0.06f, 0.05f, 0.9f), o.yaw, pole);
    V3 lp = o.p + V3(0, 6.85f, 0) + f * 1.7f;
    Col lc = L.night > 0.3f ? Col(1, 0.85f, 0.55f) : Col(0.7f, 0.7f, 0.7f);
    shadedBox(lp, V3(0.18f, 0.06f, 0.3f), o.yaw, lc, -1, nullptr, 0);
    if (L.night > 0.3f) {
        R3.billboard(lp - V3(0, 0.15f, 0), 1.0f, 1.0f, toSDL(Col(1, 0.75f, 0.4f) * (0.5f * L.night)), 0, 3, -0.2f);
        if (dist < 160) R3.groundSprite(V3(lp.x, 0.06f, lp.z), V3(5.5f, 0, 0), V3(0, 0, 5.5f), toSDL(Col(0.45f, 0.36f, 0.2f) * L.night), 1, 0);
    }
}

static void drawBillboard(const SObj& o, float dist) {
    V3 f = fwdOf(o.yaw), r = rightOf(o.yaw);
    Col pole(0.4f, 0.4f, 0.42f);
    shadedBox(o.p + V3(-2.5f, 0, 0) * 0 + r * -2.5f + V3(0, 2.5f, 0), V3(0.12f, 2.5f, 0.12f), o.yaw, pole);
    shadedBox(o.p + r * 2.5f + V3(0, 2.5f, 0), V3(0.12f, 2.5f, 0.12f), o.yaw, pole);
    V3 c = o.p + V3(0, 6.2f, 0);
    {
        // корпус щита без лицевой грани (её закрывает полотно); задняя сторона — полосами
        Col fr(0.85f, 0.85f, 0.85f);
        for (int k = 0; k < 10; k++) {
            float x0 = -5.2f + k * 1.04f, x1 = x0 + 1.04f;
            V3 a = c - f * 0.12f + r * x0, b = c - f * 0.12f + r * x1;
            R3.quadW(a + V3(0, 1.6f, 0), b + V3(0, 1.6f, 0), b - V3(0, 1.6f, 0), a - V3(0, 1.6f, 0), fogged(shadeN(fr, -f, c), dist), 2, 0, 0);
            R3.quadW(a + V3(0, 1.6f, 0), b + V3(0, 1.6f, 0), b + V3(0, 1.6f, 0) + f * 0.24f, a + V3(0, 1.6f, 0) + f * 0.24f, fogged(shadeN(fr, V3(0, 1, 0), c), dist), 2, 0, 0);
            R3.quadW(a - V3(0, 1.6f, 0), b - V3(0, 1.6f, 0), b - V3(0, 1.6f, 0) + f * 0.24f, a - V3(0, 1.6f, 0) + f * 0.24f, fogged(shadeN(fr, V3(0, -1, 0), c), dist), 2, 0, 0);
        }
        for (int s = -1; s <= 1; s += 2) {
            V3 e = c + r * (5.2f * s);
            R3.quadW(e - f * 0.12f + V3(0, 1.6f, 0), e + f * 0.12f + V3(0, 1.6f, 0), e + f * 0.12f - V3(0, 1.6f, 0), e - f * 0.12f - V3(0, 1.6f, 0), fogged(shadeN(fr, r * (float)s, c), dist), 2, 0, 0);
        }
    }
    Col bg = shadeN(o.col, f, c, L.night * 0.5f);
    // полотно щита — полосами, чтобы надпись правильно сортировалась вблизи
    for (int k = 0; k < 10; k++) {
        float x0 = -5 + k, x1 = x0 + 1;
        R3.quadW(c + f * 0.13f + r * x0 + V3(0, 1.45f, 0), c + f * 0.13f + r * x1 + V3(0, 1.45f, 0), c + f * 0.13f + r * x1 - V3(0, 1.45f, 0), c + f * 0.13f + r * x0 - V3(0, 1.45f, 0), fogged(bg, dist), 2, 0, -0.02f);
    }
    if (dist < 220 && dot(R3.pos - c, f) > 0) {
        float px = std::min(0.17f, 9.6f / (utf8Len(o.text.c_str()) * 6.0f));
        drawText3D(c + f * 0.15f, -r, V3(0, 1, 0), o.text.c_str(), px, fogged(Col(1, 1, 1) * (0.8f + 0.2f * L.night), dist), -0.6f);
    }
}

static void drawPostBooth(const SObj& o, float dist) {
    V3 f = fwdOf(o.yaw), r = rightOf(o.yaw);
    Col wall(0.94f, 0.94f, 0.96f), stripe(0.1f, 0.25f, 0.65f);
    shadedBox(o.p + V3(0, 1.5f, 0), V3(2.2f, 1.5f, 2.0f), o.yaw, wall, -1, nullptr);
    for (int k = 0; k < 4; k++) {
        V3 n = k == 0 ? f : (k == 1 ? -f : (k == 2 ? r : -r));
        V3 t = k < 2 ? r : f; float hw = k < 2 ? 2.2f : 2.0f; float off = k < 2 ? 2.01f : 2.21f;
        V3 c = o.p + n * off + V3(0, 1.6f, 0);
        if (dot(R3.pos - c, n) < 0) continue;
        quadSub(c - t * hw + V3(0, 0.22f, 0), c + t * hw + V3(0, 0.22f, 0), c + t * hw - V3(0, 0.22f, 0), c - t * hw - V3(0, 0.22f, 0), fogged(shadeN(stripe, n, c), dist), -1.2f, 0.6f);
    }
    shadedBox(o.p + V3(0, 3.15f, 0), V3(2.5f, 0.15f, 2.3f), o.yaw, Col(0.3f, 0.3f, 0.35f));
    // окна
    Col gl = shadeN(Col(0.2f, 0.3f, 0.4f), f, o.p, L.night * 0.6f);
    if (L.night > 0.4f) gl = Col(1, 0.9f, 0.6f) * 0.8f;
    if (dot(R3.pos - (o.p + f * 2.0f), f) > 0) {
        quadSub(o.p + f * 2.03f - r * 1.6f + V3(0, 2.6f, 0), o.p + f * 2.03f + r * 1.6f + V3(0, 2.6f, 0), o.p + f * 2.03f + r * 1.6f + V3(0, 2.0f, 0), o.p + f * 2.03f - r * 1.6f + V3(0, 2.0f, 0), fogged(gl, dist), -1.2f, 0.6f);
        if (dist < 160) drawText3D(o.p + f * 2.05f + V3(0, 0.75f, 0), -r, V3(0, 1, 0), "ДПС", 0.09f, fogged(Col(0.1f, 0.2f, 0.6f), dist), -1.6f);
    }
    // антенна и флажок
    shadedBox(o.p + V3(1.8f, 4.2f, 1.6f), V3(0.03f, 1.0f, 0.03f), o.yaw, Col(0.3f, 0.3f, 0.3f));
}

static void drawStatPost(const SObj& o, float dist) {
    const StatPost& S = SPOSTS[o.ival];
    V3 f = S.f, r = S.r, up(0, 1, 0);
    auto P = [&](float lx, float y, float lz) { return S.c + r * lx + f * lz + up * y; };
    bool night = L.night > 0.4f;
    Col white(0.94f, 0.94f, 0.96f), blue(0.1f, 0.25f, 0.65f), grey(0.5f, 0.52f, 0.55f), dark(0.18f, 0.18f, 0.2f);
    // навес над дорогой
    shadedBox(P(0, 6.4f, 0), V3(12.3f, 0.4f, 4.6f), S.yaw, white, -1, &grey);
    shadedBox(P(0, 5.9f, 0), V3(12.32f, 0.16f, 4.62f), S.yaw, blue);
    for (int sx = -1; sx <= 1; sx += 2) for (int sz = -1; sz <= 1; sz += 2) shadedBox(P(sx * 11.9f, 3.0f, sz * 4.0f), V3(0.3f, 3.0f, 0.3f), S.yaw, grey);
    {
        Col lc = night ? Col(1, 1, 0.95f) : Col(0.75f, 0.75f, 0.78f);
        for (int k = -3; k <= 3; k++) for (int sz = -1; sz <= 1; sz += 2) {
            V3 c = P(k * 3.2f, 5.98f, sz * 2.0f);
            R3.quadW(c - r * 0.9f - f * 0.35f, c - r * 0.9f + f * 0.35f, c + r * 0.9f + f * 0.35f, c + r * 0.9f - f * 0.35f, fogged(lc, dist * (night ? 0.3f : 1)), 2, 0, -0.05f);
        }
    }
    if (dist < 260) for (int sd = -1; sd <= 1; sd += 2) {   // надписи на обеих сторонах навеса
        V3 n = f * (float)sd; V3 tr = r * (float)-sd;
        V3 c0 = P(0, 6.42f, sd * 4.63f) + n * 0.02f;
        if (dot(R3.pos - c0, n) <= 0.2f) continue;
        drawText3D(c0, tr, up, "ДПС", 0.085f, fogged(blue, dist), -0.08f);
        drawText3D(c0 + r * 7.5f, tr, up, "ПОЛИЦИЯ", 0.05f, fogged(blue, dist), -0.08f);
        drawText3D(c0 - r * 7.5f, tr, up, "ПОЛИЦИЯ", 0.05f, fogged(blue, dist), -0.08f);
    }
    // карман досмотра у здания
    // здание поста: 2 этажа + «стакан»
    {
        V3 b = P(23, 0, 0);
        shadedBox(b + up * 3.3f, V3(4.6f, 3.3f, 7.2f), S.yaw, white, -1, &grey);
        Col gl = night ? Col(1, 0.9f, 0.62f) : shadeN(Col(0.22f, 0.32f, 0.45f), -r, b);
        V3 fc = b - r * 4.62f;
        if (dot(R3.pos - fc, -r) > 0) {
            quadSub(fc - f * 7.2f + up * 1.55f, fc + f * 7.2f + up * 1.55f, fc + f * 7.2f + up * 1.15f, fc - f * 7.2f + up * 1.15f, fogged(shadeN(blue, -r, fc), dist), -0.5f, 1.5f);   // синяя полоса
            for (int k = -2; k <= 2; k++) {   // окна 1-го и 2-го этажа
                V3 w1 = fc - r * 0.02f + f * (k * 2.8f);
                if (k != 0) quadSub(w1 - f * 0.9f + up * 2.9f, w1 + f * 0.9f + up * 2.9f, w1 + f * 0.9f + up * 1.9f, w1 - f * 0.9f + up * 1.9f, fogged(gl, dist * (night ? 0.4f : 1)), -0.9f, 1.0f);
                quadSub(w1 - f * 1.0f + up * 5.9f, w1 + f * 1.0f + up * 5.9f, w1 + f * 1.0f + up * 4.6f, w1 - f * 1.0f + up * 4.6f, fogged(gl, dist * (night ? 0.4f : 1)), -0.9f, 1.0f);
            }
            quadSub(fc - r * 0.02f - f * 0.8f + up * 2.4f, fc - r * 0.02f + f * 0.8f + up * 2.4f, fc - r * 0.02f + f * 0.8f, fc - r * 0.02f - f * 0.8f, fogged(dark, dist), -0.9f, 1.0f);   // дверь
            if (dist < 220) drawText3D(fc - r * 0.03f + up * 4.0f + f * 0.0f, -f, up, "ДПС", 0.11f, fogged(blue, dist), -1.2f);
            if (dist < 160) drawText3D(fc - r * 0.03f + up * 3.25f, -f, up, "СТАЦИОНАРНЫЙ ПОСТ ДПС ГИБДД", 0.028f, fogged(blue, dist), -1.2f);
        }
        // «стакан» — застеклённая будка наблюдения
        V3 g0 = b + up * 6.6f - r * 1.0f;
        shadedBox(g0 + up * 0.15f, V3(3.0f, 0.15f, 3.0f), S.yaw, white);
        Col sg = night ? Col(1, 0.9f, 0.65f) : shadeN(Col(0.3f, 0.45f, 0.6f), -r, g0);
        for (int k = 0; k < 4; k++) {
            V3 n = k == 0 ? -r : (k == 1 ? r : (k == 2 ? f : -f)); V3 t = (k < 2) ? f : r;
            V3 c = g0 + n * 2.6f + up * 1.45f;
            if (dot(R3.pos - c, n) <= 0) continue;
            quadSub(c - t * 2.6f + up * 1.1f, c + t * 2.6f + up * 1.1f, c + t * 2.6f - up * 1.1f, c - t * 2.6f - up * 1.1f, fogged(sg, dist * (night ? 0.4f : 1)), -0.3f, 1.3f);
        }
        shadedBox(g0 + up * 2.75f, V3(3.1f, 0.18f, 3.1f), S.yaw, blue);
        shadedBox(g0 + up * 3.9f + f * 2.0f, V3(0.04f, 1.2f, 0.04f), S.yaw, grey);   // антенна
        // флаг России
        V3 fp = b - r * 6.0f + f * 9.5f;
        shadedBox(fp + up * 4.0f, V3(0.06f, 4.0f, 0.06f), S.yaw, grey);
        Col fl[3] = {Col(0.95f, 0.95f, 0.95f), Col(0.1f, 0.3f, 0.75f), Col(0.8f, 0.12f, 0.12f)};
        float wave = sinf(gWorldTime * 2.0f) * 0.15f;
        for (int k = 0; k < 3; k++) {
            float y0 = 7.8f - k * 0.4f;
            V3 a = fp + up * y0, a2 = fp + up * (y0 - 0.4f), bb = a + f * 1.8f + r * wave, bb2 = a2 + f * 1.8f + r * wave;
            R3.quadW(a, bb, bb2, a2, fogged(fl[k], dist), 2, 0, -0.02f);
        }
    }
    // шлагбаумы: для направления «по f» — справа (тумба на lx=8.4), для обратного — слева
    for (int dir = 0; dir < 2; dir++) {
        float side = dir == 0 ? 1.f : -1.f;
        float lz = dir == 0 ? -SP_BAR : SP_BAR;
        V3 base = P(side * 8.4f, 0, lz);
        shadedBox(base + up * 0.55f, V3(0.25f, 0.55f, 0.25f), S.yaw, Col(0.85f, 0.85f, 0.85f));
        float a = S.arm * (PI * 0.5f) * 0.94f;      // 0 — поднят (вертикально), 1 — опущен (горизонтально)
        float ang = PI * 0.5f - a;                  // угол над горизонтом
        V3 dirA = r * (-side * cosf(ang)) + up * sinf(ang);
        V3 piv = base + up * 1.05f;
        V3 hv = norm(cross(dirA, f)) * 0.07f;
        float Lr = 7.8f; int N = 8;
        for (int i = 0; i < N; i++) {
            V3 p0 = piv + dirA * (Lr * i / N), p1 = piv + dirA * (Lr * (i + 1) / N);
            Col cc = (i & 1) ? Col(0.95f, 0.95f, 0.95f) : Col(0.85f, 0.1f, 0.1f);
            for (int sd = -1; sd <= 1; sd += 2) {
                V3 n = f * (float)sd; V3 o2 = n * 0.05f;
                if (dot(R3.pos - (p0 + o2), n) <= 0) continue;
                R3.quadW(p0 + hv + o2, p1 + hv + o2, p1 - hv + o2, p0 - hv + o2, fogged(shadeN(cc, n, p0), dist), 2, 0, -0.05f);
            }
        }
        // мигающий фонарь на конце, когда закрыт
        if (S.arm > 0.9f && fmodf(gWorldTime, 0.8f) < 0.4f) R3.billboard(piv + dirA * Lr + up * 0.1f, 0.35f, 0.35f, toSDL(Col(1, 0.15f, 0.1f)), 0, 3, -0.2f);
    }
}

static void drawKiosk(const SObj& o, float dist) {
    V3 f = fwdOf(o.yaw), r = rightOf(o.yaw);
    shadedBox(o.p + V3(0, 1.3f, 0), V3(1.8f, 1.3f, 1.4f), o.yaw, Col(0.9f, 0.9f, 0.88f));
    shadedBox(o.p + V3(0, 2.75f, 0), V3(1.95f, 0.15f, 1.55f), o.yaw, o.col);
    Col gl = L.night > 0.4f ? Col(1, 0.92f, 0.7f) : shadeN(Col(0.3f, 0.4f, 0.5f), f, o.p);
    if (dot(R3.pos - (o.p + f * 1.4f), f) > 0) {
        quadSub(o.p + f * 1.42f - r * 1.5f + V3(0, 2.2f, 0), o.p + f * 1.42f + r * 1.5f + V3(0, 2.2f, 0), o.p + f * 1.42f + r * 1.5f + V3(0, 1.0f, 0), o.p + f * 1.42f - r * 1.5f + V3(0, 1.0f, 0), fogged(gl, dist), -1.2f, 0.6f);
        if (dist < 100) drawText3D(o.p + f * 1.56f + V3(0, 2.75f, 0), -r, V3(0, 1, 0), (o.seed & 1) ? "ПРОДУКТЫ" : "ШАУРМА", 0.05f, fogged(Col(1, 1, 1), dist), -1.6f);
    }
}

static void drawFuelStation(const SObj& o, float dist) {
    const FuelStation& F = FUELS[o.ival];
    V3 f = F.f, r = F.r, up(0, 1, 0);
    auto P = [&](float lx, float y, float lz) { return F.c + r * lx + f * lz + up * y; };
    bool night = L.night > 0.4f;
    Col red = hexc(0xc8202a), white(0.95f, 0.95f, 0.95f), grey(0.55f, 0.56f, 0.58f), dark(0.15f, 0.15f, 0.17f);
    // навес
    shadedBox(P(-1.0f, 5.6f, 0), V3(6.6f, 0.45f, 9.2f), F.yaw, white, -1, &grey);
    shadedBox(P(-1.0f, 5.05f, 0), V3(6.62f, 0.12f, 9.22f), F.yaw, red);
    for (int sx = -1; sx <= 1; sx += 2) for (int sz = -1; sz <= 1; sz += 2) shadedBox(P(-1.0f + sx * 5.2f, 2.5f, sz * 7.5f), V3(0.22f, 2.5f, 0.22f), F.yaw, grey);
    // светильники под навесом
    {
        Col lc = night ? Col(1, 1, 0.95f) : Col(0.75f, 0.75f, 0.78f);
        for (int k = -1; k <= 1; k++) for (int sx = -1; sx <= 1; sx += 2) {
            V3 c = P(-1.0f + sx * 3.2f, 5.14f, k * 5.0f);
            R3.quadW(c - r * 0.9f - f * 0.5f, c - r * 0.9f + f * 0.5f, c + r * 0.9f + f * 0.5f, c + r * 0.9f - f * 0.5f, fogged(lc, dist * (night ? 0.3f : 1)), 2, 0, -0.05f);
        }
    }
    // надписи на навесе
    if (dist < 220) {
        SDL_Color tc = fogged(hexc(0xc8202a), dist);
        struct FT { V3 p, n, rt; } fts[3] = {{P(-1.0f - 6.62f, 5.62f, 0) - r * 0.03f, -r, -f}, {P(-1.0f, 5.62f, 9.22f) + f * 0.03f, f, -r}, {P(-1.0f, 5.62f, -9.22f) - f * 0.03f, -f, r}};
        for (const FT& t : fts) if (dot(R3.pos - t.p, t.n) > 0.2f) drawText3D(t.p, t.rt, up, "АЗС", 0.1f, tc, -0.06f);
    }
    // разделительный газон с бордюром
    {
        float L = F.hl - FUEL_THROAT;
        shadedBox(P(-F.hw + 2.0f, 0.08f, 0), V3(1.5f, 0.08f, L), F.yaw, Col(0.75f, 0.75f, 0.72f), -1, nullptr, 0.02f);
        V3 a = P(-F.hw + 0.65f, 0.17f, -L + 0.15f), b = P(-F.hw + 0.65f, 0.17f, L - 0.15f), c2 = P(-F.hw + 3.35f, 0.17f, L - 0.15f), d2 = P(-F.hw + 3.35f, 0.17f, -L + 0.15f);
        quadSub(a, b, c2, d2, fogged(shadeN(Col(0.3f, 0.5f, 0.22f), up, a), dist), -0.05f, 6.0f);
        if (dist < 140) for (int k = -2; k <= 2; k++) {   // кусты на газоне
            if (k == -2) continue;
            SObj t; t.p = P(-F.hw + 2.0f, 0, k * L * 0.4f); t.h = V3(0, 1.4f, 0); t.col = Col(0.22f, 0.45f, 0.18f); t.seed = F.seed + k; t.ival = 0; t.type = OB_BUSH; t.yaw = 0; t.radius = 1; t.floors = 0;
            SObj tb = t; tb.h.y = 1.4f; drawTree(tb, dist);
        }
    }
    // островок и колонки
    shadedBox(P(-1.0f, 0.1f, 0), V3(0.7f, 0.1f, 5.2f), F.yaw, Col(0.7f, 0.7f, 0.68f));
    for (int k = -1; k <= 1; k += 2) {
        shadedBox(P(-1.0f, 1.0f, k * 2.6f), V3(0.45f, 0.8f, 0.6f), F.yaw, white);
        shadedBox(P(-1.0f, 1.7f, k * 2.6f), V3(0.46f, 0.12f, 0.61f), F.yaw, red);
        Col scr = night ? Col(0.5f, 1, 0.6f) : Col(0.15f, 0.3f, 0.2f);
        for (int sd = -1; sd <= 1; sd += 2) {
            V3 c = P(-1.0f + sd * 0.47f, 1.3f, k * 2.6f); V3 n = r * (float)sd;
            R3.quadW(c - f * 0.3f + up * 0.15f, c + f * 0.3f + up * 0.15f, c + f * 0.3f - up * 0.15f, c - f * 0.3f - up * 0.15f, fogged(scr, dist * (night ? 0.4f : 1)), 2, 0, -0.03f);
            // шланг
            if (dist < 80) R3.quadW(c + n * 0.02f + f * 0.35f, c + n * 0.02f + f * 0.42f, c + n * 0.12f + f * 0.42f - up * 1.0f, c + n * 0.12f + f * 0.35f - up * 1.0f, fogged(dark, dist), 2, 0, -0.02f);
        }
    }
    // магазин
    {
        V3 c = P(9.5f, 0, 0);
        shadedBox(c + up * 1.8f, V3(2.6f, 1.8f, 7.0f), F.yaw, Col(0.88f, 0.88f, 0.86f), -1, &grey);
        shadedBox(c + up * 3.75f, V3(2.7f, 0.25f, 7.1f), F.yaw, red);
        Col gl = night ? Col(1, 0.92f, 0.72f) : shadeN(Col(0.3f, 0.42f, 0.55f), -r, c);
        V3 fc = c - r * 2.75f;
        if (dot(R3.pos - fc, -r) > 0) {
            quadSub(fc - f * 6.2f + up * 2.6f, fc + f * 6.2f + up * 2.6f, fc + f * 6.2f + up * 0.3f, fc - f * 6.2f + up * 0.3f, fogged(gl, dist * (night ? 0.4f : 1)), -1.6f, 0.8f);
            for (int k = -2; k <= 2; k++) { V3 m = fc - r * 0.02f + f * (k * 3.1f); R3.quadW(m - f * 0.08f + up * 2.6f, m + f * 0.08f + up * 2.6f, m + f * 0.08f + up * 0.3f, m - f * 0.08f + up * 0.3f, fogged(Col(0.3f, 0.3f, 0.32f), dist), 2, 0, -1.8f); }
            if (dist < 150) drawText3D(fc - r * 0.02f + up * 3.75f, -f, up, "МАГАЗИН  КАФЕ", 0.045f, fogged(Col(1, 1, 1), dist), -0.8f);
        }
    }
    // стела с ценами
    {
        V3 c = P(-F.hw + 2.0f, 0, -F.hl + FUEL_THROAT + 5);
        shadedBox(c + up * 3.6f, V3(0.9f, 3.6f, 0.35f), F.yaw, Col(0.2f, 0.22f, 0.26f));
        shadedBox(c + up * 6.8f, V3(0.95f, 0.45f, 0.38f), F.yaw, red);
        if (dist < 160) {
            SDL_Color tc = fogged(Col(1, 1, 1), dist), yc = fogged(night ? Col(1, 0.75f, 0.2f) : Col(1, 0.85f, 0.3f), dist * (night ? 0.4f : 1));
            for (int sd = -1; sd <= 1; sd += 2) {
                V3 n = f * (float)sd, tr = r * (float)-sd;   // лицевая сторона к подъезжающим (и обратно)
                V3 o0 = c + n * 0.37f;
                if (dot(R3.pos - o0, n) < 0.1f) continue;
                drawText3D(o0 + up * 6.8f, tr, up, "АЗС", 0.075f, tc, -0.3f);
                drawText3D(o0 + up * 5.6f, tr, up, "АИ-92  53.40", 0.032f, yc, -0.3f);
                drawText3D(o0 + up * 4.9f, tr, up, fmt("АИ-95  %.2f", FUEL_PRICE).c_str(), 0.032f, yc, -0.3f);
                drawText3D(o0 + up * 4.2f, tr, up, "ДТ     69.10", 0.032f, yc, -0.3f);
            }
        }
    }
    // машины у колонок
    if (dist < 160) {
        static const int mdl[] = {0, 1, 2, 3, 12, 13, 18, 19, 22, 23, 26};
        auto car = [&](float lx, float lz, uint32_t sd) {
            DrawCar dc; dc.pos = P(lx, 0, lz); dc.yaw = F.yaw; dc.paint = Col(0.2f + (sd % 7) * 0.11f, 0.25f + (sd / 7 % 5) * 0.13f, 0.3f + (sd / 35 % 4) * 0.15f);
            dc.camDist = dist; drawCarModel(mdl[sd % 11], dc);
        };
        if (F.seed & 1) car(2.6f, (F.seed & 2) ? 2.8f : -2.8f, F.seed >> 4);
        if (F.seed & 4) car(9.5f - 5.2f, (F.seed & 8) ? 12.0f : -12.0f, F.seed >> 9);
    }
}

// знак 7.3 «АЗС» (синий, белый квадрат с колонкой) + табличка расстояния 8.1.1
static void drawFuelSign(const SObj& o, float dist) {
    if (dist > 180) return;
    V3 f = fwdOf(o.yaw), r = rightOf(o.yaw), up(0, 1, 0);
    V3 n = -f;   // лицом к подъезжающим
    shadedBox(o.p + up * 1.4f, V3(0.05f, 1.4f, 0.05f), o.yaw, Col(0.5f, 0.5f, 0.52f));
    V3 c = o.p + up * 2.9f - f * 0.08f;
    if (dot(R3.pos - c, n) <= 0) { shadedBox(c + f * 0.03f, V3(0.45f, 0.6f, 0.02f), o.yaw, Col(0.6f, 0.6f, 0.62f)); return; }
    auto rq = [&](V3 cc, float hx, float hy, Col col, float bias) {
        R3.quadW(cc - r * hx + up * hy, cc + r * hx + up * hy, cc + r * hx - up * hy, cc - r * hx - up * hy, fogged(col, dist), 2, 0, bias);
    };
    rq(c, 0.45f, 0.6f, Col(0.95f, 0.95f, 0.95f), 0);                 // окантовка
    rq(c, 0.41f, 0.56f, Col(0.1f, 0.3f, 0.7f), -0.02f);              // синее поле
    V3 wc = c + up * 0.12f;
    rq(wc, 0.3f, 0.3f, Col(0.97f, 0.97f, 0.97f), -0.04f);            // белый квадрат
    rq(wc + r * -0.05f - up * 0.02f, 0.11f, 0.2f, Col(0.08f, 0.08f, 0.1f), -0.06f);   // колонка
    rq(wc + r * -0.05f + up * 0.08f, 0.07f, 0.05f, Col(0.97f, 0.97f, 0.97f), -0.08f); // окошко
    rq(wc + r * 0.1f + up * 0.02f, 0.025f, 0.14f, Col(0.08f, 0.08f, 0.1f), -0.06f);   // шланг
    rq(wc + r * 0.07f + up * 0.15f, 0.05f, 0.025f, Col(0.08f, 0.08f, 0.1f), -0.06f);
    if (dist < 120) drawText3D(c - f * 0.01f - up * 0.37f, r, up, "АЗС", 0.025f, fogged(Col(1, 1, 1), dist), -0.1f);
    if (o.floors > 0) {
        V3 pc = c - up * 0.8f;
        rq(pc, 0.4f, 0.17f, Col(0.95f, 0.95f, 0.95f), -0.02f);
        rq(pc, 0.37f, 0.14f, Col(0.1f, 0.3f, 0.7f), -0.03f);
        if (dist < 120) drawText3D(pc - f * 0.01f, r, up, fmt("%d М", o.floors).c_str(), 0.028f, fogged(Col(1, 1, 1), dist), -0.1f);
    }
}

static void drawBench(const SObj& o, float dist) {
    (void)dist;
    shadedBox(o.p + V3(0, 0.45f, 0), V3(0.9f, 0.04f, 0.22f), o.yaw, o.col);
    shadedBox(o.p + V3(0, 0.75f, -0.2f), V3(0.9f, 0.18f, 0.03f), o.yaw, o.col);
    shadedBox(o.p + V3(-0.8f, 0.22f, 0), V3(0.04f, 0.22f, 0.2f), o.yaw, Col(0.2f, 0.2f, 0.2f));
    shadedBox(o.p + V3(0.8f, 0.22f, 0), V3(0.04f, 0.22f, 0.2f), o.yaw, Col(0.2f, 0.2f, 0.2f));
}

static void drawGuardRails() {
    V3 cam = R3.pos;
    // сигнальные столбики каждые 25 м вдоль трассы (со световозвращателями)
    for (size_t ei = 0; ei < EDGES.size(); ei++) {
        const Edge& e = EDGES[ei];
        if (!e.highway) continue;
        float near0 = dot(cam - e.pa, e.dir);
        if (dist2d(cam, e.pa + e.dir * clampf(near0, 0, e.slen)) > 170) continue;
        V3 rr = rightOf(e.yaw);
        float s0 = clampf(near0 - 170, 0, e.slen), s1 = clampf(near0 + 170, 0, e.slen);
        for (float s = floorf(s0 / 25) * 25; s < s1; s += 25) {
            for (int side = -1; side <= 1; side += 2) {
                V3 p = e.pa + e.dir * s + rr * (side * (e.halfW + 2.7f));
                float d = dist2d(p, cam); if (d > 170) continue;
                if (fuelZone(p, 4) >= 0) continue;
                { bool np = false; for (const StatPost& S : SPOSTS) if (dist2d(p, S.c) < 55) np = true; if (np) continue; }
                if (!R3.sphereVisible(p + V3(0, 0.6f, 0), 1)) continue;
                V3 n = rr * (float)-side;
                Col w = shadeN(Col(0.95f, 0.95f, 0.95f), n, p);
                R3.quadW(p + V3(0, 1.1f, 0) - e.dir * 0.06f, p + V3(0, 1.1f, 0) + e.dir * 0.06f, p + e.dir * 0.06f, p - e.dir * 0.06f, fogged(w, d), 2, 0, 0);
                Col b = Col(0.08f, 0.08f, 0.08f);
                R3.quadW(p + V3(0, 1.0f, 0) - e.dir * 0.065f + n * 0.01f, p + V3(0, 1.0f, 0) + e.dir * 0.065f + n * 0.01f, p + V3(0, 0.85f, 0) + e.dir * 0.065f + n * 0.01f, p + V3(0, 0.85f, 0) - e.dir * 0.065f + n * 0.01f, fogged(b, d), 2, 0, -0.02f);
                // световозвращатель: ночью вспыхивает в свете фар
                Col rc = side > 0 ? Col(1, 1, 1) : Col(1, 0.45f, 0.1f);
                float glow = L.night > 0.3f && d < 90 ? L.night * (1 - d / 90) : 0;
                R3.quadW(p + V3(0, 0.98f, 0) - e.dir * 0.04f + n * 0.02f, p + V3(0, 0.98f, 0) + e.dir * 0.04f + n * 0.02f, p + V3(0, 0.88f, 0) + e.dir * 0.04f + n * 0.02f, p + V3(0, 0.88f, 0) - e.dir * 0.04f + n * 0.02f, fogged(lerpc(rc * 0.5f, rc, glow), d * (1 - glow)), 2, 0, -0.04f);
                if (glow > 0.05f) R3.billboard(p + V3(0, 0.93f, 0) + n * 0.05f, 0.25f, 0.25f, toSDL(rc * (glow * 0.8f)), 0, 3, -0.2f);
            }
        }
    }
    Col rail(0.72f, 0.74f, 0.76f), post(0.45f, 0.45f, 0.47f);
    for (size_t ei = 0; ei < EDGES.size(); ei++) {
        const Edge& e = EDGES[ei];
        if (!e.highway) continue;
        float near0 = dot(cam - e.pa, e.dir);
        if (dist2d(cam, e.pa + e.dir * clampf(near0, 0, e.slen)) > 160) continue;
        V3 rr = rightOf(e.yaw);
        float s0 = clampf(near0 - 160, 0, e.slen), s1 = clampf(near0 + 160, 0, e.slen);
        for (float s = floorf(s0 / 16) * 16; s < s1; s += 16) {
            float sb = std::min(s + 16, s1);
            for (int side = -1; side <= 1; side += 2) {
                V3 a = e.pa + e.dir * s + rr * (side * (e.halfW + 3.3f)), b = e.pa + e.dir * sb + rr * (side * (e.halfW + 3.3f));
                if (!R3.sphereVisible((a + b) * 0.5f, 10)) continue;
                bool nearPost = false; for (int k = 0; k < 4; k++) if (dist2d((a + b) * 0.5f, POSTS[k].pos) < 45) nearPost = true;
                if (nearPost) continue;
                if (fuelZone(a, 6) >= 0 || fuelZone(b, 6) >= 0 || fuelZone((a + b) * 0.5f, 6) >= 0) continue;
                float d = dist2d(a, cam);
                V3 n = rr * (float)-side;
                Col s1c = shadeN(rail, n, a);
                R3.quadW(a + V3(0, 0.85f, 0), b + V3(0, 0.85f, 0), b + V3(0, 0.55f, 0), a + V3(0, 0.55f, 0), fogged(s1c, d), 2, 0, 0);
                if (d < 90) for (float k = 0; k < 16; k += 4) {
                    V3 p = a + e.dir * k;
                    R3.quadW(p + V3(0, 0.55f, 0) - n * 0.05f, p + V3(0, 0.55f, 0) + e.dir * 0.12f - n * 0.05f, p + e.dir * 0.12f - n * 0.05f, p - n * 0.05f, fogged(shadeN(post, n, p), d), 2, 0, 0.05f);
                }
            }
        }
    }
}

// ---------------------------------------------------------------------
//  Пешеходы
// ---------------------------------------------------------------------
struct Ped {
    bool alive = false;
    V3 pos, target; float yaw = 0, speed = 1.3f, anim = 0;
    int edge = -1, side = 1; int toNode = -1; int state = 0;   // 0 идёт по тротуару, 1 ждёт у перехода, 2 переходит
    int crossEdge = -1, crossNode = -1;
    Col shirt, pants, skin, hair; float h = 1.75f; float wait = 0;
};
static std::vector<Ped> PEDS;

static V3 sidewalkPoint(const Edge& e, int side, float s) {
    V3 rr = rightOf(e.yaw);
    return e.pa + e.dir * s + rr * (side * (e.halfW + e.sidewalk * 0.55f));
}
static void pedPickTarget(Ped& p) {
    const Edge& e = EDGES[p.edge];
    p.target = sidewalkPoint(e, p.side, p.toNode == e.b ? e.slen + 2.0f : -2.0f);
}
static void spawnPed(Ped& p, const V3& near) {
    // случайный городской участок рядом
    for (int tries = 0; tries < 20; tries++) {
        int ei = grng.i((int)EDGES.size());
        const Edge& e = EDGES[ei];
        if (e.highway) continue;
        float s = grng.range(5, e.slen - 5);
        int side = grng.chance(0.5f) ? 1 : -1;
        V3 pos = sidewalkPoint(e, side, s);
        float d = dist2d(pos, near);
        if (d < 40 || d > 160) continue;
        p.alive = true; p.edge = ei; p.side = side; p.pos = pos; p.toNode = grng.chance(0.5f) ? e.a : e.b; p.state = 0;
        static const Col shirts[] = {hexc(0x2a4f8a), hexc(0x8a2a2a), hexc(0x2f6b3a), hexc(0x444444), hexc(0xd8c070), hexc(0xe0e0e0), hexc(0x6a3a7a)};
        p.shirt = shirts[grng.i(7)]; p.pants = grng.chance(0.6f) ? hexc(0x2a2f3a) : hexc(0x55504a);
        static const Col skins[] = {hexc(0xf1c8a6), hexc(0xe0b090), hexc(0xc89070)};
        p.skin = skins[grng.i(3)]; p.hair = grng.chance(0.5f) ? hexc(0x3a2a1a) : hexc(0x8a6a3a);
        p.h = grng.range(1.6f, 1.88f); p.speed = grng.range(1.1f, 1.6f);
        pedPickTarget(p);
        return;
    }
}
static bool pedCrossingNear(const V3& p, const V3& fwd, float range, float latW) {
    for (const Ped& q : PEDS) {
        if (!q.alive || q.state != 2) continue;
        V3 d = q.pos - p; float along = dot(d, fwd);
        if (along < 0 || along > range) continue;
        float lat = fabsf(d.x * fwd.z - d.z * fwd.x);
        if (lat < latW) return true;
    }
    return false;
}
static void updatePeds(float dt, const V3& center, bool active) {
    if (PEDS.empty()) PEDS.resize(26);
    for (Ped& p : PEDS) {
        if (!p.alive) { if (active && districtAt(center) == 0) spawnPed(p, center); continue; }
        if (dist2d(p.pos, center) > 190) { p.alive = false; continue; }
        if (p.state == 1) {
            // ждём красный для машин на пересекаемой улице
            p.wait += dt;
            int ax = lightAxisOf(EDGES[p.crossEdge]);
            if ((lightState(p.crossNode, ax) == 2 && lightRemaining(p.crossNode, ax) > 6) || p.wait > 40) p.state = 2;
            continue;
        }
        V3 d = p.target - p.pos; d.y = 0; float l = len(d);
        if (l < 0.3f) {
            if (p.state == 2) {
                // перешли — идём обратно по другой стороне
                p.state = 0; p.side = -p.side;
                const Edge& e = EDGES[p.edge];
                p.toNode = (p.toNode == e.a) ? e.b : e.a;
                pedPickTarget(p);
                continue;
            }
            const Edge& e = EDGES[p.edge];
            const Node& n = NODES[p.toNode];
            if (n.light && grng.chance(0.5f)) {
                // переход по «зебре» через текущую улицу
                p.crossEdge = p.edge; p.crossNode = p.toNode;
                V3 inw = (p.toNode == e.a) ? e.dir : -e.dir;
                V3 base = (p.toNode == e.a) ? e.pa : e.pb;
                V3 rr = rightOf(e.yaw);
                p.pos = base + inw * 2.2f + rr * (p.side * (e.halfW + 0.8f));
                p.target = base + inw * 2.2f + rr * (-p.side * (e.halfW + 0.8f));
                p.state = 1; p.wait = 0;
                continue;
            }
            // поворот за угол квартала: ближайший тротуар другой улицы
            float best = 1e9f; int be = -1, bs = 1;
            for (int ei : n.edges) {
                if (ei == p.edge) continue;
                const Edge& e2 = EDGES[ei];
                for (int sd = -1; sd <= 1; sd += 2) {
                    V3 sp = sidewalkPoint(e2, sd, e2.a == p.toNode ? -2.0f : e2.slen + 2.0f);
                    float dd = dist2d(sp, p.pos);
                    if (dd < best) { best = dd; be = ei; bs = sd; }
                }
            }
            if (be < 0 || best > 14 || EDGES[be].highway) { p.alive = false; continue; }
            p.edge = be; p.side = bs;
            const Edge& e2 = EDGES[be];
            p.toNode = (e2.a == p.toNode) ? e2.b : e2.a;
            pedPickTarget(p);
            continue;
        }
        V3 dn = d * (1 / l);
        p.yaw = atan2f(dn.x, dn.z);
        float sp = p.speed * (p.state == 2 ? 1.25f : 1);
        p.pos += dn * std::min(l, sp * dt);
        p.anim += dt * sp * 4.0f;
    }
}
static void drawPed(const Ped& p) {
    float dist = dist2d(p.pos, R3.pos);
    if (dist > 85 || !R3.sphereVisible(p.pos + V3(0, 1, 0), 1.2f)) return;
    float h = p.h, sw = sinf(p.anim) * (p.state == 1 ? 0 : 0.5f);
    V3 f = fwdOf(p.yaw), r = rightOf(p.yaw);
    float legH = h * 0.47f;
    for (int s = -1; s <= 1; s += 2) {
        V3 hip = p.pos + r * (s * 0.1f) + V3(0, legH, 0);
        float a = sw * s;
        V3 foot = hip + f * (sinf(a) * legH) - V3(0, cosf(a) * legH, 0);
        V3 mid = (hip + foot) * 0.5f;
        shadedBox(mid, V3(0.08f, legH * 0.5f, 0.09f), p.yaw + 0, p.pants);
    }
    shadedBox(p.pos + V3(0, legH + h * 0.15f, 0), V3(0.21f, h * 0.15f, 0.12f), p.yaw, p.shirt);
    for (int s = -1; s <= 1; s += 2) {
        float a = -sw * s * 0.8f;
        V3 sh = p.pos + r * (s * 0.27f) + V3(0, legH + h * 0.28f, 0);
        V3 hand = sh + f * (sinf(a) * h * 0.3f) - V3(0, cosf(a) * h * 0.3f, 0);
        shadedBox((sh + hand) * 0.5f, V3(0.06f, h * 0.15f, 0.06f), p.yaw, p.shirt * 0.9f);
    }
    shadedBox(p.pos + V3(0, h - 0.12f, 0), V3(0.11f, 0.12f, 0.11f), p.yaw, p.skin);
    shadedBox(p.pos + V3(0, h - 0.02f, -0.01f), V3(0.12f, 0.04f, 0.12f), p.yaw, p.hair);
    R3.groundSprite(p.pos + V3(0, 0.07f, 0), V3(0.35f, 0, 0), V3(0, 0, 0.35f), RGBA(0, 0, 0, (int)(90 * (1 - L.night * 0.6f))), 0, 0);
}

static void drawStatic() {
    V3 cam = R3.pos;
    int g0 = gridIdx(cam.x, cam.z); (void)g0;
    float range = std::min(L.fogEnd + 30, 380.f);
    int r = (int)(range / GRID_CS) + 1;
    int cgx = (int)((cam.x - GRID_X0) / GRID_CS), cgz = (int)((cam.z - GRID_Z0) / GRID_CS);
    static std::vector<int> seen; static int stamp = 0; static std::vector<int> mark;
    if (mark.size() != OBJS.size()) mark.assign(OBJS.size(), -1);
    stamp++;
    for (int gz = cgz - r; gz <= cgz + r; gz++) for (int gx = cgx - r; gx <= cgx + r; gx++) {
        if (gx < 0 || gz < 0 || gx >= GRID_NX || gz >= GRID_NZ) continue;
        for (int id : GRID[gz * GRID_NX + gx]) {
            if (mark[id] == stamp) continue;
            mark[id] = stamp;
            const SObj& o = OBJS[id];
            float d = dist2d(o.p, cam);
            float lim = range + o.radius;
            if (o.type == OB_TREE || o.type == OB_BUSH) lim = std::min(lim, 260.f);
            if (o.type == OB_BENCH) lim = 60;
            if (d > lim) continue;
            float cy = o.type == OB_BUILDING ? o.h.y * 0.5f : 2.0f;
            if (!R3.sphereVisible(o.p + V3(0, cy, 0), o.radius + cy + 1)) continue;
            switch (o.type) {
                case OB_BUILDING: drawBuilding(o, d); break;
                case OB_TREE: drawTree(o, d); break;
                case OB_BUSH: {
                    SObj t = o; t.h.y = o.h.y * 2.2f; drawTree(t, d);
                } break;
                case OB_LAMP: drawLamp(o, d); break;
                case OB_SIGN: if (d < 160) drawSign(o, d); break;
                case OB_TLIGHT: drawTrafficLight(o, d); break;
                case OB_BILLBOARD: drawBillboard(o, d); break;
                case OB_POST: drawPostBooth(o, d); break;
                case OB_KIOSK: drawKiosk(o, d); break;
                case OB_BENCH: drawBench(o, d); break;
                case OB_FUEL: drawFuelStation(o, d); break;
                case OB_FSIGN: drawFuelSign(o, d); break;
                case OB_SPOST: drawStatPost(o, d); break;
                default: break;
            }
        }
    }
}

// столкновение круга со статикой: выталкивает, возвращает true при ударе
static bool collideStatic(V3& p, float rad, V3* normalOut) {
    int g = gridIdx(p.x, p.z); if (g < 0) return false;
    bool hit = false;
    for (int dz = -1; dz <= 1; dz++) for (int dx = -1; dx <= 1; dx++) {
        int gg = gridIdx(p.x + dx * GRID_CS, p.z + dz * GRID_CS); if (gg < 0) continue;
        for (int id : GRID[gg]) {
            const SObj& o = OBJS[id];
            if (!o.collide) continue;
            if (o.type == OB_FBOX) {   // повёрнутый прямоугольник
                V3 f = fwdOf(o.yaw), r = rightOf(o.yaw); V3 d = p - o.p;
                float lx = d.x * r.x + d.z * r.z, lz = d.x * f.x + d.z * f.z;
                float qx = clampf(lx, -o.h.x, o.h.x), qz = clampf(lz, -o.h.z, o.h.z);
                float dx2 = lx - qx, dz2 = lz - qz, dd = sqrtf(dx2 * dx2 + dz2 * dz2);
                if (dd < rad) {
                    V3 n;
                    if (dd < 1e-4f) { float ex = o.h.x - fabsf(lx), ez = o.h.z - fabsf(lz); n = ex < ez ? r * (lx > 0 ? 1.f : -1.f) : f * (lz > 0 ? 1.f : -1.f); p += n * (rad + std::min(ex, ez)); }
                    else { n = norm(r * dx2 + f * dz2); p += n * (rad - dd); }
                    hit = true; if (normalOut) *normalOut = n;
                }
                continue;
            }
            if (o.type == OB_FPOLE) {
                float dd = dist2d(p, o.p), orad = o.h.x;
                if (dd < rad + orad) { V3 n = norm(V3(p.x - o.p.x, 0, p.z - o.p.z)); p += n * (rad + orad - dd); hit = true; if (normalOut) *normalOut = n; }
                continue;
            }
            if (o.type == OB_BUILDING || o.type == OB_POST || o.type == OB_KIOSK) {
                float hx = o.h.x, hz = o.h.z;
                if (o.type != OB_BUILDING) { hx = std::max(o.h.x, o.h.z); hz = hx; }
                float qx = clampf(p.x, o.p.x - hx, o.p.x + hx), qz = clampf(p.z, o.p.z - hz, o.p.z + hz);
                float dx2 = p.x - qx, dz2 = p.z - qz, dd = sqrtf(dx2 * dx2 + dz2 * dz2);
                if (dd < rad) {
                    if (dd < 1e-4f) { dx2 = p.x - o.p.x; dz2 = p.z - o.p.z; dd = sqrtf(dx2 * dx2 + dz2 * dz2) + 1e-4f; }
                    V3 n(dx2 / dd, 0, dz2 / dd);
                    p += n * (rad - dd); hit = true; if (normalOut) *normalOut = n;
                }
            } else {
                float orad = (o.type == OB_TREE) ? 0.35f : (o.type == OB_BILLBOARD ? 0.4f : 0.2f);
                if (o.type == OB_BILLBOARD) {
                    V3 r = rightOf(o.yaw);
                    for (int s = -1; s <= 1; s += 2) {
                        V3 pp = o.p + r * (2.5f * s);
                        float dd = dist2d(p, pp);
                        if (dd < rad + orad) { V3 n = norm(V3(p.x - pp.x, 0, p.z - pp.z)); p += n * (rad + orad - dd); hit = true; if (normalOut) *normalOut = n; }
                    }
                    continue;
                }
                float dd = dist2d(p, o.p);
                if (dd < rad + orad) { V3 n = norm(V3(p.x - o.p.x, 0, p.z - o.p.z)); p += n * (rad + orad - dd); hit = true; if (normalOut) *normalOut = n; }
            }
        }
    }
    return hit;
}

