struct PlayerCar {
    int spec = 0; V3 pos; float yaw = 0, speed = 0, steer = 0, yawRate = 0;
    float pitch = 0, roll = 0, pv = 0, rv = 0, spin = 0;
    bool siren = false, flash = false, brakeLight = false, reverse = false, offroad = false, sliding = false;
    int gear = 1;
    float lastSpeed = 0, rpm = 0, load = 0, exhaustT = 0, hitCooldown = 0, limitKmh = 60;
    float velYaw = 0; bool velInit = false;   // направление скорости (для заноса)
    float halfW = 0.85f, halfL = 2.1f;
};
static PlayerCar PL;
struct Input { float steer = 0, throttle = 0, brake = 0; };

static float specVmax() { const PatrolSpec& s = PATROL[SV.car]; return s.vmax / 3.6f * (1 + 0.07f * SV.upg[U_ENGINE]); }
static float specAccel() { const PatrolSpec& s = PATROL[SV.car]; return s.accel * (1 + 0.15f * SV.upg[U_ENGINE]); }
static float specBrake() { const PatrolSpec& s = PATROL[SV.car]; return s.brake * (1 + 0.15f * SV.upg[U_BRAKES]); }
static float specGrip() { const PatrolSpec& s = PATROL[SV.car]; return s.grip * (1 + 0.08f * SV.upg[U_TIRES]) * (L.rain > 0.3f ? 0.82f : 1.0f); }

static void playerSetCar() {
    PL.spec = SV.car;
    const CarModel& M = CM[PATROL[SV.car].model];
    PL.halfW = M.halfW; PL.halfL = M.halfL;
}

// круги для столкновений (локальные смещения по оси машины)
static int carCircles(const V3& pos, float yaw, float halfW, float halfL, V3* out) {
    V3 f = fwdOf(yaw);
    float r = halfW; float span = std::max(0.0f, halfL - r);
    int n = span > 2.2f ? 3 : 2;
    if (span > 5) n = 5;
    for (int i = 0; i < n; i++) { float t = n == 1 ? 0 : (i / (float)(n - 1)) * 2 - 1; out[i] = pos + f * (span * t); }
    return n;
}

static void sfxCrash(float strength) { sfx(SFX_CRASH, clampf(strength, 0.2f, 1.0f)); }

static float gCrashFlag = 0;   // для геймплея: последний удар
static int gLastHitCar = -1;

static void updatePlayer(float dt, const Input& in) {
    const CarModel& M = CM[PATROL[PL.spec].model];
    float vmax = specVmax(), acc = specAccel(), brk = specBrake(), grip = specGrip();
    float lim = 60;
    PL.offroad = !onRoadSurface(PL.pos, &lim);
    PL.limitKmh = lim;
    if (PL.siren) vmax *= 1.08f;          // режим преследования
    if (PL.offroad) vmax *= 0.72f;
    float thr = in.throttle, br = in.brake;
    PL.reverse = false;
    float sp = std::max(PL.speed, 0.f);
    if (thr > 0.01f) {
        if (PL.speed < -0.3f) PL.speed = approach(PL.speed, 0, brk * dt * thr);
        else {
            // тяга падает квадратично — машина уверенно набирает высокую скорость
            float k = 1 - (sp / vmax) * (sp / vmax);
            if (k < 0) k = 0;
            PL.speed += acc * k * thr * dt * (sp < 12 ? 1.25f : 1.0f);
        }
    }
    if (br > 0.01f) {
        if (PL.speed > 0.3f) PL.speed = std::max(0.f, PL.speed - brk * br * dt);
        else { PL.speed = std::max(PL.speed - 4.0f * dt * br, -9.0f); PL.reverse = true; }
    }
    if (thr <= 0.01f && br <= 0.01f) {
        float drag = (0.4f + fabsf(PL.speed) * 0.012f) * dt;
        PL.speed = approach(PL.speed, 0, drag);
    }
    if (PL.offroad) PL.speed = approach(PL.speed, 0, fabsf(PL.speed) * 0.18f * dt);
    if (PL.speed > vmax) PL.speed = approach(PL.speed, vmax, 3 * dt);
    float av = fabsf(PL.speed);
    // руль (настраивается игроком): резкость, скорость поворота руля, сцепление
    float maxSteer = 0.66f * SV.steerMul / (1 + av * 0.016f);
    float tgt = in.steer * maxSteer;
    float rate = ((fabsf(tgt) < fabsf(PL.steer) || tgt * PL.steer < 0) ? 9.0f : 6.5f) * SV.steerSpd;
    PL.steer = approach(PL.steer, tgt, rate * dt);
    float yr = PL.speed * tanf(PL.steer) / M.wheelbase;
    float maxLat = 9.81f * grip * 2.6f * SV.gripMul;
    if (fabsf(yr * PL.speed) > maxLat && av > 1) {
        float lim2 = maxLat / av;
        yr = (yr > 0 ? 1 : -1) * lim2;
    }
    // на очень малой скорости машина всё равно разворачивается
    if (av > 0.3f && av < 4 && fabsf(in.steer) > 0.01f) {
        float minYr = 0.55f * in.steer * (PL.speed > 0 ? 1.f : -1.f) * clampf(av / 2, 0, 1) * SV.steerMul;
        if (fabsf(yr) < fabsf(minYr)) yr = minYr;
    }
    // при низком сцеплении поворот «срывается» сильнее — машину заносит
    float yrGain = SV.gripMul < 0.9f ? 1.0f + (0.9f - SV.gripMul) * 1.6f : 1.0f;
    PL.yawRate = approach(PL.yawRate, yr * yrGain, 14.0f * SV.steerSpd * dt * std::max(1.0f, fabsf(yr - PL.yawRate)));
    yr = PL.yawRate;
    PL.yaw = wrapAngle(PL.yaw + yr * dt);
    // помощь удержания полосы (по желанию)
    if (SV.laneAssist && fabsf(in.steer) < 0.01f && av > 6 && !PL.offroad) {
        RoadHit h = nearestRoad(PL.pos);
        if (h.edge >= 0 && !h.onNode) {
            float ry = EDGES[h.edge].yaw;
            float e1 = wrapAngle(ry - PL.yaw), e2 = wrapAngle(ry + PI - PL.yaw);
            float err = fabsf(e1) < fabsf(e2) ? e1 : e2;
            if (fabsf(err) < 0.3f) PL.yaw = wrapAngle(PL.yaw + clampf(err, -1, 1) * 1.6f * dt);
        }
    }
    // направление движения догоняет направление кузова; при низком сцеплении — с запаздыванием (занос)
    if (!PL.velInit) { PL.velYaw = PL.yaw; PL.velInit = true; }
    float follow = 1.2f + 32.0f * clampf((SV.gripMul - 0.7f) / 0.5f, 0, 1);
    if (av < 3) follow = 40;
    float slip = wrapAngle(PL.yaw - PL.velYaw);
    PL.velYaw = wrapAngle(PL.velYaw + slip * std::min(1.0f, follow * dt));
    slip = wrapAngle(PL.yaw - PL.velYaw);
    if (fabsf(slip) > 1.2f) PL.velYaw = wrapAngle(PL.yaw - (slip > 0 ? 1.2f : -1.2f));
    PL.sliding = fabsf(slip) > 0.12f && av > 8;
    if (PL.sliding) PL.speed = approach(PL.speed, 0, fabsf(slip) * 3.0f * dt);
    // в повороте немного сбрасываем скорость, чтобы не вылетать
    if (fabsf(yr) * av > maxLat * 0.6f && thr < 0.5f) PL.speed = approach(PL.speed, 0, fabsf(yr) * 1.2f * dt);
    PL.pos += fwdOf(PL.velYaw) * (PL.speed * dt);
    // столкновения со статикой
    V3 cs[5]; int n = carCircles(PL.pos, PL.yaw, PL.halfW, PL.halfL, cs);
    PL.hitCooldown -= dt;
    for (int i = 0; i < n; i++) {
        V3 p = cs[i], nrm;
        if (collideStatic(p, PL.halfW, &nrm)) {
            V3 delta = p - cs[i];
            PL.pos += delta;
            float into = -dot(fwdOf(PL.yaw) * PL.speed, nrm);
            if (into > 0.5f) {
                PL.speed *= 0.35f;
                if (into > 4 && PL.hitCooldown <= 0) { sfxCrash(into / 15); PL.hitCooldown = 0.5f; gCrashFlag = into; }
            }
            for (int k = 0; k < n; k++) cs[k] += delta;
        }
    }
    // кузов
    float al = (PL.speed - PL.lastSpeed) / std::max(dt, 1e-3f);
    PL.lastSpeed = PL.speed;
    float pt = clampf(-al * 0.007f, -0.05f, 0.06f), rt = clampf(yr * PL.speed * 0.011f, -0.07f, 0.07f);
    PL.pv += ((pt - PL.pitch) * 70 - PL.pv * 9) * dt; PL.pitch += PL.pv * dt;
    PL.rv += ((rt - PL.roll) * 60 - PL.rv * 8) * dt; PL.roll += PL.rv * dt;
    float wr = M.wheels.empty() ? 0.3f : M.wheels[0].r;
    PL.spin += PL.speed * dt / wr;
    PL.brakeLight = br > 0.05f && PL.speed > 0.2f;
    // двигатель: условные передачи
    float kmh = fabsf(PL.speed) * 3.6f;
    // 6 передач, растянутых под максималку машины: мотор продолжает «расти» до самого верха
    float vmk = vmax * 3.6f;
    float gearTop[6] = {vmk * 0.12f, vmk * 0.24f, vmk * 0.38f, vmk * 0.54f, vmk * 0.74f, vmk * 1.02f};
    int g = 0; while (g < 5 && kmh > gearTop[g]) g++;
    float lo = g == 0 ? 0 : gearTop[g - 1] * 0.92f, hi = gearTop[g];
    float rpmT = clampf(0.3f + 0.7f * (kmh - lo) / (hi - lo), 0.12f, 1.0f);
    if (g == 5) rpmT = clampf(0.45f + 0.6f * (kmh - lo) / (hi - lo), 0.12f, 1.05f);
    PL.gear = g + 1;
    if (kmh < 2) rpmT = 0.12f + thr * 0.5f;
    PL.rpm = approach(PL.rpm, rpmT, 3 * dt);
    PL.load = approach(PL.load, thr, 4 * dt);
    // дым
    PL.exhaustT -= dt;
    if (PL.exhaustT <= 0) {
        PL.exhaustT = 0.08f - thr * 0.04f;
        Mat3 rot = rotYPR(PL.yaw, 0, 0);
        V3 ep = mul(rot, M.exhaust) + PL.pos;
        emitPart(ep, fwdOf(PL.yaw) * (-1.2f) + V3(grng.range(-0.2f, 0.2f), 0.3f, 0), 0.9f + thr, 0.12f, Col(0.6f, 0.6f, 0.62f), 0.25f + thr * 0.25f, 0.7f);
    }
    if (PL.sliding && fabsf(PL.speed) > 6 && grng.chance(0.5f)) {
        Mat3 rot = rotYPR(PL.yaw, 0, 0);
        for (size_t i = 2; i < M.wheels.size() && i < 4; i++) emitPart(mul(rot, M.wheels[i].p) + PL.pos - V3(0, 0.2f, 0), V3(0, 0.6f, 0), 1.2f, 0.25f, Col(0.85f, 0.85f, 0.85f), 0.35f, 1.0f);
    }
}

// ---------------------------------------------------------------------
//  ИИ-машины
// ---------------------------------------------------------------------
static float edgeLimitMs(const Edge& e) { return e.limitKmh / 3.6f; }

static void planNext(AICar& c) {
    const Edge& e = EDGES[c.edge];
    int node = edgeEndNode(e, c.dir);
    const Node& n = NODES[node];
    std::vector<int> cand;
    for (int ei : n.edges) if (ei != c.edge) cand.push_back(ei);
    // фуры и грузовики — по трассе
    if (c.trailer || c.model == MD_TRUCK) {
        std::vector<int> hw; for (int ei : cand) if (EDGES[ei].highway) hw.push_back(ei);
        if (!hw.empty()) cand = hw;
    }
    int ne;
    if (cand.empty()) ne = c.edge;
    else {
        // предпочитаем ехать прямо
        int straight = -1; float best = -2;
        for (int ei : cand) {
            const Edge& e2 = EDGES[ei]; V3 d2 = (e2.a == node) ? e2.dir : -e2.dir;
            V3 d1 = c.dir == 0 ? e.dir : -e.dir;
            float dd = dot(d1, d2); if (dd > best) { best = dd; straight = ei; }
        }
        float pStraight = 0.55f;
        if (c.mode == CMODE_FLEE) pStraight = dist2d(c.pos, PL.pos) < 70 ? 0.25f : 0.6f;   // погоня близко — резко уходит в поворот
        if (best > 0.9f && grng.chance(pStraight)) ne = straight; else ne = cand[grng.i((int)cand.size())];
        if (c.mode == CMODE_FLEE && ne == straight && cand.size() > 1 && dist2d(c.pos, PL.pos) < 70 && grng.chance(0.5f)) { int k = grng.i((int)cand.size()); if (cand[k] != straight) ne = cand[k]; }
    }
    c.planEdge = ne;
    c.planDir = (EDGES[ne].a == node) ? 0 : 1;
    if (ne == c.edge) c.planDir = 1 - c.dir;
}

// -1 налево, 0 прямо, 1 направо
static int turnSign(const Edge& e, int dir, int ne, int ndir) {
    const Edge& e2 = EDGES[ne];
    V3 f0 = dir == 0 ? e.dir : -e.dir, f2 = ndir == 0 ? e2.dir : -e2.dir;
    float cr = f0.x * f2.z - f0.z * f2.x, dd = dot(f0, f2);
    if (dd > 0.7f) return 0;
    return cr < 0 ? 1 : -1;
}
static void fugitiveCrash(AICar& c, float severity);
static void beginTurn(AICar& c) {
    const Edge& e = EDGES[c.edge];
    if (c.planEdge < 0) planNext(c);
    // повороты — только из крайней полосы; иначе едем прямо, если можно
    if (e.lanes > 1 && c.mode != CMODE_FLEE && c.planEdge != c.edge) {
        int ts = turnSign(e, c.dir, c.planEdge, c.planDir);
        int need = ts == 1 ? e.lanes - 1 : (ts == -1 ? 0 : c.lane);
        if (need != c.lane) {
            int node = edgeEndNode(e, c.dir);
            for (int ei : NODES[node].edges) {
                if (ei == c.edge) continue;
                int nd = (EDGES[ei].a == node) ? 0 : 1;
                if (turnSign(e, c.dir, ei, nd) == 0) { c.planEdge = ei; c.planDir = nd; break; }
            }
        }
    }
    c.nEdge = c.planEdge; c.nDir = c.planDir;
    const Edge& e2 = EDGES[c.nEdge];
    c.nLane = std::min(c.lane, e2.lanes - 1);
    V3 p0 = lanePos(e, c.dir, c.lane, e.slen, 0);
    V3 p2 = lanePos(e2, c.nDir, c.nLane, 0, 0);
    V3 f0 = c.dir == 0 ? e.dir : -e.dir, f2 = c.nDir == 0 ? e2.dir : -e2.dir;
    float den = f0.x * f2.z - f0.z * f2.x;
    V3 p1;
    if (fabsf(den) < 0.2f) p1 = (p0 + p2) * 0.5f;
    else {
        V3 d = p2 - p0;
        float t = (d.x * f2.z - d.z * f2.x) / den;
        p1 = p0 + f0 * t;
        if (t < 0 || t > 80) p1 = (p0 + p2) * 0.5f;
    }
    c.b0 = p0; c.b1 = p1; c.b2 = p2;
    c.tlen = std::max(2.0f, (len(p1 - p0) + len(p2 - p1) + len(p2 - p0)) * 0.5f);
    c.turning = true; c.tt = 0;
    if (c.mode == CMODE_FLEE) {
        float cosT = dot(norm(p1 - p0), norm(p2 - p1));
        float vTurn = cosT > 0.9f ? 1e9f : (NODES[edgeEndNode(e, c.dir)].city ? 15.0f : 32.0f);
        float ratio = c.speed / vTurn;
        if (ratio > 1.15f && grng.chance(clampf((ratio - 1.15f) * 1.2f, 0, 0.7f))) fugitiveCrash(c, clampf(ratio - 1.0f, 0.3f, 0.9f));
    }
    // поворотник
    float cr = f0.x * f2.z - f0.z * f2.x;
    c.blink = (c.mode == CMODE_DRIVE && fabsf(cr) > 0.3f) ? (cr < 0 ? 1 : -1) : (c.mode == CMODE_STOPPED ? 2 : 0);
}

// перекрёсток занят машиной с пересекающейся траекторией?
static bool nodeConflict(const AICar& c, int idx, int node) {
    const Edge& e = EDGES[c.edge];
    int myTs = c.planEdge >= 0 ? turnSign(e, c.dir, c.planEdge, c.planDir) : 0;
    V3 myF = c.dir == 0 ? e.dir : -e.dir;
    for (size_t i = 0; i < CARS.size(); i++) {
        if ((int)i == idx) continue;
        const AICar& o = CARS[i];
        if (!o.alive || o.crashed || o.mode == CMODE_HELPER) continue;
        const Edge& oe = EDGES[o.edge];
        if (edgeEndNode(oe, o.dir) != node) continue;
        // соседняя полоса того же подъезда въезжает туда же (сужение в одну полосу): по очереди
        if (o.edge == c.edge && o.dir == c.dir && o.lane != c.lane && c.planEdge >= 0) {
            bool sameTarget = o.turning ? (o.nEdge == c.planEdge && o.nDir == c.planDir) : (o.planEdge == c.planEdge && o.planDir == c.planDir);
            if (sameTarget && EDGES[c.planEdge].lanes == 1) {
                if (o.turning && o.tt < 0.85f) return true;
                if (!o.turning && (o.s > c.s + 0.5f || (fabsf(o.s - c.s) <= 0.5f && o.id < c.id))) return true;
            }
            continue;
        }
        int ots;
        if (o.turning) {
            if (o.tt > 0.88f) continue;
            if (o.speed < 0.5f && o.stuckD > 6) continue;   // сама стоит в заторе — не держим перекрёсток
            ots = turnSign(oe, o.dir, o.nEdge, o.nDir);
        } else {
            // ещё не въехала, но вот-вот въедет: одновременно не заезжаем — первой идёт та, что ближе (при равенстве — меньший номер)
            float oEnd = oe.slen - o.s, myEnd = e.slen - c.s;
            if (oEnd > 3.0f || o.speed < 0.8f || o.planEdge < 0) continue;
            if (oEnd > myEnd + 0.3f || (fabsf(oEnd - myEnd) <= 0.3f && o.id > c.id)) continue;
            ots = turnSign(oe, o.dir, o.planEdge, o.planDir);
        }
        V3 of = o.dir == 0 ? oe.dir : -oe.dir;
        float d = dot(myF, of);
        if (d > 0.7f) continue;                                   // та же полоса подхода — обычная очередь
        if (d < -0.7f && myTs == 0 && ots == 0) continue;         // встречные прямо — не мешают
        if (d < -0.7f && myTs == 1 && ots == 1) continue;         // встречные направо — не мешают
        return true;
    }
    return false;
}
static void carComputePose(AICar& c) {
    if (c.turning) {
        float t = clampf(c.tt, 0, 1);
        V3 p = c.b0 * ((1 - t) * (1 - t)) + c.b1 * (2 * t * (1 - t)) + c.b2 * (t * t);
        V3 tg = (c.b1 - c.b0) * (2 * (1 - t)) + (c.b2 - c.b1) * (2 * t);
        if (len(tg) < 1e-3f) tg = c.b2 - c.b0;
        float y = atan2f(tg.x, tg.z);
        c.pos = p + rightOf(y) * c.lat; c.yaw = y;
    } else {
        const Edge& e = EDGES[c.edge];
        V3 st, f, r; float y; laneFrame(e, c.dir, st, f, r, y);
        c.pos = st + f * c.s + r * (laneOffset(e, c.lane) + c.lat);
        // плавный разворот при смене бокового смещения
        // курс по реальной боковой скорости — без рывков при смене цели
        float yo = clampf(atan2f(c.latV, std::max(c.speed, 3.0f)), -0.3f, 0.3f);
        c.yaw = wrapAngle(y + yo * (c.speed > 1 ? 1 : c.speed) + c.yawOff);
    }
}

static int pickTrafficModel(bool highway, bool& trailer, bool& taxi, Col& paint, Col& paint2) {
    static const Col colors[] = {hexc(0xf0f0f0), hexc(0x151515), hexc(0xa8aab0), hexc(0x6a6d72), hexc(0x1d2f5a), hexc(0x7a1418), hexc(0x2a4a2e), hexc(0xc9b48a),
                                 hexc(0x3a3f45), hexc(0x8a8f96), hexc(0xd8d8d0), hexc(0x274a78), hexc(0x5a2d1a), hexc(0xb02020)};
    trailer = false; taxi = false;
    paint = colors[grng.i(14)];
    paint2 = grng.chance(0.5f) ? hexc(0x2a5aa0) : (grng.chance(0.5f) ? hexc(0xe8e8e8) : hexc(0x2a6a3a));
    float r = grng.f();
    if (highway) {
        if (r < 0.12f) { trailer = true; paint = grng.chance(0.5f) ? hexc(0xd02020) : hexc(0xf0f0f0); return MD_TRACTOR; }
        if (r < 0.22f) { paint = grng.chance(0.5f) ? hexc(0x2060b0) : hexc(0xe0e0e0); return MD_TRUCK; }
        if (r < 0.27f) return MD_GAZEL;
    } else {
        if (r < 0.08f) { paint = hexc(0xf2d21a); return MD_GAZEL; }
        if (r < 0.13f) { taxi = true; paint = hexc(0xf6c40f); return grng.chance(0.5f) ? MD_SEDAN : MD_SEDAN2; }
        if (r < 0.16f) { paint = hexc(0xe0e0e0); return MD_TRUCK; }
    }
    // редкие «стритрейсеры»: тюнинг и раллийные машины
    if (grng.chance(highway ? 0.05f : 0.035f)) {
        static const int racers[] = {MD_TRACK, MD_HOTHATCH, MD_RALLY, MD_SUPER2, MD_RALLYSEDAN, MD_SPORT1, MD_SPORT2, MD_SPORTCOUPE};
        return racers[grng.i(sizeof(racers) / sizeof(racers[0]))];
    }
    static const int pool[] = {MD_SEDAN, MD_HATCH, MD_WAGON, MD_CROSS, MD_BIGSUV, MD_MINIVAN, MD_OLDJEEP, MD_PICKUP, MD_SPORTSEDAN, MD_OLDSEDAN, MD_HATCH2, MD_SEDAN2,
                               MD_COUPE, MD_GTCOUPE, MD_OLDVAN, MD_CROSS2, MD_WAGON2, MD_BIGSUV2, MD_SUV3, MD_HATCH3, MD_FASTBACK, MD_SUV4, MD_MINI, MD_ESEDAN, MD_OLDCOUPE,
                               MD_OLDSEDAN, MD_SEDAN, MD_HATCH, MD_SEDAN2, MD_CROSS, MD_HATCH2, MD_HATCH3, MD_SUV3, MD_CROSS2};
    int m = pool[grng.i(sizeof(pool) / sizeof(pool[0]))];
    return m;
}

static bool isRacerModel(int m) {
    return m == MD_TRACK || m == MD_HOTHATCH || m == MD_RALLY || m == MD_SUPER2 || m == MD_RALLYSEDAN || m == MD_SPORT1 || m == MD_SPORT2 || m == MD_SPORTCOUPE;
}
// беглец: максимальная скорость (м/с) и разгон зависят от его машины
static float fleeTopSpeed(const AICar& c, bool city) {
    int m = c.model; float kmh, ckmh;
    if (m == MD_TRUCK || m == MD_TRACTOR || m == MD_GAZEL) { kmh = 125; ckmh = 85; }
    else if (m == MD_SPORT1 || m == MD_SPORT2 || m == MD_SUPER2 || m == MD_TRACK || m == MD_SPORTCOUPE) { kmh = 265; ckmh = 150; }
    else if (m == MD_RALLY || m == MD_RALLYSEDAN || m == MD_HOTHATCH || m == MD_GTCOUPE || m == MD_COUPE || m == MD_SPORTSEDAN || m == MD_ESEDAN || m == MD_FASTBACK) { kmh = 228; ckmh = 138; }
    else if (m == MD_BIGSUV || m == MD_BIGSUV2 || m == MD_OLDJEEP || m == MD_PICKUP || m == MD_MINIVAN || m == MD_OLDVAN || m == MD_SUV3 || m == MD_SUV4 || m == MD_CROSS || m == MD_CROSS2) { kmh = 178; ckmh = 112; }
    else if (m == MD_OLDSEDAN || m == MD_OLDCOUPE || m == MD_MINI || m == MD_HATCH || m == MD_HATCH2 || m == MD_HATCH3) { kmh = 185; ckmh = 118; }
    else { kmh = 205; ckmh = 125; }
    float var = 0.94f + (c.id % 13) * 0.01f;   // у каждого водителя немного своя манера
    return (city ? ckmh : kmh) / 3.6f * var * c.fleeDmg;
}
static float fleeAccel(const AICar& c) {
    float top = fleeTopSpeed(c, false) * 3.6f;
    if (top < 140) return 2.2f;
    return clampf(3.0f + (top - 170) / 30.0f, 3.5f, 7.0f);
}
// авария беглеца: занос, потеря скорости, искры; иногда — машина разбита
static void fugitiveCrash(AICar& c, float severity) {
    if (c.spinT > 0 || c.wrecked) return;
    c.spinT = 1.0f + severity * 1.4f; c.spinAmp = 0.35f + severity * 0.5f; c.spinDir = grng.chance(0.5f) ? 1 : -1;
    c.speed *= 0.55f - severity * 0.25f;
    c.overT = 0; c.overMode = 0; c.latTarget = 0;
    V3 p = c.pos + fwdOf(c.yaw) * c.halfL + V3(0, 0.5f, 0);
    for (int i = 0; i < 26; i++) emitPart(p, V3(grng.range(-4, 4), grng.range(0.5f, 4), grng.range(-4, 4)), grng.range(0.2f, 0.5f), 0.12f, Col(1, 0.75f, 0.3f), 1, 0, true);
    for (int i = 0; i < 8; i++) emitPart(p, V3(grng.range(-1, 1), grng.range(0.5f, 1.5f), grng.range(-1, 1)), grng.range(1.0f, 2.0f), 0.8f, Col(0.55f, 0.55f, 0.55f), 0.5f, 1.2f);
    float d = dist2d(c.pos, PL.pos);
    if (d < 150) sfx(SFX_CRASH, clampf(1.0f - d / 160, 0.25f, 1.0f));
    bool wreck = grng.chance(0.18f + severity * 0.45f);
    if (wreck) { c.wrecked = true; c.crashEvent = 2; c.flatMask |= 1 << grng.i(4); }
    else { c.crashEvent = 1; c.fleeDmg = std::max(0.6f, c.fleeDmg - 0.12f - severity * 0.1f); }
}

static int gPlateCounter = 4;
static int allocPlate(std::string& str, int& region, bool police = false) {
    int slot = gPlateCounter; gPlateCounter++; if (gPlateCounter >= PLATE_SLOTS) gPlateCounter = 4;
    if (police) { str = fmt("%s%04d", "А", grng.i(9000) + 1000); region = 66; }
    else str = randomPlate(grng, region);
    platePixels(slot, str, region, police);
    return slot;
}

static void initCarOnLane(AICar& c, int edge, int dir, int lane, float s) {
    c.edge = edge; c.dir = dir; c.lane = lane; c.s = s; c.turning = false; c.lat = 0; c.latTarget = 0; c.latV = 0;
    c.planEdge = -1; planNext(c);
    carComputePose(c);
    c.lastYaw = c.yaw;
    if (c.trailer) { c.tyaw = c.yaw; V3 hitch = c.pos + fwdOf(c.yaw) * CM[MD_TRACTOR].hitchZ; c.tpos = hitch - fwdOf(c.tyaw) * CM[MD_TRAILER].kingpinZ; }
}

static bool laneFree(int edge, int dir, int lane, float s, float range) {
    for (const AICar& o : CARS) {
        if (!o.alive || o.turning || o.edge != edge || o.dir != dir || o.lane != lane) continue;
        if (fabsf(o.s - s) < range) return false;
    }
    return true;
}

static void findLeader(const AICar& c, int selfIdx, float& gap, float& vLead);
static int spawnTrafficCar(const V3& center, float minD, float maxD, bool avoidView) {
    for (int tries = 0; tries < 12; tries++) {
        int ei = grng.i((int)EDGES.size());
        const Edge& e = EDGES[ei];
        float near0 = clampf(dot(center - e.pa, e.dir), 0, e.slen);
        float s = clampf(near0 + grng.range(-maxD, maxD), 2, e.slen - 2);
        int dir = grng.i(2), lane = grng.i(e.lanes);
        float sl = dir == 0 ? s : e.slen - s;
        V3 p = lanePos(e, dir, lane, sl, 0);
        float d = dist2d(p, center);
        if (d < minD || d > maxD) continue;
        if (avoidView && d < 220) {
            V3 v = R3.toView(p); if (v.z > 0 && fabsf(v.x) < v.z * 1.2f) continue;
        }
        if (!laneFree(ei, dir, lane, sl, 18)) continue;
        if (sl > e.slen - 25 || sl < 8) continue;   // не появляться вплотную к перекрёстку
        bool clear = true; for (const AICar& o : CARS) if (o.alive && (dist2d(o.pos, p) < 14 || (o.trailer && dist2d(o.tpos, p) < 14))) { clear = false; break; }
        if (!clear) continue;
        if (dist2d(p, PL.pos) < 25) continue;
        AICar c; c.alive = true; c.id = gCarIdCounter++;
        c.model = pickTrafficModel(e.highway, c.trailer, c.taxi, c.paint, c.paint2);
        if (!e.highway && (c.trailer)) continue;
        if (c.trailer && lane == 0 && e.lanes > 1) lane = 1;
        const CarModel& M = CM[c.model]; c.halfW = M.halfW; c.halfL = M.halfL;
        bool heavy = c.trailer || c.model == MD_TRUCK;
        bool racer = isRacerModel(c.model);
        c.racer = racer;
        c.speeder = !heavy && grng.chance(racer ? 0.75f : (e.highway ? 0.16f : 0.08f));
        c.redRunner = !heavy && grng.chance(0.06f);
        c.desired = c.speeder ? grng.range(1.3f, 1.65f) : grng.range(0.82f, 1.1f);
        if (heavy) c.desired = grng.range(0.75f, 0.9f);
        {   // дорожные «привычки» нарушителей
            float rv = grng.f(); bool nightNow = gClockMin < 6 * 60 || gClockMin > 21 * 60;
            c.vice = 0;
            if (!heavy && e.highway && rv < 0.09f) c.vice = 1;
            else if (!heavy && rv >= 0.09f && rv < 0.15f) { c.vice = 2; c.desired = std::max(c.desired, grng.range(1.15f, 1.4f)); }
            else if (rv >= 0.15f && rv < (nightNow ? 0.25f : 0.19f)) c.vice = 3;
        }
        c.plate = allocPlate(c.plateStr, c.region);
        initCarOnLane(c, ei, dir, lane, sl);
        c.speed = edgeLimitMs(e) * c.desired * 0.8f;
        {   // не появляться на скорости вплотную к медленному лидеру
            float g, vl; findLeader(c, -1, g, vl);
            if (g < 1e8f) c.speed = std::min(c.speed, vl + sqrtf(2 * 5.0f * std::max(0.f, g - 4)));
        }
        // занять свободный слот
        for (size_t i = 0; i < CARS.size(); i++) if (!CARS[i].alive) { CARS[i] = c; return (int)i; }
        CARS.push_back(c); return (int)CARS.size() - 1;
    }
    return -1;
}

// ближайшее препятствие впереди: возвращает зазор и скорость лидера
static void findLeader(const AICar& c, int selfIdx, float& gap, float& vLead) {
    gap = 1e9f; vLead = 0;
    V3 f = fwdOf(c.yaw), r = rightOf(c.yaw);
    float look = std::max(55.0f, c.speed * 3.2f + 15);
    for (size_t i = 0; i < CARS.size(); i++) {
        if ((int)i == selfIdx) continue;
        const AICar& o = CARS[i]; if (!o.alive || o.mode == CMODE_GONE) continue;
        // «страховка от тупика» игнорирует только чужие траектории, но не машины на своей полосе
        if (c.ghostT > 0 && !(!o.turning && !c.turning && o.edge == c.edge && o.dir == c.dir && o.lane == c.lane)) continue;
        // слияние в одну полосу после поворота: приоритет у того, кто ближе к выходу
        bool mergeLeader = false;
        if (c.turning && o.turning && o.nEdge == c.nEdge && o.nDir == c.nDir && o.nLane == c.nLane && o.edge != c.edge) {
            { float ro = (1 - o.tt) * o.tlen, rc = (1 - c.tt) * c.tlen; mergeLeader = ro < rc - 0.5f || (fabsf(ro - rc) <= 0.5f && o.id < c.id); }   // равные — по очереди
            if (!mergeLeader) continue;
        }
        if (c.turning && !o.turning && o.edge == c.nEdge && o.dir == c.nDir && o.lane == c.nLane && o.s < 25) mergeLeader = true;
        if (mergeLeader) {
            float g = dist2d(o.pos, c.pos) - c.halfL - o.halfL;
            if (g < gap) { gap = g; vLead = o.speed; }
            continue;
        }
        // в перекрёстке пересекающиеся траектории не считаем лидерами (иначе — взаимная блокировка)
        if ((c.turning || o.turning) && dot(fwdOf(o.yaw), f) < 0.35f) continue;
        V3 objs[2] = {o.pos, o.tpos}; int no = o.trailer ? 2 : 1;
        for (int k = 0; k < no; k++) {
            V3 d = objs[k] - c.pos; float along = dot(d, f);
            float ohl = k == 0 ? o.halfL : CM[MD_TRAILER].halfL;
            if (along < -ohl || along > look + ohl) continue;
            float lat = dot(d, r);
            float thr = c.halfW + o.halfW * 0.9f + 0.15f;
            bool sameLane = k == 0 && !o.crashed && !c.turning && !o.turning && o.edge == c.edge && o.dir == c.dir && o.lane == c.lane && fabsf(o.lat - c.lat) < 2.2f;
            if (fabsf(lat) > thr && !sameLane) continue;
            // встречные на повороте не считаем
            if (dot(fwdOf(k == 0 ? o.yaw : o.tyaw), f) < -0.3f && fabsf(lat) > 1.0f) continue;
            float g = along - c.halfL - ohl;
            if (g < gap) { gap = g; vLead = std::max(0.f, o.speed * dot(fwdOf(o.yaw), f)); }
        }
    }
    // игрок
    if (c.mode != CMODE_HELPER) {
        V3 d = PL.pos - c.pos; float along = dot(d, f), lat = dot(d, r);
        if (along > -PL.halfL && along < look && fabsf(lat) < c.halfW + PL.halfW * 0.9f + 0.2f) {
            float g = along - c.halfL - PL.halfL;
            if (g < gap) { gap = g; vLead = std::max(0.f, PL.speed * dot(fwdOf(PL.yaw), f)); }
        }
    }
    // блокпост
    if (gBlock.active) {
        V3 d = gBlock.pos - c.pos; float along = dot(d, f), lat = dot(d, r);
        if (along > 0 && along < 90 && fabsf(lat) < 9) { float g = along - c.halfL - 3; if (g < gap) { gap = g; vLead = 0; } }
    }
}

static void carAccel(AICar& c, float v0, float gap, float vl, float dt, float amax, float bcomf, float headway = 1.1f) {
    float v = c.speed;
    if (v0 < 0.1f) v0 = 0.1f;
    float sStar = 2.0f + v * headway + v * (v - vl) / (2 * sqrtf(amax * bcomf));
    if (sStar < 2) sStar = 2;
    float g = std::max(gap, 0.1f);
    float acc = amax * (1 - powf(std::min(v / v0, 2.0f), 4) - (sStar / g) * (sStar / g));
    acc = clampf(acc, -9.5f, amax);
    c.speed = std::max(0.f, v + acc * dt);
    c.brake = acc < -1.2f || (c.speed < 0.3f && v0 > 0.5f);
}

static void tryLaneChange(AICar& c, int newLane, bool ignorePlayer = false) {
    const Edge& e = EDGES[c.edge];
    if (newLane < 0 || newLane >= e.lanes || newLane == c.lane || c.turning) return;
    if (c.s > e.slen - 25) return;
    bool nearAcc = gAccActive && dist2d(c.pos, gAccPos) < 80;
    if (c.speed < 3 && c.mode != CMODE_PULLOVER && !nearAcc) return;
    // проверка: свободна ли целевая полоса
    for (const AICar& o : CARS) {
        if (!o.alive || &o == &c || o.turning || o.edge != c.edge || o.dir != c.dir || o.lane != newLane) continue;
        float ds = o.s - c.s;
        if (ds > -12 - std::max(0.f, o.speed - c.speed) * 2.5f - o.speed * 0.5f && ds < 22) return;
    }
    V3 d = PL.pos - c.pos; float along = dot(d, fwdOf(c.yaw)); float lat = dot(d, rightOf(c.yaw));
    float wantLat = (newLane - c.lane) * e.laneW;
    if (!ignorePlayer && fabsf(lat - wantLat) < 2.5f && along > -12 && along < 22) return;
    c.lat += (c.lane - newLane) * e.laneW;
    int dirB = newLane > c.lane ? 1 : -1;
    c.lane = newLane;
    if (c.vice == 2 && c.mode == CMODE_DRIVE) {   // «шашечник» — без поворотника
        c.laneBlinkT = 0;
        if (dist2d(c.pos, PL.pos) < 90) c.seen |= 2;
    } else { c.laneBlinkT = 2.2f; c.laneBlinkDir = dirB; }
}

static float shoulderLat(const AICar& c) {
    const Edge& e = EDGES[c.edge];
    float off = laneOffset(e, c.lane);
    if (e.highway) return e.halfW + 1.6f - off;
    return e.halfW - off - c.halfW - 0.15f;
}

static int gChaseCar = -1;

static void updateAICar(AICar& c, int idx, float dt) {
    c.modeT += dt;
    if (c.crashT > 0) c.crashT -= dt;
    const Edge& e = EDGES[c.edge];
    float lim = edgeLimitMs(e);
    float v0 = lim * c.desired;
    float amax = (c.trailer || c.model == MD_TRUCK) ? 1.1f : 2.2f, bcomf = 3.5f;
    bool ignoreLights = false;
    if (c.mode == CMODE_HELPER) {
        // коллега едет по следу беглеца
        if (c.helperTarget < 0 || c.helperTarget >= (int)CARS.size() || !CARS[c.helperTarget].alive) { c.mode = CMODE_GONE; return; }
        AICar& t = CARS[c.helperTarget];
        V3 goal = c.trailIdx < (int)t.trail.size() ? t.trail[c.trailIdx] : t.pos;
        V3 d = goal - c.pos; d.y = 0; float l = len(d);
        if (l < 3 && c.trailIdx < (int)t.trail.size()) { c.trailIdx++; }
        float dt2 = dist2d(c.pos, t.pos);
        float vt = dt2 > 18 ? std::max(t.speed * 1.12f + 4, 12.f) : t.speed * 0.95f;
        c.speed = approach(c.speed, std::min(vt, 52.f), 6 * dt);
        if (l > 0.1f) {
            float ty = atan2f(d.x, d.z);
            c.yaw = wrapAngle(c.yaw + clampf(wrapAngle(ty - c.yaw), -2.5f * dt, 2.5f * dt));
        }
        c.pos += fwdOf(c.yaw) * (c.speed * dt);
        if (dt2 < 16 && t.mode == CMODE_FLEE) t.pressure += dt * 0.55f;
        c.spin += c.speed * dt / 0.33f;
        return;
    }
    if (c.mode == CMODE_BLOCK) { c.speed = 0; return; }
    if (c.mode == CMODE_STOPPED) {
        c.speed = approach(c.speed, 0, 6 * dt); c.blink = 2; c.brake = true;
        c.lat = approach(c.lat, c.latTarget, 1.0f * dt); c.latV = 0;
        carComputePose(c);
        return;
    }
    if (c.mode == CMODE_FLEE) {
        v0 = std::max(lim * 1.3f, fleeTopSpeed(c, !e.highway)); amax = fleeAccel(c); bcomf = 8; ignoreLights = true;
        if (c.modeT < 5) amax *= 1.5f;   // рывок в начале погони
        if (c.wrecked) { v0 = 0; amax = 0.5f; }
        // перед поворотом на перекрёстке приходится тормозить
        if (!c.turning && c.planEdge >= 0) {
            int node = edgeEndNode(e, c.dir);
            int ts = turnSign(e, c.dir, c.planEdge, c.planDir);
            if (ts != 0 || NODES[node].edges.size() == 2) {
                float vTurn = NODES[node].city ? 14.0f : 31.0f;
                if (ts == 0 && NODES[node].edges.size() == 2) vTurn = 42.0f;   // плавная дуга трассы
                float distEnd = e.slen - c.s - (NODES[node].city ? 4.0f : 10.0f);
                float vAllow = sqrtf(vTurn * vTurn + 2 * 7.0f * std::max(0.f, distEnd));
                // лихач иногда «не успевает»: тормозит поздно
                if (c.id % 3 == 1) vAllow *= 1.3f;
                v0 = std::min(v0, vAllow);
            }
        }
        // занос после аварии
        if (c.spinT > 0) {
            c.spinT -= dt; c.spinAmp = approach(c.spinAmp, 0, dt * 0.35f);
            c.yawOff = sinf(c.spinT * 9.0f) * c.spinAmp * c.spinDir;
            v0 = 0; amax = 0.5f; bcomf = 9;
            if (c.spinT <= 0) c.yawOff = 0;
        }
        if (c.pressure > 0) c.pressure -= dt * 0.08f;
        if (c.trail.empty() || dist2d(c.trail.back(), c.pos) > 4) { c.trail.push_back(c.pos); if (c.trail.size() > 800) c.trail.erase(c.trail.begin(), c.trail.begin() + 100); }
    }
    if (c.mode == CMODE_PULLOVER) {
        // сначала перестроиться в правый ряд, и только оттуда — на обочину (не через соседнюю полосу)
        if (!c.turning && c.lane < e.lanes - 1) {
            c.pullWait += dt;
            tryLaneChange(c, e.lanes - 1, c.pullWait > 2.5f);   // инспектор сзади пропускает
        }
        bool rightLane = c.lane >= e.lanes - 1;
        if (!c.turning) c.latTarget = rightLane ? shoulderLat(c) : 0.0f;
        c.blink = 1;
        bool there = !c.turning && rightLane && fabsf(c.lat - c.latTarget) < 0.6f;
        v0 = there ? 0.0f : std::max(4.0f, std::min(v0, 9.0f));
        if (there && c.speed < 0.25f) { c.mode = CMODE_STOPPED; c.modeT = 0; c.speed = 0; c.blink = 2; }
    }
    if (c.mode == CMODE_LEAVE) {
        c.latTarget = 0; c.blink = c.modeT < 3 ? -1 : 0;
        if (!c.turning && fabsf(c.lat) > 0.6f) {   // встраиваться в полосу — только в свободное место
            bool busy = false;
            for (const AICar& o : CARS) {
                if (!o.alive || &o == &c || o.turning || o.edge != c.edge || o.dir != c.dir || o.lane != c.lane || fabsf(o.lat) > 1.3f) continue;
                float ds = o.s - c.s, need = c.halfL + o.halfL + 2.5f;
                if (ds > -need - std::max(0.f, o.speed) * 1.8f && ds < need) { busy = true; break; }
            }
            if (busy) { c.latTarget = c.lat; c.modeT = std::min(c.modeT, 1.4f); }
        }
        if (c.modeT > 4 && fabsf(c.lat) < 0.3f) { c.mode = CMODE_DRIVE; }
        if (c.modeT < 1.5f) v0 = 0;
    }
    if (c.mode == CMODE_DRIVE) {
        // уступить дорогу машине с сиреной: только тем, кого игрок догоняет прямо сзади
        bool wantYield = false;
        if (PL.siren && gChaseCar != idx && PL.speed > 4 && !c.turning) {
            V3 d = c.pos - PL.pos; float along = dot(d, fwdOf(PL.yaw)), lat = fabsf(dot(d, rightOf(PL.yaw)));
            float closing = PL.speed - c.speed * dot(fwdOf(c.yaw), fwdOf(PL.yaw));
            bool sameDir = dot(fwdOf(c.yaw), fwdOf(PL.yaw)) > 0.7f;
            float range = (c.id % 10 == 0) ? 15.f : 45.f;          // кто-то замечает поздно
            if (sameDir && along > 0 && along < range && lat < 4.5f && closing > -1.0f) wantYield = true;
        }
        if (wantYield) {
            c.yieldWait += dt;
            if (c.yieldWait > 0.3f + (c.id % 7) * 0.18f) c.yieldT = 2.0f;   // разное время реакции
        } else c.yieldWait = std::max(0.f, c.yieldWait - dt);
        if (c.yieldT > 0) {
            c.yieldT -= dt;
            if (!c.turning) {
                if (e.lanes > 1 && c.lane < e.lanes - 1) { tryLaneChange(c, e.lanes - 1); c.latTarget = 0; v0 *= 0.85f; }   // просто освободить левую полосу
                else if (e.lanes > 1) {
                    // решение «на обочину или нет» принимается один раз за манёвр (иначе машина мечется)
                    if (c.yieldMode < 0) {
                        float relLane = dot(PL.pos - c.pos, rightOf(c.yaw)) + c.lat;   // игрок относительно центра моей полосы
                        c.yieldMode = fabsf(relLane) < 1.9f ? 1 : 0;
                    }
                    bool toShoulder = c.yieldMode == 1;
                    c.latTarget = toShoulder ? shoulderLat(c) * 0.8f : 0.0f; v0 *= toShoulder ? 0.6f : 0.85f;
                }
                else if (c.hornYield) { c.latTarget = std::min(shoulderLat(c), 0.9f); v0 = std::max(v0, lim * 1.12f); }   // в городе на гудок — прижаться и прибавить
                else { c.latTarget = std::min(shoulderLat(c), 0.6f); v0 *= 0.6f; }   // в городе — прижаться вправо, не на тротуар
            }
            c.blink = (c.latTarget > 0.3f || c.lat < -0.3f) ? 1 : 0;   // поворотник и при перестроении вправо
            if (c.yieldT <= 0) { c.latTarget = 0; c.blink = 0; c.yieldMode = -1; c.hornYield = false; }
        } else { c.latTarget = 0; c.yieldMode = -1; c.hornYield = false; }
        // гудок игрока: водитель впереди в той же полосе замечает и реагирует
        if (gHornT > 0 && c.hornT <= 0 && !c.turning) {
            V3 dd = c.pos - PL.pos; float along = dot(dd, fwdOf(PL.yaw)), lat = fabsf(dot(dd, rightOf(PL.yaw)));
            bool sameDir = dot(fwdOf(c.yaw), fwdOf(PL.yaw)) > 0.7f;
            if (sameDir && along > 2 && along < 45 && lat < 3.0f) c.hornT = 3.6f;
        }
        if (c.hornT > 0) {
            float prev = c.hornT;
            c.hornT -= dt;
            if (prev >= 3.0f && c.hornT < 3.0f) {   // ~0.6 с на реакцию
                bool grumpy = (c.id % 10 == 3) && !PL.siren;   // редкий водитель сначала сигналит в ответ и тормозит назло
                if (grumpy) {
                    float dd = dist2d(c.pos, PL.pos);
                    sfx(SFX_HORN, clampf(0.7f - dd / 80, 0.15f, 0.6f), 0, 0, 0.7f);
                    c.hornT = 1.6f;
                } else {
                    c.yieldT = std::max(c.yieldT, 3.5f); c.hornYield = true;   // уйти вправо и пропустить
                }
            }
            bool grumpyNow = (c.id % 10 == 3) && !PL.siren && c.hornT > 0 && c.hornT < 1.6f;
            if (grumpyNow && c.hornT > 0.8f) v0 *= 0.5f;                              // «торможение назло»...
            if (grumpyNow && c.hornT - dt <= 0.8f && c.hornT > 0.8f - dt * 1.5f) { c.yieldT = std::max(c.yieldT, 3.0f); c.hornYield = true; }   // ...но потом всё же уступает
        }
        // место ДТП: «зеваки» притормаживают
        if (gAccActive && !c.crashed && dist2d(c.pos, gAccPos) < 70) v0 = std::min(v0, (e.highway ? 40.f : 25.f) / 3.6f);
        // камеры: притормаживают
        for (const Camera_& cam : SPEEDCAMS) {
            if (cam.edge != c.edge || cam.dir != c.dir || c.turning) continue;
            float ds = cam.s - c.s;
            if (ds > -5 && ds < 160 && !(c.speeder && (c.id % 3 == 0))) v0 = std::min(v0, lim * 0.96f);
            if (ds < 0 && ds > -c.speed * dt - 0.01f && c.speed > lim + 10 / 3.6f) c.flashT = 0.25f;
        }
    }
    // нарушитель объезжает затор по обочине (только трасса, правая полоса)
    if (c.vice == 1 && c.mode == CMODE_DRIVE && !c.turning && e.highway && e.lanes > 1 && c.lane == e.lanes - 1 && c.yieldT <= 0) {
        float g0, vl0; findLeader(c, idx, g0, vl0);
        bool clear = c.s < e.slen - 60;
        for (const AICar& o : CARS) {
            if (!clear) break;
            if (!o.alive || &o == &c || o.turning || o.edge != c.edge || o.dir != c.dir) continue;
            float ds = o.s - c.s;
            if (ds > -6 && ds < 70 && (o.lat > 1.4f || o.mode == CMODE_STOPPED || o.mode == CMODE_PULLOVER)) clear = false;
        }
        { V3 d = PL.pos - c.pos; float al = dot(d, fwdOf(c.yaw)), la = dot(d, rightOf(c.yaw)); if (al > -6 && al < 70 && la > 1.6f) clear = false; }
        if (c.viceT <= 0 && clear && g0 < 40 && vl0 < std::max(c.speed, lim * 0.6f) * 0.9f) c.viceT = 4.0f + grng.range(0, 3);
        if (c.viceT > 0) {
            c.viceT -= dt;
            if (!clear) c.viceT = std::min(c.viceT, 0.3f);
            c.latTarget = shoulderLat(c);
            v0 = std::max(v0, lim * 0.85f);
            if (c.lat > 1.8f && dist2d(c.pos, PL.pos) < 100) c.seen |= 1;
        }
        if (c.viceT <= 0 && c.lat > 0.8f) {
            // вернуться в полосу можно только в свободное место, иначе ехать/стоять на обочине дальше
            bool blocked = false;
            for (const AICar& o : CARS) {
                if (!o.alive || &o == &c || o.turning || o.edge != c.edge || o.dir != c.dir || o.lane != c.lane || o.lat > 1.4f) continue;
                float ds = o.s - c.s, need = c.halfL + o.halfL + 3.0f;
                if (ds > -need - std::max(0.f, o.speed - c.speed) * 1.5f && ds < need + 1.0f) { blocked = true; break; }
            }
            { V3 d = PL.pos - c.pos; float al = dot(d, fwdOf(c.yaw)), la = dot(d, rightOf(c.yaw)) + c.lat; if (fabsf(la) < 2.0f && al > -c.halfL - PL.halfL - 3 && al < c.halfL + PL.halfL + 4) blocked = true; }
            if (blocked) c.latTarget = shoulderLat(c);
        }
    } else if (c.vice == 1) c.viceT = 0;
    // «шашечник»: частые перестроения
    if (c.vice == 2 && c.mode == CMODE_DRIVE && !c.turning && e.lanes > 1 && c.yieldT <= 0) {
        float g0, vl0; findLeader(c, idx, g0, vl0);
        if (g0 < 45 && vl0 < v0 * 0.97f && grng.chance(dt * 1.2f)) tryLaneChange(c, c.lane == 0 ? 1 : c.lane - 1);
    }
    // светофор
    float gap, vl; findLeader(c, idx, gap, vl);
    bool redStop = false;
    if (!c.turning && !ignoreLights) {
        int node = edgeEndNode(e, c.dir);
        float distEnd = e.slen - c.s;
        if (NODES[node].light && distEnd < std::max(60.f, c.speed * c.speed / 5 + 20) && distEnd > 3.5f) {
            int st = lightState(node, lightAxisOf(e));
            float stopAt = distEnd - 4.8f;
            bool mustStop = st == 2 || (st == 1 && stopAt > c.speed * c.speed / (2 * 4.0f));
            if (mustStop && c.redRunner && c.mode == CMODE_DRIVE) mustStop = false;
            if (mustStop) { float g = stopAt - c.halfL * 0.0f - 0.5f; redStop = true; if (g < gap) { gap = g; vl = 0; } }
        }
    }
    // стационарный пост ДПС: перед ним сбрасывают скорость, у закрытого шлагбаума — стоят
    if (!c.turning && c.mode != CMODE_HELPER) {
        for (const StatPost& P : SPOSTS) {
            if (P.edge != c.edge) continue;
            float db = spDistToBarrier(P, c.dir, c.s);
            if (c.mode != CMODE_FLEE && db > -SP_BAR * 2 - 10 && db < 260) {
                float lk = db > 130 ? 70.f : 40.f;
                if (c.speeder && c.id % 3 == 0) lk += 15;   // кто-то всё равно не сбрасывает
                if (c.wanted) lk += 10;
                float vlim = lk / 3.6f;
                if (db > 0) vlim = std::max(vlim, std::min(v0, sqrtf(vlim * vlim + 2 * 2.5f * std::max(0.f, db - 130.f))));
                v0 = std::min(v0, vlim);
            }
            if (P.arm > 0.5f && db > -1.0f && db < 160) {
                float g = db - c.halfL - 2.4f;
                if (g < gap) { gap = std::max(0.f, g); vl = 0; }
                redStop = true;
            }
        }
    }
    // занятый перекрёсток: ждём у стоп-линии, пока проедут машины с пересекающихся направлений
    if (!c.turning && c.mode != CMODE_HELPER) {
        int node = edgeEndNode(e, c.dir);
        float distEnd = e.slen - c.s;
        if (NODES[node].edges.size() >= 3 && distEnd < std::max(10.f, c.speed * c.speed / 12 + 7) && distEnd > 0.5f && nodeConflict(c, idx, node)) {
            float g = std::max(0.f, distEnd - (NODES[node].light ? 4.8f : 1.5f) - 0.5f);
            if (g < gap) { gap = g; vl = 0; }
            redStop = true;
        }
    }
    // пешеходы на переходе
    if (!ignoreLights && !PEDS.empty() && pedCrossingNear(c.pos, fwdOf(c.yaw), c.halfL + 10, 3.0f)) { float g = 5.0f; if (g < gap) { gap = g; vl = 0; } }
    // пробитые колёса: машина теряет скорость, виляет и сыплет искрами с дисков
    if (c.flatMask) {
        int nf = bitCount(c.flatMask);
        v0 *= nf == 1 ? 0.62f : (nf == 2 ? 0.3f : 0.08f);
        amax *= nf == 1 ? 0.6f : 0.35f;
        c.yawOff = sinf(c.modeT * 7.3f + c.id) * 0.035f * nf * clampf(c.speed / 10, 0, 1);
        if (c.speed > 4 && dist2d(c.pos, PL.pos) < 90) {
            const CarModel& M = CM[c.model]; Mat3 rot = rotYPR(c.yaw, 0, 0);
            for (size_t wi = 0; wi < M.wheels.size() && wi < 8; wi++) {
                if (!((c.flatMask >> wi) & 1) || !grng.chance(dt * (8 + c.speed))) continue;
                V3 wp = mul(rot, M.wheels[wi].p) + c.pos; wp.y = 0.1f;
                V3 v = fwdOf(c.yaw) * (-c.speed * 0.4f) + V3(grng.range(-2, 2), grng.range(0.5f, 2.5f), grng.range(-2, 2));
                emitPart(wp, v, grng.range(0.15f, 0.35f), 0.1f, Col(1, 0.75f, 0.3f), 1, 0, true);
                if (grng.chance(0.3f)) emitPart(wp + V3(0, 0.2f, 0), V3(0, 0.6f, 0), 1.2f, 0.4f, Col(0.6f, 0.6f, 0.6f), 0.35f, 0.9f);
            }
        }
    }
    carAccel(c, v0, gap, vl, dt, amax, bcomf, c.mode == CMODE_FLEE ? 0.45f : 1.1f);
    if (c.holdV >= 0) { c.speed = std::min(c.speed, c.holdV); c.holdV = -1; }
    // страховка от редких тупиков: долго стоим не на красный — проезжаем «сквозь»
    if (c.ghostT > 0) c.ghostT -= dt;
    bool nearBlock = gBlock.active && dist2d(c.pos, gBlock.pos) < 150;
    if ((c.mode == CMODE_DRIVE || c.mode == CMODE_LEAVE) && c.speed < 0.2f && !redStop && !nearBlock) {
        c.stuckD += dt;
        if (c.stuckD > 45) {
            // тупик: сквозь машины больше не проезжаем. Невидимую игроку машину тихо убираем,
            // видимая ждёт, пока затор рассосётся сам
            bool special = c.caseIdx >= 0 || c.wanted || c.crashed || c.vanish;
            bool seen = R3.sphereVisible(c.pos + V3(0, 1, 0), c.halfL + 1) && dist2d(c.pos, PL.pos) < 160;
            if (!special && !seen) { c.alive = false; return; }
            c.stuckD = 30;
        }
    } else c.stuckD = 0;
    // беглец: хитрые манёвры и риск аварии
    if (c.mode == CMODE_FLEE && !c.wrecked && c.spinT <= 0) {
        float distEnd = e.slen - c.s;
        // 1) не успевает затормозить перед медленной машиной — удар
        if (gap < 2.5f && c.speed - vl > 7) fugitiveCrash(c, clampf((c.speed - vl) / 30.0f, 0.2f, 1.0f));
        // 2) инспектор сел на хвост — резко уходит в сторону, чтобы не дать себя толкнуть
        {
            V3 d = PL.pos - c.pos; float al = dot(d, fwdOf(c.yaw)), la = dot(d, rightOf(c.yaw)) - c.lat * 0;
            if (al < -c.halfL && al > -c.halfL - 12 && fabsf(la) < 2.5f && PL.speed > c.speed - 1.5f && !c.turning && c.overMode == 0) {
                if (e.lanes > 1 && grng.chance(dt * 1.6f)) tryLaneChange(c, c.lane == 0 ? 1 : 0, true);
                else if (e.lanes == 1 && grng.chance(dt * 1.2f)) { c.overMode = 3; c.overT = 0.9f; c.spinDir = grng.chance(0.5f) ? 1 : -1; }
            }
        }
        // 3) обгон: на трассе — по обочине, в городе — по встречке
        if (c.overMode == 0 && !c.turning && gap < 30 && vl < c.speed * 0.8f && distEnd > 45 && c.s > 10) {
            if (e.lanes > 1 && e.highway && c.lane == e.lanes - 1 && grng.chance(dt * 2.5f)) {
                bool clear = true;
                for (const AICar& o : CARS) if (o.alive && &o != &c && !o.turning && o.edge == c.edge && o.dir == c.dir && o.lat > 1.3f && o.s - c.s > -4 && o.s - c.s < 60) clear = false;
                if (clear) { c.overMode = 2; c.overT = 3.5f; if (c.speed > 42 && grng.chance(0.08f)) fugitiveCrash(c, 0.4f); }
            } else if (e.lanes == 1 && !e.highway && grng.chance(dt * 2.0f)) {
                bool clear = true;
                V3 f = fwdOf(c.yaw);
                for (const AICar& o : CARS) {
                    if (!o.alive || &o == &c || o.edge != c.edge || o.dir == c.dir) continue;
                    float al = dot(o.pos - c.pos, f); if (al > -5 && al < 90) clear = false;
                }
                { float al = dot(PL.pos - c.pos, f), la = dot(PL.pos - c.pos, rightOf(c.yaw)); if (al > -5 && al < 70 && la < -1.0f) clear = false; }
                if (clear) { c.overMode = 1; c.overT = 3.0f; }
            }
        }
        if (c.overMode) {
            c.overT -= dt;
            if (c.overMode == 1) {
                c.latTarget = -e.laneW;   // на встречную полосу
                // встречная машина появилась близко — назад в свою полосу (или авария)
                V3 f = fwdOf(c.yaw);
                for (const AICar& o : CARS) {
                    if (!o.alive || &o == &c || o.edge != c.edge || o.dir == c.dir) continue;
                    float al = dot(o.pos - c.pos, f);
                    if (al > 0 && al < 18 && c.lat < -1.5f) { fugitiveCrash(c, 0.8f); break; }
                    if (al > 0 && al < 45) c.overT = std::min(c.overT, 0.0f);
                }
            } else if (c.overMode == 3) c.latTarget = c.spinDir * 0.9f;   // рывок в сторону в своей полосе
            else c.latTarget = shoulderLat(c);
            // закончить обгон, когда свою полосу впереди освободили
            bool sideBusy = false;
            for (const AICar& o : CARS) if (o.alive && &o != &c && !o.turning && o.edge == c.edge && o.dir == c.dir && o.lane == c.lane && fabsf(o.lat) < 1.3f && o.s - c.s > -c.halfL - o.halfL - 3 && o.s - c.s < c.halfL + o.halfL + 4) sideBusy = true;
            if ((c.overT <= 0 && !sideBusy) || c.turning || distEnd < 25) { c.overMode = 0; c.latTarget = 0; }
        }
    }
    // обгон/перестроение на трассе
    if (!c.turning && e.lanes > 1 && (c.mode == CMODE_DRIVE || c.mode == CMODE_FLEE)) {
        if (gap < 35 && vl < v0 * 0.85f && c.lane == 1 && grng.chance(dt * (c.mode == CMODE_FLEE ? 4.0f : 0.8f))) tryLaneChange(c, 0);
        else if (c.lane == 0 && gap > 60 && c.mode == CMODE_DRIVE && grng.chance(dt * 0.25f)) tryLaneChange(c, 1);
        else if (c.mode == CMODE_FLEE && gap < 25 && c.lane == 0 && grng.chance(dt * 3)) tryLaneChange(c, 1);
        // беглец петляет между машинами на большой скорости — иногда задевает соседей
        if (c.mode == CMODE_FLEE && c.speed > 45 && fabsf(c.lat) > 1.5f && c.overMode == 0 && grng.chance(dt * 0.12f)) fugitiveCrash(c, 0.35f);
    }
    // объезд разбитых машин: сменить полосу, если впереди затор у места ДТП
    if (gAccActive && !c.crashed && !c.turning && e.lanes > 1 && c.mode == CMODE_DRIVE && gap < 22 && vl < 1 && dist2d(c.pos, gAccPos) < 80 && grng.chance(dt * 2)) tryLaneChange(c, c.lane == 0 ? 1 : 0);
    // беглец толкается
    if (c.mode == CMODE_FLEE && gap < 4 && c.speed < 6) { c.stuck += dt; if (c.stuck > 2.5f) { c.lat += 0; c.pressure += dt * 0.6f; } } else c.stuck = 0;
    // боковое смещение
    {   // плавное боковое движение: скорость сноса нарастает и спадает постепенно
        float tgt = c.turning ? 0 : c.latTarget;
        bool fl = c.mode == CMODE_FLEE;
        float maxV = fl ? 3.2f : 1.5f;
        float wantV = clampf((tgt - c.lat) * (fl ? 1.6f : 0.9f), -maxV, maxV);
        c.latV = approach(c.latV, wantV, (fl ? 7.0f : 2.0f) * dt);
        c.lat += c.latV * dt;
        if (fabsf(tgt - c.lat) < 0.03f && fabsf(c.latV) < 0.08f) { c.lat = tgt; c.latV = 0; }
    }
    // движение по пути
    float ds = c.speed * dt;
    if (!c.turning) {
        float prevEnd = e.slen - c.s;
        c.s += ds;
        int node = edgeEndNode(e, c.dir);
        if (NODES[node].light && prevEnd > 4.8f && e.slen - c.s <= 4.8f) {
            int st = lightState(node, lightAxisOf(e));
            if (st == 2 && c.mode == CMODE_DRIVE && dist2d(c.pos, PL.pos) < 110 && c.viol == 0) { c.viol = 3; c.violLimit = e.limitKmh; }
        }
        if (c.s >= e.slen) {
            if (c.mode == CMODE_PULLOVER || c.mode == CMODE_STOPPED) { /* продолжаем — найдём обочину дальше */ }
            beginTurn(c);
            c.tt = (c.s - e.slen) / c.tlen;
        }
    } else {
        c.tt += ds / c.tlen;
        if (c.tt >= 1) {
            float rem = (c.tt - 1) * c.tlen;
            c.edge = c.nEdge; c.dir = c.nDir; c.lane = c.nLane; c.s = rem; c.turning = false; c.lat = 0; c.latV = 0;
            c.planEdge = -1; planNext(c);
            if (c.mode == CMODE_DRIVE || c.mode == CMODE_FLEE) c.blink = 0;
        }
    }
    // поворотник при обычном перестроении
    if (c.laneBlinkT > 0) {
        c.laneBlinkT -= dt;
        if (!c.turning && c.mode == CMODE_DRIVE && c.yieldT <= 0) c.blink = c.laneBlinkT > 0 ? c.laneBlinkDir : 0;
    }
    carComputePose(c);
    // прицеп
    if (c.trailer) {
        const CarModel& T = CM[MD_TRACTOR]; const CarModel& TR = CM[MD_TRAILER];
        V3 hitch = c.pos + fwdOf(c.yaw) * T.hitchZ;
        V3 axle = c.tpos + fwdOf(c.tyaw) * (-5.0f);
        V3 d = hitch - axle; c.tyaw = atan2f(d.x, d.z);
        c.tpos = hitch - fwdOf(c.tyaw) * TR.kingpinZ;
    }
    // кузов
    float al = (c.speed - c.lastSpeed) / std::max(dt, 1e-3f); c.lastSpeed = c.speed;
    float yr = wrapAngle(c.yaw - c.lastYaw) / std::max(dt, 1e-3f); c.lastYaw = c.yaw;
    float pt = clampf(-al * 0.007f, -0.04f, 0.05f), rt = clampf(yr * c.speed * 0.01f, -0.06f, 0.06f);
    c.pv += ((pt - c.pitch) * 60 - c.pv * 8) * dt; c.pitch += c.pv * dt;
    c.rv += ((rt - c.roll) * 50 - c.rv * 7) * dt; c.roll += c.rv * dt;
    c.steerVis = approach(c.steerVis, clampf(yr * 0.35f, -0.5f, 0.5f), 2 * dt);
    float wr = CM[c.model].wheels.empty() ? 0.3f : CM[c.model].wheels[0].r;
    c.spin += c.speed * dt / wr;
    if (c.flashT > 0) c.flashT -= dt;
}

// столкновения игрока с машинами
static void collidePlayerCars(float dt) {
    (void)dt;
    V3 pc[5]; int pn = carCircles(PL.pos, PL.yaw, PL.halfW, PL.halfL, pc);
    float pmass = PATROL[SV.car].mass;
    for (size_t i = 0; i < CARS.size(); i++) {
        AICar& c = CARS[i]; if (!c.alive || c.mode == CMODE_GONE) continue;
        if (dist2d(c.pos, PL.pos) > 30 && !(c.trailer && dist2d(c.tpos, PL.pos) < 20)) continue;
        V3 cc[12]; int cn = carCircles(c.pos, c.yaw, c.halfW, c.halfL, cc); int nMain = cn;
        if (c.trailer) cn += carCircles(c.tpos, c.tyaw, CM[MD_TRAILER].halfW, CM[MD_TRAILER].halfL, cc + cn);
        float cmass = CM[c.model].mass * (c.mode == CMODE_STOPPED || c.mode == CMODE_BLOCK ? 2.5f : 1.0f);
        for (int a = 0; a < pn; a++) for (int b = 0; b < cn; b++) {
            float ra = PL.halfW * 0.95f, rb = (b < nMain ? c.halfW : CM[MD_TRAILER].halfW) * 0.95f;
            V3 d = pc[a] - cc[b]; d.y = 0; float l = len(d);
            if (l < ra + rb && l > 1e-4f) {
                V3 n = d * (1 / l); float pen = ra + rb - l;
                float wp = cmass / (pmass + cmass), wc = pmass / (pmass + cmass);
                PL.pos += n * (pen * wp);
                for (int k = 0; k < pn; k++) pc[k] += n * (pen * wp);
                if (c.mode != CMODE_BLOCK && !c.trailer) { if (!c.turning) c.lat += dot(n * (-pen * wc), rightOf(c.yaw)); }
                V3 pv = fwdOf(PL.yaw) * PL.speed, cv = fwdOf(c.yaw) * c.speed;
                float rel = dot(pv - cv, -n);
                if (rel > 0.3f) {
                    PL.speed *= 1 - 0.5f * wp;
                    c.speed = std::max(0.f, c.speed - rel * wc * 0.6f);
                    if (rel > 3 && PL.hitCooldown <= 0) {
                        sfxCrash(rel / 14); PL.hitCooldown = 0.6f; gCrashFlag = rel; gLastHitCar = (int)i;
                        if (c.mode == CMODE_FLEE) {
                            c.pressure += 1.2f + rel * 0.08f * pmass;
                            // сильный удар в угол на скорости — беглеца разворачивает (иногда разбивает)
                            float side = fabsf(dot(n, rightOf(c.yaw)));
                            if (rel > 6 && c.speed > 12 && side > 0.35f && grng.chance(0.35f)) fugitiveCrash(c, clampf(rel / 25.0f, 0.2f, 0.8f));
                        }
                        for (int k = 0; k < 6; k++) emitPart((pc[a] + cc[b]) * 0.5f + V3(0, 0.6f, 0), V3(grng.range(-2, 2), grng.range(0.5f, 2), grng.range(-2, 2)), 0.3f, 0.06f, Col(1, 0.8f, 0.3f), 1, 0, true);
                    }
                }
            }
        }
    }
}

static void updateTraffic(float dt, bool spawn) {
    if (gHornT > 0) gHornT -= dt;
    V3 center = PL.pos;
    int target = (int)clampf((districtAt(center) == 0 ? 26.f : 22.f) * trafficLevelAt(center), 9, 42);
    int alive = 0;
    for (size_t i = 0; i < CARS.size(); i++) {
        AICar& c = CARS[i]; if (!c.alive) continue;
        if (c.mode == CMODE_GONE) { c.alive = false; continue; }
        float d = dist2d(c.pos, center);
        if (c.vanish && (d > 90 || (c.modeT > 25 && R3.toView(c.pos).z < 0))) { c.alive = false; continue; }
        bool special = c.crashed || c.vanish || c.caseIdx >= 0 || (int)i == gChaseCar || c.mode == CMODE_HELPER || c.mode == CMODE_BLOCK || c.wanted;
        if (d > 470 && !special) { c.alive = false; continue; }
        if (d > 900) { c.alive = false; continue; }
        alive++;
        updateAICar(c, (int)i, dt);
        // дым из выхлопной трубы у ближних машин
        if (d < 45) {
            c.exhaustT -= dt;
            if (c.exhaustT <= 0) {
                c.exhaustT = 0.15f + grng.f() * 0.1f;
                const CarModel& M = CM[c.model];
                if (M.exhaust.y > 0) {
                    Mat3 rot = rotYPR(c.yaw, 0, 0);
                    bool heavy = c.model == MD_TRUCK || c.model == MD_TRACTOR;
                    V3 vel = heavy ? V3(0, 1.2f, 0) : fwdOf(c.yaw) * -0.8f + V3(0, 0.2f, 0);
                    emitPart(mul(rot, M.exhaust) + c.pos, vel, heavy ? 1.6f : 0.9f, heavy ? 0.2f : 0.1f, heavy ? Col(0.35f, 0.35f, 0.37f) : Col(0.65f, 0.65f, 0.67f), heavy ? 0.35f : 0.18f, 0.6f);
                }
            }
        }
    }
    // страховка от «въезда друг в друга»: у каждой машины перед бампером «щуп»; если он задевает
    // другую машину (в любом направлении) — стоп. Если две машины упёрлись друг в друга носами,
    // уступает та, у которой соседка прямо по курсу, а вторая медленно проезжает, пока нет касания кузовом.
    auto boxHit = [](const V3& ap, float ayaw, float ahl, float ahw, float probe, const V3& bp, float byaw, float bhl, float bhw) {
        V3 fa = fwdOf(ayaw), ra = rightOf(ayaw), fb = fwdOf(byaw), rb = rightOf(byaw);
        V3 ac = ap + fa * (probe * 0.5f); float hl = ahl + probe * 0.5f;
        V3 dc = bp - ac;
        V3 axes[4] = {fa, ra, fb, rb};
        for (int ax = 0; ax < 4; ax++) {
            V3 n = axes[ax];
            float r1 = fabsf(dot(fa, n)) * hl + fabsf(dot(ra, n)) * ahw;
            float r2 = fabsf(dot(fb, n)) * bhl + fabsf(dot(rb, n)) * bhw;
            if (fabsf(dot(dc, n)) > r1 + r2) return false;
        }
        return true;
    };
    for (size_t i = 0; i < CARS.size(); i++) {
        AICar& a = CARS[i];
        if (!a.alive || a.crashed || a.mode == CMODE_HELPER || a.mode == CMODE_STOPPED || a.mode == CMODE_BLOCK) continue;
        if (dist2d(a.pos, center) > 300) continue;
        V3 fa = fwdOf(a.yaw);
        float probe = 0.5f + a.speed * 0.25f;
        for (size_t j = 0; j < CARS.size(); j++) {
            if (i == j) continue;
            const AICar& b = CARS[j];
            if (!b.alive || b.mode == CMODE_HELPER || b.mode == CMODE_GONE) continue;
            for (int k = 0; k < (b.trailer ? 2 : 1); k++) {
                V3 bp = k == 0 ? b.pos : b.tpos; float byaw = k == 0 ? b.yaw : b.tyaw;
                float bhl = k == 0 ? b.halfL : CM[MD_TRAILER].halfL, bhw = k == 0 ? b.halfW : CM[MD_TRAILER].halfW;
                V3 d = bp - a.pos; float dl = len(d);
                if (dl > a.halfL + bhl + probe + 2.0f) continue;
                if (dot(d, fa) <= 0.3f) continue;          // сзади или вровень — не наша забота
                if (!boxHit(a.pos, a.yaw, a.halfL, a.halfW * 0.95f, probe, bp, byaw, bhl, bhw * 0.95f)) continue;
                bool touching = boxHit(a.pos, a.yaw, a.halfL, a.halfW * 0.95f, 0.15f, bp, byaw, bhl, bhw * 0.95f);
                if (!touching && k == 0 && dot(fwdOf(b.yaw), fa) < 0.5f) {
                    // встречное упирание: проверить, видит ли b нас своим щупом
                    float pb = 0.5f + b.speed * 0.25f;
                    V3 db = a.pos - b.pos;
                    if (dot(db, fwdOf(b.yaw)) > 0.3f && boxHit(b.pos, b.yaw, b.halfL, b.halfW * 0.95f, pb, a.pos, a.yaw, a.halfL, a.halfW * 0.95f)) {
                        float aheadA = dot(d, fa) / std::max(dl, 0.1f), aheadB = dot(db, fwdOf(b.yaw)) / std::max(dl, 0.1f);
                        bool aYields = aheadA > aheadB + 0.02f || (fabsf(aheadA - aheadB) <= 0.02f && a.id > b.id);
                        if (!aYields) continue;               // проезжаем первыми, пока не коснулись
                    }
                }
                float vb = k == 0 ? b.speed * std::max(0.f, dot(fwdOf(byaw), fa)) : 0;
                if (touching) vb = 0;
                a.speed = std::min(a.speed, vb); a.brake = true;
                a.holdV = a.holdV < 0 ? vb : std::min(a.holdV, vb);
            }
        }
    }
    if (spawn) {
        int tries = 0;
        while (alive < target && tries < 2) { if (spawnTrafficCar(center, 110, 380, true) >= 0) alive++; tries++; }
    }
}

static void drawAICar(const AICar& c, float time, bool highlight) {
    DrawCar d;
    d.pos = c.pos; d.yaw = c.yaw; d.pitch = c.pitch; d.roll = c.roll; d.paint = c.paint; d.paint2 = c.paint2;
    d.plate = c.plate; d.taxi = c.taxi; d.police = c.police || c.mode == CMODE_HELPER || c.mode == CMODE_BLOCK;
    d.flash = d.police; d.headOn = (L.night > 0.35f || L.rain > 0.5f) && !(c.vice == 3 && c.mode == CMODE_DRIVE); d.brake = c.brake; d.blink = c.blink;
    d.spin = c.spin; d.steer = c.steerVis; d.time = time + (c.id % 7) * 0.13f; d.highlight = highlight;
    d.flatMask = c.flatMask;
    if (c.flatMask) {   // крен на сторону спущенных колёс
        const CarModel& MM = CM[c.model]; float rl = 0, pt = 0;
        for (size_t wi = 0; wi < MM.wheels.size() && wi < 8; wi++) if ((c.flatMask >> wi) & 1) { rl += MM.wheels[wi].p.x > 0 ? 1.f : -1.f; pt += MM.wheels[wi].p.z > 0 ? 1.f : -1.f; }
        d.roll += rl * 0.035f; d.pitch += pt * 0.02f;
    }
    // тень
    float dist = dist2d(c.pos, R3.pos);
    if (dist < 150) {
        const CarModel& M = CM[c.model];
        V3 f = fwdOf(c.yaw), r = rightOf(c.yaw);
        R3.groundSprite(c.pos + V3(0, 0.08f, 0) + f * ((M.maxZ + M.minZ) * 0.5f), r * (M.halfW * 1.35f), f * (M.halfL * 1.15f), RGBA(0, 0, 0, (int)(150 * (1 - L.night * 0.5f))), 0, 0);
        if (c.trailer) R3.groundSprite(c.tpos + V3(0, 0.08f, 0), rightOf(c.tyaw) * 1.6f, fwdOf(c.tyaw) * 7.4f, RGBA(0, 0, 0, (int)(150 * (1 - L.night * 0.5f))), 0, 0);
    }
    drawCarModel(c.model, d);
    if (c.trailer) {
        DrawCar t = d; t.pos = c.tpos; t.yaw = c.tyaw; t.pitch = 0; t.roll = c.roll * 0.5f; t.plate = c.plate; t.highlight = false;
        drawCarModel(MD_TRAILER, t);
    }
    if (c.flashT > 0) R3.billboard(c.pos + V3(0, 2.5f, 0), 3, 3, RGBA(255, 255, 255, 255), 0, 3, -2);
}

static void drawPlayerCar(float time, bool cockpit) {
    DrawCar d;
    d.pos = PL.pos; d.yaw = PL.yaw; d.pitch = PL.pitch; d.roll = PL.roll;
    d.paint = Col(0.95f, 0.95f, 0.96f); d.police = true; d.flash = PL.flash; d.headOn = L.night > 0.3f || L.rain > 0.4f;
    d.brake = PL.brakeLight; d.reverse = PL.reverse; d.spin = PL.spin; d.steer = PL.steer; d.time = time; d.plate = 2;
    d.hideBody = cockpit;
    const CarModel& M = CM[PATROL[SV.car].model];
    if (!cockpit) {
        V3 f = fwdOf(PL.yaw), r = rightOf(PL.yaw);
        R3.groundSprite(PL.pos + V3(0, 0.08f, 0) + f * ((M.maxZ + M.minZ) * 0.5f), r * (M.halfW * 1.35f), f * (M.halfL * 1.15f), RGBA(0, 0, 0, (int)(160 * (1 - L.night * 0.5f))), 0, 0);
    }
    drawCarModel(PATROL[SV.car].model, d);
    if (PL.flash && L.night > 0.3f) {
        bool ph = fmodf(time, 0.5f) < 0.25f;
        R3.groundSprite(PL.pos + V3(0, 0.07f, 0), V3(7, 0, 0), V3(0, 0, 7), ph ? RGBA(120, 10, 10) : RGBA(10, 30, 140), 1, 0);
    }
}

// блокпост: две машины поперёк и барьеры
static void drawRoadblock(float time) {
    if (!gBlock.active) return;
    V3 f = fwdOf(gBlock.yaw), r = rightOf(gBlock.yaw);
    for (int k = -1; k <= 1; k += 2) {
        DrawCar d; d.pos = gBlock.pos + r * (k * 3.2f + 1.5f); d.yaw = gBlock.yaw + PI / 2 * k; d.police = true; d.flash = true; d.time = time + k; d.paint = Col(0.95f, 0.95f, 0.96f); d.plate = 3;
        d.headOn = L.night > 0.3f;
        drawCarModel(MD_SEDAN, d);
    }
    for (int i = -3; i <= 3; i++) {
        V3 p = gBlock.pos + r * (i * 2.0f + 1.5f) - f * 6;
        shadedBox(p + V3(0, 0.5f, 0), V3(0.9f, 0.18f, 0.05f), gBlock.yaw, (i & 1) ? Col(0.9f, 0.1f, 0.1f) : Col(0.95f, 0.95f, 0.95f));
        shadedBox(p + V3(0, 0.25f, 0), V3(0.05f, 0.25f, 0.2f), gBlock.yaw, Col(0.3f, 0.3f, 0.3f));
    }
    (void)f;
}

// камеры скорости в мире
static void camWorldPos(const Camera_& c, V3& pos, float& yaw) {
    const Edge& e = EDGES[c.edge];
    V3 st, f, r; float y; laneFrame(e, c.dir, st, f, r, y);
    pos = st + f * c.s + r * (e.halfW + (e.highway ? 3.0f : e.sidewalk - 0.5f)); yaw = y;
}
static void drawSpeedCams(float time) {
    (void)time;
    for (const Camera_& c : SPEEDCAMS) {
        V3 p; float y; camWorldPos(c, p, y);
        float d = dist2d(p, R3.pos); if (d > 250) continue;
        if (!R3.sphereVisible(p + V3(0, 3, 0), 4)) continue;
        shadedBox(p + V3(0, 2.5f, 0), V3(0.08f, 2.5f, 0.08f), y, Col(0.55f, 0.55f, 0.58f));
        V3 f = fwdOf(y);
        shadedBox(p + V3(0, 5.1f, 0) - f * 0.1f, V3(0.25f, 0.2f, 0.4f), y, Col(0.9f, 0.9f, 0.9f));
        shadedBox(p + V3(0, 5.1f, 0) - f * 0.55f, V3(0.12f, 0.1f, 0.06f), y, Col(0.05f, 0.05f, 0.05f));
        // знак «фотофиксация»
        shadedBox(p + V3(0, 3.2f, 0) - f * 0.12f, V3(0.3f, 0.3f, 0.02f), y, Col(0.15f, 0.35f, 0.75f));
    }
}

