enum Art { ART_SPEED, ART_RED, ART_OSAGO, ART_BELT, ART_PHONE, ART_TINT, ART_SHOULDER, ART_SIGNAL, ART_LIGHTS, ART_N };
static const char* ART_NAMES[ART_N] = {"СТ. 12.9 ПРЕВЫШЕНИЕ СКОРОСТИ", "СТ. 12.12 ПРОЕЗД НА КРАСНЫЙ", "СТ. 12.37 НАРУШЕНИЕ ОСАГО", "СТ. 12.6 НЕ ПРИСТЁГНУТ РЕМЕНЬ", "СТ. 12.36.1 ТЕЛЕФОН ЗА РУЛЁМ", "СТ. 12.5 Ч.3.1 ТОНИРОВКА", "СТ. 12.15 Ч.1 ЕЗДА ПО ОБОЧИНЕ", "СТ. 12.14 Ч.1 БЕЗ ПОВОРОТНИКА", "СТ. 12.20 НЕ ВКЛЮЧЕНЫ ФАРЫ"};
static const char* ART_SHORT[ART_N] = {"12.9", "12.12", "12.37", "12.6", "12.36.1", "12.5", "12.15", "12.14", "12.20"};
