static int gTarget = -1;      // машина-цель (подсвечена)
static int gInspect = -1;     // осматриваемая машина
static void drawWorldScene(float dt, bool drawPlayer, bool cockpit) {
    L.hlOn = (L.night > 0.4f) ? 1.0f : 0.0f;
    const CarModel& M = CM[PATROL[SV.car].model];
    L.hlPos = PL.pos + fwdOf(PL.yaw) * M.maxZ + V3(0, 0.7f, 0); L.hlDir = fwdOf(PL.yaw);
    drawSky();
    UI.flush();
    drawGround();
    drawRoads();
    drawStatic();
    drawGuardRails();
    for (const Ped& p : PEDS) if (p.alive) drawPed(p);
    for (size_t i = 0; i < CARS.size(); i++) if (CARS[i].alive) drawAICar(CARS[i], gTime, (int)i == gTarget);
    drawRoadblock(gTime);
    drawAccidentWorld();
    drawSpeedCams(gTime);
    if (drawPlayer) drawPlayerCar(gTime, cockpit);
    drawParts();
    R3.draw();
    (void)dt;
}

// ---------------------------------------------------------------------
//  Сохранение
// ---------------------------------------------------------------------
static void saveGame() {
    if (gSavePath.empty()) return;
    FILE* f = fopen(gSavePath.c_str(), "w");
    if (!f) return;
    fprintf(f, "money %d\nrep %d\nday %d\nowned %d\ncar %d\n", SV.money, SV.rep, SV.day, SV.carOwned, SV.car);
    for (int i = 0; i < U_COUNT; i++) fprintf(f, "upg%d %d\n", i, SV.upg[i]);
    fprintf(f, "complaints %d\nchecks %d\nfines %d\ndetain %d\nchases %d\ncorrect %d\nwrong %d\n", SV.complaints, SV.totalChecks, SV.totalFines, SV.totalDetain, SV.totalChases, SV.totalCorrect, SV.totalWrong);
    fprintf(f, "fuel %d\n", (int)(SV.fuel * 10));
    fprintf(f, "sound %d\ncamview %d\ndistrict %d\ntutorial %d\n", SV.sound ? 1 : 0, SV.camView, SV.lastDistrict, SV.tutorialShown ? 1 : 0);
    fprintf(f, "steermul %d\ngripmul %d\nsteerspd %d\nassist %d\ntilt %d\ntiltinv %d\ntiltsens %d\n", (int)(SV.steerMul * 100), (int)(SV.gripMul * 100), (int)(SV.steerSpd * 100), SV.laneAssist ? 1 : 0, SV.tilt ? 1 : 0, SV.tiltInv ? 1 : 0, (int)(SV.tiltSens * 100));
    for (const Camera_& c : SPEEDCAMS) fprintf(f, "cam %d %d %.1f\n", c.edge, c.dir, c.s);
    fclose(f);
}
static void loadGame() {
    if (gSavePath.empty()) return;
    FILE* f = fopen(gSavePath.c_str(), "r");
    if (!f) return;
    char key[64]; SPEEDCAMS.clear();
    while (fscanf(f, "%63s", key) == 1) {
        if (!strcmp(key, "cam")) { Camera_ c; if (fscanf(f, "%d %d %f", &c.edge, &c.dir, &c.s) == 3 && c.edge >= 0 && c.edge < (int)EDGES.size()) SPEEDCAMS.push_back(c); continue; }
        int v = 0; if (fscanf(f, "%d", &v) != 1) break;
        if (!strcmp(key, "money")) SV.money = v; else if (!strcmp(key, "rep")) SV.rep = v; else if (!strcmp(key, "day")) SV.day = std::max(1, v);
        else if (!strcmp(key, "owned")) SV.carOwned = v | 1; else if (!strcmp(key, "car")) SV.car = clampf((float)v, 0, PATROL_N - 1);
        else if (!strncmp(key, "upg", 3)) { int i = atoi(key + 3); if (i >= 0 && i < U_COUNT) SV.upg[i] = std::max(0, std::min(3, v)); }
        else if (!strcmp(key, "complaints")) SV.complaints = v; else if (!strcmp(key, "checks")) SV.totalChecks = v; else if (!strcmp(key, "fines")) SV.totalFines = v;
        else if (!strcmp(key, "detain")) SV.totalDetain = v; else if (!strcmp(key, "chases")) SV.totalChases = v; else if (!strcmp(key, "correct")) SV.totalCorrect = v;
        else if (!strcmp(key, "wrong")) SV.totalWrong = v; else if (!strcmp(key, "sound")) SV.sound = v != 0; else if (!strcmp(key, "camview")) SV.camView = v;
        else if (!strcmp(key, "fuel")) SV.fuel = clampf(v / 10.f, 0, 60);
        else if (!strcmp(key, "steermul")) SV.steerMul = clampf(v / 100.f, 0.4f, 2.0f);
        else if (!strcmp(key, "gripmul")) SV.gripMul = clampf(v / 100.f, 0.5f, 2.0f);
        else if (!strcmp(key, "steerspd")) SV.steerSpd = clampf(v / 100.f, 0.3f, 2.5f);
        else if (!strcmp(key, "tiltsens")) SV.tiltSens = clampf(v / 100.f, 0.3f, 2.5f);
        else if (!strcmp(key, "assist")) SV.laneAssist = v != 0;
        else if (!strcmp(key, "tilt")) SV.tilt = v != 0;
        else if (!strcmp(key, "tiltinv")) SV.tiltInv = v != 0;
        else if (!strcmp(key, "district")) SV.lastDistrict = std::max(0, std::min(3, v)); else if (!strcmp(key, "tutorial")) SV.tutorialShown = v != 0;
    }
    fclose(f);
    if (!(SV.carOwned & (1 << SV.car))) SV.car = 0;
}

// ---------------------------------------------------------------------
//  Начало / конец смены
// ---------------------------------------------------------------------
static void clearWorldActors() {
    for (AICar& c : CARS) c.alive = false;
    CARS.clear(); CASES.clear(); PARTS.clear(); PEDS.clear();
    gChaseCar = -1; gBlock.active = false; gTarget = -1; gInspect = -1;
    ACC = Accident(); gAccActive = false;
}
static void startShift() {
    clearWorldActors();
    SHF = ShiftState();
    for (int k = 0; k < PK_N; k++) gProbSeenShift[k] = false;
    SHF.active = true; SHF.district = gPlannedDistrict; SHF.night = gPlannedNight; SHF.weather = gPlannedWeather;
    SHF.startMin = SHF.night ? 20 * 60 : 8 * 60; SHF.minutes = SHF.startMin; SHF.endMin = SHF.startMin + 8 * 60;
    SHF.lastCamMin = SHF.minutes; SHF.nextWanted = SHF.minutes + 50 + grng.i(60);
    SHF.startRank = rankOf(SV.rep); SHF.startMoney = SV.money;
    SHF.tutorial = !SV.tutorialShown; SHF.tutStep = 0;
    genTasks();
    TOASTS.clear();
    gNextAccMin = SHF.minutes + 25 + grng.i(35);
    SV.lastDistrict = SHF.district;
    const Post& P = POSTS[SHF.district];
    PL = PlayerCar(); playerSetCar();
    PL.pos = P.pos; PL.yaw = P.yaw;
    gCamMode = SV.camView;
    gWorldTime = grng.range(0, 100);
    gHour = SHF.minutes / 60.0f;
    updateLighting(fmodf(gHour, 24), SHF.weather);
    updateCamera(0, true);
    // начальный трафик
    gClockMin = SHF.minutes;
    { int n0 = (int)clampf(24 * trafficLevelAt(PL.pos), 8, 40); for (int i = 0; i < n0; i++) spawnTrafficCar(PL.pos, 40, 380, false); }
    platePixels(2, "А0166", 66, true); platePixels(3, "А0266", 66, true);
    gScreen = SC_DRIVE;
    toast(fmt("СМЕНА НАЧАЛАСЬ. УЧАСТОК: %s. ТРАФИК %s — ДОХОД X%.2f", DISTRICT_NAMES[SHF.district], trafficName(trafficLevelAt(PL.pos)), payMulAt(PL.pos)), 0, 5);
    if (SHF.tutorial) toast("ПОДСКАЗКА: НАЙДИ НАРУШИТЕЛЯ РАДАРОМ, ВКЛЮЧИ МИГАЛКУ И НАЖМИ «ТРЕБОВАТЬ»", 3, 7);
    sfx(SFX_RADIO, 0.6f, 0, 0, 1.2f);
}
static void endShift() {
    SHF.active = false;
    // зарплата
    int salary = 2500 + rankOf(SV.rep) * 400;
    if (SHF.night) salary += 800;
    float worked = clampf((SHF.minutes - SHF.startMin) / (SHF.endMin - SHF.startMin), 0, 1);
    salary = (int)(salary * worked);
    for (Task& t : SHF.tasks) if (t.type == T_NOERR && !t.done && SHF.wrong == 0 && SHF.checks >= 3 && worked > 0.95f) { t.done = true; SHF.bonus += t.reward; SV.money += t.reward; }
    SV.money += salary; SHF.bonus += 0;
    SHF.camIncome += 0;
    SHF.penalties += 0;
    SHF.checks += 0;
    SHF.startMoney = SV.money - SHF.startMoney;  // теперь — итог за смену
    SHF.lastCamMin = (float)salary;             // сохраняем зарплату для экрана итогов
    SV.day++;
    sfx(SFX_SUCCESS);
    saveGame();
    gScreen = SC_SUMMARY;
}

// ---------------------------------------------------------------------
//  Логика остановки
// ---------------------------------------------------------------------
static float gRadarSpeed = -1; static int gRadarCar = -1; static float gRadarLimit = 60;
static float gDemandCooldown = 0; static float gHelpCooldown = 0, gBlockCooldown = 0; static bool gHelpUsed = false, gBlockUsed = false;
static float gChaseFarT = 0; static float gCrashRepCd = 0; static float gTutHintT = 0;
static std::string gSubtitle; static float gSubtitleT = 0;

static void subtitle(const std::string& s, float t = 2.5f) { gSubtitle = s; gSubtitleT = t; }

static int gManualTarget = -1; static uint32_t gManualId = 0;
static bool targetable(const AICar& c, int i) {
    if (!c.alive || c.mode == CMODE_HELPER || c.mode == CMODE_BLOCK || c.mode == CMODE_GONE || c.mode == CMODE_STOPPED || c.mode == CMODE_PULLOVER || c.mode == CMODE_LEAVE) return false;
    if (i == gChaseCar || c.checked || c.vanish) return false;
    return true;
}
static void pickTarget() {
    gTarget = -1;
    // цель, выбранная касанием, — в приоритете
    if (gManualTarget >= 0) {
        if (gManualTarget < (int)CARS.size() && CARS[gManualTarget].id == gManualId && targetable(CARS[gManualTarget], gManualTarget) && dist2d(CARS[gManualTarget].pos, PL.pos) < 100) { gTarget = gManualTarget; return; }
        gManualTarget = -1;
    }
    float best = 1e9f;
    V3 f = fwdOf(PL.yaw);
    bool parked = fabsf(PL.speed) < 1.5f;
    for (size_t i = 0; i < CARS.size(); i++) {
        const AICar& c = CARS[i];
        if (!targetable(c, (int)i)) continue;
        V3 d = c.pos - PL.pos; float dd = len(d);
        if (dd > (parked ? 50.f : 80.f) || dd < 2) continue;
        float cs = dot(d * (1 / dd), f);
        // рядом (до 25 м) — в любом направлении, дальше — в широком конусе впереди
        if (dd > 25 && cs < (parked ? -0.2f : 0.3f)) continue;
        float score = dd * (c.viol > 0 || c.seen ? 0.4f : 1.0f) * (c.wanted ? 0.3f : 1.0f) * (cs > 0.8f ? 0.8f : 1.0f);
        if (score < best) { best = score; gTarget = (int)i; }
    }
}

static void updateRadar() {
    gRadarSpeed = -1; gRadarCar = -1;
    float range = RADAR_RANGE[SV.upg[U_RADAR]];
    V3 f = fwdOf(PL.yaw);
    float best = 1e9f;
    for (size_t i = 0; i < CARS.size(); i++) {
        AICar& c = CARS[i]; if (!c.alive || c.mode != CMODE_DRIVE) continue;
        V3 d = c.pos - PL.pos; float dd = len(d);
        if (dd > range || dd < 3) continue;
        float cs = dot(d * (1 / dd), f); if (cs < 0.93f) continue;
        if (dd < best) { best = dd; gRadarCar = (int)i; }
    }
    {   // замеченные нарушения ПДД
        bool dark = L.night > 0.35f || L.rain > 0.5f;
        for (AICar& c : CARS) {
            if (!c.alive || c.mode != CMODE_DRIVE) continue;
            if (c.vice == 3 && dark && dist2d(c.pos, PL.pos) < 70 && R3.sphereVisible(c.pos + V3(0, 1, 0), 2.5f)) c.seen |= 4;
            uint8_t nw = c.seen & ~c.seenToast;
            if (!nw) continue;
            c.seenToast |= nw;
            if (nw & 1) toast("НАРУШЕНИЕ: ОБЪЕЗД ПО ОБОЧИНЕ! МОЖНО ОСТАНОВИТЬ.", 2, 2.5f);
            else if (nw & 2) toast("НАРУШЕНИЕ: ПЕРЕСТРОЕНИЕ БЕЗ ПОВОРОТНИКА!", 2, 2.5f);
            else if (nw & 4) toast("НАРУШЕНИЕ: ЕДЕТ БЕЗ ФАР!", 2, 2.5f);
        }
    }
    if (gRadarCar >= 0) {
        AICar& c = CARS[gRadarCar];
        const Edge& e = EDGES[c.edge];
        gRadarSpeed = c.speed * 3.6f; gRadarLimit = e.limitKmh;
        float over = gRadarSpeed - e.limitKmh;
        if (over > 10 && c.viol != 3) { if (c.viol != 2) toast(fmt("РАДАР: %d КМ/Ч ПРИ ОГРАНИЧЕНИИ %d!", (int)gRadarSpeed, (int)e.limitKmh), 2, 2.5f); c.viol = 2; c.violSpeed = std::max(c.violSpeed, gRadarSpeed); c.violLimit = e.limitKmh; }
        else if (over > 3 && c.viol == 0) { c.viol = 1; c.violSpeed = gRadarSpeed; c.violLimit = e.limitKmh; }
    }
}

static bool seriousIssue(const Case& c) { return c.lForged || c.wanted || c.contraband || c.deprived || c.plateMismatch || c.otherPerson; }

static void demandStop() {
    if (gTarget < 0 || gDemandCooldown > 0) return;
    AICar& c = CARS[gTarget];
    gDemandCooldown = 2.0f;
    bool parked = fabsf(PL.speed) < 1.5f;
    if (parked) { sfx(SFX_WHISTLE, 0.7f); subtitle("ИНСПЕКТОР ПОКАЗЫВАЕТ ЖЕЗЛОМ: К ОБОЧИНЕ!"); }
    else { sfx(SFX_SPEECH, 0.9f, 115, 0, 1.6f); subtitle(fmt("«ВОДИТЕЛЬ %s %s, ПРИЖМИТЕСЬ К ОБОЧИНЕ!»", CM[c.model].name.c_str(), c.plateStr.c_str())); }
    c.demands++; c.reactT = 1.3f;
}

static void startChase(int idx) {
    AICar& c = CARS[idx];
    c.mode = CMODE_FLEE; c.modeT = 0; c.pressure = 0; c.trail.clear(); c.blink = 0; c.latTarget = 0;
    gChaseCar = idx; gChaseFarT = 0; gHelpUsed = false; gBlockUsed = false; gHelpCooldown = 0; gBlockCooldown = 0;
    SHF.chases++; SV.totalChases++;
    if (c.wanted || (c.caseIdx >= 0 && CASES[c.caseIdx].wanted)) toast("УГНАННАЯ МАШИНА УХОДИТ! ПОГОНЯ! БЛОКПОСТ РАЗРЕШЁН.", 2, 4);
    else if (c.racer) toast("СТРИТРЕЙСЕР УХОДИТ! ПОГОНЯ! БЛОКПОСТ РАЗРЕШЁН.", 2, 4);
    else toast("НАРУШИТЕЛЬ ПЫТАЕТСЯ СКРЫТЬСЯ! ПОГОНЯ!", 2, 3.5f);
    sfx(SFX_RADIO, 0.6f);
    if (!PL.siren) { PL.siren = true; PL.flash = true; }
}
static void endChase(bool success) {
    if (gChaseCar < 0) return;
    AICar& c = CARS[gChaseCar];
    for (AICar& h : CARS) if (h.alive && h.mode == CMODE_HELPER) h.mode = CMODE_GONE;
    gBlock.active = false;
    if (success) {
        c.mode = CMODE_PULLOVER; c.caught = true; c.speed = std::min(c.speed, 12.f);
        if (c.wrecked) { c.mode = CMODE_STOPPED; c.speed = 0; c.blink = 2; }
        c.overMode = 0; c.latTarget = c.wrecked ? c.lat : c.latTarget; c.yawOff = c.wrecked ? c.yawOff : 0; c.spinT = 0;
        if (c.caseIdx < 0) c.caseIdx = createCase(gChaseCar, 0);
        Case& cs = CASES[c.caseIdx]; cs.fled = true; computeTruth(cs);
        SHF.chaseWins++;
        toast("НАРУШИТЕЛЬ ОСТАНОВЛЕН! ПРОВЕРЬ ДОКУМЕНТЫ.", 1, 4);
        taskProgress(T_CATCH);
        sfx(SFX_SUCCESS);
    } else {
        c.alive = false;
        toast("НАРУШИТЕЛЬ СКРЫЛСЯ. ПОГОНЯ ПРОВАЛЕНА.", 2, 4);
        addRep(-5); sfx(SFX_ERROR);
    }
    gChaseCar = -1;
}

static void requestHelp() {
    if (gChaseCar < 0 || gHelpUsed) return;
    AICar& t = CARS[gChaseCar];
    if (t.trail.size() < 4) { toast("РАЦИЯ: УТОЧНИТЕ НАПРАВЛЕНИЕ...", 3); return; }
    AICar h; h.alive = true; h.id = gCarIdCounter++; h.model = MD_SEDAN; h.police = true; h.paint = Col(0.95f, 0.95f, 0.96f);
    h.mode = CMODE_HELPER; h.helperTarget = gChaseCar;
    int start = 0;
    for (int k = (int)t.trail.size() - 1; k >= 0; k--) { if (dist2d(t.trail[k], t.pos) > 35 && dist2d(t.trail[k], PL.pos) > 30) { start = k; break; } }
    h.pos = t.trail[start]; h.trailIdx = start + 1;
    V3 d = t.trail[std::min((int)t.trail.size() - 1, start + 1)] - h.pos; h.yaw = atan2f(d.x, d.z);
    h.speed = t.speed; h.halfW = CM[MD_SEDAN].halfW; h.halfL = CM[MD_SEDAN].halfL; h.plate = 3; h.plateStr = "А0266";
    CARS.push_back(h);
    gHelpUsed = true;
    toast("РАЦИЯ: ЭКИПАЖ 2-14 ПОДКЛЮЧИЛСЯ К ПРЕСЛЕДОВАНИЮ!", 3, 4);
    sfx(SFX_RADIO, 0.7f, 0, 0, 1.4f);
}
// блокпост выставляют только для угнанных/разыскиваемых машин и стритрейсеров
static bool roadblockAllowed() {
    if (gChaseCar < 0 || gChaseCar >= (int)CARS.size()) return false;
    const AICar& c = CARS[gChaseCar];
    if (c.wanted || c.racer) return true;
    return c.caseIdx >= 0 && c.caseIdx < (int)CASES.size() && CASES[c.caseIdx].wanted;
}
static void requestRoadblock() {
    if (gChaseCar < 0 || gBlockUsed || !roadblockAllowed()) return;
    AICar& t = CARS[gChaseCar];
    int edge, dir; float s;
    if (!t.turning && EDGES[t.edge].slen - t.s > 200) { edge = t.edge; dir = t.dir; s = t.s + 170; }
    else {
        if (t.planEdge < 0) planNext(t);
        edge = t.turning ? t.nEdge : t.planEdge; dir = t.turning ? t.nDir : t.planDir;
        s = std::min(120.f, EDGES[edge].slen * 0.6f);
    }
    const Edge& e = EDGES[edge];
    V3 st, f, r; float y; laneFrame(e, dir, st, f, r, y);
    gBlock.active = true; gBlock.edge = edge; gBlock.dir = dir; gBlock.s = s; gBlock.yaw = y;
    gBlock.pos = st + f * s + r * (e.halfW * 0.5f);
    gBlock.pos = st + f * s + r * (e.halfW * 0.5f) - r * 1.5f;
    gBlockUsed = true;
    toast("РАЦИЯ: БЛОКПОСТ ВЫСТАВЛЕН ВПЕРЕДИ ПО ХОДУ!", 3, 4);
    sfx(SFX_RADIO, 0.7f, 0, 0, 1.4f);
}

static void spawnWanted() {
    int idx = spawnTrafficCar(PL.pos, 160, 330, false);
    if (idx < 0) return;
    AICar& c = CARS[idx];
    c.wanted = true;
    SHF.wantedCar = idx;
    SHF.wantedDesc = fmt("%s, %s, %s %d", CM[c.model].name.c_str(), colorName(c.paint), c.plateStr.c_str(), c.region);
    toast("ОРИЕНТИРОВКА: РАЗЫСКИВАЕТСЯ " + SHF.wantedDesc, 3, 7);
    sfx(SFX_RADIO, 0.7f, 0, 0, 2.0f);
}

static void reactToDemand(int idx) {
    AICar& c = CARS[idx];
    if (c.caseIdx < 0) {
        int reason = 0;
        if (c.viol == 2) reason = 2; else if (c.viol == 3) reason = 3; else if (c.seen) reason = 4; else if (c.viol == 1) reason = 1;
        c.caseIdx = createCase(idx, reason);
    }
    Case& cs = CASES[c.caseIdx];
    float lightsK = SV.upg[U_LIGHTS] * 0.05f;
    float pFlee = 0.04f + (seriousIssue(cs) ? 0.4f : 0) + (c.wanted ? 0.3f : 0) + (c.racer ? 0.3f : 0) - lightsK + (c.demands > 1 ? 0.15f : 0);
    float pIgnore = (PL.flash ? 0.1f : 0.32f) - lightsK + (c.demands > 2 ? -0.2f : 0);
    if (c.trailer || c.model == MD_TRUCK) pFlee *= 0.2f;
    // задание «поймай беглеца» — чаще бегут
    for (Task& t : SHF.tasks) if (t.type == T_CATCH && !t.done && SHF.chases == 0) pFlee += 0.12f;
    float r = grng.f();
    if (r < pFlee) { startChase(idx); return; }
    if (r < pFlee + pIgnore) { c.ignoring = true; toast("ВОДИТЕЛЬ ДЕЛАЕТ ВИД, ЧТО НЕ ЗАМЕТИЛ...", 0, 2.5f); return; }
    c.mode = CMODE_PULLOVER; c.modeT = 0; c.ignoring = false; c.yieldT = 0;
    if (c.viol == 1 || c.viol == 2) { SHF.speeders++; taskProgress(T_SPEEDERS); }
    toast("ВОДИТЕЛЬ ОСТАНАВЛИВАЕТСЯ.", 0, 2);
}

static void finishInspection(int verdict, bool* arts, std::string& outTitle, std::vector<std::string>& outLines, int& moneyD, int& repD, bool& good) {
    AICar& car = CARS[gInspect];
    Case& c = CASES[car.caseIdx];
    computeTruth(c);
    c.decided = true; car.checked = true;
    SHF.checks++; SV.totalChecks++; taskProgress(T_CHECK);
    moneyD = 0; repD = 0; good = false;
    int need = c.needLevel;
    bool artOk = true; int artHit = 0, artNeed = 0, artExtra = 0;
    if (verdict == V_FINE) {
        for (int i = 0; i < ART_N; i++) { if (c.needArt[i]) artNeed++; if (arts[i] && c.needArt[i]) artHit++; if (arts[i] && !c.needArt[i]) artExtra++; }
        artOk = (artHit == artNeed && artExtra == 0);
    }
    outLines.clear();
    bool acceptable = (verdict == need) || (need == V_WARN && verdict == V_FINE && arts[ART_SPEED] && artExtra == 0);
    if (verdict == V_FINE && need == V_FINE && !artOk) acceptable = false;
    if (acceptable) {
        good = true;
        static const int rewards[5] = {150, 250, 450, 900, 1600};
        static const int reps[5] = {2, 3, 4, 6, 9};
        moneyD = rewards[verdict]; repD = reps[verdict];
        if (verdict == V_FINE) {
            int sum = 0;
            for (int i = 0; i < ART_N; i++) if (arts[i]) {
                int a = i == ART_SPEED ? ((c.violSpeed - c.violLimit) > 40 ? 1500 : 500) : (i == ART_RED ? 1000 : (i == ART_OSAGO ? 800 : (i == ART_PHONE || i == ART_SHOULDER ? 1500 : (i == ART_TINT || i == ART_SIGNAL || i == ART_LIGHTS ? 500 : 1000))));
                sum += a;
            }
            moneyD += sum / 10; SHF.fines++; SHF.finesSum += sum; SV.totalFines++; taskProgress(T_FINES);
            outLines.push_back(fmt("ШТРАФ ВЫПИСАН НА %d ₽", sum));
        }
        if (verdict == V_DETAIN) { SHF.detains++; SV.totalDetain++; taskProgress(T_DETAIN); if (c.fled) moneyD += 1000; }
        if (c.contraband && c.trunkOpened) { bool found = false; for (auto& it : c.items) if (it.illegal && it.inspected) found = true; if (found) { SHF.contra++; taskProgress(T_CONTRA); moneyD += 1500; } }
        if (c.wanted && car.wanted) { moneyD += 2500; outLines.push_back("РАЗЫСКИВАЕМЫЙ АВТОМОБИЛЬ ЗАДЕРЖАН!"); }
        SHF.correct++; SV.totalCorrect++;
        outTitle = "ВЕРНОЕ РЕШЕНИЕ";
    } else {
        SHF.wrong++; SV.totalWrong++;
        if (verdict > need || (verdict == V_FINE && need == V_FINE && artExtra > 0)) {
            outTitle = "ПРИДИРКА! ВОДИТЕЛЬ ПОДАЛ ЖАЛОБУ";
            moneyD = -500; repD = -6; SV.complaints++;
        } else if (verdict == V_FINE && need == V_FINE) {
            outTitle = "НЕВЕРНЫЕ СТАТЬИ В ПРОТОКОЛЕ";
            moneyD = 100; repD = -1;
            SHF.fines++; SV.totalFines++; taskProgress(T_FINES);
        } else {
            outTitle = need == V_DETAIN ? "ОПАСНЫЙ НАРУШИТЕЛЬ ОТПУЩЕН!" : "НАРУШЕНИЕ ПРОПУЩЕНО";
            moneyD = need == V_DETAIN ? -800 : -300; repD = need == V_DETAIN ? -10 : -4;
        }
        SHF.penalties += -std::min(0, moneyD);
    }
    outLines.push_back(std::string("ТРЕБОВАЛОСЬ: ") + VERDICT_NAMES[need]);
    for (auto& f : c.facts) outLines.push_back("- " + f);
    if (need == V_FINE) {
        std::string a = "СТАТЬИ:"; for (int i = 0; i < ART_N; i++) if (c.needArt[i]) a += std::string(" ") + ART_SHORT[i];
        outLines.push_back(a);
    }
    if (moneyD > 0) {   // надбавка за плотность трафика в зоне
        float pm = payMulAt(PL.pos);
        if (fabsf(pm - 1) > 0.01f) { int add = (int)(moneyD * (pm - 1)); moneyD += add; outLines.push_back(fmt("%s ЗА ТРАФИК (X%.2f): %+d ₽", pm > 1 ? "НАДБАВКА" : "ПОНИЖЕНИЕ", pm, add)); }
    }
    SV.money = std::max(0, SV.money + moneyD); addRep(repD);
    if (good) sfx(SFX_COIN); else sfx(SFX_ERROR);
    // судьба машины
    if (verdict == V_EVAC || verdict == V_DETAIN) {
        car.mode = CMODE_STOPPED; car.vanish = true; car.caseIdx = -1; car.modeT = 0; car.viol = 0; car.seen = car.seenToast = 0;
        outLines.push_back(verdict == V_EVAC ? "АВТОМОБИЛЬ ОТПРАВЛЕН НА ШТРАФСТОЯНКУ." : "НАРУШИТЕЛЬ ДОСТАВЛЕН В ДЕЖУРНУЮ ЧАСТЬ.");
    }
    else { car.mode = CMODE_LEAVE; car.modeT = 0; car.caseIdx = -1; car.viol = 0; car.seen = car.seenToast = 0; }
    SHF.minutes += 3;
}

// ---------------------------------------------------------------------
//  Обновление вождения
// ---------------------------------------------------------------------
static Input gIn;
// ---- стационарный пост ДПС ----
struct Intercept { bool active = false; int idx = -1; uint32_t id = 0; int post = -1; bool done = false; };
static Intercept gIcpt;
static float gPostT = 0, gIcptNext = 50;   // сколько стоим на посту; когда следующая ориентировка
static int nearStatPost(float range) {
    int best = -1; float bd = range;
    for (size_t i = 0; i < SPOSTS.size(); i++) { float d = dist2d(PL.pos, SPOSTS[i].c); if (d < bd) { bd = d; best = (int)i; } }
    return best;
}
static bool onPost() { return nearStatPost(45) >= 0 && fabsf(PL.speed) < 1.5f; }
static void toggleBarrier(int pi) {
    StatPost& P = SPOSTS[pi];
    P.closed = !P.closed; P.closedT = 0;
    sfx(SFX_BEEP, 0.5f, P.closed ? 500 : 900);
    toast(P.closed ? "ШЛАГБАУМЫ ОПУЩЕНЫ: ДВИЖЕНИЕ ЧЕРЕЗ ПОСТ ПЕРЕКРЫТО." : "ШЛАГБАУМЫ ПОДНЯТЫ.", 3, 2.5f);
}
// разыскиваемая машина едет к посту — её нужно вычислить в потоке и остановить
static int spawnCarOnLane(int edge, int dir, int lane, float s) {
    const Edge& e = EDGES[edge];
    AICar c; c.alive = true; c.id = gCarIdCounter++;
    for (int k = 0; k < 10; k++) { c.trailer = false; c.taxi = false; c.model = pickTrafficModel(e.highway, c.trailer, c.taxi, c.paint, c.paint2); if (!c.trailer && c.model != MD_TRUCK && !c.taxi) break; }
    if (c.trailer || c.taxi) { c.trailer = false; c.taxi = false; c.model = MD_SEDAN; }
    const CarModel& M = CM[c.model]; c.halfW = M.halfW; c.halfL = M.halfL;
    c.desired = grng.range(0.95f, 1.12f); c.vice = 0;
    c.plate = allocPlate(c.plateStr, c.region);
    initCarOnLane(c, edge, dir, lane, s);
    c.speed = edgeLimitMs(e) * 0.85f;
    for (size_t i = 0; i < CARS.size(); i++) if (!CARS[i].alive) { CARS[i] = c; return (int)i; }
    CARS.push_back(c); return (int)CARS.size() - 1;
}
static void startIntercept(int pi) {
    const StatPost& P = SPOSTS[pi]; const Edge& e = EDGES[P.edge];
    int dir = grng.i(2);
    for (int t = 0; t < 2; t++, dir ^= 1) {
        float sp = (dir == 0 ? P.s : e.slen - P.s) - SP_BAR;
        float s = sp - grng.range(450, 750);
        if (s < 30) s = std::min(sp - 250, 40.f);
        if (s < 20) continue;
        int lane = grng.i(e.lanes);
        if (!laneFree(P.edge, dir, lane, s, 20)) lane = (lane + 1) % e.lanes;
        if (!laneFree(P.edge, dir, lane, s, 20)) continue;
        int idx = spawnCarOnLane(P.edge, dir, lane, s);
        AICar& c = CARS[idx];
        c.wanted = true;
        gIcpt.active = true; gIcpt.idx = idx; gIcpt.id = c.id; gIcpt.post = pi; gIcpt.done = false;
        SHF.wantedCar = idx;
        SHF.wantedDesc = fmt("%s, %s, %s %d", CM[c.model].name.c_str(), colorName(c.paint), c.plateStr.c_str(), c.region);
        toast("РАЦИЯ: К ВАШЕМУ ПОСТУ ДВИЖЕТСЯ РАЗЫСКИВАЕМЫЙ: " + SHF.wantedDesc + ". ПЕРЕХВАТИТЬ!", 3, 8);
        sfx(SFX_RADIO, 0.8f, 0, 0, 2.2f);
        return;
    }
}
static void updatePost(float dt) {
    if (SHF.minutes < SHF.startMin + 0.05f) {   // новая смена
        gIcpt = Intercept(); gPostT = 0; gIcptNext = 50;
        for (StatPost& P : SPOSTS) { P.closed = false; P.arm = 0; P.closedT = 0; }
    }
    for (StatPost& P : SPOSTS) {
        P.arm = approach(P.arm, P.closed ? 1.f : 0.f, dt * 0.7f);
        if (P.closed) {
            P.closedT += dt;
            bool needed = gChaseCar >= 0 || gIcpt.active;
            if (P.closedT > (needed ? 150.f : 75.f)) { P.closed = false; toast("ШЛАГБАУМЫ ПОДНЯТЫ АВТОМАТИЧЕСКИ — НЕЛЬЗЯ ДОЛГО ДЕРЖАТЬ ТРАССУ ЗАКРЫТОЙ.", 3, 3); }
        }
    }
    bool on = onPost();
    if (on) gPostT += dt;
    // ориентировка на перехват: только когда инспектор на посту
    if (on && !gIcpt.active && gChaseCar < 0) {
        gIcptNext -= dt;
        if (gIcptNext <= 0) { startIntercept(nearStatPost(45)); gIcptNext = grng.range(70, 130); SHF.nextWanted = SHF.minutes + 90; }
    }
    if (gIcpt.active) {
        bool alive = gIcpt.idx >= 0 && gIcpt.idx < (int)CARS.size() && CARS[gIcpt.idx].alive && CARS[gIcpt.idx].id == gIcpt.id;
        if (!alive) { gIcpt.active = false; return; }
        AICar& c = CARS[gIcpt.idx];
        const StatPost& P = SPOSTS[gIcpt.post];
        bool stopped = c.mode == CMODE_PULLOVER || c.mode == CMODE_STOPPED || c.caught;
        if (stopped) {
            gIcpt.active = false;
            SV.money += 2500; SHF.bonus += 2500; addRep(12);
            toast("ПЕРЕХВАТ УДАЛСЯ! РАЗЫСКИВАЕМЫЙ ОСТАНОВЛЕН. ПРЕМИЯ 2500 ₽, +12 РЕП.", 1, 4); sfx(SFX_SUCCESS);
        } else if (c.mode == CMODE_DRIVE && c.edge == P.edge && spDistToBarrier(P, c.dir, c.s) < -60) {
            gIcpt.active = false; addRep(-10);
            toast("РАЗЫСКИВАЕМЫЙ ПРОЕХАЛ ПОСТ! ПЕРЕХВАТ ПРОВАЛЕН. -10 РЕП.", 2, 4); sfx(SFX_ERROR);
        } else if (c.mode == CMODE_DRIVE && c.edge != P.edge) {
            gIcpt.active = false;   // свернул куда-то в сторону — ориентировка остаётся в силе
        }
    }
}
// ---- топливо ----
static const float FUEL_TANK = 60;
static bool gFueling = false; static float gFuelPaidL = 0; static int gFuelPaid = 0;
static bool gFuelLowWarned = false, gFuelEmptyWarned = false;
static float fuelUseMul() { const PatrolSpec& sp = PATROL[SV.car]; return 0.75f + sp.mass * 0.2f + (sp.vmax - 175) / 400.0f; }
// игрок стоит у колонки?
static int fuelPumpNear() {
    float lx, lz; int i = fuelAt(PL.pos, 0, &lx, &lz);
    if (i < 0) return -1;
    if (fabsf(lz) < 8.5f && fabsf(lx + 1.0f) < 5.5f) return i;
    return -1;
}
static void updateFuel(float dt) {
    float kmh = fabsf(PL.speed) * 3.6f;
    // расход: л/км растёт со скоростью (масштаб игровой — бака хватает примерно на 2 смены)
    float perKm = (1.3f + kmh / 100.0f * 1.1f + std::max(0.f, kmh - 140) / 60.0f) * fuelUseMul();
    float use = fabsf(PL.speed) * dt / 1000.0f * perKm + dt * 0.004f;
    if (!gFueling) SV.fuel = std::max(0.f, SV.fuel - use);
    if (SV.fuel < 8 && !gFuelLowWarned) { gFuelLowWarned = true; toast("МАЛО ТОПЛИВА! ЗАЕДЬ НА АЗС (ЗНАЧОК «А» НА КАРТЕ).", 2, 4); }
    if (SV.fuel > 12) gFuelLowWarned = false;
    if (SV.fuel <= 0 && !gFuelEmptyWarned) { gFuelEmptyWarned = true; toast("ТОПЛИВО КОНЧИЛОСЬ! ВЫЗОВИ ТОПЛИВОЗАПРАВЩИК.", 2, 5); }
    if (SV.fuel > 0.5f) gFuelEmptyWarned = false;
    // заправка
    if (gFueling) {
        if (fuelPumpNear() < 0 || fabsf(PL.speed) > 0.8f) gFueling = false;
        else {
            float add = std::min(FUEL_TANK - SV.fuel, 9.0f * dt);
            float afford = std::max(0.f, SV.money / FUEL_PRICE);
            add = std::min(add, afford);
            if (add <= 0.001f) {
                gFueling = false;
                toast(SV.fuel >= FUEL_TANK - 0.05f ? fmt("ЗАПРАВЛЕНО %.1f Л НА %d ₽. ПОЛНЫЙ БАК!", gFuelPaidL, gFuelPaid) : fmt("НЕ ХВАТАЕТ ДЕНЕГ. ЗАПРАВЛЕНО %.1f Л НА %d ₽.", gFuelPaidL, gFuelPaid), 0, 3);
            } else {
                SV.fuel += add; gFuelPaidL += add;
                int cost = (int)(gFuelPaidL * FUEL_PRICE + 0.5f);
                SV.money -= cost - gFuelPaid; SHF.fuelSpent += cost - gFuelPaid; gFuelPaid = cost;
            }
        }
    }
}
static void updateDrive(float dt) {
    SHF.minutes += dt * (40.0f / 60.0f);
    gClockMin = SHF.minutes;
    {   // сообщить о смене зоны или наступлении/окончании часа пик
        static int lastD = -1; static int lastCls = -1;
        if (SHF.minutes < SHF.startMin + 1.0f) lastD = -1;   // начало смены — об этом уже сказано при заступлении
        int dd = districtAt(PL.pos); float lv = trafficLevelAt(PL.pos);
        int cls = lv < 0.55f ? 0 : (lv < 0.9f ? 1 : (lv < 1.3f ? 2 : 3));
        if (lastD >= 0 && (dd != lastD || cls != lastCls))
            toast(fmt("%s: ТРАФИК %s — ДОХОД X%.2f", DISTRICT_NAMES[dd], trafficName(lv), payMulAt(PL.pos)), 3, 3.5f);
        lastD = dd; lastCls = cls;
    }
    gHour = fmodf(SHF.minutes / 60.0f, 24);
    updateLighting(gHour, SHF.weather);
    gWorldTime += dt;
    {
        Input in2 = gIn; if (SV.fuel <= 0) in2.throttle = 0;
        updatePlayer(dt, in2);
    }
    updateFuel(dt);
    updatePost(dt);
    collidePlayerCars(dt);
    updateTraffic(dt, true);
    updatePeds(dt, PL.pos, true);
    updateParts(dt);
    updateRadar();
    updateAccident(dt);
    pickTarget();
    if (gDemandCooldown > 0) gDemandCooldown -= dt;
    if (gCrashRepCd > 0) gCrashRepCd -= dt;
    if (gSubtitleT > 0) gSubtitleT -= dt;
    for (size_t i = 0; i < TOASTS.size();) { TOASTS[i].t -= dt; if (TOASTS[i].t <= 0) TOASTS.erase(TOASTS.begin() + i); else i++; }
    // реакции на требование
    for (size_t i = 0; i < CARS.size(); i++) {
        AICar& c = CARS[i];
        if (!c.alive || c.reactT < 0) continue;
        c.reactT -= dt;
        if (c.reactT < 0 && c.mode == CMODE_DRIVE) reactToDemand((int)i);
    }
    // ДТП с мирными машинами
    if (gCrashFlag > 0) {
        if (gLastHitCar >= 0 && gLastHitCar != gChaseCar && gCrashFlag > 7 && gCrashRepCd <= 0 && CARS[gLastHitCar].alive && CARS[gLastHitCar].mode != CMODE_HELPER) {
            addRep(-2); toast("ДТП С УЧАСТИЕМ ИНСПЕКТОРА! -2 РЕПУТАЦИИ", 2, 3); gCrashRepCd = 5;
        }
        gCrashFlag = 0; gLastHitCar = -1;
    }
    // погоня
    if (gChaseCar >= 0) {
        AICar& c = CARS[gChaseCar];
        if (!c.alive) { gChaseCar = -1; }
        else {
            float d = dist2d(c.pos, PL.pos);
            if (c.crashEvent) {
                if (c.crashEvent == 2) toast("БЕГЛЕЦ РАЗБИЛ МАШИНУ! ПОДЪЕЗЖАЙ И ЗАДЕРЖИ.", 1, 4);
                else if (d < 250) { toast("БЕГЛЕЦ ВРЕЗАЛСЯ, НО УХОДИТ ДАЛЬШЕ!", 2, 3); if (d < 60) c.pressure += 1.5f; }
                c.crashEvent = 0;
            }
            if (c.wrecked) { gChaseFarT = 0; if (d < 25) c.pressure = 99; }
            for (const StatPost& P : SPOSTS) if (P.arm > 0.5f && dist2d(c.pos, P.c) < 35 && c.speed < 3) {
                if (c.pressure < 6) toast("БЕГЛЕЦ УПЁРСЯ В ШЛАГБАУМ ПОСТА!", 1, 3);
                c.pressure = 99;
            }
            if (d < 16) c.pressure += dt * (0.35f + PATROL[SV.car].mass * 0.12f);
            if (gBlock.active && dist2d(c.pos, gBlock.pos) < 20 && c.speed < 3) c.pressure = 99;
            if (bitCount(c.flatMask) >= 2 && c.speed < 3.5f && d < 60) c.pressure += dt * 2.5f;   // на дисках далеко не уедет
            if (d > 280) gChaseFarT += dt; else gChaseFarT = std::max(0.f, gChaseFarT - dt * 0.5f);
            if (c.pressure >= 6) endChase(true);
            else if (gChaseFarT > 7 || d > 450) endChase(false);
        }
    }
    // остановленная машина рядом / брошенная
    int stoppedNear = -1;
    for (size_t i = 0; i < CARS.size(); i++) {
        AICar& c = CARS[i];
        if (!c.alive || c.mode != CMODE_STOPPED || c.caseIdx < 0) continue;
        float d = dist2d(c.pos, PL.pos);
        if (d < 16) stoppedNear = (int)i;
        if (d > 130) { c.modeT += 0; if (c.modeT > 30) { c.mode = CMODE_LEAVE; c.modeT = 0; c.caseIdx = -1; c.checked = true; addRep(-1); toast("ВОДИТЕЛЬ НЕ ДОЖДАЛСЯ И УЕХАЛ. -1 РЕП.", 2); } }
    }
    gInspect = stoppedNear;
    // ориентировка
    if (SHF.minutes > SHF.nextWanted && gChaseCar < 0) { spawnWanted(); SHF.nextWanted = SHF.minutes + 120 + grng.i(90); }
    if (SHF.wantedCar >= 0 && (SHF.wantedCar >= (int)CARS.size() || !CARS[SHF.wantedCar].alive || !CARS[SHF.wantedCar].wanted)) SHF.wantedCar = -1;
    // доход камер
    while (SHF.minutes - SHF.lastCamMin >= 1.0f) {
        SHF.lastCamMin += 1.0f;
        int inc = 0;
        for (const Camera_& cam : SPEEDCAMS) { const Edge& ce = EDGES[cam.edge]; V3 cp = ce.pa + ce.dir * cam.s; inc += (int)roundf((ce.highway ? 12 : 8) * payMulAt(cp)); }
        if (inc > 0) { SHF.camIncome += inc; SV.money += inc; }
    }
    // подсказки обучения
    if (SHF.tutorial) {
        gTutHintT -= dt;
        if (gTutHintT <= 0) {
            gTutHintT = 14;
            static const char* tips[] = {"ПОДСКАЗКА: РАДАР ВНИЗУ ПОКАЗЫВАЕТ СКОРОСТЬ МАШИНЫ ВПЕРЕДИ", "ПОДСКАЗКА: ЦЕЛЬ ПОДСВЕЧЕНА ЖЁЛТОЙ РАМКОЙ. «!» — НАРУШИТЕЛЬ",
                                         "ПОДСКАЗКА: СТОЯ НА МЕСТЕ, МОЖНО ОСТАНАВЛИВАТЬ МАШИНЫ ЖЕЗЛОМ", "ПОДСКАЗКА: ПОДЪЕДЬ К ОСТАНОВЛЕННОЙ МАШИНЕ И ПРОВЕРЬ ДОКУМЕНТЫ",
                                         "ПОДСКАЗКА: ПАМЯТКА С ПРАВИЛАМИ — В ПАУЗЕ И НА ЭКРАНЕ ДОКУМЕНТОВ"};
            if (SHF.tutStep < 5) toast(tips[SHF.tutStep++], 3, 6); else { SHF.tutorial = false; SV.tutorialShown = true; }
        }
    }
    // звук
    SY.engRpm = PL.rpm; SY.engLoad = PL.load; SY.engVol = 1;
    { float wv = fabsf(PL.speed) / 70; SY.wind = clampf(wv * wv, 0, 1.4f) * (gCamMode == 1 ? 0.75f : 1.f); } SY.siren = PL.siren ? 1.f : 0.f;
    SY.rain = L.rain; SY.ambient = districtAt(PL.pos) == 0 ? 0.25f : 0.12f;
    SY.screech = PL.sliding ? clampf(fabsf(PL.speed) / 20, 0, 1) : 0;
    if (SHF.minutes >= SHF.endMin) endShift();
}

// ---------------------------------------------------------------------
//  HUD
// ---------------------------------------------------------------------
static void drawIconArrow(float cx, float cy, float s, int dir, SDL_Color c) {
    if (dir < 0) UI.tri(cx - s, cy, cx + s * 0.6f, cy - s, cx + s * 0.6f, cy + s, c);
    else UI.tri(cx + s, cy, cx - s * 0.6f, cy - s, cx - s * 0.6f, cy + s, c);
}
static void drawMinimap(float x, float y, float sz) {
    panel(x, y, sz, sz, RGBA(10, 16, 26, 190));
    float scale = sz / 600.0f;
    float cx = x + sz / 2, cy = y + sz / 2;
    float yw = PL.yaw;
    auto tr = [&](const V3& p, float& ox, float& oy) {
        float dx = p.x - PL.pos.x, dz = p.z - PL.pos.z;
        // поворот так, чтобы направление движения было вверх
        float rx = dx * cosf(yw) - dz * sinf(yw), rz = dx * sinf(yw) + dz * cosf(yw);
        ox = cx + rx * scale; oy = cy - rz * scale;
    };
    // обрезка — грубо: рисуем только сегменты внутри
    for (const Edge& e : EDGES) {
        int ns = (int)(e.len / 40) + 1;
        V3 A = NODES[e.a].p, B = NODES[e.b].p;
        for (int k = 0; k < ns; k++) {
            V3 p0 = lerp3(A, B, k / (float)ns), p1 = lerp3(A, B, (k + 1) / (float)ns);
            float x0, y0, x1, y1; tr(p0, x0, y0); tr(p1, x1, y1);
            if (x0 < x + 3 || x0 > x + sz - 3 || y0 < y + 3 || y0 > y + sz - 3 || x1 < x + 3 || x1 > x + sz - 3 || y1 < y + 3 || y1 > y + sz - 3) continue;
            UI.line(x0, y0, x1, y1, e.highway ? 4 : 2.5f, e.highway ? RGBA(200, 200, 210) : RGBA(130, 140, 155));
        }
    }
    auto dot2 = [&](const V3& p, SDL_Color c, float r) {
        float ox, oy; tr(p, ox, oy);
        ox = clampf(ox, x + r, x + sz - r); oy = clampf(oy, y + r, y + sz - r);
        UI.circle(ox, oy, r, c, 10);
    };
    for (const Camera_& cam : SPEEDCAMS) { V3 p; float yy; camWorldPos(cam, p, yy); float ox, oy; tr(p, ox, oy); if (ox > x && ox < x + sz && oy > y && oy < y + sz) UI.rect(ox - 2, oy - 2, 4, 4, C_YELLOW); }
    for (size_t i = 0; i < CARS.size(); i++) {
        const AICar& c = CARS[i]; if (!c.alive) continue;
        if ((int)i == gChaseCar) dot2(c.pos, fmodf(gTime, 0.5f) < 0.25f ? C_RED : C_WHITE, 4.5f);
        else if (c.wanted && !(gIcpt.active && (int)i == gIcpt.idx && dist2d(c.pos, PL.pos) > 60)) dot2(c.pos, RGBA(255, 120, 0), 4);
        else if (c.mode == CMODE_STOPPED && c.caseIdx >= 0) dot2(c.pos, C_YELLOW, 3.5f);
        else if (c.mode == CMODE_HELPER) dot2(c.pos, RGBA(80, 140, 255), 3.5f);
    }
    for (const FuelStation& F : FUELS) {
        float fx, fy; tr(F.c, fx, fy);
        if (fx > x + 6 && fx < x + sz - 6 && fy > y + 6 && fy < y + sz - 6) { UI.roundRect(fx - 5, fy - 5, 10, 10, 2, RGBA(200, 40, 40)); UI.text(fx, fy - 3.5f, "А", 0.9f * U() * 0.8f, C_WHITE, 1); }
    }
    if (gBlock.active) dot2(gBlock.pos, RGBA(80, 140, 255), 5);
    if (ACC.active) dot2(ACC.pos, fmodf(gTime, 0.6f) < 0.3f ? RGBA(255, 60, 40) : C_YELLOW, 5.5f);
    float ox, oy; tr(POSTS[SHF.district].pos, ox, oy);
    if (ox > x && ox < x + sz && oy > y && oy < y + sz) UI.text(ox, oy - 3, "П", 1.2f * U() * 0.8f, RGBA(120, 200, 255), 1);
    UI.tri(cx, cy - 7, cx - 5, cy + 6, cx + 5, cy + 6, C_WHITE);
}

static void worldLabel(const V3& p, const char* s, SDL_Color c, float sc) {
    float sx, sy, sz;
    if (!R3.project(p, sx, sy, sz)) return;
    if (sx < 0 || sx > SW || sy < 0 || sy > SH) return;
    float w = UI.textW(s, sc) + 8 * sc / U();
    UI.roundRect(sx - w / 2, sy - 9 * sc, w, 11 * sc, 3, RGBA(0, 0, 0, 150));
    UI.text(sx, sy - 7.5f * sc, s, sc, c, 1);
}

static void drawSpeedLines() {
    float kmh = fabsf(PL.speed) * 3.6f;
    float k = clampf((kmh - 90) / 90, 0, 1);
    if (k <= 0) return;
    float hk = clampf((kmh - 170) / 110, 0, 1);    // на 170..280 км/ч — гуще, длиннее, быстрее + затемнение по краям
    if (hk > 0) {
        int a = (int)(70 * hk);
        UI.rectGH(0, 0, SW * 0.2f, SH, RGBA(0, 0, 0, a), RGBA(0, 0, 0, 0));
        UI.rectGH(SW * 0.8f, 0, SW * 0.2f, SH, RGBA(0, 0, 0, 0), RGBA(0, 0, 0, a));
        UI.rectG(0, 0, SW, SH * 0.18f, RGBA(0, 0, 0, a / 2), RGBA(0, 0, 0, 0));
    }
    float cx = SW * 0.5f, cy = SH * 0.42f;
    int nLines = 28 + (int)(44 * hk);
    for (int i = 0; i < nLines; i++) {
        uint32_t h = hash32(i * 977 + 3);
        float ang = (h % 6283) / 1000.0f;
        float ph = fmodf(gTime * (1.6f + (h >> 12) % 100 / 60.0f) * (1 + hk * 1.2f) + (h >> 20) % 100 / 100.0f, 1.0f);
        float r0 = SH * (0.45f - hk * 0.12f + ph * 0.7f), r1 = r0 + SH * (0.08f + 0.18f * k + 0.2f * hk);
        float ca = cosf(ang), sa = sinf(ang);
        float x0 = cx + ca * r0 * 1.6f, y0 = cy + sa * r0, x1 = cx + ca * r1 * 1.6f, y1 = cy + sa * r1;
        if (y0 > SH * 0.8f) continue;
        UI.line(x0, y0, x1, y1, std::max(1.5f, SH / 400.0f) * (1 + hk * 0.6f), RGBA(255, 255, 255, (int)((70 + 50 * hk) * k * (1 - ph))));
    }
}
static void drawDriveHUD() {
    float u = U();
    drawSpeedLines();
    float mx = std::max(SW * 0.035f, 16.0f), mt = SH * 0.045f;
    // маркеры над машинами
    for (size_t i = 0; i < CARS.size(); i++) {
        const AICar& c = CARS[i]; if (!c.alive) continue;
        float d = dist2d(c.pos, PL.pos); if (d > 140) continue;
        V3 top = c.pos + V3(0, CM[c.model].height + 0.6f, 0);
        if ((int)i == gChaseCar) worldLabel(top, "БЕГЛЕЦ", C_RED, u * 1.1f);
        else if (c.mode == CMODE_STOPPED && c.caseIdx >= 0) worldLabel(top, "ЖДЁТ ПРОВЕРКИ", C_YELLOW, u * 0.9f);
        else if (c.wanted && d < 100 && !(gIcpt.active && (int)i == gIcpt.idx)) worldLabel(top, "РОЗЫСК", RGBA(255, 140, 0), u * 1.0f);
        else if (c.racer && d < 90 && c.mode == CMODE_DRIVE) worldLabel(top, "СТРИТРЕЙСЕР", RGBA(255, 110, 200), u * 0.9f);
        else if (c.checked && !c.vanish && d < 50 && (c.mode == CMODE_DRIVE || c.mode == CMODE_LEAVE)) worldLabel(top, "ПРОВЕРЕН", RGBA(170, 180, 190), u * 0.8f);
        else if ((c.viol > 0 || c.seen) && d < 110 && c.mode == CMODE_DRIVE) {
            std::string l = c.viol == 3 ? "! КРАСНЫЙ" : (c.viol >= 1 ? fmt("! %d", (int)c.violSpeed) : std::string());
            if (c.seen & 1) l += std::string(l.empty() ? "! " : " ") + "ОБОЧИНА";
            if (c.seen & 2) l += std::string(l.empty() ? "! " : " ") + "БЕЗ ПОВОРОТНИКА";
            if (c.seen & 4) l += std::string(l.empty() ? "! " : " ") + "БЕЗ ФАР";
            worldLabel(top, l.c_str(), RGBA(255, 90, 80), u * 1.0f);
        }
    }
    if (gTarget >= 0) {
        const AICar& c = CARS[gTarget];
        float sx, sy, sz;
        if (R3.project(c.pos + V3(0, CM[c.model].height * 0.5f, 0), sx, sy, sz)) {
            float r = std::max(20.f, CM[c.model].radius * R3.focal / sz * 0.75f);
            SDL_Color yc = RGBA(255, 220, 60, 220);
            float L2 = r * 0.35f, t = std::max(2.f, u * 0.8f);
            for (int k = 0; k < 4; k++) {
                float sxk = (k & 1) ? 1.f : -1.f, syk = (k & 2) ? 1.f : -1.f;
                float px = sx + sxk * r, py = sy + syk * r * 0.65f;
                UI.rect(sxk > 0 ? px - L2 : px, py - t / 2, L2, t, yc);
                UI.rect(px - t / 2, syk > 0 ? py - L2 : py, t, L2, yc);
            }
        }
    }
    // верхняя левая панель
    float pw = u * 120, ph = u * 38;
    panel(mx, mt, pw, ph);
    int hh = (int)gHour, mm = (int)((gHour - hh) * 60);
    UI.text(mx + u * 5, mt + u * 4, fmt("%02d:%02d", hh, mm).c_str(), u * 1.4f, C_WHITE);
    UI.text(mx + pw - u * 5, mt + u * 5, fmt("%d ₽", SV.money).c_str(), u * 1.15f, C_YELLOW, 2);
    UI.text(mx + u * 5, mt + u * 18, RANKS[rankOf(SV.rep)], u * 0.95f, C_LIGHT);
    UI.text(mx + u * 5, mt + u * 28, fmt("РЕПУТАЦИЯ %d", SV.rep).c_str(), u * 0.9f, RGBA(150, 200, 255));
    drawMinimap(mx, mt + ph + u * 4, u * 74);
    // задания
    float tx = mx + pw + u * 8, tw = u * 150;
    panel(tx, mt, tw, u * 34, RGBA(18, 26, 40, 170));
    for (int i = 0; i < 3; i++) {
        const Task& t = SHF.tasks[i];
        UI.text(tx + u * 5, mt + u * (4 + i * 10), taskText(t), u * 0.9f, t.done ? RGBA(110, 220, 120) : C_WHITE);
    }
    // трафик в зоне и множитель дохода
    {
        float lv = trafficLevelAt(PL.pos), pm = payMulAt(PL.pos);
        SDL_Color tc = lv < 0.55f ? RGBA(150, 160, 175) : (lv < 0.9f ? RGBA(120, 220, 140) : (lv < 1.3f ? RGBA(255, 210, 80) : RGBA(255, 120, 80)));
        // под мини-картой, чтобы не мешать сообщениям
        float cy = mt + ph + u * 4 + u * 74 + u * 4, cw2 = u * 74;
        UI.roundRect(mx, cy, cw2, u * 20, u * 2, RGBA(18, 26, 40, 170));
        UI.text(mx + cw2 / 2, cy + u * 2.5f, fmt("ТРАФИК: %s", trafficName(lv)).c_str(), u * 0.75f, tc, 1);
        UI.text(mx + cw2 / 2, cy + u * 11, fmt("ДОХОД X%.2f", pm).c_str(), u * 0.85f, pm >= 1 ? RGBA(255, 220, 90) : RGBA(170, 180, 190), 1);
    }
    // кнопки справа сверху
    float bs = u * 30;
    float bx = SW - mx - bs;
    if (button(bx, mt, bs, bs, "", C_GRAY, u * 1.6f) || gBackPressed) { gBackPressed = false; gScreen = SC_PAUSE; }
    UI.rect(bx + bs * 0.32f, mt + bs * 0.28f, bs * 0.12f, bs * 0.44f, C_WHITE); UI.rect(bx + bs * 0.56f, mt + bs * 0.28f, bs * 0.12f, bs * 0.44f, C_WHITE);
    if (button(bx - bs - u * 5, mt, bs, bs, gCamMode == 0 ? "ВИД" : "ВИД", C_GRAY, u * 1.0f)) { gCamMode = 1 - gCamMode; SV.camView = gCamMode; updateCamera(0, true); }
    if (button(bx - 2 * (bs + u * 5), mt, bs, bs, "КАРТА", C_GRAY, u * 0.8f)) { gMapReturn = SC_DRIVE; gScreen = SC_MAP; TOASTS.clear(); }
    // сообщения
    float my = mt + u * 40 + (SHF.wantedCar >= 0 ? u * 6 : 0);
    for (size_t i = 0; i < TOASTS.size(); i++) {
        const Toast& t = TOASTS[i];
        SDL_Color bg = t.kind == 1 ? RGBA(30, 110, 50, 220) : (t.kind == 2 ? RGBA(140, 30, 30, 220) : (t.kind == 3 ? RGBA(25, 60, 130, 220) : RGBA(20, 25, 35, 210)));
        float s = u * 1.05f; float tw0 = UI.textW(t.text.c_str(), s); if (tw0 > SW * 0.52f) { s *= SW * 0.52f / tw0; tw0 = SW * 0.52f; } float w = tw0 + u * 12;
        float a = clampf(t.t * 2, 0, 1);
        bg.a = (Uint8)(bg.a * a);
        UI.roundRect(SW / 2 - w / 2, my, w, u * 13, u * 3, bg);
        UI.text(SW / 2, my + u * 3, t.text.c_str(), s, RGBA(255, 255, 255, (int)(255 * a)), 1);
        my += u * 15;
    }
    if (gSubtitleT > 0) {
        float s = u * 1.1f; float w = UI.textW(gSubtitle.c_str(), s) + u * 10;
        UI.roundRect(SW / 2 - w / 2, SH * 0.62f, w, u * 13, u * 3, RGBA(0, 0, 0, 170));
        UI.text(SW / 2, SH * 0.62f + u * 3, gSubtitle.c_str(), s, C_YELLOW, 1);
    }
    // ориентировка
    if (SHF.wantedCar >= 0) {
        std::string s = "РОЗЫСК: " + SHF.wantedDesc;
        float w = UI.textW(s.c_str(), u * 0.9f) + u * 8;
        float wy = mt + bs + u * 5;
        float sc2 = u * 0.8f; w = UI.textW(s.c_str(), sc2) + u * 8;
        UI.roundRect(SW - mx - w, wy, w, u * 10, u * 2, RGBA(150, 70, 0, 200));
        UI.text(SW - mx - w / 2, wy + u * 1.8f, s.c_str(), sc2, C_WHITE, 1);
    }
    // спидометр и радар
    float sw = u * 84, sh = u * 40, sx = SW / 2 - sw / 2, sy = SH - sh - u * 6;
    if (gCamMode != 1) {   // в кабине скорость и радар показывают приборы на торпедо
    panel(sx, sy, sw, sh, RGBA(10, 14, 22, 200));
    int kmh = (int)(fabsf(PL.speed) * 3.6f + 0.5f);
    bool over = kmh > PL.limitKmh + 5;
    UI.text(sx + u * 34, sy + u * 5, fmt("%d", kmh).c_str(), u * 2.6f, over ? RGBA(255, 120, 100) : C_WHITE, 1);
    UI.text(sx + u * 34, sy + u * 26, "КМ/Ч", u * 0.9f, C_LIGHT, 1);
    // знак ограничения
    float lx = sx + sw - u * 18, ly = sy + u * 17;
    UI.circle(lx, ly, u * 12, RGBA(210, 30, 30), 20); UI.circle(lx, ly, u * 9.3f, C_WHITE, 20);
    UI.text(lx, ly - u * 3.3f, fmt("%d", (int)PL.limitKmh).c_str(), u * 0.95f, RGBA(0, 0, 0), 1);
    if (PL.reverse) UI.text(sx + u * 6, sy + u * 5, "R", u * 1.4f, C_YELLOW);
    // радар
    float rw = u * 70, rx = sx - rw - u * 6;
    panel(rx, sy, rw, sh, RGBA(10, 14, 22, 200));
    UI.text(rx + rw / 2, sy + u * 4, "РАДАР", u * 0.9f, RGBA(120, 200, 255), 1);
    if (gRadarSpeed >= 0) {
        bool ov = gRadarSpeed > gRadarLimit + 10;
        UI.text(rx + rw / 2, sy + u * 14, fmt("%d", (int)gRadarSpeed).c_str(), u * 2.0f, ov ? RGBA(255, 90, 80) : RGBA(120, 255, 140), 1);
        UI.text(rx + rw / 2, sy + u * 30, fmt("ЛИМИТ %d", (int)gRadarLimit).c_str(), u * 0.8f, C_LIGHT, 1);
    } else UI.text(rx + rw / 2, sy + u * 17, "---", u * 1.6f, RGBA(90, 100, 110), 1);
    }
    // топливо
    {
        float fw = u * 58, fh = u * 16, fx = sx + sw + u * 6, fy = SH - fh - u * 6;
        if (gChaseCar >= 0 || ACC.active) { fx = sx + sw / 2 - fw / 2; fy = sy - fh - u * 3; }   // справа от спидометра — панель погони/ДТП
        if (gCamMode == 1) { fx = SW / 2 - fw / 2; fy = u * 6 + u * 16; }
        float k = clampf(SV.fuel / FUEL_TANK, 0, 1);
        bool low = SV.fuel < 8;
        panel(fx, fy, fw, fh, RGBA(10, 14, 22, 200));
        UI.text(fx + u * 4, fy + u * 2.5f, fmt("ТОПЛИВО %d Л", (int)(SV.fuel + 0.5f)).c_str(), u * 0.75f, low && fmodf(gTime, 0.8f) < 0.4f ? RGBA(255, 90, 80) : C_LIGHT);
        UI.rect(fx + u * 4, fy + u * 10, fw - u * 8, u * 3, RGBA(40, 44, 52));
        UI.rect(fx + u * 4, fy + u * 10, (fw - u * 8) * k, u * 3, low ? RGBA(230, 60, 50) : (k < 0.3f ? RGBA(230, 170, 40) : RGBA(90, 200, 110)));
    }
    // заправка / топливозаправщик
    {
        float bw = u * 150, bh = u * 22, bx = SW / 2 - bw / 2, by = SH * 0.58f;
        int st = fuelPumpNear();
        if (gFueling) {
            panel(bx, by, bw, bh, RGBA(20, 60, 30, 220));
            UI.text(SW / 2, by + u * 6, fmt("ЗАПРАВКА: %.1f Л  —  %d ₽", gFuelPaidL, gFuelPaid).c_str(), u * 1.0f, C_WHITE, 1);
        } else if (st >= 0 && fabsf(PL.speed) < 0.8f && SV.fuel < FUEL_TANK - 0.5f) {
            float need = FUEL_TANK - SV.fuel; int cost = (int)(need * FUEL_PRICE + 0.5f);
            if (button(bx, by, bw, bh, fmt("ЗАПРАВИТЬСЯ: %.0f Л ЗА %d ₽", need, cost).c_str(), RGBA(40, 150, 70), u * 1.0f, SV.money > 0)) { gFueling = true; gFuelPaidL = 0; gFuelPaid = 0; sfx(SFX_BEEP, 0.4f, 900); }
        } else if (st >= 0 && fabsf(PL.speed) < 0.8f) {
            panel(bx, by, bw, bh, RGBA(10, 14, 22, 200));
            UI.text(SW / 2, by + u * 6, "БАК ПОЛНЫЙ", u * 1.0f, C_LIGHT, 1);
        } else if (fuelAt(PL.pos) >= 0 && fabsf(PL.speed) < 3) {
            panel(bx, by, bw, bh * 0.8f, RGBA(10, 14, 22, 180));
            UI.text(SW / 2, by + u * 4.5f, "ВСТАНЬ У КОЛОНКИ, ЧТОБЫ ЗАПРАВИТЬСЯ", u * 0.85f, C_LIGHT, 1);
        } else if (SV.fuel <= 0 && fabsf(PL.speed) < 1.0f) {
            const int price = 1500;
            if (button(bx, by, bw, bh, fmt("ВЫЗВАТЬ ТОПЛИВОЗАПРАВЩИК: 10 Л ЗА %d ₽", price).c_str(), RGBA(200, 120, 20), u * 0.9f)) {
                SV.fuel = 10; SV.money -= price; SHF.fuelSpent += price;
                toast("ПРИЕХАЛ ТОПЛИВОЗАПРАВЩИК: +10 Л. ДОЕДЬ ДО АЗС.", 0, 3.5f); sfx(SFX_BEEP, 0.4f, 700);
            }
        }
    }
    // погоня
    if (gChaseCar >= 0) {
        const AICar& c = CARS[gChaseCar];
        float d = dist2d(c.pos, PL.pos);
        float cw = u * 90, cx = sx + sw + u * 6;
        panel(cx, sy, cw, sh, RGBA(90, 15, 15, 210));
        UI.text(cx + cw / 2, sy + u * 4, "ПОГОНЯ", u * 1.1f, C_WHITE, 1);
        UI.text(cx + cw / 2, sy + u * 15, fmt("%d М", (int)d).c_str(), u * 1.2f, d > 200 ? C_YELLOW : C_WHITE, 1);
        UI.rect(cx + u * 6, sy + u * 29, cw - u * 12, u * 5, RGBA(0, 0, 0, 160));
        UI.rect(cx + u * 6, sy + u * 29, (cw - u * 12) * clampf(c.pressure / 6, 0, 1), u * 5, C_YELLOW);
    }
    // управление: руль
    float b = SH * 0.2f;
    float by = SH - b - SH * 0.04f;
    float lbx = mx, rbx = mx + b * 1.12f;
    bool lh = heldIn(lbx - mx, by - b * 0.3f, b + mx + b * 0.06f, b * 1.4f), rh = heldIn(rbx - b * 0.06f, by - b * 0.3f, b * 1.2f, b * 1.4f);
    UI.roundRect(lbx, by, b, b, b * 0.2f, lh ? RGBA(255, 255, 255, 90) : RGBA(255, 255, 255, 45));
    UI.roundRect(rbx, by, b, b, b * 0.2f, rh ? RGBA(255, 255, 255, 90) : RGBA(255, 255, 255, 45));
    drawIconArrow(lbx + b / 2, by + b / 2, b * 0.25f, -1, RGBA(255, 255, 255, 220));
    drawIconArrow(rbx + b / 2, by + b / 2, b * 0.25f, 1, RGBA(255, 255, 255, 220));
    // педали
    float gw = b * 0.82f, gh = b * 1.35f;
    float gx = SW - mx - gw, gy = SH - gh - SH * 0.04f;
    float bw = b * 0.95f, bh = b * 0.9f, bkx = gx - bw - b * 0.12f, bky = SH - bh - SH * 0.04f;
    bool gas = heldIn(gx - b * 0.06f, gy - b * 0.1f, gw + mx + b * 0.06f, gh + SH * 0.04f + b * 0.1f);
    bool brk = heldIn(bkx - b * 0.06f, bky - b * 0.1f, bw + b * 0.15f, bh + SH * 0.04f + b * 0.1f);
    UI.roundRect(gx, gy, gw, gh, b * 0.15f, gas ? RGBA(60, 200, 90, 160) : RGBA(60, 200, 90, 80));
    for (int k = 0; k < 4; k++) UI.rect(gx + gw * 0.2f, gy + gh * (0.2f + k * 0.17f), gw * 0.6f, gh * 0.06f, RGBA(255, 255, 255, 120));
    UI.text(gx + gw / 2, gy + gh - u * 12, "ГАЗ", u * 1.1f, C_WHITE, 1);
    UI.roundRect(bkx, bky, bw, bh, b * 0.15f, brk ? RGBA(220, 60, 60, 160) : RGBA(220, 60, 60, 80));
    for (int k = 0; k < 3; k++) UI.rect(bkx + bw * 0.15f, bky + bh * (0.2f + k * 0.2f), bw * 0.7f, bh * 0.08f, RGBA(255, 255, 255, 110));
    UI.text(bkx + bw / 2, bky + bh - u * 12, "ТОРМОЗ", u * 1.0f, C_WHITE, 1);
    // кнопки действий
    float ab = b * 0.72f;
    float ax = SW - mx - ab, ay = gy - ab - b * 0.18f;
    // мигалка
    {
        bool on = PL.flash;
        SDL_Color c = on ? (fmodf(gTime, 0.5f) < 0.25f ? RGBA(200, 40, 40) : RGBA(40, 80, 220)) : RGBA(50, 60, 80);
        if (button(ax, ay, ab, ab * 0.8f, "МИГАЛКА", c, u * 0.85f)) { PL.flash = !PL.flash; PL.siren = PL.flash; sfx(SFX_BEEP, 0.5f, PL.flash ? 1200 : 600); }
    }
    {
        bool parked = fabsf(PL.speed) < 1.5f;
        bool en = gTarget >= 0 && gDemandCooldown <= 0;
        if (button(ax - ab - b * 0.12f, ay, ab, ab * 0.8f, parked ? "ЖЕЗЛ" : "ТРЕБОВАТЬ", en ? RGBA(200, 140, 20) : RGBA(70, 70, 70), u * 0.85f, en)) demandStop();
    }
    // гудок
    {
        float hw = ab * 0.8f, hx = ax - 2 * (ab + b * 0.12f) + (ab - hw);
        SDL_Color hc = gHornT > 0 ? RGBA(230, 230, 240) : RGBA(80, 90, 110);
        if (button(hx, ay + ab * 0.1f, hw, ab * 0.6f, "ГУДОК", hc, u * 0.8f) && gHornT <= 0.0f) { sfx(SFX_QUACK, 0.9f); gHornT = 1.25f; }
    }
    // стационарный пост: шлагбаум
    {
        int pi = nearStatPost(260);
        if (pi >= 0) {
            float hw = ab * 0.8f, hx = ax - 2 * (ab + b * 0.12f) + (ab - hw);
            float by2 = ay - ab * 0.8f - b * 0.1f;
            if (gChaseCar >= 0) by2 -= ab * 0.7f + b * 0.1f;
            const StatPost& P = SPOSTS[pi];
            SDL_Color bc = P.closed ? RGBA(200, 40, 40) : RGBA(60, 90, 140);
            if (button(hx - ab * 0.35f, by2, hw + ab * 0.35f, ab * 0.7f, P.closed ? "ПОДНЯТЬ ШЛАГБАУМ" : "ШЛАГБАУМ", bc, u * 0.75f)) toggleBarrier(pi);
            if (onPost()) {
                const char* t = gIcpt.active ? "НА ПОСТУ: ИЩИ РАЗЫСКИВАЕМОГО В ПОТОКЕ" : "НА ПОСТУ ДПС: ВЫБЕРИ МАШИНУ И НАЖМИ «ЖЕЗЛ»";
                float tw = UI.textW(t, u * 0.85f) + u * 10;
                UI.roundRect(SW / 2 - tw / 2, mt + bs + u * 4, tw, u * 12, u * 3, RGBA(20, 50, 120, 210));
                UI.text(SW / 2, mt + bs + u * 6.5f, t, u * 0.85f, C_WHITE, 1);
            }
        }
    }
    if (gChaseCar >= 0) {
        float ry = ay - ab * 0.8f - b * 0.1f;
        if (button(ax, ry, ab, ab * 0.7f, "ПОМОЩЬ", C_BLUE, u * 0.85f, !gHelpUsed)) requestHelp();
        if (button(ax - ab - b * 0.12f, ry, ab, ab * 0.7f, "БЛОКПОСТ", roadblockAllowed() ? C_BLUE : RGBA(70, 70, 70), u * 0.85f, !gBlockUsed && roadblockAllowed())) requestRoadblock();
    }
    // вызов на ДТП: метка, указатель, кнопка оформления
    if (ACC.active) {
        float d = dist2d(ACC.pos, PL.pos);
        worldLabel(ACC.pos + V3(0, 3.2f, 0), "ДТП", RGBA(255, 80, 60), u * 1.2f);
        float iw = u * 108, ix = SW - mx - iw, iy = mt + bs + u * (SHF.wantedCar >= 0 ? 18 : 5);
        UI.roundRect(ix, iy, iw, u * 22, u * 3, RGBA(140, 25, 20, 210));
        int left = std::max(0, (int)(ACC.deadline - SHF.minutes));
        UI.text(ix + u * 22, iy + u * 3, fmt("ДТП: %d М", (int)d).c_str(), u * 1.0f, C_WHITE);
        UI.text(ix + u * 22, iy + u * 13, ACC.stage == 0 ? fmt("ОСТАЛОСЬ %d МИН", left).c_str() : "ВЫ НА МЕСТЕ", u * 0.75f, C_YELLOW);
        // стрелка направления относительно курса
        V3 dv = ACC.pos - PL.pos; float ang = wrapAngle(atan2f(dv.x, dv.z) - PL.yaw);
        float ax0 = ix + u * 11, ay0 = iy + u * 11, ar = u * 8;
        float sa = sinf(ang), ca = cosf(ang);
        UI.tri(ax0 + sa * ar, ay0 - ca * ar, ax0 + ca * ar * 0.55f - sa * ar * 0.5f, ay0 + sa * ar * 0.55f + ca * ar * 0.5f, ax0 - ca * ar * 0.55f - sa * ar * 0.5f, ay0 - sa * ar * 0.55f + ca * ar * 0.5f, C_YELLOW);
        if (d < 28 && fabsf(PL.speed) < 2.0f && gInspect < 0) {
            float cw = u * 150, ch = u * 24;
            if (button(SW / 2 - cw / 2, sy - ch - u * 8, cw, ch, "ОФОРМИТЬ ДТП", RGBA(170, 50, 40), u * 1.3f)) { gScreen = SC_ACCIDENT; PL.speed = 0; sfx(SFX_THUNK); }
        } else if (d < 28) UI.text(SW / 2, sy - u * 18, "ОСТАНОВИСЬ, ЧТОБЫ ОФОРМИТЬ ДТП", u * 1.0f, C_YELLOW, 1, true);
    }
    // контекстная кнопка: проверить документы
    if (gInspect >= 0 && fabsf(PL.speed) < 2.0f) {
        float cw = u * 150, ch = u * 24;
        if (button(SW / 2 - cw / 2, sy - ch - u * 8, cw, ch, "ПРОВЕРИТЬ ДОКУМЕНТЫ", C_GREEN, u * 1.3f)) {
            gScreen = SC_DOCS; sfx(SFX_THUNK);
            PL.speed = 0;
            Case& c = CASES[CARS[gInspect].caseIdx];
            sfx(SFX_SPEECH, 0.8f, c.female ? 210 : 120, 0, 1.8f);
        }
    } else if (gInspect >= 0) {
        UI.text(SW / 2, sy - u * 18, "ОСТАНОВИСЬ РЯДОМ С МАШИНОЙ", u * 1.0f, C_YELLOW, 1, true);
    }
    // выбор цели касанием по машине (вне зон кнопок)
    for (Tap& t : TAPS) {
        if (t.used) continue;
        bool inSteer = t.x < rbx + b * 1.2f && t.y > by - b * 0.35f;
        bool inPedals = t.x > bkx - b * 0.2f && t.y > ay - b * 0.1f;
        if (inSteer || inPedals) continue;
        int bi = -1; float bd = 1e9f; bool checkedHit = false;
        for (size_t i = 0; i < CARS.size(); i++) {
            const AICar& c = CARS[i]; if (!c.alive) continue;
            float px, py, pz;
            if (!R3.project(c.pos + V3(0, CM[c.model].height * 0.5f, 0), px, py, pz)) continue;
            float r = std::max(u * 22, CM[c.model].radius * R3.focal / pz * 0.8f);
            float dd = sqrtf((px - t.x) * (px - t.x) + (py - t.y) * (py - t.y));
            if (dd < r && dd < bd) { bd = dd; bi = (int)i; }
        }
        if (bi < 0) continue;
        t.used = true;
        if (targetable(CARS[bi], bi) && dist2d(CARS[bi].pos, PL.pos) < 100) { gManualTarget = bi; gManualId = CARS[bi].id; gTarget = bi; sfx(SFX_CLICK); }
        else if (CARS[bi].checked) toast("ЭТОТ ВОДИТЕЛЬ УЖЕ ПРОВЕРЕН", 0, 2);
        else if (CARS[bi].mode == CMODE_STOPPED || CARS[bi].mode == CMODE_PULLOVER) toast("МАШИНА УЖЕ ОСТАНАВЛИВАЕТСЯ", 0, 2);
        else if (dist2d(CARS[bi].pos, PL.pos) >= 100) toast("СЛИШКОМ ДАЛЕКО — ПОДЪЕДЬ БЛИЖЕ", 0, 2);
        (void)checkedHit;
    }
    if (gTarget < 0 && gInspect < 0 && gChaseCar < 0) UI.text(ax + ab * 0.5f - ab * 0.56f, ay - u * 12, "НАЖМИ НА МАШИНУ", u * 0.8f, RGBA(255, 255, 255, 200), 1, true);
    // ввод
    gIn.steer = (rh ? 1.f : 0.f) - (lh ? 1.f : 0.f);
    if (SV.tilt && gAccel && !lh && !rh) gIn.steer = accelSteer();
    gIn.throttle = gas ? 1.f : 0.f; gIn.brake = brk ? 1.f : 0.f;
}

// капли на лобовом стекле (смахиваются дворниками)
struct GlassDrop { float x, y, r, life; };
static std::vector<GlassDrop> gDrops;
static float gCockpitT = -1, gWiperPh = 0;
static inline SDL_Color mixc(SDL_Color a, SDL_Color b, float t) {
    return RGBA((int)(a.r + (b.r - a.r) * t), (int)(a.g + (b.g - a.g) * t), (int)(a.b + (b.b - a.b) * t), (int)(a.a + (b.a - a.a) * t));
}
static inline SDL_Color scaleC(SDL_Color a, float k, int alpha = 255) {
    return RGBA((int)clampf(a.r * k, 0, 255), (int)clampf(a.g * k, 0, 255), (int)clampf(a.b * k, 0, 255), alpha);
}
// циферблат: значения 0..vmax, шкала 270°
static void cockpitGauge(float cx, float cy, float r, float val, float vmax, int majors, int minorsPer, float redFrom, const char* unit, bool numbersX1000, float lit) {
    float u = U();
    UI.circle(cx, cy, r * 1.08f, RGBA(52, 54, 60), 36);                 // хромовый ободок
    UI.circle(cx, cy, r * 1.02f, RGBA(18, 19, 22), 36);
    UI.circle(cx, cy, r, RGBA(8, 9, 12), 36);
    UI.ring(cx, cy, r * 0.6f, r * 0.98f, RGBA(14, 16, 22), 36);
    SDL_Color tick = mixc(RGBA(200, 205, 215), RGBA(255, 236, 200), lit);
    float a0 = PI * 0.75f, span = PI * 1.5f;
    int nT = majors * minorsPer;
    for (int k = 0; k <= nT; k++) {
        float f = (float)k / nT, an = a0 + span * f;
        bool major = k % minorsPer == 0;
        float r0 = major ? r * 0.76f : r * 0.86f;
        bool red = f * vmax >= redFrom;
        UI.line(cx + cosf(an) * r0, cy + sinf(an) * r0, cx + cosf(an) * r * 0.95f, cy + sinf(an) * r * 0.95f, major ? u * 1.1f : u * 0.6f, red ? RGBA(230, 50, 40) : tick);
        if (major && r > u * 16) {
            int v = (int)(f * vmax + 0.5f); if (numbersX1000) v /= 1000;
            UI.text(cx + cosf(an) * r * 0.6f, cy + sinf(an) * r * 0.6f - u * 1.5f, fmt("%d", v).c_str(), u * 0.42f, red ? RGBA(230, 70, 60) : tick, 1);
        }
    }
    UI.text(cx, cy + r * 0.28f, unit, u * 0.42f, RGBA(150, 155, 165), 1);
    float an = a0 + span * clampf(val / vmax, 0, 1.02f);
    if (lit > 0.3f) UI.glow(cx + cosf(an) * r * 0.45f, cy + sinf(an) * r * 0.45f, r * 0.5f, RGBA(90, 25, 0, (int)(255 * lit)));
    UI.line(cx - cosf(an) * r * 0.15f, cy - sinf(an) * r * 0.15f, cx + cosf(an) * r * 0.9f, cy + sinf(an) * r * 0.9f, u * 1.4f, RGBA(255, 90, 30));
    UI.circle(cx, cy, r * 0.11f, RGBA(40, 42, 48), 16);
}
static void drawCockpitOverlay() {
    float u = U();
    float W = (float)SW, H = (float)SH;
    float dt = gCockpitT < 0 ? 0.016f : clampf(gTime - gCockpitT, 0, 0.1f); gCockpitT = gTime;
    float day = 1 - L.night * 0.6f;
    SDL_Color interD = scaleC(RGBA(24, 25, 28), day);
    float lit = clampf(L.night * 1.3f + L.rain * 0.3f, 0, 1);    // подсветка приборов
    bool flashPh = fmodf(gTime, 0.5f) < 0.25f;

    // --- капот (видна передняя кромка) ---
    Col hc = shadeN(Col(0.92f, 0.92f, 0.94f), norm(V3(0, 1, 0.15f)), PL.pos);
    hc = lerpc(hc, L.skyHor, 0.12f);
    SDL_Color hoodT = toSDL(hc * 1.05f), hoodB = toSDL(hc * 0.78f);
    const int HN = 24;
    for (int i = 0; i < HN; i++) {
        float t0 = (float)i / HN, t1 = (float)(i + 1) / HN;
        float x0 = W * (0.1f + 0.84f * t0), x1 = W * (0.1f + 0.84f * t1);
        float e0 = (t0 - 0.5f) * 2, e1 = (t1 - 0.5f) * 2;
        float y0 = H * (0.585f + 0.06f * e0 * e0), y1 = H * (0.585f + 0.06f * e1 * e1);
        UI.quadC(x0, y0, hoodT, x1, y1, hoodT, x1, H * 0.7f, hoodB, x0, H * 0.7f, hoodB);
    }
    // блик и отражения мигалки на капоте
    UI.rectG(W * 0.2f, H * 0.592f, W * 0.6f, H * 0.012f, RGBA(255, 255, 255, (int)(60 * day)), RGBA(255, 255, 255, 0));
    if (PL.flash) UI.glow(W * (flashPh ? 0.38f : 0.62f), H * 0.6f, H * 0.12f, flashPh ? RGBA(160, 20, 20) : RGBA(20, 40, 170));

    // --- дворники и капли ---
    float wiperA = PI;    // в покое — лежат вдоль низа стекла
    if (L.rain > 0.05f) {
        gWiperPh += dt * (0.55f + L.rain * 0.6f);
        float t = fmodf(gWiperPh, 1.0f); float ph = t < 0.5f ? t * 2 : 2 - t * 2;
        ph = ph * ph * (3 - 2 * ph);
        wiperA = PI + ph * 1.45f;
        // новые капли
        float rate = 70 * L.rain;
        int n = (int)(rate * dt) + (grng.f() < fmodf(rate * dt, 1.0f) ? 1 : 0);
        for (int k = 0; k < n && gDrops.size() < 160; k++) gDrops.push_back({W * grng.range(0.08f, 0.92f), H * grng.range(0.07f, 0.6f), u * grng.range(0.6f, 2.2f), grng.range(3.f, 8.f)});
    }
    float pivX[2] = {W * 0.27f, W * 0.62f}, pivY = H * 0.655f, wl = H * 0.56f;
    for (size_t i = 0; i < gDrops.size();) {
        GlassDrop& g = gDrops[i];
        g.life -= dt; g.y -= fabsf(PL.speed) * dt * u * 0.35f; g.x += (g.x - W * 0.5f) / W * fabsf(PL.speed) * dt * u * 0.3f;
        bool wiped = false;
        for (int k = 0; k < 2 && L.rain > 0.05f; k++) {
            float dx = g.x - pivX[k], dy = g.y - pivY, rr = sqrtf(dx * dx + dy * dy);
            float an = atan2f(dy, dx); if (an < 0) an += 2 * PI;
            if (rr < wl && fabsf(an - wiperA) < 0.07f) wiped = true;
        }
        if (g.life <= 0 || wiped || g.y < H * 0.05f) { gDrops[i] = gDrops.back(); gDrops.pop_back(); continue; }
        i++;
    }
    for (const GlassDrop& g : gDrops) {
        UI.circle(g.x, g.y, g.r, RGBA(170, 185, 200, 55), 8);
        UI.circle(g.x - g.r * 0.3f, g.y - g.r * 0.3f, g.r * 0.35f, RGBA(255, 255, 255, 90), 6);
    }
    for (int k = 0; k < 2; k++) {
        float ca = cosf(wiperA), sa = sinf(wiperA);
        float tx = pivX[k] + ca * wl, ty = pivY + sa * wl;
        UI.line(pivX[k], pivY, tx, ty, u * 1.6f, RGBA(12, 12, 14));                      // поводок
        float bx0 = pivX[k] + ca * wl * 0.18f, by0 = pivY + sa * wl * 0.18f;
        UI.line(bx0 - sa * u * 1.2f, by0 + ca * u * 1.2f, tx - sa * u * 1.2f, ty + ca * u * 1.2f, u * 2.6f, RGBA(20, 20, 22));   // щётка
        UI.circle(pivX[k], pivY, u * 2.5f, RGBA(15, 15, 17), 10);
    }

    // --- стойки, крыша, козырьки ---
    SDL_Color pil = scaleC(RGBA(46, 47, 52), day), pilE = scaleC(RGBA(70, 72, 78), day);
    UI.quadC(0, 0, pil, W * 0.075f, 0, pil, W * 0.155f, H * 0.66f, interD, 0, H * 0.7f, interD);
    UI.line(W * 0.075f, 0, W * 0.155f, H * 0.66f, u * 1.2f, pilE);
    UI.quadC(W * 0.955f, 0, pil, W, 0, pil, W, H * 0.68f, interD, W * 0.905f, H * 0.66f, interD);
    UI.line(W * 0.955f, 0, W * 0.905f, H * 0.66f, u * 1.0f, pilE);
    UI.rectG(0, 0, W, H * 0.055f, scaleC(RGBA(60, 61, 66), day), scaleC(RGBA(40, 41, 46), day));
    UI.rect(0, H * 0.055f, W, u * 1.2f, scaleC(RGBA(20, 20, 23), day));
    // козырьки
    UI.quadC(W * 0.1f, H * 0.055f, scaleC(RGBA(70, 70, 74), day), W * 0.37f, H * 0.055f, scaleC(RGBA(70, 70, 74), day), W * 0.36f, H * 0.12f, scaleC(RGBA(52, 52, 57), day), W * 0.115f, H * 0.13f, scaleC(RGBA(52, 52, 57), day));
    UI.quadC(W * 0.63f, H * 0.055f, scaleC(RGBA(70, 70, 74), day), W * 0.9f, H * 0.055f, scaleC(RGBA(70, 70, 74), day), W * 0.885f, H * 0.11f, scaleC(RGBA(52, 52, 57), day), W * 0.64f, H * 0.105f, scaleC(RGBA(52, 52, 57), day));
    // отсвет мигалки на потолке
    if (PL.flash) {
        UI.glow(W * (flashPh ? 0.35f : 0.65f), 0, H * 0.18f, flashPh ? RGBA(200, 30, 30) : RGBA(30, 60, 220));
    }

    // --- зеркало заднего вида с отражением дороги ---
    {
        float mcx = W * 0.6f, mw = W * 0.17f, mh = H * 0.085f, mx0 = mcx - mw / 2, my0 = H * 0.072f;
        UI.rect(mcx - u * 1.5f, H * 0.05f, u * 3, H * 0.03f, RGBA(25, 25, 28));
        UI.roundRect(mx0 - u * 2, my0 - u * 2, mw + u * 4, mh + u * 4, u * 5, RGBA(18, 18, 20));
        float hz = my0 + mh * 0.5f;
        UI.rectG(mx0 + u, my0 + u, mw - u * 2, hz - my0 - u, toSDL(L.skyTop * 0.8f), toSDL(L.skyHor * 0.85f));
        UI.rectG(mx0 + u, hz, mw - u * 2, my0 + mh - hz - u, toSDL(L.fog * 0.6f), toSDL(Col(0.22f, 0.22f, 0.24f) * (0.4f + 0.6f * day)));
        // дорога назад сходится к горизонту
        UI.tri(mcx - mw * 0.05f, hz, mcx + mw * 0.05f, hz, mcx, hz, RGBA(0, 0, 0, 0));
        V3 f = fwdOf(PL.yaw), r = rightOf(PL.yaw);
        for (const AICar& c : CARS) {
            if (!c.alive) continue;
            V3 d = c.pos - PL.pos; float back = -dot(d, f), lat = dot(d, r);
            if (back < 4 || back > 160) continue;
            float px = mcx + lat / back * mw * 0.9f, sz = clampf(mh * 2.2f / back, u * 0.6f, mh * 0.45f);
            if (px - sz < mx0 + u || px + sz > mx0 + mw - u) continue;
            float py = hz + mh * 0.9f / back * 4;
            if (py > my0 + mh - u) continue;
            Col pc = c.taxi ? Col(0.95f, 0.75f, 0.1f) : c.paint;
            UI.rect(px - sz, py - sz * 0.6f, sz * 2, sz * 0.75f, toSDL(lerpc(pc * (0.3f + 0.6f * day), L.fog, clampf(back / 160, 0, 0.8f))));
            if (L.night > 0.3f || L.rain > 0.4f) { UI.glow(px - sz * 0.6f, py - sz * 0.2f, sz * 0.7f, RGBA(255, 240, 200)); UI.glow(px + sz * 0.6f, py - sz * 0.2f, sz * 0.7f, RGBA(255, 240, 200)); }
            if (c.police || c.mode == CMODE_HELPER) UI.glow(px, py - sz * 0.7f, sz, flashPh ? RGBA(255, 40, 40) : RGBA(40, 80, 255));
        }
        UI.rectG(mx0 + u, my0 + u, mw - u * 2, mh * 0.3f, RGBA(255, 255, 255, 35), RGBA(255, 255, 255, 0));
    }

    // --- торпедо ---
    const int DN = 40;
    auto dashY = [&](float x) {
        float b = expf(-powf((x - W * 0.3f) / (W * 0.12f), 2));
        float e = (x / W - 0.5f) * 2;
        return H * (0.665f - 0.07f * b + 0.012f * e * e);
    };
    for (int i = 0; i < DN; i++) {
        float x0 = W * i / DN, x1 = W * (i + 1) / DN;
        UI.quadC(x0, dashY(x0), scaleC(RGBA(58, 59, 65), day), x1, dashY(x1), scaleC(RGBA(58, 59, 65), day), x1, H, interD, x0, H, interD);
        UI.line(x0, dashY(x0), x1, dashY(x1), u * 1.0f, scaleC(RGBA(85, 87, 95), day));
    }
    // мягкая тень под стеклом
    UI.rectG(0, H * 0.68f, W, H * 0.05f, RGBA(0, 0, 0, 60), RGBA(0, 0, 0, 0));
    // дефлекторы
    for (int k = 0; k < 2; k++) {
        float vx = k == 0 ? W * 0.11f : W * 0.79f, vy = H * 0.73f, vw = W * 0.08f, vh = H * 0.07f;
        UI.roundRect(vx, vy, vw, vh, u * 3, scaleC(RGBA(20, 20, 23), day));
        for (int s = 1; s < 5; s++) UI.rect(vx + u * 2, vy + vh * s / 5.f, vw - u * 4, u * 0.8f, scaleC(RGBA(55, 56, 62), day));
    }
    // бардачок
    UI.line(W * 0.66f, H * 0.83f, W * 0.95f, H * 0.83f, u, scaleC(RGBA(30, 31, 35), day));
    UI.line(W * 0.66f, H * 0.83f, W * 0.67f, H * 0.95f, u, scaleC(RGBA(30, 31, 35), day));

    // --- радар «Искра» на торпедо ---
    {
        float rw = W * 0.13f, rh = H * 0.07f, rx = W * 0.6f, ry = H * 0.62f;
        UI.roundRect(rx, ry, rw, rh, u * 2, RGBA(32, 34, 38));
        UI.rect(rx + u * 2, ry + u * 2, rw - u * 4, u * 1.2f, RGBA(60, 63, 70));
        float bw = rw * 0.44f, bh = rh * 0.62f, by = ry + rh * 0.3f;
        UI.rect(rx + rw * 0.04f, by, bw, bh, RGBA(12, 4, 4));
        UI.rect(rx + rw * 0.52f, by, bw, bh, RGBA(4, 10, 4));
        UI.text(rx + rw * 0.04f + bw / 2, ry + u * 3.5f, "ЦЕЛЬ", u * 0.42f, RGBA(170, 170, 175), 1);
        UI.text(rx + rw * 0.52f + bw / 2, ry + u * 3.5f, "ПАТРУЛЬ", u * 0.42f, RGBA(170, 170, 175), 1);
        bool ov = gRadarSpeed > gRadarLimit + 10;
        std::string ts = gRadarSpeed >= 0 ? fmt("%d", (int)gRadarSpeed) : std::string("--");
        SDL_Color tc = gRadarSpeed >= 0 ? (ov ? RGBA(255, 60, 40) : RGBA(255, 150, 40)) : RGBA(90, 40, 30);
        UI.text(rx + rw * 0.04f + bw / 2, by + bh * 0.18f, ts.c_str(), u * 1.05f, tc, 1);
        int kmh = (int)(fabsf(PL.speed) * 3.6f + 0.5f);
        UI.text(rx + rw * 0.52f + bw / 2, by + bh * 0.18f, fmt("%d", kmh).c_str(), u * 1.05f, RGBA(90, 255, 110), 1);
        if (lit > 0.2f) { UI.glow(rx + rw * 0.26f, by + bh / 2, bw * 0.6f, RGBA(70, 15, 0, (int)(200 * lit))); UI.glow(rx + rw * 0.74f, by + bh / 2, bw * 0.6f, RGBA(0, 50, 10, (int)(200 * lit))); }
        if (ov && fmodf(gTime, 0.4f) < 0.2f) UI.circle(rx + rw - u * 4, ry + u * 4, u * 1.6f, RGBA(255, 40, 30), 8);
    }

    // --- центральная консоль: пульт СГУ и рация ---
    {
        float cx0 = W * 0.47f, cw = W * 0.16f, cy0 = H * 0.71f;
        UI.roundRect(cx0, cy0, cw, H * 0.3f, u * 3, scaleC(RGBA(30, 31, 35), day));
        // пульт мигалки
        float py = cy0 + u * 4, ph = H * 0.06f;
        UI.roundRect(cx0 + u * 3, py, cw - u * 6, ph, u * 2, RGBA(16, 17, 20));
        const char* lab[4] = {"СВЕТ", "СИРЕНА", "РУПОР", "ВСПЫШ"};
        for (int k = 0; k < 4; k++) {
            float bx = cx0 + u * 5 + k * (cw - u * 10) / 4, bw2 = (cw - u * 10) / 4 - u * 2;
            bool on = (k == 0 && PL.flash) || (k == 1 && PL.siren) || (k == 2 && gHornT > 0);
            SDL_Color lc = on ? (k == 0 ? (flashPh ? RGBA(255, 50, 40) : RGBA(50, 90, 255)) : RGBA(255, 190, 40)) : RGBA(60, 62, 68);
            UI.roundRect(bx, py + u * 2, bw2, ph - u * 4, u * 1.5f, RGBA(40, 42, 47));
            UI.rect(bx + u * 1.5f, py + u * 3, bw2 - u * 3, u * 1.5f, lc);
            if (on) UI.glow(bx + bw2 / 2, py + u * 4, bw2 * 0.7f, scaleC(lc, 0.6f));
            UI.text(bx + bw2 / 2, py + ph - u * 6.5f, lab[k], u * 0.36f, RGBA(170, 172, 180), 1);
        }
        // рация
        float ry = py + ph + u * 4;
        UI.roundRect(cx0 + u * 3, ry, cw - u * 6, H * 0.055f, u * 2, RGBA(14, 15, 18));
        UI.rect(cx0 + u * 6, ry + u * 3, cw * 0.55f, H * 0.055f - u * 6, scaleC(RGBA(40, 120, 70), 0.6f + lit * 0.5f));
        UI.text(cx0 + u * 8, ry + u * 5, gChaseCar >= 0 ? "ПОГОНЯ  2-14" : "ДПС-1  154.5", u * 0.5f, RGBA(10, 30, 15));
        UI.circle(cx0 + cw - u * 12, ry + H * 0.0275f, u * 5, RGBA(40, 42, 47), 14);
    }

    // --- приборный щиток ---
    {
        float kx = W * 0.3f, ky = H * 0.715f;
        float gr = H * 0.068f, gap = gr * 2.35f;
        UI.ellipse(kx, ky + gr * 0.1f, gap + gr * 1.45f, gr * 1.45f, RGBA(10, 11, 13), 40);
        float sp = fabsf(PL.speed) * 3.6f;
        // условные передачи и обороты
        int g = PL.gear - 1;
        float rpm = 300 + PL.rpm * 6600;
        cockpitGauge(kx - gap / 2, ky, gr, sp, 300, 6, 5, 999, "КМ/Ч", false, lit);
        cockpitGauge(kx + gap / 2, ky, gr, rpm, 8000, 8, 2, 6500, "X1000", true, lit);
        // индикаторы между приборами
        float ix = kx, iy = ky - gr * 0.55f;
        UI.text(ix, iy, PL.reverse ? "R" : (sp < 1 ? "N" : fmt("%d", g + 1).c_str()), u * 0.9f, RGBA(120, 220, 255), 1);
        if (PL.flash) UI.circle(ix, iy + u * 10, u * 1.6f, flashPh ? RGBA(255, 50, 40) : RGBA(60, 100, 255), 8);
        if (L.night > 0.3f || L.rain > 0.4f) UI.circle(ix, iy + u * 15, u * 1.4f, RGBA(60, 220, 90), 8);
        if (PL.brakeLight) UI.circle(ix, iy + u * 20, u * 1.4f, RGBA(255, 120, 40), 8);
        UI.text(kx - gap / 2, ky + gr * 0.48f, fmt("%d", (int)(sp + 0.5f)).c_str(), u * 0.6f, RGBA(230, 235, 245), 1);
    }

    // --- руль ---
    {
        float cx = W * 0.3f, cy = H * 1.1f, R = H * 0.36f, th = H * 0.055f;
        float a = -PL.steer * 2.4f;
        // спицы (под ободом)
        float spA[3] = {0, PI, PI * 0.5f};
        for (int k = 0; k < 3; k++) {
            float an = a + spA[k];
            float ca = cosf(an), sa = sinf(an), pc = -sa, ps = ca;
            float w0 = k == 2 ? H * 0.06f : H * 0.05f, w1 = H * 0.035f;
            float r0 = R * 0.2f, r1 = R - th * 0.5f;
            UI.quadC(cx + ca * r0 + pc * w0, cy + sa * r0 + ps * w0, scaleC(RGBA(38, 38, 42), day),
                     cx + ca * r1 + pc * w1, cy + sa * r1 + ps * w1, scaleC(RGBA(30, 30, 34), day),
                     cx + ca * r1 - pc * w1, cy + sa * r1 - ps * w1, scaleC(RGBA(22, 22, 25), day),
                     cx + ca * r0 - pc * w0, cy + sa * r0 - ps * w0, scaleC(RGBA(26, 26, 29), day));
        }
        // ступица с подушкой
        UI.circle(cx, cy, R * 0.32f, scaleC(RGBA(24, 24, 27), day), 28);
        UI.circle(cx, cy, R * 0.27f, scaleC(RGBA(34, 34, 38), day), 28);
        UI.ring(cx, cy, R * 0.25f, R * 0.27f, scaleC(RGBA(50, 50, 56), day), 28, PI * 1.1f, PI * 1.9f);
        // обод
        UI.ring(cx, cy, R - th, R, scaleC(RGBA(20, 20, 22), day), 64);
        UI.ring(cx, cy, R - th * 0.75f, R - th * 0.35f, scaleC(RGBA(38, 38, 42), day), 64, PI * 1.15f, PI * 1.85f);
        UI.ring(cx, cy, R - th * 0.6f, R - th * 0.45f, scaleC(RGBA(62, 62, 68), day), 64, PI * 1.3f, PI * 1.7f);
        // метка «12 часов» на ободе
        float ma = a - PI * 0.5f;
        UI.line(cx + cosf(ma) * (R - th), cy + sinf(ma) * (R - th), cx + cosf(ma) * R, cy + sinf(ma) * R, u * 2.2f, scaleC(RGBA(150, 40, 30), 0.6f + day * 0.4f));
    }
    // ночью — общий полумрак салона
    if (L.night > 0.3f) UI.rectG(0, H * 0.66f, W, H * 0.34f, RGBA(0, 0, 0, 0), RGBA(0, 0, 0, (int)(90 * L.night)));
}

// ---------------------------------------------------------------------
//  Экран документов
// ---------------------------------------------------------------------
static void docField(float x, float& y, float u, const char* label, const std::string& val, SDL_Color vc = RGBA(20, 20, 30)) {
    UI.text(x, y, label, u * 0.8f, RGBA(90, 80, 90));
    UI.text(x + UI.textW(label, u * 0.8f) + u * 3, y - u * 0.3f, val.c_str(), u * 1.0f, vc);
    y += u * 10;
}
static void drawDocs(float dt) {
    float u = U();
    AICar& car = CARS[gInspect];
    Case& c = CASES[car.caseIdx];
    UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, 150));
    float mx = std::max(SW * 0.035f, 16.0f), mt = SH * 0.04f;
    float W = SW - mx * 2;
    // верхняя строка
    panel(mx, mt, W, u * 20, C_DARK);
    std::string top = fmt("СЕГОДНЯ: %s    АВТОМОБИЛЬ: %s, %s, %s %d", dateStr(TODAY()).c_str(), CM[car.model].name.c_str(), car.taxi ? "ЖЁЛТЫЙ" : colorName(car.paint), car.plateStr.c_str(), car.region);
    UI.text(mx + u * 6, mt + u * 6, top.c_str(), u * 1.05f, C_WHITE);
    float y0 = mt + u * 24;
    float colW = W * 0.25f;
    // водитель
    panel(mx, y0, colW, SH * 0.62f, C_DARK);
    UI.text(mx + u * 5, y0 + u * 4, "ВОДИТЕЛЬ", u * 1.0f, RGBA(150, 200, 255));
    float fw = colW - u * 10, fh = SH * 0.3f;
    drawFace(mx + u * 5, y0 + u * 14, fw, fh, c.face, c.female, c.age, true, c.belt, c.nervous);
    {   // телефон у уха и плёнка на стекле
        float px = mx + u * 5, py = y0 + u * 14;
        if (c.phone) {
            float ex = px + fw * 0.5f + fw * 0.24f, ey = py + fh * 0.47f;
            UI.ellipse(ex + fw * 0.03f, ey + fh * 0.16f, fw * 0.07f, fh * 0.1f, RGBA(220, 175, 140));
            UI.roundRect(ex - fw * 0.02f, ey - fh * 0.1f, fw * 0.07f, fh * 0.2f, fw * 0.015f, RGBA(20, 20, 24));
            UI.rect(ex - fw * 0.008f, ey - fh * 0.085f, fw * 0.045f, fh * 0.15f, RGBA(70, 110, 160));
        }
        int a = (int)clampf((76 - c.tint) * 3.6f, 0, 200);
        if (a > 0) UI.rect(px, py, fw, fh, RGBA(8, 10, 14, a));
    }
    UI.text(mx + colW - u * 5, y0 + u * 4, fmt("СТЁКЛА: %d%%", c.tint).c_str(), u * 0.85f, c.tint < 70 ? RGBA(255, 150, 120) : RGBA(170, 200, 170), 2);
    float ty = y0 + u * 16 + fh;
    UI.textBox(mx + u * 5, ty, fw, ("«" + c.speech + "»").c_str(), u * 0.85f, C_WHITE);
    // причина
    static const char* reasons[] = {"ПРОВЕРКА ДОКУМЕНТОВ", "ПРЕВЫШЕНИЕ СКОРОСТИ", "ПРЕВЫШЕНИЕ СКОРОСТИ", "ПРОЕЗД НА КРАСНЫЙ", "НАРУШЕНИЕ ПДД"};
    std::string rs = std::string("ПРИЧИНА: ") + reasons[c.reason];
    if (c.road) {
        std::string r2; if (c.road & 1) r2 += "ОБОЧИНА"; if (c.road & 2) r2 += std::string(r2.empty() ? "" : ", ") + "БЕЗ ПОВОРОТНИКА"; if (c.road & 4) r2 += std::string(r2.empty() ? "" : ", ") + "БЕЗ ФАР";
        rs += c.reason == 4 ? " (" + r2 + ")" : " + " + r2;
    }
    if (c.reason == 1 || c.reason == 2) rs += fmt(" (%d ПРИ %d)", (int)c.violSpeed, (int)c.violLimit);
    if (c.fled) rs = "ПРИЧИНА: ПОПЫТКА СКРЫТЬСЯ";
    panel(mx, y0 + SH * 0.62f + u * 4, colW, u * 22, RGBA(60, 20, 20, 220));
    UI.textBox(mx + u * 5, y0 + SH * 0.62f + u * 8, colW - u * 10, rs.c_str(), u * 0.85f, C_WHITE);
    // ВУ
    float cx = mx + colW + u * 6, cw = W * 0.37f, ch = SH * 0.42f;
    UI.roundRect(cx, y0, cw, ch, u * 5, RGBA(245, 220, 225));
    UI.rectG(cx, y0, cw, u * 14, RGBA(220, 150, 170), RGBA(235, 190, 200));
    UI.text(cx + cw / 2, y0 + u * 4, c.lForged ? "ВОДИТЕЛСКОЕ УДОСТОВЕРЕНИЕ" : "ВОДИТЕЛЬСКОЕ УДОСТОВЕРЕНИЕ", u * 0.95f, RGBA(80, 20, 40), 1);
    float pw = cw * 0.3f, ph = ch * 0.62f;
    drawFace(cx + u * 6, y0 + u * 18, pw, ph, c.lFace, c.female, c.age + (c.lFace != c.face ? 0 : -3), false, false, false);
    float fx = cx + pw + u * 12, fy = y0 + u * 18;
    docField(fx, fy, u, "1.", c.lSur);
    docField(fx, fy, u, "2.", c.lName + " " + c.lPatr);
    docField(fx, fy, u, "3.", dateStr(c.lBdate));
    docField(fx, fy, u, "4А.", dateStr(c.lIssue));
    docField(fx, fy, u, "4В.", dateStr(c.lValid), c.lValid < TODAY() ? RGBA(20, 20, 30) : RGBA(20, 20, 30));
    docField(fx, fy, u, "5.", c.lNum);
    docField(fx, fy, u, "9.", c.lCats);
    UI.text(cx + u * 6, y0 + ch - u * 12, "RUS", u * 1.2f, RGBA(80, 20, 40));
    if (!c.lForged) {
        float hx = cx + cw - u * 26, hy = y0 + ch - u * 24;
        for (int k = 0; k < 6; k++) { float t = fmodf(gTime * 0.3f + k / 6.0f, 1.0f); UI.circle(hx + u * 9, hy + u * 9, u * (9 - k * 1.3f), toSDL(Col(0.5f + 0.5f * sinf(t * 6.28f), 0.5f + 0.5f * sinf(t * 6.28f + 2), 0.5f + 0.5f * sinf(t * 6.28f + 4)), 0.6f), 16); }
    } else {
        UI.text(cx + cw - u * 30, y0 + ch - u * 14, "— — —", u * 0.9f, RGBA(160, 140, 150));
    }
    // СТС
    float sy = y0 + ch + u * 6, sh = SH * 0.62f + u * 26 - ch - u * 6;
    UI.roundRect(cx, sy, cw, sh, u * 5, RGBA(220, 238, 220));
    UI.rectG(cx, sy, cw, u * 13, RGBA(140, 190, 140), RGBA(190, 220, 190));
    UI.text(cx + cw / 2, sy + u * 3.5f, "СВИДЕТЕЛЬСТВО О РЕГИСТРАЦИИ ТС", u * 0.9f, RGBA(20, 60, 20), 1);
    float gy = sy + u * 17;
    docField(cx + u * 6, gy, u, "РЕГ. ЗНАК:", fmt("%s %d", c.sPlate.c_str(), c.sRegion));
    docField(cx + u * 6, gy, u, "МАРКА, МОДЕЛЬ:", c.sModel);
    docField(cx + u * 6, gy, u, "ЦВЕТ:", c.sColor);
    docField(cx + u * 6, gy, u, "СОБСТВЕННИК:", c.oSur + " " + firstLetter(c.oName) + "." + firstLetter(c.oPatr) + ".");
    docField(cx + u * 6, gy, u, "СЕРИЯ, №:", c.sNum);
    // ОСАГО
    float ox = cx + cw + u * 6, ow = W - colW - cw - u * 12, oh = SH * 0.32f;
    if (c.osPresent) {
        UI.roundRect(ox, y0, ow, oh, u * 5, RGBA(235, 240, 250));
        UI.rectG(ox, y0, ow, u * 13, RGBA(110, 150, 210), RGBA(170, 195, 235));
        UI.text(ox + ow / 2, y0 + u * 3.5f, "ПОЛИС ОСАГО", u * 1.0f, RGBA(10, 30, 80), 1);
        float oy = y0 + u * 17;
        docField(ox + u * 5, oy, u, "№", c.osNum);
        docField(ox + u * 5, oy, u, "ДЕЙСТВУЕТ ДО:", dateStr(c.osValid));
        docField(ox + u * 5, oy, u, "ТС:", fmt("%s %d", c.osPlate.c_str(), c.osRegion));
        UI.text(ox + u * 5, oy, "ДОПУЩЕНЫ К УПРАВЛЕНИЮ:", u * 0.8f, RGBA(90, 80, 90)); oy += u * 9;
        UI.textBox(ox + u * 5, oy, ow - u * 10, c.osUnlimited ? "БЕЗ ОГРАНИЧЕНИЙ" : c.osDrivers.c_str(), u * 0.9f, RGBA(20, 20, 30));
    } else {
        UI.roundRect(ox, y0, ow, oh, u * 5, RGBA(70, 75, 85, 220));
        UI.textBox(ox + u * 8, y0 + oh / 2 - u * 8, ow - u * 16, "ПОЛИС ОСАГО НЕ ПРЕДЪЯВЛЕН: «ЗАБЫЛ ДОМА...»", u * 1.0f, C_WHITE);
    }
    // база данных
    float by = y0 + oh + u * 6, bh = SH * 0.62f + u * 26 - oh - u * 6;
    panel(ox, by, ow, bh, RGBA(5, 25, 15, 235));
    UI.text(ox + u * 5, by + u * 4, "БАЗА ДАННЫХ ГИБДД", u * 0.95f, RGBA(100, 255, 140));
    if (!c.baseChecked && c.baseT <= 0) {
        if (button(ox + u * 5, by + u * 16, ow - u * 10, u * 20, "ПРОБИТЬ ПО БАЗЕ", RGBA(20, 110, 60), u * 1.0f)) { c.baseT = 2.0f; sfx(SFX_RADIO, 0.5f, 0, 0, 1.6f); }
    } else if (!c.baseChecked) {
        c.baseT -= dt;
        int dots = (int)(gTime * 3) % 4;
        UI.text(ox + u * 5, by + u * 18, (std::string("ЗАПРОС") + std::string(dots, '.')).c_str(), u * 1.0f, RGBA(100, 255, 140));
        if (((int)(gTime * 20)) % 3 == 0) sfx(SFX_TYPE, 0.3f);
        if (c.baseT <= 0) c.baseChecked = true;
    } else {
        float ly = by + u * 16; float lw = ow - u * 10;
        SDL_Color g = RGBA(120, 255, 150), r = RGBA(255, 110, 100);
        std::string l1 = c.lForged ? "ВУ: НЕ НАЙДЕНО В БАЗЕ!" : (c.deprived ? "ВУ: ЛИШЁН ПРАВ ДО " + dateStr(c.deprivedUntil) : "ВУ " + c.lNum + ": " + c.lSur);
        ly += UI.textBox(ox + u * 5, ly, lw, l1.c_str(), u * 0.85f, (c.lForged || c.deprived) ? r : g) + u * 2;
        std::string l2 = c.plateMismatch ? std::string("НОМЕР ") + car.plateStr + ": ЗАРЕГИСТРИРОВАН НА ДРУГОЕ ТС!" : std::string("НОМЕР ") + car.plateStr + ": " + c.sModel;
        ly += UI.textBox(ox + u * 5, ly, lw, l2.c_str(), u * 0.85f, c.plateMismatch ? r : g) + u * 2;
        std::string l3 = c.wanted ? "РОЗЫСК: АВТОМОБИЛЬ В УГОНЕ!" : "РОЗЫСК: НЕ ЧИСЛИТСЯ";
        UI.textBox(ox + u * 5, ly, lw, l3.c_str(), u * 0.85f, c.wanted ? r : g);
    }
    // нижние кнопки
    float bh2 = u * 26, bw = (W - u * 12) / 3, byb = SH - bh2 - SH * 0.04f;
    if (button(mx, byb, bw, bh2, "ОСМОТР БАГАЖНИКА", C_GRAY, u * 1.1f)) { gScreen = SC_TRUNK; c.trunkOpened = true; sfx(SFX_THUNK); }
    if (button(mx + bw + u * 6, byb, bw, bh2, "ПАМЯТКА", C_GRAY, u * 1.1f)) { gHelpReturn = SC_DOCS; gScreen = SC_HELP; }
    if (button(mx + 2 * (bw + u * 6), byb, bw, bh2, "ПРИНЯТЬ РЕШЕНИЕ", C_BLUE, u * 1.1f)) { gScreen = SC_DECIDE; }
    if (gBackPressed) { gBackPressed = false; gScreen = SC_DRIVE; }
}

// ---------------------------------------------------------------------
//  Багажник
// ---------------------------------------------------------------------
static int gTrunkSel = -1;
static void trunkCamera(const AICar& car, int model) {
    const CarModel& M = CM[model];
    V3 pos = car.trailer ? car.tpos : car.pos; float yaw = car.trailer ? car.tyaw : car.yaw;
    V3 f = fwdOf(yaw);
    V3 rearPt = pos + f * M.trunkZ + V3(0, M.trunkY * 0.85f, 0);
    float back = M.tallRear ? 3.4f : 2.6f;
    V3 cam = pos + f * (M.minZ - back) + V3(0, M.trunkY + (M.tallRear ? 0.3f : 1.0f), 0);
    V3 d = rearPt - cam;
    R3.setCamera(cam, atan2f(d.x, d.z), atan2f(d.y, sqrtf(d.x * d.x + d.z * d.z)), 62);
}
static void drawTrunkInterior(const AICar& car, int model, Case& c) {
    const CarModel& M = CM[model];
    V3 pos = car.trailer ? car.tpos : car.pos; float yaw = car.trailer ? car.tyaw : car.yaw;
    Mat3 rot = rotYPR(yaw, 0, 0);
    auto W = [&](V3 p) { return mul(rot, p) + pos; };
    bool big = M.tallRear;
    float floorY = big ? (model == MD_TRUCK || model == MD_TRAILER ? 1.25f : 0.62f) : M.trunkY - 0.42f;
    float topY = big ? M.trunkY - 0.05f : M.trunkY;
    float z0 = M.minZ + 0.02f, z1 = M.trunkZ + (big ? 1.2f : 0.85f);
    if (model == MD_TRUCK) z1 = M.trunkZ + 2.2f;
    if (model == MD_TRAILER) z1 = M.trunkZ + 3.0f;
    if (model == MD_PICKUP) { floorY = 0.94f; z1 = M.trunkZ + 1.75f; topY = 1.47f; }
    float w = M.trunkW + 0.05f;
    Col carpet(0.14f, 0.14f, 0.16f), wall(0.2f, 0.2f, 0.22f);
    auto q = [&](V3 a, V3 b, V3 cc, V3 d, Col col) {
        V3 n = norm(cross(W(b) - W(a), W(d) - W(a)));
        R3.quadW(W(a), W(b), W(cc), W(d), toSDL(shadeN(col, n, W(a)) + col * 0.3f), 2, 0, 0);
    };
    q(V3(-w, floorY, z0), V3(w, floorY, z0), V3(w, floorY, z1), V3(-w, floorY, z1), carpet);
    q(V3(-w, floorY, z1), V3(w, floorY, z1), V3(w, topY, z1), V3(-w, topY, z1), wall);
    q(V3(-w, floorY, z0), V3(-w, floorY, z1), V3(-w, topY, z1), V3(-w, topY, z0), wall * 0.85f);
    q(V3(w, floorY, z0), V3(w, topY, z0), V3(w, topY, z1), V3(w, floorY, z1), wall * 0.85f);
    // крышка/дверь
    Col lid = car.paint;
    if (big) q(V3(-w - 0.05f, topY + 0.05f, z0 + 0.25f), V3(w + 0.05f, topY + 0.05f, z0 + 0.25f), V3(w + 0.05f, topY + 0.25f, z0 - 0.75f), V3(-w - 0.05f, topY + 0.25f, z0 - 0.75f), lid);
    else q(V3(-w - 0.03f, topY + 0.02f, z1), V3(w + 0.03f, topY + 0.02f, z1), V3(w + 0.03f, topY + 0.85f, z1 - 0.35f), V3(-w - 0.03f, topY + 0.85f, z1 - 0.35f), lid);
    R3.draw();
    // предметы
    for (size_t i = 0; i < c.items.size(); i++) {
        TrunkItem& it = c.items[i];
        Col col = it.col;
        if ((int)i == gTrunkSel) col = col + Col(0.25f, 0.22f, 0.05f);
        V3 cpos = W(it.lp);
        if (it.kind == 6) {
            DrawCar d; d.pos = cpos; d.yaw = yaw; d.spin = 0; d.steer = 0;
            WheelDef wd; wd.p = V3(0, 0, 0); wd.r = it.hs.x; wd.w = it.hs.y * 2; wd.steer = false;
            Mat3 rr = rotYPR(yaw + PI / 2, 0, PI / 2);
            drawWheel(wd, rr, cpos, yaw, d, 0, false);
        } else {
            shadedBox(cpos, it.hs, yaw, col);
            if (it.kind == 2) shadedBox(cpos + V3(0, it.hs.y + 0.03f, 0), V3(0.02f, 0.03f, it.hs.z * 0.6f), yaw, col * 0.6f);
            if (it.kind == 3 || it.kind == 0) shadedBox(cpos + V3(0, it.hs.y + 0.04f, 0), V3(it.hs.x * 0.4f, 0.03f, 0.02f), yaw, Col(0.1f, 0.1f, 0.1f));
            if (it.kind == 1) shadedBox(cpos + V3(0, it.hs.y + 0.002f, 0), V3(0.03f, 0.003f, it.hs.z), yaw, Col(0.75f, 0.65f, 0.4f));
        }
    }
    R3.draw();
}
static void drawTrunkScreen(float dt) {
    (void)dt;
    float u = U();
    AICar& car = CARS[gInspect];
    Case& c = CASES[car.caseIdx];
    int model = car.trailer ? MD_TRAILER : car.model;
    trunkCamera(car, model);
    drawWorldScene(dt, true, false);
    drawTrunkInterior(car, model, c);
    // выбор предмета
    for (Tap& t : TAPS) {
        if (t.used) continue;
        if (t.y > SH - u * 40) continue;
        float best = 1e9f; int bi = -1;
        Mat3 rot = rotYPR(car.trailer ? car.tyaw : car.yaw, 0, 0);
        V3 pos = car.trailer ? car.tpos : car.pos;
        for (size_t i = 0; i < c.items.size(); i++) {
            float sx, sy, sz;
            if (!R3.project(mul(rot, c.items[i].lp) + pos, sx, sy, sz)) continue;
            float r = std::max(c.items[i].hs.x, c.items[i].hs.z) * R3.focal / sz + u * 12;
            float d = sqrtf((sx - t.x) * (sx - t.x) + (sy - t.y) * (sy - t.y));
            if (d < r && d < best) { best = d; bi = (int)i; }
        }
        if (bi >= 0) { t.used = true; gTrunkSel = bi; c.items[bi].inspected = true; sfx(SFX_THUNK, 0.6f); if (c.items[bi].illegal) sfx(SFX_ERROR, 0.4f); }
    }
    for (size_t i = 0; i < c.items.size(); i++) {
        const TrunkItem& it = c.items[i];
        Mat3 rot = rotYPR(car.trailer ? car.tyaw : car.yaw, 0, 0);
        V3 pos = car.trailer ? car.tpos : car.pos;
        V3 wp = mul(rot, it.lp + V3(0, it.hs.y + 0.12f, 0)) + pos;
        std::string s = it.inspected ? std::string(ITEM_NAMES[it.kind]) + ": " + it.content : std::string(ITEM_NAMES[it.kind]) + " (?)";
        float sx, sy, sz;
        if (!R3.project(wp, sx, sy, sz)) continue;
        float sc = u * 1.0f, w = UI.textW(s.c_str(), sc) + u * 8, h = u * 11;
        // раздвигаем пересекающиеся подписи
        static std::vector<SDL_FRect> used; if (i == 0) used.clear();
        bool moved = true; int guard = 0;
        while (moved && guard++ < 10) {
            moved = false;
            for (const SDL_FRect& r : used) if (fabsf(r.x - sx) < (r.w + w) * 0.5f && fabsf(r.y - sy) < h) { sy = r.y - h - u; moved = true; }
        }
        SDL_FRect rr = {sx, sy, w, h}; used.push_back(rr);
        UI.roundRect(sx - w / 2, sy - 9 * sc, w, h, 3, RGBA(0, 0, 0, 160));
        UI.text(sx, sy - 7.5f * sc, s.c_str(), sc, it.illegal && it.inspected ? RGBA(255, 90, 80) : C_WHITE, 1);
    }
    float mx = std::max(SW * 0.035f, 16.0f);
    panel(mx, SH * 0.04f, SW - 2 * mx, u * 18, C_DARK);
    UI.text(SW / 2, SH * 0.04f + u * 5, "ОСМОТР БАГАЖНИКА: НАЖИМАЙ НА ПРЕДМЕТЫ, ЧТОБЫ ОСМОТРЕТЬ", u * 1.0f, C_WHITE, 1);
    if (button(SW / 2 - u * 70, SH - u * 30 - SH * 0.04f, u * 140, u * 26, "ЗАКРЫТЬ БАГАЖНИК", C_BLUE, u * 1.1f) || gBackPressed) { gBackPressed = false; gScreen = SC_DOCS; gTrunkSel = -1; sfx(SFX_THUNK); }
}

// ---------------------------------------------------------------------
//  Решение и результат
// ---------------------------------------------------------------------
static bool gArts[ART_N]; static bool gFineMode = false;
static std::string gResTitle; static std::vector<std::string> gResLines; static int gResMoney = 0, gResRep = 0; static bool gResGood = false;
static void drawDecide() {
    float u = U();
    UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, 170));
    float w = u * 260, h = SH * 0.86f, x = SW / 2 - w / 2, y = SH * 0.07f;
    panel(x, y, w, h, C_DARK);
    UI.text(SW / 2, y + u * 6, gFineMode ? "ВЫБЕРИТЕ СТАТЬИ КОАП" : "РЕШЕНИЕ ПО ВОДИТЕЛЮ", u * 1.4f, C_WHITE, 1);
    float by = y + u * 24, bh = u * 25, bw = w - u * 20, bx = x + u * 10;
    if (!gFineMode) {
        SDL_Color cols[5] = {C_GREEN, RGBA(60, 120, 170), RGBA(200, 140, 20), RGBA(170, 90, 30), C_RED};
        for (int i = 0; i < 5; i++) {
            if (button(bx, by, bw, bh, VERDICT_NAMES[i], cols[i], u * 1.2f)) {
                if (i == V_FINE) { gFineMode = true; for (int k = 0; k < ART_N; k++) gArts[k] = false; }
                else { bool none[ART_N] = {}; finishInspection(i, none, gResTitle, gResLines, gResMoney, gResRep, gResGood); gScreen = SC_RESULT; }
            }
            by += bh + u * 5;
        }
        if (button(bx, by + u * 4, bw, bh * 0.8f, "НАЗАД К ДОКУМЕНТАМ", C_GRAY, u * 1.0f) || gBackPressed) { gBackPressed = false; gScreen = SC_DOCS; }
    } else {
        float ah = std::min(bh, (h - u * 100) / ART_N - u * 3);
        for (int i = 0; i < ART_N; i++) {
            std::string l = std::string(gArts[i] ? "[X] " : "[ ] ") + ART_NAMES[i];
            if (button(bx, by, bw, ah, l.c_str(), gArts[i] ? RGBA(200, 140, 20) : C_GRAY, u * 0.95f)) gArts[i] = !gArts[i];
            by += ah + u * 3;
        }
        bool any = false; for (int i = 0; i < ART_N; i++) any |= gArts[i];
        if (button(bx, by + u * 4, bw, bh, "ВЫПИСАТЬ ШТРАФ", C_BLUE, u * 1.2f, any)) { finishInspection(V_FINE, gArts, gResTitle, gResLines, gResMoney, gResRep, gResGood); gScreen = SC_RESULT; gFineMode = false; }
        by += bh + u * 8;
        if (button(bx, by + u * 4, bw, bh * 0.8f, "НАЗАД", C_GRAY, u * 1.0f) || gBackPressed) { gBackPressed = false; gFineMode = false; }
    }
}
static void drawResult() {
    float u = U();
    UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, 170));
    float w = u * 280, h = SH * 0.84f, x = SW / 2 - w / 2, y = SH * 0.08f;
    panel(x, y, w, h, C_DARK);
    UI.roundRect(x, y, w, u * 24, u * 5, gResGood ? RGBA(30, 120, 50) : RGBA(150, 30, 30));
    UI.text(SW / 2, y + u * 7, gResTitle.c_str(), u * 1.3f, C_WHITE, 1);
    float ly = y + u * 32;
    for (const std::string& l : gResLines) { ly += UI.textBox(x + u * 10, ly, w - u * 20, l.c_str(), u * 1.0f, C_LIGHT) + u * 1; }
    ly += u * 6;
    UI.text(x + u * 10, ly, fmt("ДЕНЬГИ: %+d ₽", gResMoney).c_str(), u * 1.3f, gResMoney >= 0 ? RGBA(120, 255, 140) : RGBA(255, 110, 100));
    UI.text(x + w / 2 + u * 10, ly, fmt("РЕПУТАЦИЯ: %+d", gResRep).c_str(), u * 1.3f, gResRep >= 0 ? RGBA(120, 255, 140) : RGBA(255, 110, 100));
    if (button(SW / 2 - u * 60, y + h - u * 32, u * 120, u * 24, "ДАЛЕЕ", C_BLUE, u * 1.2f) || gBackPressed) {
        gBackPressed = false; gScreen = SC_DRIVE; gInspect = -1;
        int rk = rankOf(SV.rep);
        static int lastRank = -1; if (lastRank < 0) lastRank = SHF.startRank;
        if (rk > lastRank) { toast(std::string("ПОВЫШЕНИЕ! НОВОЕ ЗВАНИЕ: ") + RANKS[rk], 1, 5); sfx(SFX_SUCCESS); }
        lastRank = rk;
    }
}

// ---------------------------------------------------------------------
//  Оформление ДТП
// ---------------------------------------------------------------------
static void drawSchemeCar(float cx, float cy, float ang, float s, SDL_Color c, const char* letter) {
    // прямоугольник машины, повернутый на ang (0 — вверх)
    float w = s * 0.45f, h = s;
    float ca = cosf(ang), sa = sinf(ang);
    auto P = [&](float x, float y, float& ox, float& oy) { ox = cx + x * ca - y * sa; oy = cy + x * sa + y * ca; };
    float x0, y0, x1, y1, x2, y2, x3, y3;
    P(-w / 2, -h / 2, x0, y0); P(w / 2, -h / 2, x1, y1); P(w / 2, h / 2, x2, y2); P(-w / 2, h / 2, x3, y3);
    UI.quad(x0, y0, x1, y1, x2, y2, x3, y3, c);
    float fx, fy; P(0, -h / 2 - s * 0.45f, fx, fy); float bx, by; P(0, -h / 2, bx, by);
    UI.line(bx, by, fx, fy, std::max(2.f, s * 0.06f), RGBA(255, 255, 255, 200));
    float ax1, ay1, ax2, ay2; P(-s * 0.12f, -h / 2 - s * 0.3f, ax1, ay1); P(s * 0.12f, -h / 2 - s * 0.3f, ax2, ay2);
    UI.tri(fx, fy, ax1, ay1, ax2, ay2, RGBA(255, 255, 255, 200));
    UI.text(cx, cy - s * 0.18f, letter, s * 0.06f, RGBA(0, 0, 0), 1);
}
static void drawScheme(float x, float y, float w, float h) {
    float u = U();
    UI.roundRect(x, y, w, h, u * 4, RGBA(70, 110, 70));
    float cx = x + w / 2, cy = y + h / 2, s = std::min(w, h) * 0.2f;
    SDL_Color road = RGBA(90, 90, 96), line = RGBA(230, 230, 230);
    int g = ACC.guilty, v = 1 - g;
    const char* L[2] = {"А", "Б"};
    SDL_Color col[2] = {toSDL(CARS[ACC.car[0]].paint * 0.9f + Col(0.08f, 0.08f, 0.08f)), toSDL(CARS[ACC.car[1]].paint * 0.9f + Col(0.08f, 0.08f, 0.08f))};
    if (ACC.type == ACC_REAREND || ACC.type == ACC_LANE) {
        UI.rect(cx - s * 1.1f, y + 2, s * 2.2f, h - 4, road);
        for (float yy = y + 6; yy < y + h - 6; yy += s * 0.5f) UI.rect(cx - 1, yy, 2, s * 0.25f, line);
        if (ACC.type == ACC_REAREND) { drawSchemeCar(cx + s * 0.55f, cy - s * 0.7f, 0, s, col[v], L[v]); drawSchemeCar(cx + s * 0.55f, cy + s * 0.55f, 0, s, col[g], L[g]); UI.text(cx + s * 0.55f, cy - s * 0.1f, "*", s * 0.09f, C_YELLOW, 1); }
        else { drawSchemeCar(cx + s * 0.55f, cy - s * 0.3f, 0, s, col[v], L[v]); drawSchemeCar(cx - s * 0.45f, cy + s * 0.2f, 0.45f, s, col[g], L[g]); UI.text(cx + s * 0.05f, cy - s * 0.35f, "*", s * 0.09f, C_YELLOW, 1); }
        UI.text(x + u * 4, y + u * 3, "ОДНО НАПРАВЛЕНИЕ", u * 0.75f, C_WHITE);
    } else {
        UI.rect(cx - s * 0.9f, y + 2, s * 1.8f, h - 4, road);
        UI.rect(x + 2, cy - s * 0.9f, w - 4, s * 1.8f, road);
        drawSchemeCar(cx + s * 0.45f, cy + s * 1.0f, 0, s, col[g], L[g]);
        if (ACC.type == ACC_YIELD) drawSchemeCar(cx + s * 1.2f, cy - s * 0.45f, -PI / 2, s, col[v], L[v]);
        else drawSchemeCar(cx - s * 1.2f, cy + s * 0.45f, PI / 2, s, col[v], L[v]);
        UI.text(cx + s * 0.45f, cy + s * 0.25f, "*", s * 0.09f, C_YELLOW, 1);
        UI.text(x + u * 4, y + u * 3, ACC.type == ACC_RED ? "РЕГУЛИРУЕМЫЙ ПЕРЕКРЁСТОК" : "СВЕТОФОР НЕ РАБОТАЛ", u * 0.75f, C_WHITE);
        if (ACC.type == ACC_RED) { UI.rect(x + w - u * 12, y + u * 4, u * 7, u * 18, RGBA(20, 20, 20)); for (int k = 0; k < 3; k++) UI.circle(x + w - u * 8.5f, y + u * (7.5f + k * 5.5f), u * 2, k == 0 ? RGBA(200, 40, 40) : (k == 1 ? RGBA(200, 170, 40) : RGBA(40, 180, 80)), 10); }
    }
}

static void finishAccident() {
    int g = ACC.guilty;
    bool okGuilty = ACC.pickGuilty == g;
    static const int needArt[ACC_NTYPES] = {AA_DIST, AA_RED, AA_LANE, AA_YIELD};
    bool okArt = ACC.pickArt == needArt[ACC.type];
    float late = clampf((SHF.minutes - ACC.callMin - 20) / 55, 0, 1);   // штраф за опоздание
    int money = 0, rep = 0;
    gResLines.clear();
    if (okGuilty && okArt) { money = (int)(2500 * (1 - 0.6f * late)); rep = 6; gResTitle = "ДТП ОФОРМЛЕНО ВЕРНО"; gResGood = true; }
    else if (okGuilty) { money = 800; rep = 1; gResTitle = "ВИНОВНИК ВЕРНЫЙ, НО СТАТЬЯ НЕ ТА"; gResGood = false; }
    else { money = -500; rep = -6; gResTitle = "ОШИБКА: НАКАЗАН НЕВИНОВНЫЙ!"; gResGood = false; SV.complaints++; }
    const char* L[2] = {"А", "Б"};
    gResLines.push_back(std::string("ВИНОВНИК: ВОДИТЕЛЬ ") + L[g] + " (" + carDesc(ACC.car[g]) + ")");
    gResLines.push_back(std::string("СТАТЬЯ: ") + ACC_ART_NAMES[needArt[ACC.type]]);
    gResLines.push_back("- " + ACC.witnessText);
    for (int k = 0; k < 2; k++) if (ACC.drunk[k]) {
        if (ACC.tested[k]) { money += 1500; rep += 2; gResLines.push_back(std::string("+ ВОДИТЕЛЬ ") + L[k] + " ПЬЯН — ОТСТРАНЁН ОТ УПРАВЛЕНИЯ (12.8)"); }
        else { rep -= 3; gResLines.push_back(std::string("- ПРОПУЩЕНО: ВОДИТЕЛЬ ") + L[k] + " БЫЛ ПЬЯН (НЕ ПРОВЕРЕН АЛКОТЕСТЕРОМ)"); }
    }
    if (ACC.injured) {
        if (ACC.ambulance) { rep += 1; gResLines.push_back("+ ПОСТРАДАВШЕМУ ВЫЗВАНА СКОРАЯ"); }
        else { rep -= 4; money -= 300; gResLines.push_back("- НЕ ВЫЗВАНА СКОРАЯ ДЛЯ ПОСТРАДАВШЕГО!"); }
    }
    if (late > 0.01f) gResLines.push_back(fmt("ОПОЗДАНИЕ: НАГРАДА МЕНЬШЕ НА %d%%", (int)(late * 60)));
    if (money > 0) { float pm = payMulAt(ACC.pos); if (fabsf(pm - 1) > 0.01f) { int add = (int)(money * (pm - 1)); money += add; gResLines.push_back(fmt("%s ЗА ТРАФИК (X%.2f): %+d ₽", pm > 1 ? "+ НАДБАВКА" : "- ПОНИЖЕНИЕ", pm, add)); } }
    gResMoney = money; gResRep = rep;
    SV.money = std::max(0, SV.money + money); addRep(rep);
    if (gResGood) { SHF.correct++; SV.totalCorrect++; sfx(SFX_COIN); taskProgress(T_ACCIDENT); } else { SHF.wrong++; SV.totalWrong++; sfx(SFX_ERROR); }
    SHF.accidents++;
    SHF.minutes += 10;
    clearAccident(true);
    gScreen = SC_RESULT; gInspect = -1;
}

static void drawAccidentScreen(float dt) {
    (void)dt;
    float u = U();
    UI.rect(0, 0, SW, SH, RGBA(0, 0, 0, 150));
    float mx = std::max(SW * 0.035f, 16.0f), mt = SH * 0.04f, W = SW - mx * 2;
    panel(mx, mt, W, u * 20, C_DARK);
    UI.text(mx + u * 6, mt + u * 6, ("ОФОРМЛЕНИЕ ДТП: " + ACC.where).c_str(), u * 1.05f, C_WHITE);
    float y0 = mt + u * 24, colW = W * 0.3f, colH = SH * 0.66f;
    const char* L[2] = {"А", "Б"};
    for (int k = 0; k < 2; k++) {
        float x = k == 0 ? mx : mx + W - colW;
        panel(x, y0, colW, colH, C_DARK);
        const Case& cs = CASES[ACC.caseIdx[k]];
        UI.text(x + u * 5, y0 + u * 4, (std::string("ВОДИТЕЛЬ ") + L[k] + ": " + cs.sur + " " + firstLetter(cs.name) + ".").c_str(), u * 0.9f, RGBA(150, 200, 255));
        UI.text(x + u * 5, y0 + u * 14, carDesc(ACC.car[k]).c_str(), u * 0.8f, C_LIGHT);
        float fw = colW * 0.42f, fh = fw * 1.15f;
        drawFace(x + u * 5, y0 + u * 24, fw, fh, cs.face, cs.female, cs.age, true, true, true);
        float tx = x + fw + u * 9, tw = colW - fw - u * 14;
        UI.text(tx, y0 + u * 25, "ПОВРЕЖДЕНИЯ:", u * 0.75f, RGBA(255, 180, 120));
        UI.textBox(tx, y0 + u * 34, tw, ACC.damage[k].c_str(), u * 0.8f, C_WHITE);
        float sy = y0 + u * 28 + fh;
        float hh = UI.textBox(x + u * 5, sy, colW - u * 10, ("«" + ACC.stmt[k] + "»").c_str(), u * 0.85f, C_WHITE);
        float by = std::max(sy + hh + u * 4, y0 + colH - u * 24);
        if (!ACC.tested[k]) { if (button(x + u * 5, by, colW - u * 10, u * 19, "АЛКОТЕСТЕР", RGBA(110, 80, 160), u * 0.95f)) { ACC.tested[k] = true; sfx(SFX_BEEP, 0.6f, 1300, 1300, 0.6f); } }
        else UI.text(x + colW / 2, by + u * 5, ACC.drunk[k] ? "0.62 МГ/Л — ОПЬЯНЕНИЕ!" : "0.00 МГ/Л — ТРЕЗВ", u * 0.95f, ACC.drunk[k] ? RGBA(255, 110, 100) : RGBA(120, 255, 140), 1);
    }
    // центр: схема, свидетель, скорая
    float cx = mx + colW + u * 6, cw = W - 2 * colW - u * 12;
    float schH = SH * 0.3f;
    drawScheme(cx, y0, cw, schH);
    float ty = y0 + schH + u * 5;
    if (!ACC.witness) { if (button(cx, ty, cw, u * 19, "ОПРОСИТЬ СВИДЕТЕЛЯ", C_GRAY, u * 0.95f)) { ACC.witness = true; sfx(SFX_SPEECH, 0.7f, 160, 0, 1.4f); } ty += u * 23; }
    else { panel(cx, ty, cw, u * 36, RGBA(30, 40, 30, 230)); UI.textBox(cx + u * 4, ty + u * 3, cw - u * 8, ("СВИДЕТЕЛЬ: «" + ACC.witnessText + "»").c_str(), u * 0.75f, C_WHITE); ty += u * 40; }
    if (ACC.injured) {
        if (!ACC.ambulance) { if (button(cx, ty, cw, u * 19, "ВЫЗВАТЬ СКОРУЮ (ЖАЛОБЫ НА БОЛЬ)", RGBA(170, 50, 50), u * 0.85f)) { ACC.ambulance = true; sfx(SFX_RADIO, 0.6f); } }
        else UI.text(cx + cw / 2, ty + u * 5, "СКОРАЯ ВЫЗВАНА", u * 0.9f, RGBA(120, 255, 140), 1);
        ty += u * 23;
    }
    // нижняя панель: виновник и статья
    float by = y0 + colH + u * 5;
    float bh = u * 20;
    UI.text(mx, by + u * 6, "ВИНОВНИК:", u * 0.9f, C_WHITE);
    float bx = mx + u * 50;
    for (int k = 0; k < 2; k++) if (button(bx + k * (u * 42), by, u * 38, bh, (std::string("ВОДИТ. ") + L[k]).c_str(), ACC.pickGuilty == k ? C_BLUE : C_GRAY, u * 0.85f)) ACC.pickGuilty = k;
    float ax = bx + u * 90, aw = (mx + W - ax - u * 96 - 3 * u * 3) / 4;
    for (int a = 0; a < AA_N; a++) {
        static const char* shortN[AA_N] = {"12.15 ДИСТАНЦИЯ", "12.12 КРАСНЫЙ", "12.14 ПЕРЕСТРОЕН.", "12.13 ПОМЕХА СПРАВА"};
        if (button(ax + a * (aw + u * 3), by, aw, bh, shortN[a], ACC.pickArt == a ? RGBA(200, 140, 20) : C_GRAY, u * 0.75f)) ACC.pickArt = a;
    }
    bool ready = ACC.pickGuilty >= 0 && ACC.pickArt >= 0;
    if (button(mx + W - u * 90, by, u * 90, bh, "ОФОРМИТЬ", C_GREEN, u * 1.0f, ready)) finishAccident();
    if (gBackPressed) { gBackPressed = false; gScreen = SC_DRIVE; }
}

